SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `animerelations`;
CREATE TABLE `animerelations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sourceAnimeId` int NOT NULL,
  `targetAnimeId` int NOT NULL,
  `relationType` varchar(255) NOT NULL COMMENT 'SEQUEL, PREQUEL, SIDE_STORY, SPIN_OFF, PARENT, ALTERNATIVE, etc.',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_anime_relation` (`sourceAnimeId`,`targetAnimeId`,`relationType`),
  KEY `anime_relations_source_anime_id` (`sourceAnimeId`),
  KEY `anime_relations_target_anime_id` (`targetAnimeId`),
  CONSTRAINT `animerelations_ibfk_1` FOREIGN KEY (`sourceAnimeId`) REFERENCES `animes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `animerelations_ibfk_2` FOREIGN KEY (`targetAnimeId`) REFERENCES `animes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4178 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


DROP TABLE IF EXISTS `animes`;
CREATE TABLE `animes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `src` varchar(255) NOT NULL,
  `category` varchar(255) NOT NULL,
  `rating` varchar(255) NOT NULL DEFAULT '0.0',
  `description` text,
  `studio` varchar(255) DEFAULT NULL,
  `year` varchar(255) DEFAULT NULL,
  `type` enum('series','movie') NOT NULL DEFAULT 'series',
  `status` enum('upcoming','airing','released') NOT NULL DEFAULT 'released',
  `releaseDate` date DEFAULT NULL,
  `anilistId` int DEFAULT NULL,
  `homeFeatured` tinyint(1) DEFAULT '0',
  `homeOrder` int DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `bannerImage` varchar(255) DEFAULT NULL,
  `genres` text COMMENT 'Comma-separated genres',
  `format` varchar(255) DEFAULT NULL COMMENT 'TV, MOVIE, OVA, etc.',
  `season` varchar(255) DEFAULT NULL COMMENT 'WINTER, SPRING, SUMMER, FALL',
  `episodes` int DEFAULT NULL,
  `popularity` int DEFAULT NULL,
  `trailer` varchar(255) DEFAULT NULL COMMENT 'YouTube trailer link',
  `lastSuccessfulRefreshAt` datetime DEFAULT NULL,
  `relationsCheckedAt` datetime DEFAULT NULL COMMENT 'Timestamp of last relations scan for batch tracking',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  UNIQUE KEY `name_2` (`name`),
  UNIQUE KEY `name_3` (`name`),
  UNIQUE KEY `name_4` (`name`),
  UNIQUE KEY `name_5` (`name`),
  UNIQUE KEY `name_6` (`name`),
  UNIQUE KEY `name_7` (`name`),
  UNIQUE KEY `name_8` (`name`),
  UNIQUE KEY `name_9` (`name`),
  UNIQUE KEY `name_10` (`name`),
  UNIQUE KEY `name_11` (`name`),
  UNIQUE KEY `name_12` (`name`),
  UNIQUE KEY `name_13` (`name`),
  UNIQUE KEY `name_14` (`name`),
  UNIQUE KEY `name_15` (`name`),
  UNIQUE KEY `name_16` (`name`),
  UNIQUE KEY `name_17` (`name`),
  UNIQUE KEY `name_18` (`name`),
  UNIQUE KEY `name_19` (`name`),
  UNIQUE KEY `name_20` (`name`),
  UNIQUE KEY `name_21` (`name`),
  UNIQUE KEY `name_22` (`name`),
  UNIQUE KEY `name_23` (`name`),
  UNIQUE KEY `name_24` (`name`),
  UNIQUE KEY `name_25` (`name`),
  UNIQUE KEY `anilistId` (`anilistId`),
  UNIQUE KEY `anilistId_2` (`anilistId`),
  UNIQUE KEY `anilistId_3` (`anilistId`),
  UNIQUE KEY `anilistId_4` (`anilistId`),
  UNIQUE KEY `anilistId_5` (`anilistId`),
  UNIQUE KEY `anilistId_6` (`anilistId`),
  UNIQUE KEY `anilistId_7` (`anilistId`),
  UNIQUE KEY `anilistId_8` (`anilistId`),
  UNIQUE KEY `anilistId_9` (`anilistId`),
  UNIQUE KEY `anilistId_10` (`anilistId`)
) ENGINE=InnoDB AUTO_INCREMENT=3544 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1, 'DAN DA DAN', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx171018-60q1B6GK2Ghb.jpg', 'series', '8.3', 'This is a story about Momo, a high school girl who comes from a family of spirit mediums, and her classmate Okarun, an occult fanatic. After Momo rescues Okarun from being bullied, they begin talking. However, an argument ensues between them since Momo believes in ghosts but denies aliens exist, and Okarun believes in aliens but denies ghosts exist.

To prove to each other what they believe in is real, Momo goes to an abandoned hospital where a UFO has been spotted and Okarun goes to a tunnel rumored to be haunted. To their surprise, they each encounter overwhelming paranormal activities that transcend comprehension. Amid these predicaments, Momo awakens her hidden power and Okarun gains the power of a curse to overcome these new dangers! Their fateful love begins as well!?

The story of the occult battle and adolescence starts!

(Source: Crunchyroll) 

Notes: 

- Worldwide premiere of Episode 1 before the Japanese television premiere occurred at Anime Expo July 6, 2024. 

- Episodes 1-3 titled as DAN DA DAN: FIRST ENCOUNTER was pre-screened in advance in theaters on August 31, 2024 in Asia, September 7, 2024 in Europe and September 13, 2024 in North America. The regular TV broadcast began October 4, 2024.', 'Science SARU', '2024', 'series', 'released', '2024-10-04', 171018, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:24', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/171018-SpwPNAduszXl.jpg', 'Action, Comedy, Drama, Romance, Sci-Fi, Supernatural', 'TV', 'FALL', 12, 366736, 'https://www.youtube.com/watch?v=rJo1MnsuxyY', '2026-07-25 15:12:05', '2026-09-03 15:29:24');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2, 'Death Note', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1535-kUgkcrfOrkUM.jpg', 'series', '8.4', 'Light Yagami is a genius high school student who is about to learn about life through a book of death. When a bored shinigami, a God of Death, named Ryuk drops a black notepad called a Death Note, Light receives power over life and death with the stroke of a pen. Determined to use this dark gift for the best, Light sets out to rid the world of evil… namely, the people he believes to be evil. Should anyone hold such power?

The consequences of Light’s actions will set the world ablaze.

(Source: VIZ Media)', 'MADHOUSE', '2006', 'series', 'released', '2006-10-04', 1535, 0, 1, '2026-03-08 23:01:33', '2026-09-03 15:29:26', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1535.jpg', 'Mystery, Psychological, Supernatural, Thriller', 'TV', 'FALL', 37, 955698, 'https://www.youtube.com/watch?v=NlJZ-YgAt-c', '2026-07-25 15:12:07', '2026-09-03 15:29:26');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3, 'Frieren: Beyond Journey’s End', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx154587-qQTzQnEJJ3oB.jpg', 'series', '9.1', 'The adventure is over but life goes on for an elf mage just beginning to learn what living is all about. Elf mage Frieren and her courageous fellow adventurers have defeated the Demon King and brought peace to the land. But Frieren will long outlive the rest of her former party. How will she come to understand what life means to the people around her? Decades after their victory, the funeral of one her friends confronts Frieren with her own near immortality. Frieren sets out to fulfill the last wishes of her comrades and finds herself beginning a new adventure…

(Source: Crunchyroll)', 'MADHOUSE', '2023', 'series', 'released', '2023-09-29', 154587, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:27', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/154587-ivXNJ23SM1xB.jpg', 'Adventure, Drama, Fantasy', 'TV', 'FALL', 28, 462783, 'https://www.youtube.com/watch?v=tR8YH0G67Rk', '2026-07-25 15:12:09', '2026-09-03 15:29:27');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (4, 'Fullmetal Alchemist: Brotherhood', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx5114-nSWCgQlmOMtj.jpg', 'series', '9.0', '"In order for something to be obtained, something of equal value must be lost."

Alchemy is bound by this Law of Equivalent Exchange—something the young brothers Edward and Alphonse Elric only realize after attempting human transmutation: the one forbidden act of alchemy. They pay a terrible price for their transgression—Edward loses his left leg, Alphonse his physical body. It is only by the desperate sacrifice of Edward''s right arm that he is able to affix Alphonse''s soul to a suit of armor. Devastated and alone, it is the hope that they would both eventually return to their original bodies that gives Edward the inspiration to obtain metal limbs called "automail" and become a state alchemist, the Fullmetal Alchemist.

Three years of searching later, the brothers seek the Philosopher''s Stone, a mythical relic that allows an alchemist to overcome the Law of Equivalent Exchange. Even with military allies Colonel Roy Mustang, Lieutenant Riza Hawkeye, and Lieutenant Colonel Maes Hughes on their side, the brothers find themselves caught up in a nationwide conspiracy that leads them not only to the true nature of the elusive Philosopher''s Stone, but their country''s murky history as well. In between finding a serial killer and racing against time, Edward and Alphonse must ask themselves if what they are doing will make them human again... or take away their humanity.

(Source: MAL Rewrite)', 'bones', '2009', 'series', 'released', '2009-04-05', 5114, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:29', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/5114-q0V5URebphSG.jpg', 'Action, Adventure, Drama, Fantasy', 'TV', 'SPRING', 64, 714960, 'https://www.youtube.com/watch?v=1ac3_YdSSy0', '2026-07-25 15:12:12', '2026-09-03 15:29:29');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (5, 'JoJo''s Bizarre Adventure', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx666-kYzXvKlUbeMP.jpg', 'series', '7.3', 'Kujo Jotaro is a normal, popular Japanese high-schooler, until he thinks that he is possessed by a spirit, and locks himself in prison. After seeing his grandfather, Joseph Joestar, and fighting Joseph''s friend Muhammad Abdul, Jotaro learns that the "Spirit" is actually Star Platinum, his Stand, or fighting energy given a semi-solid form. Later, his mother gains a Stand, and becomes sick. Jotaro learns that it is because the vampire Dio Brando has been revived 100 years after his defeat to Jonathan Joestar, Jotaro''s great-great-grandfather. Jotaro decides to join Joseph and Abdul in a trip to Egypt to defeat Dio once and for all.', 'APPP', '1993', 'series', 'released', '1993-11-19', 666, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:31', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/666-emK2J3PsdHb2.jpg', 'Action, Adventure, Drama, Horror, Supernatural', 'OVA', 'FALL', 6, 46072, 'https://www.youtube.com/watch?v=EeCX8Y0a278', '2026-07-25 15:12:14', '2026-09-03 15:29:31');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (6, 'HAIKYU!!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20464-ooZUyBe4ptp9.png', 'series', '8.4', 'Inspired after watching a volleyball ace nicknamed "Little Giant" in action, small-statured Shouyou Hinata revives the volleyball club at his middle school. The newly-formed team even makes it to a tournament; however, their first match turns out to be their last when they are brutally squashed by the "King of the Court," Tobio Kageyama. Hinata vows to surpass Kageyama, and so after graduating from middle school, he joins Karasuno High School''s volleyball team—only to find that his sworn rival, Kageyama, is now his teammate.

Thanks to his short height, Hinata struggles to find his role on the team, even with his superior jumping power. Surprisingly, Kageyama has his own problems that only Hinata can help with, and learning to work together appears to be the only way for the team to be successful. Based on Haruichi Furudate''s popular shounen manga of the same name, Haikyuu!! is an exhilarating and emotional sports comedy following two determined athletes as they attempt to patch a heated rivalry in order to make their high school volleyball team the best in Japan.

[Written by MAL Rewrite]', 'Production I.G', '2014', 'series', 'released', '2014-04-06', 20464, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20464-PpYjO9cPN1gs.jpg', 'Comedy, Drama, Sports', 'TV', 'SPRING', 25, 565268, 'https://www.youtube.com/watch?v=9kLRkH9zC5k', '2026-07-25 15:12:00', '2026-09-03 15:29:33');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (7, 'Tomodachi Game', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx141014-bTWr7TtS0wt9.jpg', 'series', '7.6', 'High school student Katagiri Yuuichi, who values friendship above all else, enjoys a fulfilling life with his close friends Sawagiri Shiho, Mikasa Tenji, Shibe Makoto, and Kokorogi Yutori.

However, after a particular incident, they''re dragged into a debt repayment game.

 

The only way to beat the "Tomodachi Game" is to not doubt their friends. Bound together by solid friendships, the game should''ve been easy, but– The hugely popular comic that sold over two million copies is finally becoming an anime! Will they trust or betray their precious friends? The true nature of humanity is exposed in the ultimate psychological game!

(Source: Crunchyroll)

Note: Premiered on Hulu and d Anime Store at 0:00 on Wednesdays, 1 hour 29 minutes ahead of Nippon TV''s broadcast.', 'Okuruto Noboru', '2022', 'series', 'released', '2022-04-06', 141014, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:35', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/141014-ocrpDt7M8EfY.jpg', 'Drama, Mystery, Psychological, Thriller', 'ONA', 'SPRING', 12, 161144, 'https://www.youtube.com/watch?v=eP2FlJtfwL8', '2026-07-25 15:12:16', '2026-09-03 15:29:35');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (8, 'My Hero Academia Season 6', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx139630-3v4gxWtNZxLV.jpg', 'series', '8.2', 'With Tomura Shigaraki at its helm, the former Liberation Army is now known as the Paranormal Liberation Front. This organized criminal group poses an immense threat to the Hero Association, not only because of its sheer size and strength, but also the overpowering quirks of Jin "Twice" Bubaigawara and Gigantomachia.

As new intel from the covert hero Keigo "Hawks" Takami confirms that Shigaraki is nowhere to be seen, the Hero Association decides to strike the enemy headquarters with a surprise attack using the entirety of its assets—and the UA students find themselves on the battlefield once again. As the fight rages on, the unsuspecting villains must regroup and push back, but the brave heroes are determined to eradicate every last one of them.

(Source: MAL Rewrite)', 'bones', '2022', 'series', 'released', '2022-10-01', 139630, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:37', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/139630-XLc90c6CJjZv.jpg', 'Action, Adventure', 'TV', 'FALL', 25, 256959, 'https://www.youtube.com/watch?v=WxCJMYbGtzA', '2026-07-25 15:12:18', '2026-09-03 15:29:37');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (9, 'ONE PIECE', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx21-ELSYx3yMPcKM.jpg', 'series', '8.7', 'Gold Roger was known as the Pirate King, the strongest and most infamous being to have sailed the Grand Line. The capture and death of Roger by the World Government brought a change throughout the world. His last words before his death revealed the location of the greatest treasure in the world, One Piece. It was this revelation that brought about the Grand Age of Pirates, men who dreamed of finding One Piece (which promises an unlimited amount of riches and fame), and quite possibly the most coveted of titles for the person who found it, the title of the Pirate King.

Enter Monkey D. Luffy, a 17-year-old boy that defies your standard definition of a pirate. Rather than the popular persona of a wicked, hardened, toothless pirate who ransacks villages for fun, Luffy’s reason for being a pirate is one of pure wonder; the thought of an exciting adventure and meeting new and intriguing people, along with finding One Piece, are his reasons of becoming a pirate. Following in the footsteps of his childhood hero, Luffy and his crew travel across the Grand Line, experiencing crazy adventures, unveiling dark mysteries and battling strong enemies, all in order to reach One Piece.

*This includes the following special episodes:

- Chopperman to the Rescue! Protect the TV Station by the Shore! (Episode 336)

- The Strongest Tag-Team! Luffy and Toriko''s Hard Struggle! (Episode 492)

- Team Formation! Save Chopper (Episode 542)

- History''s Strongest Collaboration vs. Glutton of the Sea (Episode 590)

- 20th Anniversary! Special Romance Dawn (Episode 907)', 'Toei Animation', '1999', 'series', 'airing', '1999-10-20', 21, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:42:09', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21-wf37VakJmZqs.jpg', 'Action, Adventure, Comedy, Drama, Fantasy', 'TV', 'FALL', NULL, 747203, NULL, '2026-09-03 15:42:09', '2026-09-03 15:29:40');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (10, 'Pokémon', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b527-t6dBVJ5OVcXK.png', 'series', '7.3', 'A young boy named Satoshi embarks on a journey to become a "Pokémon Master" with his first Pokémon, Pikachu. Joining him on his travels are Takeshi, a girl-obsessed Rock Pokemon Trainer, and Kasumi, a tomboyish Water Pokémon Trainer who may have a crush on him. Satoshi and Co. end up traveling through various regions, including Kanto, the Orange Islands, and Johto, and then enter the Pokémon League competitions there. Along the way, they run into many confrontations with Musashi, Kojirou, and Nyarth, a trio of Pokémon thieves who are apart of an evil organization called "Team Rocket". But everytime Team Rocket try to do their evil deeds, they fail thanks to Satoshi and his Pokémon.

(Source: Anime News Network)', 'OLM', '1997', 'series', 'released', '1997-04-01', 527, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:42', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/527-69bO9vmmewWm.jpg', 'Action, Adventure, Comedy, Fantasy', 'TV', 'SPRING', 276, 145075, 'https://www.youtube.com/watch?v=nS0ico6na_U', '2026-07-25 15:12:21', '2026-09-03 15:29:42');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (11, 'SPY x FAMILY', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx140960-Kb6R5nYQfjmP.jpg', 'series', '8.3', 'Everyone has a part of themselves they cannot show to anyone else.

At a time when all nations of the world were involved in a fierce war of information happening behind closed doors, Ostania and Westalis had been in a state of cold war against one another for decades. The Westalis Intelligence Services'' Eastern-Focused Division (WISE) sends their most talented spy, "Twilight," on a top-secret mission to investigate the movements of Donovan Desmond, the chairman of Ostania''s National Unity Party, who is threatening peace efforts between the two nations.

This mission is known as "Operation Strix." It consists of "putting together a family in one week in order to infiltrate social gatherings organized by the elite school that Desmond''s son attends." 

"Twilight" takes on the identity of psychiatrist Loid Forger and starts looking for family members. But Anya, the daughter he adopts, turns out to have the ability to read people''s minds, while his wife, Yor, is an assassin! With it being in each of their own interests to keep these facts hidden, they start living together while concealing their true identities from one another. 

World peace is now in the hands of this brand-new family as they embark on an adventure full of surprises.

(Source: Crunchyroll)', 'CloverWorks', '2022', 'series', 'released', '2022-04-09', 140960, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:44', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/140960-Z7xSvkRxHKfj.jpg', 'Action, Comedy, Slice of Life, Supernatural', 'TV', 'SPRING', 12, 553024, 'https://www.youtube.com/watch?v=_VRxEEBa1XU', '2026-07-25 15:12:23', '2026-09-03 15:29:44');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (12, 'The Seven Deadly Sins: Revival of the Commandments', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99539-caPX28RSsgRP.jpg', 'series', '7.3', 'Melodias, Hawk, and Elizabeth retook the Kingdom of Leones from the Holy Knights. The festival went off without a hitch and the crew enjoyed their well-earned peace. And yet, another threat looms on the horizon. The Ten Commandments, a group of elite demon clan warriors, have their sights set on the kingdom.

(Source: Anime News Network)', 'A-1 Pictures', '2018', 'series', 'released', '2018-01-13', 99539, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:46', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99539-ermF56v2Gz2p.png', 'Action, Adventure, Comedy, Ecchi, Fantasy, Supernatural', 'TV', 'WINTER', 24, 275678, 'https://www.youtube.com/watch?v=ULP_6faadB4', '2026-07-25 15:12:25', '2026-09-03 15:29:46');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (13, 'Dragon Ball Super', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21175-EH06qlfF8TnB.jpg', 'series', '7.3', 'After 18 years, we have the newest Dragon Ball story from creator Akira Toriyama. With Majin Buu defeated, Goku has taken a completely new role as...a radish farmer?! With Earth at peace, our heroes have settled into normal lives. But they can’t get too comfortable. Far away, the powerful God of Destruction, Beerus, awakens to a prophecy revealing his demise at the hands of an even more formidable being. When his search for the Saiyan God brings him to Earth, can Goku and his friends take on their strongest foe yet?

(Source: Crunchyroll)', 'Toei Animation', '2015', 'series', 'released', '2015-07-05', 21175, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:48', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21175-bXEDZ4sk6jTJ.png', 'Action, Adventure, Comedy, Fantasy, Sci-Fi', 'TV', 'SUMMER', 131, 214026, 'https://www.youtube.com/watch?v=ycaU9xEEdi8', '2026-07-25 15:12:27', '2026-09-03 15:29:48');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (14, 'The Promised Neverland', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101759-8UR7r9MNVpz2.jpg', 'series', '8.3', 'Emma, Norman and Ray are the brightest kids at the Grace Field House orphanage. And under the care of the woman they refer to as “Mom,” all the kids have enjoyed a comfortable life. Good food, clean clothes and the perfect environment to learn—what more could an orphan ask for? One day, though, Emma and Norman uncover the dark truth of the outside world they are forbidden from seeing.

(Source: VIZ Media)', 'CloverWorks', '2019', 'series', 'released', '2019-01-10', 101759, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:50', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101759-MhlCoeqnODso.jpg', 'Drama, Fantasy, Horror, Mystery, Psychological, Thriller', 'TV', 'WINTER', 12, 620472, 'https://www.youtube.com/watch?v=ApLudqucq-s', '2026-07-25 15:12:29', '2026-09-03 15:29:50');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (15, 'Hunter x Hunter (2011)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11061-y5gsT1hoHuHw.png', 'series', '8.9', 'A new adaption of the manga of the same name by Togashi Yoshihiro.

A Hunter is one who travels the world doing all sorts of dangerous tasks. From capturing criminals to searching deep within uncharted lands for any lost treasures. Gon is a young boy whose father disappeared long ago, being a Hunter. He believes if he could also follow his father''s path, he could one day reunite with him.

After becoming 12, Gon leaves his home and takes on the task of entering the Hunter exam, notorious for its low success rate and high probability of death to become an official Hunter. He befriends the revenge-driven Kurapika, the doctor-to-be Leorio and the rebellious ex-assassin Killua in the exam, with their friendship prevailing throughout the many trials and threats they come upon taking on the dangerous career of a Hunter.', 'MADHOUSE', '2011', 'series', 'released', '2011-10-02', 11061, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:52', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11061-8WkkTZ6duKpq.jpg', 'Action, Adventure, Fantasy', 'TV', 'FALL', 148, 825593, 'https://www.youtube.com/watch?v=d6kBeJjTGnY', '2026-07-25 15:12:32', '2026-09-03 15:29:52');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (16, 'Attack on Titan', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx16498-buvcRTBx4NSm.jpg', 'series', '8.5', 'Several hundred years ago, humans were nearly exterminated by titans. Titans are typically several stories tall, seem to have no intelligence, devour human beings and, worst of all, seem to do it for the pleasure rather than as a food source. A small percentage of humanity survived by walling themselves in a city protected by extremely high walls, even taller than the biggest of titans.


Flash forward to the present and the city has not seen a titan in over 100 years. Teenage boy Eren and his foster sister Mikasa witness something horrific as the city walls are destroyed by a colossal titan that appears out of thin air. As the smaller titans flood the city, the two kids watch in horror as their mother is eaten alive. Eren vows that he will murder every single titan and take revenge for all of mankind.


(Source: MangaHelpers)', 'WIT STUDIO', '2013', 'series', 'released', '2013-04-07', 16498, 0, 1, '2026-03-08 23:01:33', '2026-09-03 15:29:56', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/16498-8jpFCOcDmneX.jpg', 'Action, Drama, Fantasy, Mystery', 'TV', 'SPRING', 25, 1049900, 'https://www.youtube.com/watch?v=LHtdKWJdif4	', '2026-07-25 15:12:34', '2026-09-03 15:29:54');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (17, 'Attack on Titan Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx20958-HuFJyr54Mmir.jpg', 'series', '8.5', 'Eren Jaeger swore to wipe out every last Titan, but in a battle for his life he wound up becoming the thing he hates most. With his new powers, he fights for humanity''s freedom facing the monsters that threaten his home. After a bittersweet victory against the Female Titan, Eren finds no time to rest—a horde of Titans is approaching Wall Rose and the battle for humanity continues!

(Source: Funimation)', 'WIT STUDIO', '2017', 'series', 'released', '2017-04-01', 20958, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:29:56', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20958-Y7eQdz9VENBD.jpg', 'Action, Drama, Fantasy, Mystery', 'TV', 'SPRING', 12, 731009, 'https://www.youtube.com/watch?v=zLaVP8IhIuc', '2026-07-25 15:12:03', '2026-09-03 15:29:56');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (18, 'Attack on Titan Season 3', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx99147-AiPDD8cwlCfi.jpg', 'series', '8.6', 'Eren and his companions in the 104th are assigned to the newly-formed Levi Squad, whose assignment is to keep Eren and Historia safe given Eren''s newly-discovered power and Historia''s knowledge and pedigree. Levi and Erwin have good reason to be concerned, because the priest of the Church that Hanji had hidden away was found tortured to death, making it clear that the Military Police are involved with the cover-up. Things get more harrowing when the MPs make a move on Erwin and the Levi Squad narrowly avoids capture. Eren is also having problems with his Titan transformation, and a deadly killer has been hired to secure Eren and Historia, one Levi knows all too well from his youth.

(Source: Anime News Network)', 'WIT STUDIO', '2018', 'series', 'released', '2018-07-23', 99147, 0, 1, '2026-03-08 23:01:33', '2026-09-03 15:29:58', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99147-HACsFVrynFf5.jpg', 'Action, Drama, Fantasy, Mystery', 'TV', 'SUMMER', 12, 684133, 'https://www.youtube.com/watch?v=EHzBhrncmac', '2026-07-25 15:12:36', '2026-09-03 15:29:58');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (19, 'Attack on Titan Season 3 Part 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx104578-k61nx3LPjvgd.jpg', 'series', '9.0', 'The battle to retake Wall Maria begins now! With Eren’s new hardening ability, the Scouts are confident they can seal the wall and take back Shiganshina District. If they succeed, Eren can finally unlock the secrets of the basement—and the world. But danger lies in wait as Reiner, Bertholdt, and the Beast Titan have plans of their own. Could this be humanity’s final battle for survival?

(Source: Funimation)', 'WIT STUDIO', '2019', 'series', 'released', '2019-04-29', 104578, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:00', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/104578-z7SadpYEuAsy.jpg', 'Action, Drama, Fantasy, Mystery', 'TV', 'SPRING', 10, 608934, 'https://www.youtube.com/watch?v=fJm2nD3cv_4', '2026-07-25 15:12:39', '2026-09-03 15:30:00');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (20, 'Attack on Titan Final Season', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx110277-sKUNXAsWMNFw.jpg', 'series', '8.7', 'It’s been four years since the Scout Regiment reached the shoreline, and the world looks different now. Things are heating up as the fate of the Scout Regiment—and the people of Paradis—are determined at last. However, Eren is missing. Will he reappear before age-old tensions between Marleyans and Eldians result in the war of all wars?

(Source: Crunchyroll)', 'MAPPA', '2020', 'series', 'released', '2020-12-07', 110277, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:02', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/110277-iuGn6F5bK1U1.jpg', 'Action, Drama, Fantasy, Mystery', 'TV', 'WINTER', 16, 640542, 'https://www.youtube.com/watch?v=MUCN-JwUvbY', '2026-07-25 15:13:19', '2026-09-03 15:30:02');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (21, 'Attack on Titan Final Season Part 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx131681-5ooUqvqNtee1.jpg', 'series', '8.7', 'The war for Paradis zeroes in on Shiganshina just as Jaegerists have seized control. After taking a huge blow from a surprise attack led by Eren, Marley swiftly acts to return the favor. With Zeke’s true plan revealed and a military forced under new rule, this battle might be fought on two fronts. Does Eren intend on fulfilling his half-brother’s wishes or does he have a plan of his own?

(Source: Funimation)', 'MAPPA', '2022', 'series', 'released', '2022-01-10', 131681, 1, 1, '2026-03-08 23:01:33', '2026-09-03 15:30:02', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/131681-3tNurPRsqsfz.jpg', 'Action, Drama, Fantasy, Mystery, Psychological', 'TV', 'WINTER', 12, 438768, 'https://www.youtube.com/watch?v=EIVVnLlhzr0', '2026-07-25 15:12:41', '2026-09-02 17:37:14');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (22, 'Attack on Titan Final Season THE FINAL CHAPTERS Special 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx162314-qIWdAAFtvY8J.jpg', 'series', '8.7', 'Eren, as the Founding Titan, advances on Fort Salta with countless other Titans. Appearing before the refugees, who stand on the brink of despair, are Mikasa, Armin, Jean, Conny, Reiner, Pieck, and Levi, who narrowly escaped from the rumbling. The battle between former comrades and childhood friends with Eren concludes here.

(Source: Crunchyroll)', 'MAPPA', '2023', 'series', 'released', '2023-11-05', 162314, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:07', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/162314-N5M4XMz6O1j4.jpg', 'Action, Drama, Fantasy, Psychological, Romance', 'SPECIAL', 'FALL', 1, 155947, 'https://www.youtube.com/watch?v=sBLsE-NKEoI', '2026-07-25 15:12:43', '2026-09-03 15:30:07');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (23, 'Naruto', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx20-dE6UHbFFg1A5.jpg', 'series', '8.0', 'Naruto Uzumaki, a hyperactive and knuckle-headed ninja, lives in Konohagakure, the Hidden Leaf village. Moments prior to his birth, a huge demon known as the Kyuubi, the Nine-tailed Fox, attacked Konohagakure and wreaked havoc. In order to put an end to the Kyuubi''s rampage, the leader of the village, the 4th Hokage, sacrificed his life and sealed the monstrous beast inside the newborn Naruto. 

Shunned because of the presence of the Kyuubi inside him, Naruto struggles to find his place in the village. He strives to become the Hokage of Konohagakure, and he meets many friends and foes along the way. 

(Source: MAL Rewrite)', 'Studio Pierrot', '2002', 'series', 'released', '2002-10-03', 20, 0, 1, '2026-03-08 23:01:33', '2026-09-03 15:30:12', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20-HHxhPj5JD13a.jpg', 'Action, Adventure, Comedy, Drama, Fantasy, Supernatural', 'TV', 'FALL', 220, 722577, 'https://www.youtube.com/watch?v=-G9BqkgZXRA', '2026-07-25 15:14:05', '2026-09-03 15:30:09');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (24, 'Naruto: Shippuden', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1735-kGfVm0YqCPcu.png', 'series', '8.2', 'Naruto: Shippuuden is the continuation of the original animated TV series Naruto. The story revolves around an older and slightly more matured Uzumaki Naruto and his quest to save his friend Uchiha Sasuke from the grips of the snake-like Shinobi, Orochimaru. After 2 and a half years Naruto finally returns to his village of Konoha, and sets about putting his ambitions to work, though it will not be easy, as he has amassed a few (more dangerous) enemies, in the likes of the shinobi organization; Akatsuki. 

(Source: Anime News Network)', 'Studio Pierrot', '2007', 'series', 'released', '2007-02-15', 1735, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:12', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1735.jpg', 'Action, Adventure, Comedy, Drama, Fantasy, Supernatural', 'TV', 'WINTER', 500, 607722, NULL, '2026-07-25 15:12:45', '2026-09-03 15:30:12');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (25, 'Re:ZERO -Starting Life in Another World-', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx21355-wRVUrGxpvIQQ.jpg', 'series', '8.1', 'In the story, Subaru Natsuki is an ordinary high school student who is lost in an alternate world, where he is rescued by a beautiful, silver-haired girl. He stays near her to return the favor, but the destiny she is burdened with is more than Subaru can imagine. Enemies attack one by one, and both of them are killed. He then finds out he has the power to rewind death, back to the time he first came to this world. But only he remembers what has happened since.

(Source: Anime News Network)

Notes:

- The first episode aired with a runtime of ~50 minutes as opposed to the standard 25 minute long episode.

- In the Winter 2020 season, Re:ZERO was rebroadcast and re-edited to fit into an hour time-slot. This edit included the first OVA and added slight modifications to certain scenes throughout. It also added an additional scene at the end of the final episode.', 'WHITE FOX', '2016', 'series', 'released', '2016-04-04', 21355, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:17', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21355-f9SjOfEJMk5P.jpg', 'Action, Adventure, Drama, Fantasy, Psychological, Romance, Thriller', 'TV', 'SPRING', 25, 618881, 'https://www.youtube.com/watch?v=vFfXjuVA1Jk', '2026-07-25 15:12:48', '2026-09-03 15:30:14');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (26, 'Re:ZERO -Starting Life in Another World- Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx108632-lQWnmw7XaNOK.jpg', 'series', '8.3', 'Even after dying countless times, Subaru finally ended the threat of the White Whale and defeated the Witch Cult''s Sin Archbishop representing sloth, Petelgeuse Romaneeconti. But only shortly after overcoming a tragic ending and reuniting with his beloved Emilia, Subaru learns that Rem has been erased from this world, having fallen victim to the White Whale''s Fog of Elimination in the midst of Subaru''s death loop. With the White Whale now gone, Subaru and Emilia are forced to confront a reality they never dreamed would happen.

(Source: Crunchyroll)', 'WHITE FOX', '2020', 'series', 'released', '2020-07-08', 108632, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:17', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108632-yeLbrgPN4Oni.jpg', 'Action, Adventure, Drama, Fantasy, Psychological, Thriller', 'TV', 'SUMMER', 13, 377918, 'https://www.youtube.com/watch?v=P_YtFPg9tNE', '2026-07-25 15:13:13', '2026-09-03 15:30:17');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (27, 'Re:ZERO -Starting Life in Another World- Season 2 Part 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx119661-GDbUZxrZMz01.png', 'series', '8.4', 'After learning more behind the Death Loop and Witches of Sin, Subaru vows to save Emilia and his friends from further doom.

(Source: Crunchyroll)', 'WHITE FOX', '2021', 'series', 'released', '2021-01-06', 119661, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:19', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/119661-9C7DvtL7yfCu.jpg', 'Action, Adventure, Drama, Fantasy, Psychological, Romance, Thriller', 'TV', 'WINTER', 12, 305922, 'https://www.youtube.com/watch?v=yTjbZQyOesY', '2026-07-25 15:13:15', '2026-09-03 15:30:19');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (28, 'Re:ZERO -Starting Life in Another World- Season 3', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx163134-yieRFbvUOH9a.jpg', 'series', '8.4', 'A year has passed since Subaru’s victory at the Sanctuary. He savors a life of fulfillment while Emilia’s camp stands united for the royal selection—until a fateful letter arrives. Anastasia, a royal selection candidate, has invited Emilia to the Watergate City of Priestella. But as the party begins its journey, crisis stirs beneath the surface and Subaru meets a cruel fate once again.

(Source: Crunchyroll) 

Note: The first episode has an extended runtime of ~90 minutes, and received an early premiere at Anime Expo on July 5, 2024.', 'KADOKAWA', '2024', 'series', 'released', '2024-10-02', 163134, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:21', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/163134-CqaXjXVivwJ5.jpg', 'Action, Adventure, Drama, Fantasy, Psychological, Romance, Thriller', 'TV', 'FALL', 16, 194027, 'https://www.youtube.com/watch?v=qMJNdQFPaHk', '2026-07-25 15:13:17', '2026-09-03 15:30:21');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (29, 'Gintama: THE VERY FINAL', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx114129-RLgSuh6YbeYx.jpg', 'movies', '9.1', 'Gintama: THE FINAL is the 3rd and final film adaptation of the remainder of the Silver Soul arc and is the series finale.

Two years have passed following the Tendoshuu''s invasion of the O-Edo Central Terminal. Since then, the Yorozuya have gone their separate ways. Foreseeing Utsuro''s return, Gintoki Sakata begins surveying Earth''s ley lines for traces of the other man''s Altana. After an encounter with the remnants of the Tendoshuu—who continue to press on in search of immortality—Gintoki returns to Edo.

Later, the regrouped Shinsengumi and Yorozuya begin an attack on the occupied Central Terminal. With the Altana harvested by the wreckage of the Tendoshuu''s ship in danger of detonating, the Yorozuya and their allies fight their enemies while the safety of Edo—and the rest of the world—hangs in the balance. Fulfilling the wishes of their teacher, Shouyou Yoshida''s former students unite and relive their pasts one final time in an attempt to save their futures.', 'Bandai Namco Pictures', '2021', 'movie', 'released', '2021-01-08', 114129, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:23', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/114129-ZsLDkdwaYeJY.jpg', 'Action, Comedy, Drama, Sci-Fi', 'MOVIE', 'WINTER', 1, 52537, 'https://www.youtube.com/watch?v=SvRHM7AONB4', '2026-07-25 15:14:07', '2026-09-03 15:30:23');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (30, 'Violet Evergarden: the Movie', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx103047-odblDHHEdehK.jpg', 'movies', '8.7', 'While writing other people’s emotions, she may have neglected her own. Violet Evergarden, the child soldier turned Auto Memory Doll, writes letters that evoke the words her clients can’t. But when a terminally ill boy requests her services for his family, her own feelings about love and loss resurface. Now she must confront her past and the death of the Major.

(Source: Funimation)', 'Kyoto Animation', '2020', 'movie', 'released', '2020-09-18', 103047, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:24', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/103047-Tjvsh5w1XZP4.jpg', 'Drama, Fantasy, Slice of Life', 'MOVIE', 'SUMMER', 1, 193683, 'https://www.youtube.com/watch?v=BUfSen2rYQs', '2026-07-25 15:15:27', '2026-09-03 15:30:24');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (31, 'A Silent Voice', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20954-sYRfE5jQRtSB.jpg', 'movies', '8.8', 'After transferring into a new school, a deaf girl, Shouko Nishimiya, is bullied by the popular Shouya Ishida. As Shouya continues to bully Shouko, the class turns its back on him. Shouko transfers and Shouya grows up as an outcast. Alone and depressed, the regretful Shouya finds Shouko to make amends.

(Source: Eleven Arts)', 'Kyoto Animation', '2016', 'movie', 'released', '2016-09-17', 20954, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:26', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20954-f30bHMXa5Qoe.jpg', 'Drama, Romance, Slice of Life', 'MOVIE', 'SUMMER', 1, 687637, 'https://www.youtube.com/watch?v=Sy4bPCuzfiQ', '2026-07-25 15:09:40', '2026-09-03 15:30:26');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (32, 'Your Name.', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21519-SUo3ZQuCbYhJ.png', 'movies', '8.6', 'Mitsuha Miyamizu, a high school girl, yearns to live the life of a boy in the bustling city of Tokyo—a dream that stands in stark contrast to her present life in the countryside. Meanwhile in the city, Taki Tachibana lives a busy life as a high school student while juggling his part-time job and hopes for a future in architecture.

One day, Mitsuha awakens in a room that is not her own and suddenly finds herself living the dream life in Tokyo—but in Taki''s body! Elsewhere, Taki finds himself living Mitsuha''s life in the humble countryside. In pursuit of an answer to this strange phenomenon, they begin to search for one another.

Kimi no Na wa. revolves around Mitsuha and Taki''s actions, which begin to have a dramatic impact on each other''s lives, weaving them into a fabric held together by fate and circumstance.

(Source: MAL Rewrite)', 'CoMix Wave', '2016', 'movie', 'released', '2016-08-26', 21519, 0, 3, '2026-03-08 23:01:33', '2026-09-03 15:30:28', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21519-1ayMXgNlmByb.jpg', 'Drama, Romance, Supernatural', 'MOVIE', 'SUMMER', 1, 688954, 'https://www.youtube.com/watch?v=k4xGqY5IDBE', '2026-07-25 15:14:33', '2026-09-03 15:30:28');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (33, 'Kaguya-sama: Love is War -The First Kiss That Never Ends-', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx151384-gv0q8wOE6D58.jpg', 'series', '8.7', 'Shuchiin Academy’s student council room: the place where Student Council Vice President Kaguya Shinomiya and President Miyuki Shirogane met. After a long battle in love, these two geniuses communicated their feelings and, at the Hoshin Festival, had their very first kiss. However, there was no clear confession of love. The relationship between these two, who assumed they would be a couple, remains ambiguous. Now, overly conscious of their feelings, they must face the biggest challenge yet: Christmas. It’s Shirogane who wants it to be perfect versus Kaguya who pursues the imperfect situation. This is the very “normal” love story of two geniuses and the first kiss that never ends.

(Source: Aniplex of America)

Note: The anime first premiered in theaters across Japan on December 17, 2022. It was later split into 2 parts on TV, and 4 episodes on streaming, and Blu-Ray/DVD.', 'A-1 Pictures', '2023', 'series', 'released', '2023-04-01', 151384, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:30', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/151384-JybfIpHr2gx6.jpg', 'Comedy, Psychological, Romance, Slice of Life', 'TV', 'SPRING', 4, 137713, 'https://www.youtube.com/watch?v=W3IvBLpebQ4', '2026-07-25 15:13:22', '2026-09-03 15:30:30');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (34, 'Rascal Does Not Dream of a Dreaming Girl', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx104157-rk99XI56PaIC.jpg', 'movies', '8.4', 'In Fujisawa, where the skies are bright and the seas glisten, Sakuta Azusagawa is in his second year of high school. His blissful days with his girlfriend and upperclassman, Mai Sakurajima, are interrupted with the appearance of his first crush, Shouko Makinohara. For reasons unknown, he encounters two Shouko''s: one in middle school and another who has become an adult.

As Sakuta finds himself helplessly living with the Shouko''s, the adult Shouko leads him around by the nose, causing a huge rift in his relationship with Mai.

In the midst of all of this, he discovers that the middle school Shouko is suffering from a grave illness and his scar begins to throb...

(Source: Aniplex USA)', 'CloverWorks', '2019', 'movie', 'released', '2019-06-15', 104157, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:32', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/104157-PS7tfPpvJKhk.jpg', 'Drama, Psychological, Romance, Supernatural', 'MOVIE', 'SPRING', 1, 251054, 'https://www.youtube.com/watch?v=UbLBbxSm8hs', '2026-07-25 15:14:37', '2026-09-03 15:30:32');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (35, 'I Want to Eat Your Pancreas', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99750-pNyly9d3MEgV.jpg', 'movies', '8.4', 'Spring time in April and the last of the cherry blossoms are still in bloom. The usually aloof bookworm with no interest in others comes across a book in a hospital waiting room. Handwritten on the cover are the words: "Living with Dying." He soon discovers that it is a diary kept by his very popular and genuinely cheerful classmate, Sakura Yamauchi, who reveals to him that she is secretly suffering from a pancreatic illness and only has a limited time left. It is at this moment that she gains just one more person to share her secret.

Trying to maintain a normal life as much as possible, Sakura is determined to live her life to the fullest until the very last day. As her free spirit and unpredictable actions throw him for a loop, his heart begins to gradually change.

(Source: Aniplex USA)', 'Studio VOLN', '2018', 'movie', 'released', '2018-09-01', 99750, 1, 3, '2026-03-08 23:01:33', '2026-09-03 15:30:34', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99750-KPFW2Jv03b2B.jpg', 'Drama, Romance, Slice of Life', 'MOVIE', 'SUMMER', 1, 358684, 'https://www.youtube.com/watch?v=MmoBvmJA9XI', '2026-07-25 15:14:40', '2026-09-03 15:30:34');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (36, 'Made in Abyss: Dawn of the Deep Soul', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx100643-fPH9OgEKKvcI.jpg', 'movies', '8.5', 'Dawn of the Deep Soul continues the epic adventure of plucky Riko and Reg who are joined by their new friend Nanachi. Together they descend into the Abyss’ treacherous fifth layer, the Sea of Corpses, and encounter the mysterious Bondrewd, a legendary White Whistle whose shadow looms over Nanachi’s troubled past. Bondrewd is ingratiatingly hospitable, but the brave adventurers know things are not always as they seem in the enigmatic Abyss...

(Source: Sentai Filmworks)', 'Kinema Citrus', '2020', 'movie', 'released', '2020-01-17', 100643, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:36', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100643-9cSyQS0R5u0o.jpg', 'Action, Adventure, Drama, Fantasy, Horror, Mystery, Psychological, Sci-Fi', 'MOVIE', 'WINTER', 1, 158308, 'https://www.youtube.com/watch?v=NNwD_Hx1GHY', '2026-07-25 15:10:02', '2026-09-03 15:30:36');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (37, 'HAIKYU!! The Dumpster Battle', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx153658-KVnjW77cQw3y.jpg', 'movies', '8.6', 'Theatrical follow-up to Haikyuu!! TO THE TOP 2. The first film of Haikyuu!! FINAL.

The Spring Nationals tournament continues on, with Karasuno High matched against rivals Nekoma High, the fated battle between cats versus crows, also known as the highly anticipated “Dumpster Battle”. This match is the long awaited ultimate showdown between two opposing underdog teams.

(Source: Crunchyroll, edited)', 'Production I.G', '2024', 'movie', 'released', '2024-02-16', 153658, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:38', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/153658-7MePQPgSHrH1.jpg', 'Comedy, Drama, Sports', 'MOVIE', 'WINTER', 1, 89713, 'https://www.youtube.com/watch?v=pl4a2eQUgpc', '2026-07-25 15:14:10', '2026-09-03 15:30:38');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (38, 'Demon Slayer -Kimetsu no Yaiba- The Movie: Mugen Train', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx112151-1qlQwPB1RrJe.png', 'movies', '8.4', 'This Demon Slayer movie sees Tanjiro Kamado and friends from the Demon Slayer corps board the Infinity Train on a new mission to investigate a mysterious series of disappearances, perpetrated by a demon who has been tormenting people and killing the demon slayers who oppose it.', 'ufotable', '2020', 'movie', 'released', '2020-10-16', 112151, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:40', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/112151-eHCBz19nf2yC.jpg', 'Action, Adventure, Drama, Fantasy, Mystery, Supernatural', 'MOVIE', 'FALL', 1, 491764, 'https://www.youtube.com/watch?v=23riEOmDOgM', '2026-07-25 15:14:42', '2026-09-03 15:30:40');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (39, 'Josee, the Tiger and the Fish', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113596-LKA0bYJGjLnB.jpg', 'movies', '8.3', 'The story centers on the relationship between Tsuneo and Josee. Tsuneo is a university student, and Josee is a young girl who has rarely gone out of the house by herself due to her being unable to walk. The two meet when Tsuneo finds Josee''s grandmother taking her out for a morning walk.

(Source: Anime News Network)', 'bones', '2020', 'movie', 'released', '2020-12-25', 113596, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:42', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/113596-8r3fCSFgQHIY.jpg', 'Drama, Romance, Slice of Life', 'MOVIE', 'FALL', 1, 177323, 'https://www.youtube.com/watch?v=QvgpMxoyDds', '2026-07-25 15:10:05', '2026-09-03 15:30:42');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (40, 'JUJUTSU KAISEN 0', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx131573-rpl82vDEDRm6.jpg', 'movies', '8.3', 'Yuta Okkotsu is a nervous high school student who is suffering from a serious problem—his childhood friend Rika has turned into a curse and won''t leave him alone. Since Rika is no ordinary curse, his plight is noticed by Satoru Gojo, a teacher at Jujutsu High, a school where fledgling exorcists learn how to combat curses. Gojo convinces Yuta to enroll, but can he learn enough in time to confront the curse that haunts him?

(Source: VIZ Media)', 'MAPPA', '2021', 'movie', 'released', '2021-12-24', 131573, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:44', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/131573-3veuVz5p0z2I.jpg', 'Action, Supernatural', 'MOVIE', 'FALL', 1, 415046, 'https://www.youtube.com/watch?v=2docezZl574', '2026-07-25 15:14:47', '2026-09-03 15:30:44');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (41, 'Spirited Away', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx199-sWefXJvXkDOb.jpg', 'movies', '8.6', 'On the way to their new home, 10-year-old Chihiro Ogino''s family stumbles upon a deserted theme park. Intrigued, the family investigates the park, though unbeknownst to them, it is secretly inhabited by spirits who sleep by day and appear at night. When Chihiro''s mother and father eat food from a restaurant in the street, angry spirits turn them into pigs. Furthermore, a wide sea has appeared between the spirit world and the human one, trapping Chihiro, the sole human, in a land of spirits. Luckily for her though, a mysterious boy named Haku appears, claiming to know her from the past. Under his instructions, Chihiro secures a job in the bathhouse where Haku works. With only her courage and some new found friends to aid her, Chihiro embarks on a journey to turn her parents back to their original forms and return home.', 'Studio Ghibli', '2001', 'movie', 'released', '2001-07-20', 199, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:46', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/199-Sm2RU5PSqw7T.jpg', 'Adventure, Drama, Fantasy, Supernatural', 'MOVIE', 'SUMMER', 1, 472393, 'https://www.youtube.com/watch?v=ByXuk9QqQkk', '2026-07-25 15:14:49', '2026-09-03 15:30:46');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (42, 'The Disappearance of Haruhi Suzumiya', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx7311-9Mfc1YRHwCCW.jpg', 'movies', '8.6', 'It is mid-December, and SOS Brigade chief Haruhi Suzumiya announces that the Brigade is going to hold a Christmas party in their clubroom, with Japanese hotpot for dinner. The brigade members Kyon, Yuki Nagato, Mikuru Asahina and Itsuki Koizumi start preparing everything for the party, such as costumes and decorations. But a couple of days later, Kyon arrives at school only to find that Haruhi is missing. Not only that, but Mikuru claims she has never known Kyon before, Koizumi is also missing, and Yuki has become the sole member of the literature club. The SOS Brigade seems to have never existed, nor has Haruhi Suzumiya. No one in the school has ever heard about her... except for Kyon.

(Source: Anime News Network)', 'Kyoto Animation', '2010', 'movie', 'released', '2010-02-06', 7311, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:48', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/7311-LkdBCThgXouS.jpg', 'Drama, Mystery, Sci-Fi, Supernatural', 'MOVIE', 'WINTER', 1, 146271, 'https://www.youtube.com/watch?v=eHKyNQopYXo', '2026-07-25 15:10:14', '2026-09-03 15:30:48');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (43, 'Orange: Future', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx97669-7nJlcraO2dwm.jpg', 'movies', '7.3', 'This film retells the main story from the viewpoint of Hiroto Suwa, as he continues to support Kakeru and Naho''s relationship. The film also features an original story which takes place after the events in the manga and anime series.', 'Telecom Animation Film', '2016', 'movie', 'released', '2016-11-18', 97669, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:50', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97669-mdCdz7nOcrt6.jpg', 'Drama, Psychological, Romance, Sci-Fi, Supernatural', 'MOVIE', 'FALL', 1, 39229, 'https://www.youtube.com/watch?v=I5iqGfhVRx8', '2026-07-25 15:14:12', '2026-09-03 15:30:50');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (44, 'Princess Mononoke', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx164-ySuGzCWVw2cL.jpg', 'movies', '8.5', 'A calm village residing in the mountains comes under attack from a demon-possessed boar one day.

Ashitaka, a young man and prince of the tribe, engages the creature in an attempt to save his village. During the battle, the boar bites him on the arm, leaving it blackened and cursed. Following his village''s traditions, Ashitaka is exiled and becomes a wanderer, looking for a solution to the curse before it engulfs him.

Iron Town is a fortress under the leadership of Lady Eboshi. Through the clearing of the surrounding forests, Iron Town produces large amounts of Ironsand, used for gunpowder and other machinery. However, because of the forests destruction, nearby animal clans seek revenge led by a human girl of the Wolf clan called San.

When Ashitaka comes to Iron Town, he discovers the area consumed in battle. Horrified, he attempts to create peace and befriend the Wolf Clan. However, after the forest''s eradication and the ongoing war between Human and Beast, will the Spirit of the Forest be forgiving and accept Ashitaka''s request to expel his curse?

[Written by MAL Rewrite]', 'Studio Ghibli', '1997', 'movie', 'released', '1997-07-12', 164, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:52', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/164-Aj6MINy7VTfs.jpg', 'Action, Adventure, Drama, Fantasy', 'MOVIE', 'SUMMER', 1, 296888, 'https://www.youtube.com/watch?v=4OiMOHRDs14', '2026-07-25 15:14:54', '2026-09-03 15:30:52');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (45, 'Howl‘s Moving Castle', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx431-o8Lj3XkjHm2k.jpg', 'movies', '8.5', 'Sophie, a quiet girl working in a hat shop, finds her life thrown into turmoil when she is literally swept off her feet by a handsome but mysterious wizard named Howl. The vain and vengeful Witch of the Waste, jealous of their friendship, puts a spell on Sophie. In a life-changing adventure, Sophie climbs aboard Howl''s magnificent flying castle and enters a magical world on a quest to break the spell. 


(Source: Disney)', 'Studio Ghibli', '2004', 'movie', 'released', '2004-11-20', 431, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:54', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/431-fLBlvTgdqLCz.jpg', 'Adventure, Drama, Fantasy, Romance', 'MOVIE', 'FALL', 1, 356721, 'https://www.youtube.com/watch?v=iwROgK94zcM', '2026-07-25 15:14:56', '2026-09-03 15:30:54');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (46, 'Perfect Blue', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx437-69NMlXKFeuse.jpg', 'movies', '8.5', 'Rising pop star Mima has quit singing to pursue a career as an actress and model, but her fans aren’t ready to see her go... Encouraged by her managers, Mima takes on a recurring role on a popular TV show, when suddenly her handlers and collaborators begin turning up murdered. Harboring feelings of guilt and haunted by visions of her former self, Mima’s reality and fantasy meld into a frenzied paranoia. As her stalker closes in, in person and online, the threat he poses is more real than even Mima knows, in this iconic psychological thriller that has frequently been hailed as one of the most important animated films of all time.

(Source: Shout! Factory)

Note: The film received an early premiere at the Fantasia Film Festival on August 5, 1997.', 'MADHOUSE', '1998', 'movie', 'released', '1998-02-28', 437, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:56', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/437-3yMVTyN7gl2A.jpg', 'Drama, Horror, Psychological, Thriller', 'MOVIE', 'WINTER', 1, 240206, 'https://www.youtube.com/watch?v=UXQraSkOOGs', '2026-07-25 15:14:59', '2026-09-03 15:30:56');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (47, 'Paprika', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b1943-jMCEYL1Ixmgc.png', 'movies', '7.9', 'Prepare to enter the realm of fantasy and imagination where reality and dreams collide in a kaleidoscopic mindscape of sheer visual genius. The magical tale centers on a revolutionary machine that allows scientists to enter and record a subject''s dream. After being stolen, a fearless detective and brilliant therapist join forces to recover the device before it falls into the hands of a dream terrorist.

(Source: Sony Pictures Home Entertainment)

Note: The film received an early premiere at the 63rd Venice International Film Festival on September 2, 2006.', 'MADHOUSE', '2006', 'movie', 'released', '2006-11-25', 1943, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:58', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1943.jpg', 'Fantasy, Mystery, Psychological, Sci-Fi, Thriller', 'MOVIE', 'FALL', 1, 153070, 'https://www.youtube.com/watch?v=JRwJdwTRfIA', '2026-07-25 15:10:07', '2026-09-03 15:30:58');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (48, 'Millennium Actress', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1033-d5p1pbd5qa4L.png', 'movies', '8.1', 'Millennium Actress blurs the lines between the past and the present, and truth and fiction, when a documentary filmmaker fulfills his quest to find the legendary actress Chiyoko Fujiwara, and learn why she mysteriously vanished at the height of her brilliant career. When Chiyoko grants the filmmaker’s request, he, in turn, presents her with a token – a key she had lost and thought was gone forever. The filmmaker could not have imagined that the key would not only unlock the long-held secrets of Chiyoko’s life, but also his own.

(Source: Dreamworks)

Note: The film received an early premiere at the Fantasia Film Festival on July 28, 2001.', 'MADHOUSE', '2002', 'movie', 'released', '2002-09-14', 1033, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:31:00', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1033-npnaGITec3EV.jpg', 'Drama, Fantasy, Romance', 'MOVIE', 'SUMMER', 1, 63983, 'https://www.youtube.com/watch?v=nRQ7ikz_pPg', '2026-07-25 15:14:14', '2026-09-03 15:31:00');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (49, 'SANDA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx179302-gWWAh5BfQyl4.jpg', 'series', '7.4', 'In a future where children are few and regarded as Japan''s most valuable assets, Christmas has become a mere legend of the past. For the students of Daikoku Welfare Academy—a boarding school where they are educated, protected, and monitored—the mythical Santa Claus is a forgotten character of fiction. For the adults, Santa Claus is a very real menace that needs to be neutralized by the Saint Nick Pursuit Unit in case he makes an appearance.

Shiori Fuyumura, a student of Daikoku Welfare Academy, is determined to find her best friend, Ichie Ono, who has been declared dead after being missing for six months. One morning, Fuyumura summons her fellow class representative, Kazushige Sanda, only to attack the unknowing boy. She is convinced that Sanda is the descendant of the infamous Santa Claus—the only person who can make her wish of finding Ono come true—and is determined to force out his dormant true self by any means necessary.

(Source: MAL Rewrite)', 'Science SARU', '2025', 'series', 'released', '2025-10-04', 179302, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:31:02', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/179302-hX6lxG28Nzuf.jpg', 'Action, Drama, Mystery', 'TV', 'FALL', 12, 47513, 'https://www.youtube.com/watch?v=PG9F1afLT-Y', '2026-07-25 15:13:24', '2026-09-03 15:31:02');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (50, 'The Summer Hikaru Died', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx177689-d0mB5nYgdnhi.jpg', 'series', '8.1', 'Two best friends living in a rural Japanese village: Yoshiki and Hikaru. Growing up together, they were inseparable… until the day Hikaru came back from the mountains, and was no longer himself. “Something” has taken over Hikaru’s body, memories, feelings… and everything they know begins to unravel.

(Source: Netflix)', 'CygamesPictures', '2025', 'series', 'released', '2025-07-06', 177689, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:31:04', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/177689-hbCQDYraujAG.jpg', 'Horror, Mystery, Psychological, Supernatural, Thriller', 'TV', 'SUMMER', 12, 129313, 'https://www.youtube.com/watch?v=sFaO07LwAVg', '2026-07-25 15:13:26', '2026-09-03 15:31:04');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (51, 'TOUGEN ANKI', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx177474-oHil1yLWldfl.jpg', 'series', '6.8', 'The bloodlines of “Oni” and “Momotarou” have been passed down among certain humans for generations.

Long ago, the Oni, aware of their own ferocity, lived in seclusion. However, their peace was shattered by an invasion led by Momotarou.
Over thousands of years, these two factions formed the “Momotarou Agency” and the “Oni Agency,” respectively, and have been locked in conflict ever since.

The protagonist, Shiki Ichinose, suddenly learns of his Oni lineage following an unexpected attack by Momotarou. This revelation sets Shiki on a path to discover the destiny that lies within his blood — a meeting with the Oni dwelling within him.

—A new generation of dark heroics begins here in this tale of demons!

(Source: Official Site)', 'Studio Hibari', '2025', 'series', 'released', '2025-07-11', 177474, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:32:17', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/177474-ZIPsMWa6RO0i.jpg', 'Action, Mystery, Supernatural', 'TV', 'SUMMER', 24, 67891, 'https://www.youtube.com/watch?v=2AddvIbCrr8', '2026-07-25 15:13:28', '2026-09-03 15:32:17');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (52, 'Journal with Witch', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx177385-TBpvkGdF28R7.png', 'series', '8.7', 'Reclusive novelist Makio Koudai has always preferred the company of books—but when her sister and brother-in-law pass away, Makio unexpectedly becomes the guardian of her 15-year-old niece, Asa Takumi. As they navigate grief, clashing personalities, and the challenges of living together, the two slowly open their hearts to each other, discovering warmth, understanding, and the meaning of family.

(Source: Crunchyroll)', 'Shuka', '2026', 'series', 'released', '2026-01-05', 177385, 0, NULL, '2026-03-08 23:01:33', '2026-09-03 15:30:05', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/177385-lzz3yIhQhQdB.jpg', 'Drama, Slice of Life', 'TV', 'WINTER', 13, 46509, 'https://www.youtube.com/watch?v=Cbm6m_WfmqI', '2026-07-25 15:13:35', '2026-09-03 15:30:05');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (53, 'JUJUTSU KAISEN Season 3: The Culling Game Part 1', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx172463-LnXqHzt74SJL.jpg', 'series', '8.6', 'After the Shibuya Incident, a deadly jujutsu battle known as the Culling Game orchestrated by Noritoshi Kamo erupts across ten colonies in Japan.

Haunted by guilt over the mass killings in Shibuya and wary of Sukuna’s interest in Fushiguro, Itadori chooses not to return to Jujutsu High. Instead, he teams up with Choso to exorcise the countless cursed spirits unleashed by Noritoshi Kamo.
Amid this chaos, the Jujutsu Headquarters revokes Yuji Itadori’s suspended death sentence and appoints special-grade sorcerer Yuta Okkotsu as his executioner. 

Newly awakened modern sorcerers and resurrected ancient ones,  now fighting as players in the Culling Game, collide with conflicting motives, driving the world once more toward an age ruled by jujutsu.

(Source: TOHO Animation)', 'Toho', '2026', 'series', 'released', '2026-01-09', 172463, 0, NULL, '2026-03-08 23:01:34', '2026-09-03 16:47:02', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/172463-3J2o3qQZadFJ.jpg', 'Action, Drama, Supernatural', 'TV', 'WINTER', 12, 255979, 'https://www.youtube.com/watch?v=ruX3rIj3--w', '2026-07-25 15:13:37', '2026-09-03 15:32:19');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (54, 'One-Punch Man Season 3', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx153800-8SpzdHOaZCoU.jpg', 'series', '5.0', 'Saitama is a hero who only became a hero for fun. After three years of "special training," he’s become so strong that he''s practically invincible. In fact, he''s too strong—even his mightiest opponents are taken out with a single punch. Alongside Genos, his faithful disciple, Saitama performs his official hero duties as a member of the Hero Association.

One day, monsters claiming to be from the Monster Association suddenly appeared, taking a child of Hero Association executive hostage. The S-class heroes gather and plan a raid on the Monster Association hideout to rescue the hostage. Meanwhile, Garou, a "human monster" who was taken by the Monster Association during a battle with the heroes, awakens in the Monster Association hideout.

(Source: EMOTION Label YouTube Channel Description)

Note: Excludes recap episode that aired a week before regular broadcast.', 'J.C.STAFF', '2025', 'series', 'released', '2025-10-12', 153800, 0, NULL, '2026-03-08 23:01:34', '2026-09-03 15:33:22', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/153800-bgkLxE9SHmUi.jpg', 'Action, Comedy, Sci-Fi, Supernatural', 'TV', 'FALL', 12, 151049, 'https://www.youtube.com/watch?v=_YTSMopxyqY', '2026-07-25 15:13:30', '2026-09-03 15:32:21');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (55, 'KILL BLUE', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx198113-NRa47idWSlnx.jpg', 'series', '7.4', 'Juuzou Oogami is a legendary hitman who has never failed an assignment, no matter how impossible. One day, after wiping out a powerful organization, he is stung by a mysterious wasp and collapses. When he wakes up, the fearsome 39-year-old assassin has been transformed into a 13-year-old boy!

Before he can even process what happened, his boss delivers a new order: “In that body, infiltrate a middle school.”

What awaits him is an unexpected school life filled with colorful classmates, youthful chaos, and looming danger. Can Juuzou ever return to his original form? Or will the assassins closing in on him end his second life before it even begins!?

(Source: Official Site)', 'CUE', '2026', 'series', 'released', '2026-04-11', 198113, 0, NULL, '2026-03-08 23:01:34', '2026-09-03 15:32:23', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/198113-5hYeMXL2zilW.jpg', 'Action, Comedy', 'TV', 'SPRING', 12, 43009, 'https://www.youtube.com/watch?v=9sEiONbweqI', '2026-07-25 15:18:35', '2026-09-03 15:32:23');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (56, 'The Food Diary of Miss Maid', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx197868-sm5jcjPKWhNL.png', 'series', '6.7', 'What’s a maid to do when she finds herself suddenly stuck in Japan for a year? Eat, of course! Follow maid-in-training Suzume Tachibana as she tries all sorts of Japanese food, from sweets like taiyaki and melon bread to savory snacks like takoyaki and onigiri! Be warned, though-while Suzume sates her appetite through delicious treat after delicious treat, she might just end up whetting yours!

(Source: Crunchyroll)

Note: Maid-san wa Taberu dake was streamed a week in advance on dAnimestore, ABEMA, and U-Next starting with episode 2. Episode 1 was streamed on April 1, 2026. Regular broadcasting began on April 5, 2026.', 'EMT Squared', '2026', 'series', 'released', '2026-04-01', 197868, 0, NULL, '2026-03-08 23:01:34', '2026-09-03 15:32:25', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/197868-wBmzwZ3Ay4bD.jpg', 'Slice of Life', 'ONA', 'SPRING', 12, 10524, 'https://www.youtube.com/watch?v=lPLmZANPhrM', '2026-07-25 15:13:52', '2026-09-03 15:32:25');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (57, 'LIAR GAME', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx197754-Q5KqcUhIdypp.png', 'series', '6.2', 'Wishing she would live up to the ideal, Kanzaki Nao''s father named her thusly for “honesty”. Nao has more than lived up to her father''s wishes--even exceeding them and earning the label of "a foolishly honest girl". This makes Nao the least qualified candidate for the high stakes ''Liar Game'', where winning requires deceiving the opponent out of their money and losing means receiving massive debt. However, that doesn''t stop a box containing a hundred million yen in cash and a card informing her of her participation in the game from arriving at her doorstep, nor does it stop her from being promptly tricked out of the entire sum of money. Upon hearing that a genius swindler, responsible for the bankruptcy of a major corporation, is being released from jail, Nao goes to the swindler, Shinichi Akiyama, to enlist his help. With that, the two are drawn into the dark, greed-filled, and deceptive world of the Liar Game.', 'MADHOUSE', '2026', 'series', 'airing', '2026-04-07', 197754, 0, NULL, '2026-03-08 23:01:34', '2026-09-03 15:41:58', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/197754-cMWxeRdhYrFW.jpg', 'Drama, Psychological', 'TV', 'SPRING', 26, 42099, 'https://www.youtube.com/watch?v=FIPOXj00ysQ', '2026-09-03 15:41:58', '2026-09-03 15:32:27');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (58, 'Hell’s Paradise Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx166613-uHB8q3D4qbon.jpg', 'series', '8.2', 'The second season of Jigokuraku.', 'MAPPA', '2026', 'series', 'released', '2026-01-11', 166613, 0, NULL, '2026-03-08 23:01:34', '2026-09-03 15:32:29', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/166613-drS86exJlIjG.jpg', 'Action, Adventure, Mystery, Supernatural', 'TV', 'WINTER', 12, 165713, 'https://www.youtube.com/watch?v=JLe_NUnAZVs', '2026-07-25 15:13:39', '2026-09-03 15:32:29');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (59, 'You and I Are Polar Opposites', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx184951-s8Lg2muPBhdX.jpg', 'series', '8.3', 'Suzuki’s a high school girl in love, but the guy she’s fallen for is nothing like her! While she’s cheerful, outgoing, and always trying to fit in, her classmate Yusuke Tani is stoic, quiet, and doesn’t seem to care what people think of him. Will Suzuki be able to overcome her anxieties and ask him out, or will she discover that opposites really don’t attract?

(Source: Crunchyroll)', 'Lapin Track', '2026', 'series', 'released', '2026-01-11', 184951, 0, NULL, '2026-03-08 23:01:34', '2026-09-03 15:32:31', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/184951-Rx1mZZfKa9IU.jpg', 'Comedy, Romance, Slice of Life', 'TV', 'WINTER', 12, 111406, 'https://www.youtube.com/watch?v=b5vpRUDkhT0', '2026-07-25 15:13:42', '2026-09-03 15:32:31');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (60, 'The Darwin Incident', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx177679-BgsgE0fQk3qN.jpg', 'series', '6.9', 'Created in a biological science lab, Charlie is a half human, half chimpanzee hybrid known as a "Humanzee". Raised by his adoptive human parents, Charlie is now 15 and starting high school. There he meets Lucy, a clever loner who becomes his first-ever friend. But his “normal” life is shattered when the animal rights extremists who freed his mother from the lab fifteen years ago reemerge as terrorists bent on kidnapping Charlie at all costs.

(Source: Kodansha USA)', 'BELLNOX FILMS', '2026', 'series', 'released', '2026-01-07', 177679, 0, NULL, '2026-03-08 23:01:34', '2026-09-03 15:32:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/177679-9prv8e9LblMw.jpg', 'Sci-Fi, Thriller', 'TV', 'WINTER', 13, 23727, 'https://www.youtube.com/watch?v=zRann2zoXx0', '2026-07-25 15:13:44', '2026-09-03 15:32:33');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (61, 'The Holy Grail of Eris', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx183270-CmZikKu34WPd.jpg', 'series', '6.9', 'It is common knowledge that nobles will do anything for power; lying, manipulation, and extortion are the usual tactics. However, one family is exempt from this generalization: House Grail, whose main tenets are truth and integrity. The youngest daughter, Constance Grail, is just as moral as the rest of her family, believing in always doing the right thing and helping those in need.

However, these ideals do not help her when her fiancé cheats on her with another woman. Framed by his lover in the hope of her downfall, Constance has no one to hear her pleas for justice. Everyone turns a blind eye, save for one—the spirit of the infamous Scarlett Castiel—who possesses Constance and turns the tables on her accuser. However, this aid does not come without a price.

Ten years ago, Scarlett was executed for the attempted murder of Princess Cecilia. But this was actually a setup; as blunt and harsh as Scarlett could be, she would never stoop so low as to use poison. She has no idea who orchestrated her incrimination, but Scarlett demands that Constance—as the only one who can see her—help her exact revenge on all those who wronged her!

(Source: MAL Rewrite)', 'Ashi Productions', '2026', 'series', 'released', '2026-01-08', 183270, 0, NULL, '2026-03-08 23:01:34', '2026-09-03 15:32:35', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/183270-LO0vGZ0mCJgW.jpg', 'Drama, Fantasy, Mystery, Romance, Supernatural', 'TV', 'WINTER', 12, 21271, 'https://www.youtube.com/watch?v=Xl9PRzU1MVw', '2026-07-25 15:13:47', '2026-09-03 15:32:35');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (62, 'Dead Account', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx187901-T91HmZAaNwOF.jpg', 'series', '6.5', 'Always ready for a fight! Destruction for destruction’s sake! The online streamer Aoringo is a troll, making the worst of the worst of boundary-pushing flamebait content and raking in the revenue from the hate-watchers. You may think he’s nothing more than a bottom feeder and a drain on society, but in reality, he’s high school dropout Souji Enishiro, a caring older brother with a sweet tooth who loves nothing more than his little sister. His viral videos? Just a way to pay his sister’s medical bills. And even if all of humanity hates him, he doesn’t care, so long as his little sister gets better. But then, something very strange begins to happen...

(Source: Crunchyroll)', 'SynergySP', '2026', 'series', 'released', '2026-01-10', 187901, 0, NULL, '2026-03-08 23:01:34', '2026-09-03 15:32:37', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/187901-03I5T8QVX1FG.jpg', 'Action, Supernatural', 'TV', 'WINTER', 12, 23300, 'https://www.youtube.com/watch?v=ynnk0CIyu10', '2026-07-25 15:13:49', '2026-09-03 15:32:37');
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (63, 'Medalist Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx189275-eHsK0lNnFfXH.jpg', 'series', '8.3', 'Ever since the novice coach Tsukasa Akeuraji took Inori Yuitsuka under his mentorship, she has improved her figure skating at a fast pace. After passing a qualifying badge test, she earns a spot to compete in the upcoming Chubu Block Tournament, where only five of the 15 competitors can move forward to the next stage—the prestigious All-Japan Novice Tournament. However, earning a slot will not be easy for Inori: most of her rivals have already experienced trying their luck in the competition.

The stakes are high as the competition begins, and one by one, each of the competitors strive to perform their very best in front of the big crowd. Moreover, the current figure skating generation''s prodigy, Hikaru Kamisaki, is not competing in this block, which raises everyone''s determination to qualify. That includes Inori, who must beat the odds if she wants to keep her promise to reach Hikaru and represent Japan in the Olympics with Tsukasa.

(Source: MAL Rewrite)', 'ENGI', '2026', 'series', 'released', '2026-01-25', 189275, 0, NULL, '2026-03-08 23:01:34', '2026-09-03 15:33:20', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/189275-WreT2tChg3a0.jpg', 'Drama, Psychological, Sports', 'TV', 'WINTER', 9, 19342, 'https://www.youtube.com/watch?v=GTaqXo7scOY', '2026-07-25 15:13:33', '2026-09-03 15:32:39');
