INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (110, 'Saga of Tanya the Evil Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx135865-T7XIPMAbqcxN.png', 'series', '8.0', 'The second season of Youjo Senki.', 'NUT', '2026', 'series', 'airing', '2026-07-08', 135865, 0, NULL, '2026-05-18 16:05:08', '2026-09-03 15:44:35', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/135865-Ws3e7BhBkFxd.jpg', 'Action, Fantasy', 'TV', 'SUMMER', 12, 90592, 'https://www.youtube.com/watch?v=kUvhvkPDvm0', '2026-09-03 15:44:35', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (111, 'Tokidoki Bosotto Russiago de Dereru Tonari no Alya-san Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx181641-XPV9xFwWjvu9.jpg', 'coming', '0.0', 'The second season of  Tokidoki Bosotto Russiago de Dereru Tonari no Alya-san.', 'Doga Kobo', '2027', 'series', 'upcoming', '2027-01-01', 181641, 0, NULL, '2026-05-18 16:05:08', '2026-09-03 15:49:46', NULL, 'Comedy, Romance, Slice of Life', 'TV', NULL, NULL, 40313, 'https://www.youtube.com/watch?v=xY68LJp3lm8', '2026-09-03 15:49:46', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (112, 'BLEACH: Thousand-Year Blood War - The Calamity', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx185874-aU3e6tBT6wwA.jpg', 'series', '9.0', 'The fourth and final part of BLEACH: Sennen Kessen-hen. 

Destruction looms at the end of the Thousand-Year Blood War between the Soul Reapers and Quincies… as the death of the Soul King mirrors the collapse of the Three Worlds, distortions and omens of destruction start to appear in all realms. 

Fierce battles erupt throughout the Wahr Welt between the Thirteen Court Guard Squads and the Royal Guard. Ichigo learns about Uryuu''s true intentions and renews his determination to protect the world together, as friends who trust each other. Yhwach has surpassed even his own ability, The Almighty...

The fierce battle for the survival of the Three Worlds approaches its end. Beyond the chaos of calamity, what lies in wait—despair or hope?

(Source: VIZ Media, edited)', 'PIERROT FILMS', '2026', 'series', 'airing', '2026-07-25', 185874, 0, NULL, '2026-05-18 16:05:08', '2026-09-03 15:44:38', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/185874-IdGyh1EBG91I.jpg', 'Action, Adventure, Supernatural', 'TV', 'SUMMER', 10, 79871, 'https://www.youtube.com/watch?v=IJONbpfIlUg', '2026-09-03 15:44:38', NULL);
