INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (294, 'BLACK TORCH', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx187538-fXVXKYUA3VV6.jpg', 'series', '7.0', 'Jirou Azuma is no average high schooler. A descendant of ninjas and trained in the ancient warrior art of the shinobi, Jirou is also able to talk with animals. After a mysterious encounter with an injured cat named Ragou, Jirou discovers the feline is actually the legendary Black Star of Doom! Joined by the Bureau of Espionage, they fight off swarms of mononoke lying in wait to exploit Ragou’s powers.

(Source: Crunchyroll)', '100studio', '2026', 'series', 'airing', '2026-07-04', 187538, 0, NULL, '2026-05-21 23:46:57', '2026-09-03 15:44:06', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/187538-287evzCezNl0.jpg', 'Action, Adventure, Fantasy, Sci-Fi, Supernatural', 'TV', 'SUMMER', NULL, 65029, 'https://www.youtube.com/watch?v=2clp09dITKY', '2026-09-03 15:44:06', NULL);
