INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (297, 'The Guy She Was Interested In Wasn''t a Guy At All', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx186822-9zsR5NtOP0yJ.jpg', 'coming', '0.0', 'Fashionable and upbeat high schooler Aya falls head over heels for an employee at a local CD shop. He''s got an air of mystery about him, great style, and an impeccable music taste. Little does she know—this supposedly male employee is actually her female classmate Mitsuki! Mitsuki generally keeps to herself, but since her seat is right next to Aya''s, she can''t help but be extremely aware of the other''s crush. Revealing the truth is out of the question for Mitsuki—but perhaps getting closer to Aya wouldn''t be so bad...

(Source: Yen Press)', 'CloverWorks', '2027', 'series', 'upcoming', '2027-01-01', 186822, 0, NULL, '2026-05-21 23:46:57', '2026-09-03 15:48:18', NULL, 'Music, Romance', 'TV', 'WINTER', NULL, 15791, 'https://www.youtube.com/watch?v=qWJo5abhQ08', '2026-09-03 15:48:18', NULL);
