INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (303, 'An Observation Log of My Fiancée Who Calls Herself a Villainess', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx192808-tfrX4Gn2Y1Ye.jpg', 'series', '7.7', 'Bertia is reincarnated into her favorite otome game—not as the heroine, but as the villainess engaged to the perfect Crown Prince Cecil! Fully aware that her role is to sabotage his future romance, she’s determined to bloom as a wicked flower and wither away according to the story. But no matter how hard she tries to scheme, her “evil” plans only make her more endearing!

(Source: Crunchyroll)

Note: Jishou Akuyaku Reijou na Konyakusha no Kansatsu Kiroku. was streamed 3 days in advance of the TV broadcast on Prime Video, and Crunchyroll beginning April 3, 2026. Regular broadcasting began on April 6, 2026.', 'Ashi Productions', '2026', 'series', 'released', '2026-04-03', 192808, 0, NULL, '2026-05-21 23:49:30', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/192808-iaS1GnOo5l3G.jpg', 'Comedy, Fantasy, Romance, Slice of Life', 'ONA', 'SPRING', 12, 25911, 'https://www.youtube.com/watch?v=r6RkeRy4B4c', '2026-07-25 15:17:35', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (305, 'Rooster Fighter', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx179813-cLHpUPV1IiEm.jpg', 'series', '6.6', 'Humanity is on the verge of collapse after the demonic Kaiju descend without warning, laying waste to cities and crushing all in their path. Resistance fails. Hope fades. Things look bad…until a lone rooster steps forward. Keiji, the neighborhood cock of the walk is more than just an ordinary rooster—he’s humanity’s greatest defender! His opponents may be ten stories tall, but 
with razor-sharp spurs and a battle cry that splits the sky, this unlikely hero carries the fate of the world on his wings. When defenses fall and hope fades, one bird will rise.

(Source: Crunchyroll, VIZ Media, edited)', 'SANZIGEN', '2026', 'series', 'released', '2026-03-14', 179813, 0, NULL, '2026-05-21 23:49:30', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/179813-RZI6o4qilPyH.jpg', 'Action, Adventure, Comedy, Supernatural', 'TV', 'SPRING', 12, 20870, 'https://www.youtube.com/watch?v=5hRrvJ08ZSs', '2026-07-25 15:07:30', NULL);
