INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (445, 'Sword Art Online', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11757-SxYDUzdr9rh2.jpg', 'series', '7.0', 'In the near future, a Virtual Reality Massive Multiplayer Online Role-Playing Game (VRMMORPG) called Sword Art Online has been released where players control their avatars with their bodies using a piece of technology called Nerve Gear. One day, players discover they cannot log out, as the game creator is holding them captive unless they reach the 100th floor of the game''s tower and defeat the final boss. However, if they die in the game, they die in real life. Their struggle for survival starts now...

(Source: Crunchyroll)', 'Aniplex', '2012', 'series', 'released', '2012-07-08', 11757, 0, NULL, '2026-06-21 22:31:03', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11757-TlEEV9weG4Ag.jpg', 'Action, Adventure, Fantasy, Romance', 'TV', 'SUMMER', 25, 706662, 'https://www.youtube.com/watch?v=C8Jl_-b7ju0', '2026-07-25 15:24:07', NULL);
