INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (467, 'Sousou no Frieren: ●● no Mahou', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx170068-ijY3tCP8KoWP.jpg', 'series', '7.3', 'Chibi shorts posted on the official YouTube account of TOHO animation and Twitter account of the main series.

Note: Includes "Tokubetsu-hen:「Shokutaku o Shiawase ni Suru Mahou」/ Mizkan Ajipon Collaboration"', 'TOHO animation STUDIO', '2023', 'series', 'released', '2023-10-11', 170068, 0, NULL, '2026-07-25 16:17:02', '2026-09-03 15:29:27', NULL, 'Comedy, Fantasy', 'ONA', 'FALL', 12, 10822, 'https://www.youtube.com/watch?v=X3Y9esqDspY', '2026-08-02 15:30:49', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (468, 'Sousou no Frieren: ●● no Mahou Part 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx189513-1R9Sryve0K53.png', 'series', '7.1', 'A second batch of the ●● no Mahou shorts released monthly in the lead up to the TV anime''s second season, starting with #12. Posted on the official YouTube account of TOHO animation, Frieren Twitter, and Frieren TikTok account.

Includes:

• Shinchou ga Nobiru Mahou (身長が伸びる魔法), released Apr 2, 2025. 

• Onaka-ippai ni Naru Mahou (おなかいっぱいになる魔法), released May 7, 2025. 

• Daitai Nan demo Kiru Mahou (大体なんでも切る魔法), released Jun 4, 2025. 

