INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (509, 'One Piece: Romance Dawn Story', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/5252.jpg', 'series', '7.0', 'The Straw Hat Pirates, searching for the great passage "Grand Line", are in trouble when their food runs out! Luffy, searching for food on his own, finds a ship belonging to the pirate, Gary, and takes it over!! He lands at a nearby town...

Luffy was attacked by a young girl, Silk, who mistook him for a member of the other pirate gang. As the two eat a meal, they tell their stories. Meanwhile, Gary and his band are burning with anger at Luffy, demanding payment from the town''s defenseless citizens...!!

(Source: Jumpland)', 'Toei Animation', '2008', 'series', 'released', '2008-11-24', 5252, 0, NULL, '2026-07-25 16:17:14', '2026-09-03 15:29:40', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/5252-tlTORLa2dR2u.jpg', 'Action, Comedy, Fantasy', 'OVA', 'FALL', 1, 14529, NULL, '2026-08-02 15:33:06', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (510, 'The Great Tongari Island Treasure Hunting Adventure', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b126649-sbuKTAghtsln.jpg', 'movies', '6.0', 'A Tokyo One Piece Tower exclusive film. It''s a tie-in to a real treasure hunting event in collaboration with Takarush Corp. for a limited time called Treasure Hunting: Tongari Shima no Daibouken. During this, you’ll decipher the mysteries of ancient documents found by Luffy, Usopp, and Chopper, and then set out to find the nest of the mysterious animal known as Tongari Ton!

The film itself begins at the end of your treasure hunting adventure at the Tokyo One Piece Tower, where the Straw Hat Crew are tricked into opening a chest in a cave thinking it''s where the Tongari Island treasure is.

(Source: Otakumode)', 'Toei Animation', '2016', 'movie', 'released', '2016-11-01', 126649, 0, NULL, '2026-07-25 16:17:14', '2026-09-03 15:29:40', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/126649-pxeImm81vD6l.jpg', 'Action, Adventure, Comedy', 'MOVIE', 'FALL', 1, 2181, NULL, '2026-08-02 15:33:03', NULL);
