INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (514, 'ONE PIECE FAN LETTER', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx182469-JQ808NBPxmgn.jpg', 'series', '9.0', 'To commemorate the 25th anniversary of the ONE PIECE TV anime: an animated adaptation of the "ONE PIECE novel: Mugiwara Stories". 

Two years after the Paramount War, the Straw Hats are about to reunite on the Sabaody Archipelago. At the same time, a girl who is head over heels for Nami is trying to hand a fan letter to her before the group leaves the island.

(Source: Crunchyroll)', 'Toei Animation', '2024', 'series', 'released', '2024-10-20', 182469, 0, NULL, '2026-07-25 16:17:14', '2026-09-03 15:29:40', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/182469-obNr7bznMzN7.jpg', 'Action, Adventure, Fantasy', 'SPECIAL', 'FALL', 1, 57751, 'https://www.youtube.com/watch?v=MewJ5bEM-5U', '2026-08-02 15:30:13', NULL);
