(Source: One Piece Wiki)', NULL, '2025', 'series', 'released', '2025-04-01', 188668, 0, NULL, '2026-07-25 16:17:14', '2026-09-03 15:29:40', NULL, 'Comedy, Romance', 'ONA', 'SPRING', 5, 4758, NULL, '2026-08-02 15:32:37', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (516, 'ONE PIECE HEROINES', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx197178-Ui8PY9HQbNgu.jpg', 'series', '7.8', 'Based on the novel series ONE PIECE novel HEROINES, one chapter, “episode : NAMI” is getting an anime adaptation. 

After buying a pair of shoes that end up hurting her feet, Nami returns to the shop feeling dissatisfied.
There, she meets Lebno, the designer, who tells her, “I’ll make you a brand-new pair from scratch—but only if you’ll be my model.”
The shoes are crafted by the artisan Miucha, leading to an unexpected and stylish encounter.

(Source: Toei Animation)', 'Toei Animation', '2026', 'series', 'released', '2026-07-05', 197178, 0, NULL, '2026-07-25 16:17:14', '2026-09-03 15:29:40', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/197178-kVx0Zt3P0MvD.jpg', 'Action, Adventure, Drama, Fantasy', 'SPECIAL', 'SUMMER', 1, 15390, 'https://www.youtube.com/watch?v=audhiM3Ur1I', '2026-08-02 15:32:33', NULL);
