INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (519, 'Pokémon the Series: Ruby and Sapphire', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1564-1KniCPyGiu0W.png', 'series', '6.9', 'After participating in the Johto League, Ash decides to begin anew in yet another journey; this time by himself and Pikachu, in the land of Hoenn. Though he isn''t alone for long, as 10-year-old May (who dislikes Pokemon, but just wants to come along to see the world) travels with him after Pikachu destroys her bicycle. Ash also meets up with his old companion, Brock, and May''s younger brother, Max. Together, they travel along in Hoenn, battling Gym Leaders, entering Contests, and other events on the way to the Hoenn League. 

(Source: Anime News Network)', 'TV Tokyo', '2002', 'series', 'released', '2002-11-21', 1564, 0, NULL, '2026-07-25 16:17:16', '2026-09-03 15:29:42', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1564-aEGOcnOGHHCI.png', 'Action, Adventure, Comedy, Fantasy', 'TV', 'FALL', 192, 49177, NULL, '2026-08-02 15:34:08', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (520, 'Pokémon the Movie 2000', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/1117.jpg', 'movies', '7.1', 'A greedy collector, Lawrence III, wants to capture the legendary Pokémon, Lugia. But in order to do so, he must capture the Titans of Fire, Ice, and Lightning. The titans are powerful bird-like Pokémon, and if they are disturbed they will wage a war against eachother which will ultimately result in earth''s destruction. Ash, Misty, and Tracey get caught up in the situation when they end up being washed ashore onto Shamouti Island. Soon after, Ash meets a girl named Melody who sends him into a mission where he must collect the 3 Orbs which will quell the fighting, but first Ash must gain help from the Beast of the Sea, Lugia, if he''s to succeed.

(Source: Anime News Network)', 'OLM', '1999', 'movie', 'released', '1999-07-17', 1117, 0, NULL, '2026-07-25 16:17:16', '2026-09-03 15:29:42', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1117-Dn4JVWi5fxpV.jpg', 'Action, Adventure, Drama, Fantasy', 'MOVIE', 'SUMMER', 1, 45851, 'https://www.youtube.com/watch?v=HJx0HNj_KMk', '2026-08-02 15:34:12', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (521, 'Pokémon 3: The Movie', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx1118-90hGoWgDV1k4.jpg', 'movies', '6.8', 'Young Molly Hale is a 5-year old girl who has lost her father to the Unown, a strange group of Pokémon who can make a person''s dreams real by using their Psychic energy. One day she accidently releases the Unown, and they begin to answer Molly''s wishes; first by creating Entei, a legendary lion-like Pokémon who Molly then thinks is her father because he always pretended to be Entei when he played with her. Molly then feels lonely because she has no mother, so Entei decides to kidnap Ash''s mother and forces her to become Molly''s. Ash, Brock, and Misty must then try to save Ash''s mom, Delia, and Molly; And in the process they must also try to find a way to stop the Unown from turning the town of Greenfield into a bizarre crystal wasteland. 

(Source: Anime News Network)', 'OLM', '2000', 'movie', 'released', '2000-07-08', 1118, 0, NULL, '2026-07-25 16:17:16', '2026-09-03 15:29:42', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n1118-QLIw2ueWalMZ.jpg', 'Action, Adventure, Drama, Fantasy', 'MOVIE', 'SUMMER', 1, 42810, 'https://www.youtube.com/watch?v=SEqstQn0sag', '2026-08-02 15:34:22', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (522, 'Pokémon 4Ever', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx1119-Vz0ohBLmZ5uP.jpg', 'movies', '6.7', '40 years ago, a Celebi was being attacked by a Pokémon Hunter. Luckily, a young boy named Sammy saved Celebi. Using its Time Traveling power, Celebi transported himself and Sammy 40 years into the future. There, Ash, Misty, and Brock assist Sammy to the healing lake in the forest so they can heal the wounded Celebi. Unfortunately an evil Team Rocket member, Viscious a.k.a. "The Iron Masked Marauder", tries to capture Celebi using his technology. As Ash and Co. try to get away from Viscious, they also run into Jessie, James, and Meowth, who also want to capture Celebi. Soon it becomes a race against time to get Celebi and Sammy back to the forest before Celebi is caught and is used to destroy the forest and themselves. 

(Source: Anime News Network)', 'OLM', '2001', 'movie', 'released', '2001-07-07', 1119, 0, NULL, '2026-07-25 16:17:16', '2026-09-03 15:29:42', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1119-kNBrsAGJXMXW.jpg', 'Action, Adventure, Comedy, Drama, Fantasy', 'MOVIE', 'SUMMER', 1, 39229, 'https://www.youtube.com/watch?v=9lES7wavO5E', '2026-08-02 15:34:03', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (523, 'Pokémon Heroes', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1120-dSMPMrXYWlER.jpg', 'movies', '7.0', 'Long ago, on an island called Altomare, there lived an old man and woman. One day, the couple found two small children lying on the shore, badly wounded. The couple took them in and took care of them, and the children quickly recovered. But then, the island was attacked by monsters. Within moments the island fell into the monsters'' wrath. But then...Before the old man and lady''s eyes, the children who they had taken care of transformed into the Eon Pokemon, Latios and Latias. They called their family from the sky. They came, and carried a stone with them containing the power to force the monsters away. This gem was known as the "Soul Dew". Peace returned to the island. However, later in the present, a criminal duo - Zann&acirc; and Rion - are seeking Latios and Latias in order to take control of the Soul Dew. Taking a short break in Altomare, Satoshi befriends Latias and is now dragged into the situation helping to save Altomare from becoming swallowed up by destruction again. 

(Source: Anime News Network)', 'OLM', '2002', 'movie', 'released', '2002-07-13', 1120, 0, NULL, '2026-07-25 16:17:16', '2026-09-03 15:29:42', NULL, 'Action, Adventure, Comedy, Drama, Fantasy', 'MOVIE', 'SUMMER', 1, 33185, NULL, '2026-08-02 15:33:51', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (524, 'Pokémon: Pikachu''s Winter Vacation', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/4874.jpg', 'series', '6.1', 'Pikachu''s Winter Vacations are three series of videos, each composed of several Pikachu shorts. All shorts deal with winter and Christmas. This is the first series and contains Christmas Night & Kanga Games.', 'OLM', '1998', 'series', 'released', '1998-12-22', 4874, 0, NULL, '2026-07-25 16:17:16', '2026-09-03 15:29:42', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4874-XwyIy49ugffW.jpg', 'Adventure, Comedy, Fantasy', 'OVA', 'WINTER', 2, 4282, NULL, '2026-08-02 15:33:55', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (525, 'Pokémon: Pikachu''s Winter Vacation 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx10916-Q0dYdu9lqllD.jpg', 'series', '6.1', 'Pikachu''s Winter Vacations are three series of videos, each composed of several Pikachu shorts. All shorts deal with winter and Christmas. This is the second series and contains Winter Games & Stantler''s Little Helpers.', 'OLM', '1999', 'series', 'released', '1999-12-22', 10916, 0, NULL, '2026-07-25 16:17:16', '2026-09-03 15:29:42', NULL, 'Adventure, Comedy, Fantasy', 'OVA', 'FALL', 2, 3481, NULL, '2026-08-02 15:33:59', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (526, 'Pokémon: Pikachu''s Winter Vacation (2001)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx10917-2RIr9c3BbivO.jpg', 'series', '6.1', 'Pikachu''s Winter Vacations are three series of videos, each composed of several Pikachu shorts. All shorts deal with winter and Christmas. This is the third and last series and contains Delibird''s Dilemma, Snorlax Snowman & Trouble in Big Town.', 'OLM', '2000', 'series', 'released', '2000-12-22', 10917, 0, NULL, '2026-07-25 16:17:17', '2026-09-03 15:29:42', NULL, 'Adventure, Comedy, Fantasy', 'OVA', 'FALL', 3, 3404, NULL, '2026-08-02 15:34:49', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (527, 'Pokémon Origins', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx20159-Q4VpDs7q2j3O.png', 'series', '7.5', 'One day, Red, a boy filled with dreams of going on a Pokémon journey, is called to Professor Okido''s lab. There, he and his rival Green are given a Pokédex in order to collect data on all of the Pokémon in the region. As Red works his way to become champion with his Charmander, he meets many people on his journey, including Old Man Fuji, a man who runs the home for abandoned Pokémon, and Reina, a girl who works there. As danger in Red''s journey begins to peak, he and his partner Pokémon experience a transformation like never before...

(Source: Anime News Network)', 'Production I.G', '2013', 'series', 'released', '2013-10-02', 20159, 0, NULL, '2026-07-25 16:17:17', '2026-09-03 15:29:42', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20159-hlRzN7QIuZhT.jpg', 'Action, Adventure, Fantasy', 'SPECIAL', 'FALL', 4, 54035, 'https://www.youtube.com/watch?v=cgc81i06qwY', '2026-08-02 15:34:53', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (528, 'Pokémon Generations', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/97635-I7aIU84ABBs8.jpg', 'series', '7.3', 'Pokémon Generations looks back at each generation of the Pokémon video game series, diving into the stories of the games more deeply and getting to know characters and Pokémon better. Visit each region, from Kanto to Kalos, to relive the world of Pokémon like never before!', 'The Pokemon Company International', '2016', 'series', 'released', '2016-09-16', 97635, 0, NULL, '2026-07-25 16:17:17', '2026-09-03 15:29:42', NULL, 'Action, Comedy, Fantasy', 'ONA', 'FALL', 18, 20962, 'https://www.youtube.com/watch?v=wMzwcIG8vgk', '2026-08-02 15:34:56', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (529, 'Pokémon the Movie: I Choose You!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx98298-Yqus4jNiTNgf.png', 'movies', '7.0', 'The film''s plot tells the story of how Satoshi (Ash) and Pikachu came to know each other. On the day they set out from Masara Town (Pallet Town), both of them saw a Ho-oh flying and made a vow to someday meet it.

(Source: Anime News Network, edited)', 'OLM', '2017', 'movie', 'released', '2017-07-15', 98298, 0, NULL, '2026-07-25 16:17:17', '2026-09-03 15:29:42', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/98298-GLiqMFmxovDh.jpg', 'Action, Adventure, Fantasy', 'MOVIE', 'SUMMER', 1, 20534, 'https://www.youtube.com/watch?v=5NHzI6_D4Tg', '2026-08-02 15:35:00', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (530, 'Pokémon Masters Animated Trailer', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx112152-lmjRiK6jzPrK.png', 'series', '5.9', 'An original special animated trailer made to promote the release of the game Pokémon Masters.

(Source: Bulbapedia)', 'OLM', '2019', 'series', 'released', '2019-06-27', 112152, 0, NULL, '2026-07-25 16:17:17', '2026-09-03 15:29:42', NULL, 'Action, Adventure, Fantasy', 'SPECIAL', NULL, 1, 1111, 'https://www.youtube.com/watch?v=e4w2rQq0yHU', '2026-08-02 15:34:25', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (531, 'Pokémon: Mewtwo Strikes Back—Evolution', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx106287-THH8DMCFuVNc.png', 'movies', '6.1', 'When researchers discover and exploit a fossil of the Mythical Pokémon Mew, they unleash a
creation that goes against the very laws of nature. 

The Legendary Pokémon Mewtwo was intended for use as a tool of destruction. But as Mewtwo
becomes aware of its own dubious origin, it begins to resent its human creators and seeks revenge…

(Source: Netflix)', 'OLM', '2019', 'movie', 'released', '2019-07-12', 106287, 0, NULL, '2026-07-25 16:17:17', '2026-09-03 15:29:42', NULL, 'Action, Adventure, Comedy, Drama, Fantasy, Sci-Fi', 'MOVIE', 'SUMMER', 1, 10342, 'https://www.youtube.com/watch?v=wTBieAEGrf8', '2026-08-02 15:34:30', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (532, 'Pokémon: Mewtwo Returns', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1709-vQoFgnySwLOq.jpg', 'series', '6.8', 'The Team Rocket leader, Giovanni, has found Mewtwo in a remote area of the Johto region. As Giovanni tries to re-capture Mewtwo, Ash and his friends are kidnapped by Domino, a new Team Rocket member, while trying to rescue Pikachu from Jessie and James. The Clone Pokemon are also captured and are then used as bait for Mewtwo. The situation then becomes a battle between the wills of Mewtwo and Giovanni; and Mewtwo also tries to discover if it and the clones have a purpose in life, even though they are products of science.

(Source: Anime News Network)', 'OLM', '2000', 'series', 'released', '2000-12-30', 1709, 0, NULL, '2026-07-25 16:17:17', '2026-09-03 15:29:42', NULL, 'Action, Adventure, Comedy, Drama, Fantasy, Sci-Fi', 'SPECIAL', 'WINTER', 1, 21156, NULL, '2026-08-02 15:34:45', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (533, 'Pokémon: The Legend of Thunder!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1525-5KqKphuWOmt6.jpg', 'series', '6.6', 'Kenta, a Pokemon master in the making, meets up with his childhood friend, Marina, at a Pokemon Center, to see how their skills have developed. Their battle is interrupted by a thunderstorm and the arrival of Bashou and Buson, two Roketto-Dan members using the Crystal System (which attracts Electric-type Pokemon). Their ultimate goal is to, under the guidance of Shiranui-hakase, bring Pokemon back to Sakaki. Kenta and Marina stumble upon this plan, and they try to stop it, but things get more difficult when the legendary Pokemon Raikou is captured.

(Source: Anime News Network)', 'OLM', '2001', 'series', 'released', '2001-12-30', 1525, 0, NULL, '2026-07-25 16:17:17', '2026-09-03 15:29:42', NULL, 'Action, Adventure, Comedy, Fantasy', 'SPECIAL', 'FALL', 1, 7221, NULL, '2026-08-02 15:34:34', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (534, 'Pokémon Evolutions', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx138699-V0PBmiG6hnuf.jpg', 'series', '7.3', 'An animated series created to celebrate 25 years of the global entertainment franchise. Each episode will take fans on a journey through all the known regions of the Pokémon world.', 'OLM', '2021', 'series', 'released', '2021-09-09', 138699, 0, NULL, '2026-07-25 16:17:17', '2026-09-03 15:29:42', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/138699-VT4ZvtTKyNcd.jpg', 'Action, Fantasy', 'ONA', 'FALL', 8, 11558, 'https://www.youtube.com/watch?v=NzxHrd53F0k', '2026-08-02 15:34:42', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (535, 'Toho Cinemas x Pokémon GO', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b110639-h2euvTBctoym.jpg', 'movies', '5.0', 'Collaboration shorts between Pokemon Go and Toho Cinemas, featuring Pikachu, shown in Toho theaters before films.', NULL, '2017', 'movie', 'released', '2017-03-03', 110639, 0, NULL, '2026-07-25 16:17:17', '2026-09-03 15:29:42', NULL, 'Comedy', 'MOVIE', NULL, 2, 859, NULL, '2026-08-02 15:34:37', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (536, 'SPY x FAMILY Cour 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx142838-26JrqcFU1ljB.jpg', 'series', '8.1', 'The second half of SPYxFAMILY.

With Anya Forger successfully enrolled at the renowned Eden Academy, Operation Strix advances to its second phase. To investigate Ostanian politician Donovan Desmond, Anya must either befriend his son Damian or collect eight Stella Stars to become an Imperial Scholar. Fortunately, Anya has already acquired her first star. In celebration, her adoptive father, Loid, decides to fulfill her wish to adopt a dog.

During their canine search, Loid receives new orders from his superiors, who have found that a band of Berlint University students is plotting to assassinate Westalis'' Minister Brantz using bombs worn by trained dogs. While Loid tries to stop their plans, Anya stumbles upon the terrorists'' base of operations. There, she befriends a kindhearted, clairvoyant dog who the family later names Bond.

Although the Forgers continue to lead their individual lives in secrecy, the family—with a new fluffy addition—remains united through all of the unusual obstacles thrown their way.

(Source: MAL Rewrite)', 'WIT STUDIO', '2022', 'series', 'released', '2022-10-01', 142838, 0, NULL, '2026-07-25 16:17:19', '2026-09-03 15:29:44', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/142838-tynuN00wxmKO.jpg', 'Action, Comedy, Slice of Life, Supernatural', 'TV', 'FALL', 13, 327931, 'https://www.youtube.com/watch?v=Dv3ZhzxtbQY', '2026-08-02 15:35:03', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (537, 'Nanatsu no Taizai: Eiyuu-tachi wa Hashagu', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx104175-vk7J6X23Z25l.png', 'series', '6.9', 'OVA bundled with the 34th volume of the manga.

It contains the following stories:

1. A Fight!! The Captain Knight of Food Scraps

2. Naked Heart

3. Harlequin and Helbram

4. The Sins Vacation', 'A-1 Pictures', '2018', 'series', 'released', '2018-11-14', 104175, 0, NULL, '2026-07-25 16:17:20', '2026-09-03 15:29:46', NULL, 'Action, Adventure, Fantasy', 'OVA', 'FALL', 1, 24647, NULL, '2026-08-02 15:35:07', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (538, 'Dragon Ball Z Kai: The Final Chapters', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx20635-gUYy4KZfYRb0.jpg', 'series', '7.6', 'Remastered version of the Majin Boo arc that adheres more to the manga''s story.', 'Toei Animation', '2014', 'series', 'released', '2014-04-06', 20635, 0, NULL, '2026-07-25 16:17:22', '2026-09-03 15:29:48', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20635-2eB3QP44dM1M.jpg', 'Action, Adventure, Comedy', 'TV', 'SPRING', 69, 54222, 'https://www.youtube.com/watch?v=JXVcOKppJZE', '2026-08-02 15:35:33', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (539, 'Dragon Ball Z', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx813-ZhnFNOeCU5dQ.png', 'series', '8.0', 'Goku is back with his new son, Gohan, but just when things are getting settled down, the adventures continue. Whether he is facing enemies such as Freeza, Cell, or Boo, Goku is proven to be an elite of his own and discovers his race, Saiyan. He meets many new people, gaining allies as well as enemies, as he still finds time to raise a family and be the happy-go-lucky Saiyan he is.

(Source: Anime News Network)', 'Toei Animation', '1989', 'series', 'released', '1989-04-26', 813, 0, NULL, '2026-07-25 16:17:22', '2026-09-03 15:29:48', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/813-03ZLvWJgR6Wd.jpg', 'Action, Adventure, Comedy, Fantasy, Supernatural', 'TV', 'SPRING', 291, 258146, NULL, '2026-08-02 15:35:30', NULL);
