INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (544, 'Dragon Ball DAIMA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx170083-GTwRrhTApcLR.png', 'series', '7.5', 'Goku and company were living peaceful lives when they suddenly turned small due to a conspiracy! When they discover that the reason for this may lie in a world known as the "Demon Realm", a mysterious young Majin named Glorio appears before them.

(Source: Crunchyroll)', 'Toei Animation', '2024', 'series', 'released', '2024-10-11', 170083, 0, NULL, '2026-07-25 16:17:22', '2026-09-03 15:29:48', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/170083-SYCCWWlq3hqF.jpg', 'Action, Adventure', 'TV', 'FALL', 20, 59970, 'https://www.youtube.com/watch?v=ezbYAglQoxI', '2026-08-02 15:35:10', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (545, 'The Promised Neverland Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx108725-ZKivuyr4Jtc9.jpg', 'series', '5.2', 'The second season of Yakusoku no Neverland.

Fifteen children escape Grace Field House, a false paradise, hoping for a chance at freedom. Instead, they encounter plants and animals they have never before seen, and are chased by demons. The outside world is so beautiful, and yet is almost too cruel to face.

Even so, the children refuse to give up. They are guided in their search for better lives only by a message from Minerva and a pen Norman left behind in order to fulfill their promise to return to the House to save those of their family who are still trapped within.</br>

(Source: Aniplex of America)

Note: Episode 1 streamed early on Amazon Prime on Jan 7, 2021. The regular TV broadcast started on Jan 8, 2021.', 'CloverWorks', '2021', 'series', 'released', '2021-01-08', 108725, 0, NULL, '2026-07-25 16:17:24', '2026-09-03 15:29:50', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108725-lg940Urvxzfu.jpg', 'Action, Adventure, Drama, Fantasy, Horror, Psychological, Thriller', 'TV', 'WINTER', 11, 321046, 'https://www.youtube.com/watch?v=DXNXOsZqc28', '2026-08-02 15:35:37', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (546, 'Hunter x Hunter', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx136-gj0bbCpDNrKG.jpg', 'series', '8.3', 'A Hunter is one who travels the world doing all sorts of dangerous tasks. From capturing criminals to searching deep within uncharted lands for any lost treasures. Gon is a young boy whose father disappeared long ago, being a Hunter. He believes if he could also follow his father''s path, he could one day reunite with him.

After becoming 12, Gon leaves his home and takes on the task of entering the Hunter exam, notorious for its low success rate and high probability of death to become an official Hunter. He befriends the revenge-driven Kurapika, the doctor-to-be Leorio and the rebellious ex-assassin Killua in the exam, with their friendship prevailing throughout the many trials and threats they come upon taking on the dangerous career of a Hunter. Based on the manga by Togashi Yoshihiro.', 'Nippon Animation', '1999', 'series', 'released', '1999-10-16', 136, 0, NULL, '2026-07-25 16:17:26', '2026-09-03 15:29:52', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/136-uHALFo2vGOGd.jpg', 'Action, Adventure, Fantasy', 'TV', 'FALL', 62, 134064, NULL, '2026-08-02 15:35:53', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (547, 'Hunter x Hunter: Yorknew City', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx137-u17pWQRTZfKn.jpg', 'series', '8.2', 'After reuniting with Gon and his friends, Kurapika explained to them the risks he bears because of his abilities. Believing that his target of revenge is no longer alive and the search for his fallen comrade''s eyes could truly begin, Kurapika soon after receives a message informing him that all the Spiders still lived. After much discussion between his friends, Gon, Kurapika and company decided to hunt after the one Spider member who''s ability could ultimately result in Kurapika''s defeat and death. Based on the manga by Togashi Yoshihiro.', 'Nippon Animation', '2002', 'series', 'released', '2002-01-17', 137, 0, NULL, '2026-07-25 16:17:26', '2026-09-03 15:29:52', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/137-vQTvNvv37Cyl.jpg', 'Action, Adventure, Fantasy', 'OVA', 'WINTER', 8, 30437, NULL, '2026-08-02 15:35:56', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (548, 'HUNTER×HUNTER: Greed Island', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx138-BY6R1y8zuf7s.png', 'series', '7.9', 'After the battle with the Spiders, the search for Ging continues as Gon and Killua decided to once again attempt to purchase the rare game "Greed Island". However, Gon came up with a better plan, which was to volunteer to complete the game for the billionaire who owned it. But some training must be done, as Gon and Killua''s abilities are still at a developing stage and "Greed Island" is no simple game for anyone to play with. It is the infamous game that could easily lead to one''s death. Based on the manga by Togashi Yoshihiro.', 'Nippon Animation', '2003', 'series', 'released', '2003-02-05', 138, 0, NULL, '2026-07-25 16:17:26', '2026-09-03 15:29:52', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/138-RQXeNBg62Nue.jpg', 'Action, Adventure, Fantasy', 'OVA', 'WINTER', 8, 33914, NULL, '2026-08-02 15:35:41', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (549, 'HUNTER×HUNTER: Greed Island Final', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx139-qiFhjx4o1sKI.png', 'series', '7.9', 'Continuing with their adventure at Greed Island, Gon and Killua train furiously under the guidance of Biscuit for better preparation at attempting the game. With their abilities vastly improving and the threat of player killers menacing Greed Island, Gon and company continue the game despite the dangers that they will face with the game activities and encounters with other players. Based on the manga by Togashi Yoshihiro.', 'Nippon Animation', '2004', 'series', 'released', '2004-03-03', 139, 0, NULL, '2026-07-25 16:17:26', '2026-09-03 15:29:52', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/139-3rPUPc2yOJck.jpg', 'Action, Adventure, Fantasy', 'OVA', 'SPRING', 14, 28194, NULL, '2026-08-02 15:35:45', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (550, 'Hunter x Hunter: The Last Mission', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx19951-kouyrYvcEyGP.jpg', 'movies', '7.0', 'The strongest Hunters that once existed in the Hunters Association were split into “light” and “dark”, and each walked down their respective paths. The “dark” side begins moving in order to massacre all Hunters! What actions will Gon take when the many crimes of Netero and the Hunters Association are unveiled...!?

(Source: Anime News Network)', 'MADHOUSE', '2013', 'movie', 'released', '2013-12-27', 19951, 0, NULL, '2026-07-25 16:17:26', '2026-09-03 15:29:52', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n19951-UYgobtqBfn0L.jpg', 'Action, Adventure, Fantasy', 'MOVIE', 'FALL', 1, 52796, 'https://www.youtube.com/watch?v=HUUHxCSqcvU', '2026-08-02 15:35:49', NULL);
