INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (557, 'Naruto the Movie: Ninja Clash in the Land of Snow', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx442-VJbmIVTgmne3.png', 'movies', '6.8', 'Kakashi orders Naruto, Sasuke, and Sakura to watch a movie before their next mission. Naruto is a big fan of the lead actress. After the movie, they see the heroine in person and being chased. They help her and Naruto asks for an autograph but she wouldn''t give him one. When the three returns, Kakashi tells them about their mission: to escort the actress to the Snow Country to film a new movie.

(Source: Anime News Network)', 'Studio Pierrot', '2004', 'movie', 'released', '2004-08-21', 442, 0, NULL, '2026-07-25 16:17:41', '2026-09-03 15:30:09', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/442-Mi9O1QwTaXqQ.jpg', 'Action, Adventure, Comedy, Drama, Supernatural', 'MOVIE', 'SUMMER', 1, 52207, 'https://www.youtube.com/watch?v=p2mXWbW9YZI', '2026-08-02 15:36:13', NULL);
