INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (559, 'NARUTO: Akaki Yotsuba no Clover wo Sagase', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/761.jpg', 'series', '6.2', 'The grandson of the 3rd Hokage, Konohamaru, finally has a crush on a girl, but he has a big problem she is soon to be moving away from the hidden leaf village. Konohamaru trying to make her stay seeks out the legendary crimson four-leaf clover, which is rumored to grant one wish.

(Source: Anime News Network)', 'Studio Pierrot', '2003', 'series', 'released', '2003-05-24', 761, 0, NULL, '2026-07-25 16:17:41', '2026-09-03 15:30:09', NULL, 'Adventure, Comedy', 'SPECIAL', 'SPRING', 1, 18394, NULL, '2026-08-02 15:36:09', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (560, 'Naruto the Movie: Legend of the Stone of Gelel', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx936-P1ogcIs07UR8.jpg', 'movies', '6.5', 'Naruto, Shikamaru, and Sakura are executing their mission of delivering a lost pet to a certain village. However, right in the midst of things, troops led by the mysterious knight, Temujin, attack them. In the violent battle, the three become separated. Temujin challenges Naruto to a fight and at the end of the fierce battle, both fall together from a high cliff. Furthermore, Shikamaru, having been left behind, beholds a giant moving fortress as it appears before his very eyes. In order to get a grasp on the situation, he infiltrates the fortress by himself, however once there he witnesses a frightening sight...

(Source: Anime News Network)', 'Studio Pierrot', '2005', 'movie', 'released', '2005-08-06', 936, 0, NULL, '2026-07-25 16:17:41', '2026-09-03 15:30:09', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/936-q1NJoF3NDEjF.jpg', 'Action, Adventure, Comedy, Drama, Fantasy, Supernatural', 'MOVIE', 'SUMMER', 1, 46992, 'https://www.youtube.com/watch?v=4EiTuiYlvgo', '2026-08-02 15:36:32', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (561, 'NARUTO: Narutimate Hero 3: Tsui ni Gekitotsu! Jounin VS Genin!! Musabetsu Dairansen Taikai Kaisai!!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/1074.jpg', 'series', '6.3', 'A contest is made by the Fifth Hokage called Jonin vs Genin. The point is to collect crystals for points, with the higher-ranked Chunin and Jonin holding crystals worth more points. The Genin have blue crystals, while the Chunin and Jonin have red crystals.

The video shows various fights between the Genin and Jonin, which each instance ending in the Jonin unknowingly losing their crystal (or discarding it).', 'Studio Pierrot', '2005', 'series', 'released', '2005-12-22', 1074, 0, NULL, '2026-07-25 16:17:41', '2026-09-03 15:30:09', NULL, 'Adventure, Comedy', 'OVA', 'WINTER', 1, 15895, NULL, '2026-08-02 15:36:29', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (562, 'Naruto the Movie: Guardians of the Crescent Moon Kingdom', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx2144-9FITEzdGnlWC.jpg', 'movies', '6.6', 'Led by Kakashi Hatake, Naruto Uzumaki, Sakura Haruno, and Rock Lee are tasked to escort the extravagant Prince Michiru Tsuki and his spoiled son Hikaru to the prosperous Land of Moon when the two return from a long trip around the world. As if guarding two whimsical high-ranked individuals was not challenging enough, the prince''s reckless decision to acquire an entire circus during their journey—mainly to entertain Hikaru''s wish of owning the saber-toothed tiger featured in the show—further propels the mission into disarray.

Just as things are finally settling down, the arrival of Michiru''s convoy at the Land of Moon is met with an unforeseen crisis—the greedy Chief Minister Shabadaba has taken over the country with the assistance of mysterious, powerful ninjas. While Kakashi''s team relentlessly fights the enemy by any means necessary, the two princes are forced to confront a new outlook on life through adversity.

(Source: MAL Rewrite)', 'Studio Pierrot', '2006', 'movie', 'released', '2006-08-05', 2144, 0, NULL, '2026-07-25 16:17:41', '2026-09-03 15:30:09', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2144-KnEAcgexm2SI.jpg', 'Action, Adventure', 'MOVIE', 'SUMMER', 1, 41645, 'https://www.youtube.com/watch?v=THXFAVKRs18', '2026-08-02 15:36:25', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (563, 'NARUTO: THE CROSS ROADS', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/7367.jpg', 'series', '6.4', 'This year is the 10th anniversary of Naruto''s serialization start. This work will feature an episode with Team Kakashi from Naruto''s youth era. It will be surprisingly different from the TV series, don''t miss it&#8252;', 'Studio Pierrot', '2009', 'series', 'released', '2009-10-12', 7367, 0, NULL, '2026-07-25 16:17:41', '2026-09-03 15:30:09', NULL, 'Action, Adventure, Comedy', 'SPECIAL', 'FALL', 1, 14594, NULL, '2026-08-02 15:36:22', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (564, 'Naruto, the Genie, and the Three Wishes, Believe It!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/10659.jpg', 'series', '6.5', 'Naruto discovers a genie''s bottle while he and the gang are at a genin grill party. When everyone finds out about the genie''s ability to grant wishes, the ultimate chase begins.

Note: Screened together with NARUTO: Shippuuden - The Lost Tower', 'Studio Pierrot', '2010', 'series', 'released', '2010-07-31', 10659, 0, NULL, '2026-07-25 16:17:41', '2026-09-03 15:30:09', NULL, 'Action, Comedy', 'SPECIAL', 'SUMMER', 1, 13296, NULL, '2026-08-02 15:36:19', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (565, 'Naruto Shippuden the Movie', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx2472-mYApVxceStn5.png', 'movies', '7.0', 'Demons that once almost destroyed the world, are revived by someone. To prevent the world from being destroyed, the demon has to be sealed and the only one who can do it is the shrine maiden Shion from the country of demons, who has two powers; one is sealing demons and the other is predicting the deaths of humans. This time Naruto''s mission is to guard Shion, but she predicts Naruto''s death. The only way to escape it, is to get away from Shion, which would leave her unguarded, then the demon, whose only goal is to kill Shion will do so, thus meaning the end of the world. Naruto decides to challenge this "prediction of death", but fails to prove Shion''s prediction wrong and supposedly dies in vain.', 'Studio Pierrot', '2007', 'movie', 'released', '2007-08-04', 2472, 0, NULL, '2026-07-25 16:17:43', '2026-09-03 15:30:12', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2472-yKoD8rvll5al.jpg', 'Action, Adventure, Comedy, Fantasy', 'MOVIE', 'SUMMER', 1, 58617, NULL, '2026-08-02 15:37:35', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (566, 'Naruto Shippuden the Movie: Bonds', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx4437-8LQbBZo4N6yi.jpg', 'movies', '6.9', 'A mysterious group of ninjas makes a surprise attack on the Konohagakure, which takes great damage. The nightmare of another Shinobi World War could become a reality. Sasuke, who left Konoha to kill his brother, Itachi, appears for the second time in front of Naruto at an unknown location to prevent it from coming to fruition.

(Source: Wikipedia)', 'Studio Pierrot', '2008', 'movie', 'released', '2008-08-02', 4437, 0, NULL, '2026-07-25 16:17:43', '2026-09-03 15:30:12', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4437-iYmkXFEF3ybw.jpg', 'Action, Supernatural', 'MOVIE', 'SUMMER', 1, 51233, 'https://www.youtube.com/watch?v=OkI3ZCEbx_E', '2026-08-02 15:36:37', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (567, 'Naruto Shippuden the Movie: The Will of Fire', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx6325-WaJPWmdnzgiI.jpg', 'movies', '7.1', 'Ninjas with bloodline limits begin disappearing in all the countries and blame points toward the fire nation. By Tsunade''s order, Kakashi is sacrificed to prevent an all out war. After inheriting charms left by Kakashi, Naruto fights through friends and foes to prevent his death while changing the minds of those who''ve inherited the will of fire.

(Source: Anime News Network)', 'Studio Pierrot', '2009', 'movie', 'released', '2009-08-01', 6325, 0, NULL, '2026-07-25 16:17:43', '2026-09-03 15:30:12', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/6325-DpxNXjgp7BPz.jpg', 'Action, Comedy', 'MOVIE', 'SUMMER', 1, 48202, 'https://www.youtube.com/watch?v=o0bDuM2tzi0', '2026-08-02 15:36:48', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (568, 'Naruto Shippuden the Movie: The Lost Tower', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx8246-KAi3bLLdJ4OI.jpg', 'movies', '7.1', 'Assigned on a mission to capture Mukade, a missing-nin, Naruto Uzumaki sets out for the once glorious historic ruins of "Ouran", where he pursues and corners the rogue ninja. Mukade''s goal is revealed to be a dormant leyline within the ruins; he unleashes the power of the leyline, causing a light to envelop Naruto, sending him into the past, 20 years before the series began. When Naruto awakens, he comes into contact with the Fourth Hokage, Minato Namikaze.

(Source: Wikipedia)', 'Studio Pierrot', '2010', 'movie', 'released', '2010-07-31', 8246, 0, NULL, '2026-07-25 16:17:43', '2026-09-03 15:30:12', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/8246-FfSs0aXwJpPV.jpg', 'Action, Comedy', 'MOVIE', 'SUMMER', 1, 55328, NULL, '2026-08-02 15:37:31', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (569, 'NARUTO×UT', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/10075.jpg', 'series', '6.9', 'UNIQLO clothing stores throughout Japan will be offering a Naruto x UT Original DVD with all-new animation on January 1. The DVD will contain an original Naruto anime video set to an exclusive version of Mayonaka no Orchestra, the upcoming song by the Japanese rock band Aqua Timez. A limited number of the DVDs will be offered as presents to people who buy UNIQLO''s Naruto graphic T-shirts online or in stores.

(Source: Anime News Network)', 'Studio Pierrot', '2011', 'series', 'released', '2011-01-01', 10075, 0, NULL, '2026-07-25 16:17:43', '2026-09-03 15:30:12', NULL, 'Action, Comedy', 'OVA', 'WINTER', 1, 12393, NULL, '2026-08-02 15:37:27', NULL);
