INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (581, 'Re:Zero kara Hajimeru Kyuukei Jikan (Break Time) 2nd Season Part 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b128306-94Zyoqy2fA4X.png', 'series', '6.9', 'The second cour of the second season of Re:Zero kara Hajimeru Kyuukei Jikan (Break Time).', 'Studio PuYUKAI', '2021', 'series', 'released', '2021-01-08', 128306, 0, NULL, '2026-07-25 16:17:49', '2026-09-03 15:30:19', NULL, 'Adventure, Comedy, Fantasy', 'ONA', 'WINTER', 12, 5808, 'https://www.youtube.com/watch?v=fzkWS5_XxZ4', '2026-08-02 15:37:56', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (582, 'Re:Zero kara Hajimeru Kyuukei Jikan (Break Time) 3rd Season', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx182417-zKlgy4KbGj1H.jpg', 'series', '6.9', 'The third season of Re:Zero kara Hajimeru Kyuukei Jikan (Break Time).', 'Studio PuYUKAI', '2024', 'series', 'released', '2024-10-03', 182417, 0, NULL, '2026-07-25 16:17:51', '2026-09-03 15:30:21', NULL, 'Adventure, Comedy, Fantasy', 'ONA', 'FALL', 16, 3871, 'https://www.youtube.com/watch?v=BC7el3rmNbA', '2026-08-02 15:38:00', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (583, 'Gintama: THE SEMI-FINAL', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx126819-KlcARzqDMjvf.jpg', 'series', '8.3', 'As the war temporarily calms down and Edo rebuilds, Gintoki finds Shinpachi—who is still unaware of his return—on a bridge. However, as a fight quickly breaks out between the Yorozuya and the Tenshouin Naraku, suspicion grows, forcing Gintoki to use what is nearest—a loincloth—to mask his identity. Saved for the time being, Gintoki enters the Yorozuya office, but unbeknownst to him, someone else is already waiting there...

Meanwhile, Kondou departs Earth to marry Princess Bubbles in an attempt to improve diplomatic relations. After boarding the Gorilla Amanto mother ship, he realizes that he doesn''t speak their language. Confused, Kondou tries conversing with them, only to inadvertently gain their support. However, someone associated with the princess crashes the ongoing ceremony. Will the wedding continue, or has Kondou just been saved from becoming the next Gorilla Prince?
 

(Source: MAL Rewrite)', 'Bandai Namco Pictures', '2021', 'series', 'released', '2021-01-15', 126819, 0, NULL, '2026-07-25 16:17:52', '2026-09-03 15:30:23', NULL, 'Action, Comedy', 'SPECIAL', 'WINTER', 2, 31719, 'https://www.youtube.com/watch?v=GFWgimHRucc', '2026-08-02 15:38:04', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (584, 'Kaguya-sama: Love is War -Ultra Romantic-', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx125367-1yuq9NFcQuLI.png', 'series', '8.9', 'The elite members of Shuchiin Academy''s student council continue their competitive day-to-day antics. Council president Miyuki Shirogane clashes daily against vice-president Kaguya Shinomiya, each fighting tooth and nail to trick the other into confessing their romantic love. Kaguya struggles within the strict confines of her wealthy, uptight family, rebelling against her cold default demeanor as she warms to Shirogane and the rest of her friends.

Meanwhile, council treasurer Yuu Ishigami suffers under the weight of his hopeless crush on Tsubame Koyasu, a popular upperclassman who helps to instill a new confidence in him. Miko Iino, the newest student council member, grows closer to the rule-breaking Ishigami while striving to overcome her own authoritarian moral code.

As love further blooms at Shuchiin Academy, the student council officers drag their outsider friends into increasingly comedic conflicts.

(Source: MAL Rewrite)

Note: The first episode had an advanced screening on April 2, in both New York & Los Angeles.', 'Aniplex', '2022', 'series', 'released', '2022-04-09', 125367, 0, NULL, '2026-07-25 16:18:10', '2026-09-03 15:30:30', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/125367-hGPJLSNfprO3.jpg', 'Comedy, Psychological, Romance, Slice of Life', 'TV', 'SPRING', 13, 291218, 'https://www.youtube.com/watch?v=RN4FFgHpAZo', '2026-08-02 15:38:11', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (585, 'Kaguya-sama: Love Is War -Stairway to Adulthood-', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx194884-rHgGAzKSCEWz.jpg', 'series', '8.4', 'Years after graduating from high school, Kaguya Shinomiya finds her old photo album and reminisces about when she was a part of Shuuchiin Academy''s student council. At the time, Kaguya had just started dating the president Miyuki Shirogane, and the two were hopelessly in love. With each wholesome and silly memory from their past, Kaguya is filled with bliss.

(Source: MAL Rewrite)

Note: The anime first premiered in Japan as a TV Special, and was later split into 2 episodes on streaming.', 'Aniplex', '2025', 'series', 'released', '2025-12-31', 194884, 0, NULL, '2026-07-25 16:18:10', '2026-09-03 15:30:30', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/194884-PwYRWyOUEwZI.jpg', 'Comedy, Psychological, Romance, Slice of Life', 'SPECIAL', 'FALL', 2, 50235, 'https://www.youtube.com/watch?v=LyHTqu5Yg7I', '2026-08-02 15:38:07', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (586, 'Made in Abyss', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx97986-TQ7dCgbS3y5s.jpg', 'series', '8.4', 'The "Abyss" is the last unexplored place in the world. Strange and wonderful creatures roam within, and it is full of precious relics that present humans can''t recreate. Those that dare to explore the depths are known as "Cave Raiders." An orphan girl named Riko lives on the rim. Her dream is to become a Cave Raider like her mother and solve the mysteries of the cave system. One day, Riko starts exploring the caves and discovers a robot who resembles a human boy.

(Source: Anime News Network, edited)

Note: The last episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.', 'Kinema Citrus', '2017', 'series', 'released', '2017-07-07', 97986, 0, NULL, '2026-07-25 16:18:15', '2026-09-03 15:30:36', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97986-C55UnbJKB7ZF.jpg', 'Adventure, Drama, Fantasy, Horror, Mystery, Sci-Fi', 'TV', 'SUMMER', 13, 403912, 'https://www.youtube.com/watch?v=AQbaZeby2zA', '2026-08-02 15:38:18', NULL);
