INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (591, 'Demon Slayer: Kimetsu no Yaiba Mugen Train Arc', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx129874-g6ZKXB94Hui1.jpg', 'series', '8.2', 'In Demon Slayer: Kimetsu no Yaiba Mugen Train Arc, Tanjiro Kamado and his fellow Demon Slayer members embark on a mission aboard the Infinity Train. Their new mission is to investigate a series of mysterious disappearances, carried out by a demon that has been terrorizing passengers and killing the demon slayers who oppose it.

Note: The first episode is entirely anime original. Episodes 2-7 are a re-edited version of the movie featuring new scenes and music.', 'ufotable', '2021', 'series', 'released', '2021-10-10', 129874, 0, NULL, '2026-07-25 16:18:19', '2026-09-03 15:30:40', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/129874-3ipZzS50i9Ta.jpg', 'Action, Adventure, Drama, Fantasy, Mystery, Supernatural', 'TV', 'FALL', 7, 359478, 'https://www.youtube.com/watch?v=t6MXHczeEqc', '2026-08-02 15:38:36', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (592, 'Demon Slayer: Kimetsu no Yaiba Entertainment District Arc', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx142329-kET1PIXJv2eW.jpg', 'series', '8.6', 'After visiting the Rengoku residence, Tanjirou and his comrades volunteer for a mission within the Entertainment District, a place where desires are sold and demons dwell. They journey alongside the flashy Sound Hashira, Tengen Uzui, in search of a monstrous foe terrorizing the town. Sworn to slay creatures of the night, the hunt continues.

(Source: Funimation)

Note:

- The first episode aired with a runtime of ~47 minutes.

- The last episode aired with a runtime of ~33 minutes.', 'ufotable', '2021', 'series', 'released', '2021-12-05', 142329, 0, NULL, '2026-07-25 16:18:19', '2026-09-03 15:30:40', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/142329-i413SzLmToZN.jpg', 'Action, Adventure, Fantasy, Supernatural', 'TV', 'WINTER', 11, 482095, 'https://www.youtube.com/watch?v=XoJCOAU_72U', '2026-08-02 15:38:32', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (593, 'The Melancholy of Haruhi Suzumiya (2009)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx4382-ojMWjGFfJFmN.png', 'series', '7.2', 'Kyon has found himself dragged through many adventures as of late—all because of the SOS Brigade club and its excitable leader, Haruhi Suzumiya. He has stopped believing in the supernatural long ago, but after being forced to join this club based solely on that, he has seen things that cannot be explained logically.

Joining Kyon on his various misadventures is the shy and soft-spoken Mikuru Asahina, the bookish Yuki Nagato, and the ever-cheerful Itsuki Koizumi. Whether it is summer vacation or a school festival, things involving their club and Haruhi herself always end up becoming strange.

Note:  This is a re-airing of the original Suzumiya Haruhi no Yuuutsu series, taken from the DVD release and aired in chronological order, adding 14 additional episodes with new content. These new episodes are episodes 8 (Bamboo Leaf Rhapsody), 12-19 (Endless Eight), and 20-24 (The Sigh of Suzumiya Haruhi Parts 1-5).', 'Kyoto Animation', '2009', 'series', 'released', '2009-04-03', 4382, 0, NULL, '2026-07-25 16:18:26', '2026-09-03 15:30:48', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4382-KDWzcDSH9H07.jpg', 'Comedy, Mystery, Sci-Fi, Slice of Life, Supernatural', 'TV', 'SPRING', 28, 119670, 'https://www.youtube.com/watch?v=RUQGttmjyMI', '2026-08-02 15:38:49', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (594, 'The Disappearance of Nagato Yuki-chan', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx20566-BSk4WYE7kJsy.jpg', 'series', '6.4', 'This spin-off of the Haruhi Suzumiya series takes place in the world of the "Disappearance" arc of the original novels, focusing on the high school life (and romance!) of a tentative and bashful Yuki Nagato quite unlike the one you''ve come to know and love through the usual exploits of the SOS Brigade... but no less charming!

As the shy head of the Literature Club, Nagato has had a hard time recruiting members. Her close friend Ryoko Asakura supports her in this. Drafting Kyon, she eventually meets up with Haruhi Suzumiya, Tsuruya, Mikuru Asahina and Itsuki Koizumi, and has to put up with their hijinks while trying to romance Kyon. Asakura seems ambivalent about the latter prospect.', 'Satelight', '2015', 'series', 'released', '2015-04-04', 20566, 0, NULL, '2026-07-25 16:18:26', '2026-09-03 15:30:48', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20566-ZGL4CRxIN7bl.jpg', 'Comedy, Romance, Slice of Life', 'TV', 'SPRING', 16, 35830, 'https://www.youtube.com/watch?v=nJat0lCwSR0', '2026-08-02 15:38:45', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (595, 'The Melancholy of Haruhi Suzumiya', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx849-wQM3GqLvl62P.png', 'series', '7.6', 'Kyon, your typical high school student, has long given up his belief in the supernatural. However, upon meeting Haruhi Suzumiya, he quickly finds out that it is the supernatural that she is interested in; aliens, time travelers and espers among other things. When Haruhi laments about the lack of intriguing clubs around school, Kyon inspires Haruhi to form her own club. As a result, the SOS Brigade is formed, a club which specializes in all that is the supernatural.

Much to his chagrin, Kyon, along with the silent bookworm, Yuki Nagato, the shy and timid Mikuru Asahina, and the perpetually smiling Itsuki Koizumi, are recruited as members. The story follows the crazy adventures that these four endure under their whimsical leader, Haruhi. The story is based on the light novels by Nagaru Tanigawa.

Note: This entry is for the original 14-episode 2006 airing. The series was further expanded and reordered into <a href="https://anilist.co/anime/4382/Suzumiya-Haruhi-no-Yuuutsu-2009/">a 28-episode series in 2009.</a>', 'Kyoto Animation', '2006', 'series', 'released', '2006-04-03', 849, 0, NULL, '2026-07-25 16:18:26', '2026-09-03 15:30:48', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/849-Cey4HHIDoeY2.jpg', 'Comedy, Mystery, Sci-Fi, Slice of Life, Supernatural', 'TV', 'SPRING', 14, 200245, 'https://www.youtube.com/watch?v=fXFoWkBaedU', '2026-08-02 15:38:42', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (596, 'Orange', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx21647-zMUXNhcVyRyv.png', 'series', '7.5', 'Everyone has regrets in life. So who wouldn''t take the chance to change the past if given the opportunity? When sixteen-year-old Takamiya Naho receives a mysterious letter, claiming to be from her twenty-seven-year-old self, her life is suddenly thrown into flux. The letter tells her that a new transfer student by the name of Naruse Kakeru will be joining her class, and to keep her eye on him. But why? Naho must decide what to make of the letter and its cryptic warning, and what it means not only for her future, but for Kakeru''s as well.

(Source: Anime News Network)

Note: The last episode aired with a runtime of ~40 minutes as opposed to the standard 24 minute long episode.', 'TMS Entertainment', '2016', 'series', 'released', '2016-07-04', 21647, 0, NULL, '2026-07-25 16:18:28', '2026-09-03 15:30:50', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21647-jpWsvCBJO1q5.jpg', 'Drama, Romance, Supernatural', 'TV', 'SUMMER', 13, 235207, 'https://www.youtube.com/watch?v=NkqePv9i6Yw', '2026-08-02 15:38:52', NULL);
