INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (622, 'My Hero Academia the Movie: Two Heroes Specials', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx105893-IW5rW9O9auyK.jpg', 'series', '7.1', 'Short OVAs included with the Blu-ray/DVD release of Boku no Hero Academia the Movie: Futari no Hero.
Episode 1 is a short animation about All Might''s past.
Episode 2 is an epilogue picture drama for Boku no Hero Academia the Movie: Futari no Hero.', 'bones', '2019', 'series', 'released', '2019-02-13', 105893, 0, NULL, '2026-07-25 16:40:57', '2026-09-03 15:33:54', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/105893-lIMSByqRPHTi.jpg', 'Action, Drama', 'OVA', 'WINTER', 2, 42531, NULL, '2026-08-02 15:40:24', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (623, 'TSUKIMICHI -Moonlit Fantasy- Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx139518-GZWYKM8Kg1S2.png', 'series', '7.8', 'The second season of Tsuki ga Michibiku Isekai Douchuu.

After Makoto Misumi defeats Mitsurugi and Sofia Bulga, humanity is saved from the attacking demon army—for the time being. The goddess is aware of Makoto’s growing power, and she sees him as less of a nuisance and more of a rival. Makoto continues his journey to further expand his community of outcasts and connect with more hyumans. But will he be strong enough to hold off the coming storm?

(Source: Crunchyroll)', 'J.C.STAFF', '2024', 'series', 'released', '2024-01-08', 139518, 0, NULL, '2026-07-25 16:41:57', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/139518-OxLRGjPm9Tms.jpg', 'Action, Adventure, Comedy, Fantasy', 'TV', 'WINTER', 25, 116087, 'https://www.youtube.com/watch?v=bJaTrqUGXXU', '2026-08-02 15:40:28', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (624, 'Shangri-La Frontier Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx176508-eFad4szofm8d.png', 'series', '8.2', 'The second season of Shangri-La Frontier.

Rakuro Hizutome only cares about one thing: beating crappy VR games. He devotes his entire life to these buggy games and could clear them all in his sleep. One day, he decides to challenge himself and play a popular god-tier game called Shangri-La Frontier. But he quickly learns just how difficult it is. Will his expert skills be enough to uncover its hidden secrets?

(Source: Crunchyroll)', 'C2C', '2024', 'series', 'released', '2024-10-13', 176508, 0, NULL, '2026-07-25 16:41:59', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/176508-8AtMjgNkPsFl.jpg', 'Action, Adventure, Comedy, Fantasy, Sci-Fi', 'TV', 'FALL', 25, 108733, 'https://www.youtube.com/watch?v=OIi6fBHx72U', '2026-08-02 15:40:32', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (625, 'Reincarnated as a Sword', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx139587-rbZVcigCRtHY.jpg', 'series', '7.4', 'Some isekai protagonists are reincarnated as powerful warriors or skilled wizards, but our protagonist was reborn in another life as a sentient sword! He’s taken up by Fran, a desperate girl fleeing evil-doers intent on selling her into slavery. With her new weapon’s help and guidance, she’s able to strike down her captors and secure her freedom. Together, this unconventional master-student duo embark on an epic journey to liberate those in need and exact justice on the cruel of heart.

(Source: Sentai Filmworks)

Note: Episode 1 was streamed in advance on September 28, 2022 on AbemaTV. The regular TV broadcast began on October 5, 2022.', 'C2C', '2022', 'series', 'released', '2022-09-28', 139587, 0, NULL, '2026-07-25 16:42:06', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/139587-XFbotQOPcLC4.jpg', 'Action, Adventure, Fantasy', 'ONA', 'FALL', 12, 111359, 'https://www.youtube.com/watch?v=TDN4Rh7VvkU', '2026-08-02 15:40:35', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (626, 'BOCCHI THE ROCK!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx130003-HTDmeL4RGeJ4.png', 'series', '8.7', 'Hitori Gotou, “Bocchi-chan,” is a girl who’s so introverted and shy around people that she’d always start her conversations with “Ah...”

During her middle school years, she started playing the guitar, wanting to join a band because she thought it could be an opportunity for even someone shy like her to also shine. But because she had no friends, she ended up practicing guitar for six hours every day all by herself. After becoming a skilled guitar player, she uploaded videos of herself playing the guitar to the internet under the name “Guitar Hero” and fantasized about performing at her school’s cultural festival concert. But not only could she not find any bandmates, before she knew it, she was in high school and still wasn’t able to make a single friend!

She was really close to becoming a shut-in, but one day, Nijika Ijichi, the drummer in Kessoku Band, reached out to her. And because of that, her everyday life started to change little by little...

(Source: Crunchyroll)', 'CloverWorks', '2022', 'series', 'released', '2022-10-09', 130003, 0, NULL, '2026-07-25 16:42:08', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/130003-5F90a7BtsPQN.jpg', 'Comedy, Music, Slice of Life', 'TV', 'FALL', 12, 258504, 'https://www.youtube.com/watch?v=SyMMZF5zNW4', '2026-08-02 15:40:39', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (627, 'BOCCHI THE ROCK! Recap Part 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx171099-JexoHylkSZ6r.jpg', 'movies', '8.3', 'Compilation film of Bocchi the Rock! featuring new animation intro footage and additional scenes. The second of the Bocchi compilation movie duology.', 'CloverWorks', '2024', 'movie', 'released', '2024-08-09', 171099, 0, NULL, '2026-07-25 16:42:08', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/171099-10pR2uCW5Kah.jpg', 'Comedy, Music, Slice of Life', 'MOVIE', 'SUMMER', 1, 13468, 'https://www.youtube.com/watch?v=duo1scb3dL0', '2026-08-02 15:40:43', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (628, 'BLEACH: Thousand-Year Blood War - The Conflict', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx169755-Rqb7MjnzdTc6.jpg', 'series', '8.6', 'The third part of BLEACH: Sennen Kessen-hen.

After an awe-inspiring battle with Ichibei Hyousube—leader of the Soul Society''s Royal Guard—the powerful Yhwach moves into the final stage of his master plan. He aims to slay the Soul King, the being whose very existence maintains the status quo of three worlds: Hueco Mundo, the Soul Society, and the realm of humans that Ichigo Kurosaki and his closest friends hail from. Conquering his own bout with the remainder of the Royal Guard, Uryuu Ishida joins Yhwach in his efforts to create a new world in his image.

With a flood of resolution and newfound power, Ichigo rushes to stop Yhwach from accomplishing his ultimate goal and save the countless lives within the three existing realms. But Ichigo has a complicated lineage, one that leaves him susceptible to Yhwach''s sinister influence.

Meanwhile, in a final desperate gambit, Jirou Sakuranosuke Shunsui Kyouraku, the newly promoted head captain of the Soul Society''s combat corps, enlists the help of an old enemy whose immense power may turn the tide of battle.

[Written by MAL Rewrite]', 'PIERROT FILMS', '2024', 'series', 'released', '2024-10-05', 169755, 0, NULL, '2026-07-25 16:42:15', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/169755-hCWjp9ajjMYV.jpg', 'Action, Adventure, Supernatural', 'TV', 'FALL', 14, 110482, 'https://www.youtube.com/watch?v=Nq9PkH3UgEo', '2026-08-02 15:40:45', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (629, 'Youjo Shenki 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b213961-x2ZvvtkYSTC9.png', 'series', '0.0', 'The second season of Youjo Shenki.

Chibi parody of Youjo Senki.', 'Studio PuYUKAI', '2026', 'series', 'airing', '2026-07-09', 213961, 0, NULL, '2026-07-25 16:42:19', '2026-09-03 15:44:50', NULL, 'Comedy, Fantasy', 'ONA', 'SUMMER', NULL, 607, 'https://www.youtube.com/watch?v=3yILla1h1pM', '2026-09-03 15:44:50', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (630, 'BLEACH: The Sealed Sword Frenzy', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx834-Wm0msxVlJnkT.png', 'series', '6.5', 'A Shinigami named Baishin who was sealed by Soul Society long ago is set free on Earth. On a fateful day Ichigo encounters him and has roughly half of his reiatsu drained. Its now up to Ichigo and Soul Society to finally put a stop to Baishin and his destruction.', 'Studio Pierrot', '2006', 'series', 'released', '2006-03-23', 834, 0, NULL, '2026-07-25 16:42:26', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Drama, Fantasy, Supernatural', 'SPECIAL', 'SPRING', 1, 20045, 'https://www.youtube.com/watch?v=l1JpE_tarso', '2026-08-02 15:40:55', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (631, 'Bleach the Movie: Memories of Nobody', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1686-oZQepxP4SRQ2.jpg', 'movies', '7.1', 'In Karakura Town, there has been a sudden outbreak of unidentifiable spirits called "blanks" (vacant souls) while in the skies of Soul Society, the real world has been reflected. A mysterious female shinigami called Senna has appeared before Ichigo along with a man named Ganryu, leading a group called the "Dark Ones."

(Source: Anime News Network)', 'Studio Pierrot', '2006', 'movie', 'released', '2006-12-16', 1686, 0, NULL, '2026-07-25 16:42:26', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n1686-dYv44wJMzT4t.jpg', 'Action, Adventure, Drama, Supernatural', 'MOVIE', 'FALL', 1, 47242, 'https://www.youtube.com/watch?v=DUyEuGL2vT0', '2026-08-02 15:40:59', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (632, 'Bleach the Movie: The DiamondDust Rebellion', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2889-AmnSwChuAuGT.jpg', 'movies', '7.0', 'A valuable artifact known as "King''s Seal" ("Ouin") is stolen by a mysterious group of people during transport in the Soul Society. Toshiro Hitsugaya, the 10th Division Captain of Gotei 13, is assigned to transport the seal, fights the leader of the group, and shortly after, goes missing. After the incident, the Seireitei declares Hitsugaya a traitor and orders the capture and execution of Hitsugaya. Ichigo Kurosaki refuses to believe this, and along with Rangiku Matsumoto, Rukia Kuchiki, and Renji Abarai, swears to uncover the real mastermind of the stolen seal, find Hitsugaya, and clear his name. Meanwhile, a rogue Hitsugaya searches for the perpetrators and uncovers a dark secret regarding a long dead shinigami.

(Source: Anime News Network)', 'Studio Pierrot', '2007', 'movie', 'released', '2007-12-22', 2889, 0, NULL, '2026-07-25 16:42:26', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Drama, Supernatural', 'MOVIE', 'FALL', 1, 41562, 'https://www.youtube.com/watch?v=zRbLfgVYjMY', '2026-08-02 15:41:02', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (633, 'Bleach the Movie: Fade to Black', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx4835-UqbwERH407BB.jpg', 'movies', '7.1', 'A mysterious figure has broken into Mayuri Kurotsuchi''s laboratory in the Seireitei. Rukia witnesses this catastrophe, and the intruders abduct Rukia as she feels something inside of her fade away.

Meanwhile, in the World of the Living, Ichigo and Kon experience a strange disturbance and head to Kisuke Urahara''s shop for some answers. When Kisuke informs them about the destruction of the Seireitei, the two set out for the Soul Society.

What awaits Ichigo in the devastated Seireitei, however, are Soul Reapers who seem to have lost all memory related to both him and Rukia. Ichigo must find out what happened to Rukia and try to save her before the two are forced to part ways forever!

(Source: VIZ Media)', 'Studio Pierrot', '2008', 'movie', 'released', '2008-12-13', 4835, 0, NULL, '2026-07-25 16:42:26', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n4835-85niQKlITltI.jpg', 'Action, Adventure, Drama, Supernatural', 'MOVIE', 'FALL', 1, 40928, 'https://www.youtube.com/watch?v=TnO5S9pQzzc', '2026-08-02 15:41:05', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (634, 'Bleach the Movie: Hell Verse', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx8247-VppsQKlgXoXr.png', 'movies', '7.3', 'Bleach: Jigoku-hen is set in Hell and features a fully Hollowfied Ichigo. The movie centers around Ichigo and his friends heading into Hell with the assistance of man named Kokuto to stop the merging of the two realms. However, Kokuto gives Ichigo a warning - he mustn''t Hollowfy in Hell, or he will lose control of his body and never be able to return...', 'Studio Pierrot', '2010', 'movie', 'released', '2010-12-04', 8247, 0, NULL, '2026-07-25 16:42:26', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/8247-M9lIhb1pWRTn.jpg', 'Action, Supernatural', 'MOVIE', 'FALL', 1, 43824, 'https://www.youtube.com/watch?v=7wwHPzRX-6s', '2026-08-02 15:41:12', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (635, 'BLEACH Colorful!: Gotei Juusan Yatai Daisakusen!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx100719-zujHjeEBqmo7.jpg', 'series', '6.1', 'An animated adaptation of several chapters of Colourful Bleach. Released with the "TV Animation BLEACH 5th Anniversary Box."', 'Studio Pierrot', '2008', 'series', 'released', '2008-09-21', 100719, 0, NULL, '2026-07-25 16:42:26', '2026-09-02 16:57:33', NULL, 'Comedy', 'OVA', 'FALL', 1, 5696, 'https://www.youtube.com/watch?v=l1JpE_tarso', '2026-08-02 15:41:15', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (636, 'BURN THE WITCH', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx116673-cy4sgiliurpR.jpg', 'series', '7.0', 'Historically, 72% of all the deaths in London are related to dragons, fantastical beings invisible to the majority of the people. While unknown to most, some people have been standing up to these dragons.

Only inhabitants of Reverse London who live in the hidden "reverse" side of London can see the dragons. Even then, only a selected few become qualified enough as witches or wizards to make direct contact with them.

The protagonists of the story are witch duo Noel Niihashi and Ninny Spangcole. They are protection agents for Wing Bind (WB), an organization for dragon conservation and management. Their mission is to protect and manage the dragons within London on behalf of the people.

(Source: Official Site)
</br>

Note: The show was screened in theaters and released online on the same date; the theatrical release combines all three episodes into one.', 'Studio Colorido', '2020', 'series', 'released', '2020-10-02', 116673, 0, NULL, '2026-07-25 16:42:26', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/116673-AY85zkgTYWKu.jpg', 'Action, Fantasy', 'ONA', 'FALL', 3, 101005, 'https://www.youtube.com/watch?v=VnQZcum2se4', '2026-08-02 15:41:18', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (637, 'BLEACH: memories in the rain', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b154037-7VSs4aDUL2ZG.jpg', 'series', '6.9', 'Kurosaki Ichigo, the temporary Shinigami (Death God) for Kuchiki Rukia, discovers his mother''s killer as one of the Hollows he has been hunting. He does battle with it in a prideful battle of revenge.

