INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (639, 'Farming Life in Another World', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx146850-xfeAFIE0M9hl.jpg', 'series', '7.4', 'Life cut short by illness at just 39 years old, Machio Hiraku knows not to take simple blessings for granted. When a godlike figure gives him given a chance to live again, Hiraku has only the simplest of wishes for his new life: to be healthy, to live peacefully, to speak the local language, and to spend his days on an idyllic farm. Fresh air, sunshine, honest work, and good company combine to form the happy, peaceful existence Hiraku has always dreamed of.

(Source: HIDIVE)', 'Zero-G', '2023', 'series', 'released', '2023-01-06', 146850, 0, NULL, '2026-07-25 16:42:42', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/146850-GmkEchiYFCQE.jpg', 'Fantasy, Slice of Life', 'TV', 'WINTER', 12, 108449, 'https://www.youtube.com/watch?v=iwxPf8SEmEU', '2026-08-02 15:41:32', NULL);
