INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (695, 'Detective Conan: Zero''s Tea Time', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx140002-zbEoTkcXifOa.jpg', 'series', '6.9', 'A detective who''s also a public security agent and a member of a shadowy organization juggles his triple identities in this "Detective Conan" spinoff.

(Source: Netflix)', 'TMS Entertainment', '2022', 'series', 'released', '2022-04-05', 140002, 0, NULL, '2026-07-25 16:43:03', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/140002-h4EoBJ2PfeKw.jpg', 'Action, Comedy, Drama, Slice of Life', 'ONA', 'SPRING', 6, 5490, 'https://www.youtube.com/watch?v=JofxV0ehN2s', '2026-08-02 15:45:02', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (696, 'Detective Conan: The Culprit Hanzawa', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx140005-BMmsl94sUPsw.jpg', 'series', '6.9', 'A town of crime, Beika Town. A mysterious Dark Shadow descends onto this town that ranks among the highest crime rates in the world. His (or her?) goal is to kill a “certain man.” That key player in Detective Conan is now a protagonist! Clad in tights and possessing a pure intellect, this person’s name is… the (pseudonymous) Culprit Hanzawa!

(Source: Netflix)', 'TMS Entertainment', '2022', 'series', 'released', '2022-10-04', 140005, 0, NULL, '2026-07-25 16:43:03', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/140005-CjhEaR3bgg39.jpg', 'Comedy, Mystery', 'TV_SHORT', 'FALL', 12, 5688, 'https://www.youtube.com/watch?v=QSFAnqVGm4o', '2026-08-02 15:44:54', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (697, 'Detective Conan: The Bride of Halloween', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx142219-Nu9bWFhIKn0q.jpg', 'movies', '8.0', 'The movie takes place in Shibuya on Halloween. At the Shibuya Hikarie building, a certain wedding ceremony is taking place, where Miwako Sato is in a wedding dress. Suddenly, an intruder bursts in, and Wataru Takagi is injured from protecting Miwako. At the same time, the serial bombing criminal from the incident three years ago that killed Jinpei Matsuda, whom Miwako was in love with, escapes. Is this really a coincidence?

(Source: Anime News Network)', 'TMS Entertainment', '2022', 'movie', 'released', '2022-04-15', 142219, 0, NULL, '2026-07-25 16:43:03', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/142219-FbJbKVMYwPBB.jpg', 'Action, Drama, Mystery', 'MOVIE', 'SPRING', 1, 6765, 'https://www.youtube.com/watch?v=sJwIGd22Cew', '2026-08-02 15:44:58', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (698, 'Meitantei Conan: Conan vs. Kid - SHARK & JEWEL', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/9785.jpg', 'movies', '7.0', '3D IMAX movie, shown only at the Suntory Museum in Osaka.', NULL, '2005', 'movie', 'released', '2005-07-29', 9785, 0, NULL, '2026-07-25 16:43:03', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Mystery', 'MOVIE', 'SUMMER', 1, 2396, 'https://www.youtube.com/watch?v=qloZWUTB-xc', '2026-08-02 15:45:13', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (699, 'Meitantei Conan: Conan vs. Kid - Shikkoku no Sniper', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/9786.jpg', 'movies', '6.2', '3D IMAX movie, shown only at the Suntory Museum in Osaka.

The story involves a heist taking place on 15 Aug at the Takaramachi Jewelry Museum where a jewel worth 1 Billion Yen is stolen.', NULL, '2006', 'movie', 'released', '2006-07-28', 9786, 0, NULL, '2026-07-25 16:43:03', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Mystery', 'MOVIE', 'SUMMER', 1, 1345, 'https://www.youtube.com/watch?v=EtWYaoBrpU0', '2026-08-02 15:45:09', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (700, 'Detective Conan: Black Iron Submarine', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx156841-eCdzTqfaqNb7.png', 'movies', '8.2', 'This time''s location is set in the sea near the Hachijo-jima island, Tokyo. Engineers from around the world have gathered for the full-scale operation of "Pacific Buoy," an offshore facility to connect security cameras owned by the worldwide police forces. A test of a certain "new technology" based on a face recognition system is underway there.

Meanwhile, Conan and the Detective Boys visit Hachijo-jima at Sonoko''s invitation and receive a phone call from Subaru Okiya (a graduate student in the Graduate School of Engineering at Tokyo Metropolitan University, who is an FBI agent Shuichi Akai and a black-robed organization''s Rye) informing them that a Europol employee was murdered in Germany by the Black Organization''s Jin.

Conan, who is disquieted, sneaks into the facility and finds that a female engineer has been kidnapped by the Black Organization...! Furthermore, a USB drive containing certain information in her possession ends up in the hands of the organization... A black shadow also creeps up on Ai Haibara (Detective Boys'' Ai Haibara / Shiho Miyano / the Black Organization''s Sherry),..

(Source: Crunchyroll)', 'TMS Entertainment', '2023', 'movie', 'released', '2023-04-14', 156841, 0, NULL, '2026-07-25 16:43:03', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/156841-BV1wjpf495Lp.jpg', 'Drama, Mystery', 'MOVIE', 'SPRING', 1, 6942, 'https://www.youtube.com/watch?v=0jIpAPLbpt0', '2026-08-02 15:43:58', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (701, 'Meitantei Conan: Keisatsu Gakkou-hen - Wild Police Story CASE. Furuya Rei', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx166060-Hha5lz7dQcoI.jpg', 'series', '6.4', 'Rei Furuya, Jinpei Matsuda, Hiromitsu Morofushi, Wataru Date and Kenji Hagiwara are now graduated from the police academy.

Note:

- This episode is the fifth and final episode of the Keisatsu Gakkou-hen - Wild Police Story arc.

- It was supposed to be episode 1077 in its parent story Meitantei Conan', 'TMS Entertainment', '2023', 'series', 'released', '2023-03-11', 166060, 0, NULL, '2026-07-25 16:43:03', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Mystery, Psychological', 'SPECIAL', 'WINTER', 1, 719, 'https://www.youtube.com/watch?v=hTtJX-4Kh_4', '2026-08-02 15:44:02', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (702, 'Detective Conan: The Million-dollar Pentagram', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx169754-7QA6x4pbOiJX.jpg', 'movies', '7.7', 'The 27th Detective Conan movie. 

A message has arrived from Kid the Phantom Thief, that he will steal a Japanese sword belonging to the wealthy Onoe Family in Hakodate, Hokkaido. Conan and Heiji Hattori, who happened to be in Hakodate, are on the case to capture Kid. Onoe Family''s collections are associated with Toshizo Hijikata, a historic figure who perished in Hakodate. Why is Kid, who specializes in jewels, going after a Japanese sword?

Coincidentally the family lawyer of Onoe is found murdered in the warehouse district, apparently slaughtered by a Japanese sword. The suspect is an investor/arms dealer who is said to be after Onoe family''s hidden treasure.

The grandfather of Onoe family''s patriarch was deeply involved with the army industry during wartime, and it was rumored he hid some powerful weapon that could “change the course of war” somewhere in Hakodate. Is Kid after that weapon? Meanwhile, Heiji is trying to find a perfect viewpoint to declare his love to Kazuha…

In the North among cherry blossoms, the exciting hunt for treasure begins!

(Source: TMS Entertainment USA)', 'TMS Entertainment', '2024', 'movie', 'released', '2024-04-12', 169754, 0, NULL, '2026-07-25 16:43:03', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/169754-xMWlFwvB9VuN.jpg', 'Adventure, Mystery', 'MOVIE', 'SPRING', 1, 5273, 'https://www.youtube.com/watch?v=Fwm8v1U2NIg', '2026-08-02 15:44:06', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (703, 'Detective Conan: One-Eyed Flashback', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx185212-ejyh60F81l8n.jpg', 'movies', '7.5', 'The 28th Detective Conan movie.

When a researcher is attacked in the Yatsugatake Mountains, Nagano PD’s Kansuke Yamato and Yui Uehara investigate, but Kansuke’s old eye injury flares up — hinting at a dark connection. Meanwhile, Kogoro’s ex-colleague is murdered after looking into a past incident of Kansuke’s. Teaming up with Amuro and Kazami, Conan digs in to uncover the truth behind it all.

(Source: Sony Pictures Australia)', 'TMS Entertainment', '2025', 'movie', 'released', '2025-04-18', 185212, 0, NULL, '2026-07-25 16:43:03', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/185212-yXAu1YE4K5s5.jpg', 'Mystery', 'MOVIE', 'SPRING', 1, 3458, 'https://www.youtube.com/watch?v=D22Ezh_UiVM', '2026-08-02 15:44:12', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (704, 'Detective Conan: Fallen Angel of the Highway', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx198369-80jGPuTziEa7.png', 'movies', '5.9', 'The 29th Detective Conan movie.

Conan, Ran, Sonoko, and Kogoro were heading to Yokohama''s Minato Mirai district with motorcycle enthusiast Masumi Sera for the Kanagawa Motorcycle Festival. Then, a mysterious black motorcycle appeared, leaping over the car carrying Conan and the others. And chasing it was Chihaya Hagiwara of the Kanagawa Prefectural Police Traffic Mobile Unit—the “Goddess of the Wind” Ran had once seen. However, after a fierce car chase, Chihaya''s motorcycle was wrecked, and she let the target slip away at the last moment. After arriving at the Yokohama festival venue, Conan and the others witnessed the unveiling of a new police motorcycle equipped with cutting-edge technology, named "Angel." Amidst this, reports surfaced that a runaway "black motorcycle" had now appeared in central Tokyo, evading pursuit by the Metropolitan Police Department. The purpose of the rampage remains unknown, but the vehicle''s body bears a striking resemblance to "Angel." Police have dubbed the black Angel bike "Lucifer" and continue their pursuit.

(Source: Official website, translated)', 'TMS Entertainment', '2026', 'movie', 'released', '2026-04-10', 198369, 0, NULL, '2026-07-25 16:43:03', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/198369-MmvnBvHzuB3D.jpg', 'Mystery', 'MOVIE', 'SPRING', 1, 1786, 'https://www.youtube.com/watch?v=CsxkouRl7Yo', '2026-08-02 15:44:16', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (705, 'Detective Conan: The Gold-Star Answer', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx212994-y8ByUgm6GOjq.jpg', 'series', '7.0', 'Jewelry stores across town are being robbed, but despite the crimes taking place, Conan''s friend Ayumi is excited. She notices the burglaries bear a striking resemblance to the events of her favorite anime, Precure, and she''s hopeful that she''ll get to meet the "PreCures!" if the thieves show up again.

Conan and the Junior Detective League get assigned to guard Kaneko Jewelry Store, which is rumoured to be their next target. After tailing a suspicious customer and discovering the date of the crime, as well as their hideout, the police seem to round up the thieves - but Ayumi notices something odd... Can the Detective League solve the mystery with a cute twist?!

(Source: Official website, translated, edited)

Note: Special commemorative crossover episode between Detective Conan and Star Detective Precure! for the 30th anniversary of the Detective Conan series. This is one of two episodes, the other aired as episode 18 of Star Detective Precure! series.', 'TMS Entertainment', '2026', 'series', 'released', '2026-06-06', 212994, 0, NULL, '2026-07-25 16:43:03', '2026-09-02 16:57:33', NULL, 'Comedy, Mahou Shoujo, Mystery', 'SPECIAL', 'SPRING', 1, 1299, 'https://www.youtube.com/watch?v=0vsGnRO9FKY', '2026-08-02 15:44:19', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (706, 'The Ramparts of Ice Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx213805-kQXiLbsLBkX4.png', 'coming', '0.0', 'The second season of Koori no Jouheki.', 'Studio KAI', '2026', 'series', 'upcoming', '2026-10-01', 213805, 0, NULL, '2026-07-25 16:43:06', '2026-09-03 15:51:08', NULL, 'Comedy, Drama, Romance, Slice of Life', 'TV', 'FALL', NULL, 13118, 'https://www.youtube.com/watch?v=7OHlkGNvEAE', '2026-09-03 15:51:08', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (707, 'The Beginning After the End', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx183161-5M054tuPmZJX.jpg', 'series', '6.0', 'After a mysterious death, King Grey is reborn as Arthur Leywin on the magical continent of Dicathen. Although he enters his second life as a baby, his previous wisdom remains. He begins to master magic and forge his own path as the years go by, seeking to correct the mistakes of his past life. 

(Source: Crunchyroll)', 'studio A-CAT', '2025', 'series', 'released', '2025-04-03', 183161, 0, NULL, '2026-07-25 16:43:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/183161-L5X2veRcYJnh.jpg', 'Action, Adventure, Fantasy', 'TV', 'SPRING', 12, 93075, 'https://www.youtube.com/watch?v=LwCJhJbpg4Q', '2026-08-02 15:45:38', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (708, 'Dorohedoro', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx105228-I4xr84QS9Pvk.jpg', 'series', '7.9', 'The story revolves around Kaiman, who does not remember who he was before he was transfigured by a Magic user. This transformation left him with a reptile''s head, and a desire to find out the truth about who he really is. Accompanied by Nikaido, his female companion, he tracks down Magic Users in "The Hole" and unceremoniously chomps down on their head, hoping to find out who it was that put him in this state. One by one, they witness this "second man" inside the head of Kaiman, and after pulling them back out of his mouth he asks them all a question... "What did the guy inside my head say?"', 'MAPPA', '2020', 'series', 'released', '2020-01-13', 105228, 0, NULL, '2026-07-25 16:43:12', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/105228-QBAya2q8SP52.jpg', 'Action, Adventure, Comedy, Fantasy, Horror, Mystery', 'TV', 'WINTER', 12, 186574, 'https://www.youtube.com/watch?v=IS6l1K19N1U', '2026-08-02 15:45:44', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (709, 'Dorohedoro Season 3', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx212618-8qxOOnGuaVXV.jpg', 'coming', '0.0', 'The third season of Dorohedoro.', 'MAPPA', NULL, 'series', 'upcoming', NULL, 212618, 0, NULL, '2026-07-25 16:43:12', '2026-09-03 15:51:11', NULL, 'Action, Adventure, Comedy, Fantasy, Horror, Mystery', NULL, NULL, NULL, 7160, 'https://www.youtube.com/watch?v=ZHuQn27ps2E', '2026-09-03 15:51:11', NULL);
