INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (759, 'Gintama - The Movie', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx7472-RveDgQsIZUNG.jpg', 'movies', '8.3', 'Odd Jobs Gin has taken on a lot of odd work in the past, and when you''re a Jack of All Trades agency based in a feudal Japan that''s been conquered and colonized by aliens, the term "Odd Jobs" means REALLY ODD jobs. But when some more than slightly suspicious secrets from the shadows of Gintoki Sakata''s somewhat shady former samurai past and a new pair of odd jobs collide, the action is bound to get so wild and demented that only a feature film will do it justice! 

(Source: Sentai Filmworks)', 'Sunrise', '2010', 'movie', 'released', '2010-04-24', 7472, 0, NULL, '2026-07-25 16:45:13', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/7472-twXDSWVrxXMT.jpg', 'Action, Comedy, Sci-Fi', 'MOVIE', 'SPRING', 1, 39226, 'https://www.youtube.com/watch?v=VU_-I1Bup-U', '2026-08-02 15:48:41', NULL);
