INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (780, 'Hori-san to Miyamura-kun', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b14753-FKgfBa6AO5wg.jpg', 'series', '7.3', 'People say that the youthful days are always bittersweet, but maybe it''s just bitter? 


Kyouko Hori is a flashy high school girl, who, despite her ostentatious appearance, excels in academics and has a family-loving character. Izumi Miyamura is a bland high school boy, who, despite not wanting to stand out in class, secretly wears piercings outside of school and has a large body tattoo. 


One day, Miyamura finds Hori''s little brother injured and helps him back to Hori''s house, where the relationship between Hori and Miyamura begins with Hori''s discovery of Miyamura''s secret.', 'Hoods Entertainment', '2012', 'series', 'released', '2012-09-26', 14753, 0, NULL, '2026-07-25 16:45:55', '2026-09-02 16:57:33', NULL, 'Comedy, Romance, Slice of Life', 'OVA', 'SUMMER', 6, 42529, 'https://www.youtube.com/watch?v=NQZCfFDa0xM', '2026-08-08 14:34:55', NULL);
