INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (875, 'Doraemon: Nobita no Nankyoku Kachi Kochi Daibouken', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99085-ppQX61i1NWtg.jpg', 'movies', '7.2', 'Nobita and his friends find a strange frozen ring, which guides them to Antarctica in search of its owner. There, they stumble upon some ancient ruins and begin an adventure, facing the danger that the Earth may become frozen.

(Source: Anime News Network)', NULL, '2017', 'movie', 'released', '2017-03-04', 99085, 0, NULL, '2026-07-25 16:50:01', '2026-09-02 16:57:33', NULL, 'Comedy', 'MOVIE', 'SPRING', 1, 2129, 'https://www.youtube.com/watch?v=nYSQiUGd6nQ', '2026-08-02 16:06:29', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (876, 'Doraemon: Nobita no Takarajima', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99084-wbdkDmvL1edJ.jpg', 'movies', '7.2', 'Upon hearing about the story of Treasure Island, Nobita dreams of discovering and exploring his own treasure island, despite the fact all of the Earth has been mapped already. 

Doraemon provides Nobita a special treasure map that shows him the location of a treasure island. At the same time, the media announces the discovery of a completely unknown island. Believing the new island is the treasure island, Nobita recruits Doraemon and Shizuka to journey with him, with Doraemon providing a ship. Gian and Suneo also tag along. However, as they get near the island, they are suddenly attacked by a gang of pirates.

(Source: Wikipedia)', NULL, '2018', 'movie', 'released', '2018-03-03', 99084, 0, NULL, '2026-07-25 16:50:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99084-vYGcNpdrruzX.jpg', 'Comedy, Sci-Fi', 'MOVIE', 'WINTER', 1, 3203, 'https://www.youtube.com/watch?v=dlcDgmmjXTA', '2026-08-02 16:06:25', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (877, 'Doraemon the Movie 2019: Nobita''s Chronicle of the Moon Exploration', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx106493-TWaFM37aktmG.jpg', 'movies', '7.1', 'During a Japanese robotic exploration to find life on the other side of the moon, Nobita is watching from Earth and sees the moon turn yellow. With the help of Doraemon, the pair travel to the moon and create bunnies that will build their own colony. After he returns, Nobita tells his class about their adventure but no one will believe him. That is until a new student and his sister arrive who appear to come from a very far away place...

(Source: themoviedb)', 'Shin-Ei Animation', '2019', 'movie', 'released', '2019-03-01', 106493, 0, NULL, '2026-07-25 16:50:01', '2026-09-02 16:57:33', NULL, 'Adventure, Sci-Fi', 'MOVIE', 'WINTER', 1, 2220, 'https://www.youtube.com/watch?v=AHentd63YDo', '2026-08-02 16:06:22', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (878, 'STAND BY ME Doraemon', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/20515.jpg', 'movies', '7.8', 'The robotic cat was sent by a boy in the future to the present day to help the boy''s hapless grandfather, Nobita. Doraemon, Nobita, and other children deal with everyday childhood issues, solve (and cause) problems with the gadgets in Doraemon''s fourth-dimensional pocket, and embark on escapades through time and space.', 'Shin-Ei Animation', '2014', 'movie', 'released', '2014-08-08', 20515, 0, NULL, '2026-07-25 16:50:01', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Fantasy', 'MOVIE', 'SUMMER', 1, 13655, 'https://www.youtube.com/watch?v=IVuXGgOGR7Q', '2026-08-02 16:06:19', NULL);
