INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (880, 'Doraemon: Nobita no Space Heroes', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx100291-it9jcpdWucA3.jpg', 'movies', '6.9', NULL, 'Shin-Ei Animation', '2015', 'movie', 'released', '2015-03-03', 100291, 0, NULL, '2026-07-25 16:50:01', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Fantasy', 'MOVIE', 'WINTER', 1, 2663, 'https://www.youtube.com/watch?v=koNc8t9Ttyc', '2026-08-02 16:06:04', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (881, 'Doraemon: Nobita no Little Star Wars 2021', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx126783-sgkzDqBL7Gb0.jpg', 'movies', '6.9', 'One day during summer vacation, a palm-sized alien named Papi appears from a small rocket that Nobita picks up. He is the president of Pirika, a small planet in outer space, and has come to Earth to escape the rebels. Doraemon and his friends are puzzled by Papi''s small size, but as they play together using the secret tool "Small Light", they gradually become friends. However, a whale-shaped space battleship comes to earth and attacks Doraemon, Nobita and the others in order to capture Papi. Feeling responsible for getting everyone involved, Papi tries to stand up to the rebels. Doraemon and his friends leave for the planet Pirica to protect their dear friend and his home. 

(Source: Crunchyroll)', 'Shirogumi', '2022', 'movie', 'released', '2022-03-04', 126783, 0, NULL, '2026-07-25 16:50:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/126783-sUBBiHEwRHjL.jpg', 'Adventure, Comedy, Sci-Fi', 'MOVIE', 'WINTER', 1, 1752, 'https://www.youtube.com/watch?v=ltB3OMGqiY4', '2026-08-02 16:06:02', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (882, 'Doraemon: Shin Nobita no Nippon Tanjou', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx87438-GcZMWkkCFL2S.jpg', 'movies', '7.1', 'The 36th Doraemon movie. This is a remake of the 1989 film Doraemon: Nobita no Nippon Tanjou.

Nobita wants to run away from home, again. He finds out that there is nowhere for him to go. All the land is owned by someone. His friends end up wanting to run away also, even Doraemon. They figure out that the only way to find land that isn''t owned by anyone is to go back in time to when no humans existed. They end up helping a prehistoric boy rescue his tribe from Gigazombie.', 'Shin-Ei Animation', '2016', 'movie', 'released', '2016-03-05', 87438, 0, NULL, '2026-07-25 16:50:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/87438-JkFzpwp1LZLA.jpg', 'Adventure, Comedy, Fantasy', 'MOVIE', 'WINTER', 1, 2052, 'https://www.youtube.com/watch?v=ghjF37V1cW0', '2026-08-02 16:05:58', NULL);
