INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (896, 'Sword of the Stranger Pilot', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14617-YLbJRuhN3uQz.png', 'series', '6.2', 'In the Sengoku period, a rounin called Nanashi (meaning nameless) saves a young boy Kotarou and his dog Tobimaru at an abandoned temple. Kotarou has no family, is pursued by a mysterious militia organization from China, and hires Nanashi as his bodyguard. Among the pursuers is a man called Rarou, a very skilled warrior with blond hair and blue eyes. He obeys an old man called Byakuran and is a member of the Chinese militia. Unlike his companions in the militia, he is not serving any Emperor and just wants to fight with the strong.', 'bones', '2009', 'series', 'released', '2009-04-11', 14617, 0, NULL, '2026-07-25 16:50:24', '2026-09-02 16:57:33', NULL, 'Action, Adventure', 'SPECIAL', 'SPRING', 1, 3090, 'https://www.youtube.com/watch?v=ECRj6TKwPBg', '2026-08-02 16:07:10', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (897, 'Patema Inverted: Beginning of the Day', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx13429-lHJGMc0lvKuQ.jpg', 'series', '7.0', 'This is an online distribution of the prologue of the movie, illustrating the first day of the entire story.

A world, forever beyond your expectations. 

In a dark, cramped, underground world of endless tunnels and shafts, people wear protective suits and live out their modest yet happy lives. The princess of the underground community, Patema, goes out exploring as always, inspired by her curiosity of the unknown depths of the world. 

Her favorite spot is the "danger zone", an area forbidden by the "rule" of the community. Despite being frequently chastised by her caretaker Jii, she cannot hold back her curiosity for the reason behind the rule, because no one would tell her what the "danger" was. When she approaches the hidden "secret", the story begins. 

(Source: translation of a synopsis from the nicovideo news)', 'Purple Cow Studio Japan', '2012', 'series', 'released', '2012-02-26', 13429, 0, NULL, '2026-07-25 16:50:28', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/13429-0GMIcvFh36i9.jpg', 'Sci-Fi', 'SPECIAL', 'WINTER', 4, 9238, 'https://www.youtube.com/watch?v=Aa7sa-Zd-3E', '2026-08-02 16:07:15', NULL);
