INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (913, 'Anohana: The Flower We Saw That Day', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx9989-hImMg6kCMm6I.jpg', 'series', '8.0', 'Jinta Yadomi and his group of childhood friends have become estranged after a tragic accident split them apart. Now in their high school years, a sudden surprise forces each of them to confront their guilt over what happened that day and come to terms with the ghosts of their past. 

(Source: NIS America)', 'A-1 Pictures', '2011', 'series', 'released', '2011-04-15', 9989, 0, NULL, '2026-07-25 16:51:11', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/9989-pyr6rXlV1oAm.jpg', 'Drama, Romance, Slice of Life, Supernatural', 'TV', 'SPRING', 11, 389301, 'https://www.youtube.com/watch?v=oDWkt8wcYh8', '2026-08-08 14:32:04', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (917, 'Sound! Euphonium 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21460-B52Z2pICE11i.png', 'series', '8.3', 'With another tournament fast approaching, Kumiko''s band is doubling down on practice and discipline, leaving little time for sleep or other recreational activities. The redoubled practice schedule brings Kumiko and Reina closer together, but elsewhere in the band, it seems like drama threatens to tear the group''s unity apart. The ghost of the prior year''s mass band exodus still haunts many of Kumiko''s classmates, and with former band member Nozomi Kasaki now asking to return, it seems like the grudges of the past will soon be impossible to ignore.

(Source: Anime News Network, edited)

Note: The first episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.', 'Kyoto Animation', '2016', 'series', 'released', '2016-10-06', 21460, 0, NULL, '2026-07-25 16:51:21', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21460-hAHHLxSxkxr0.jpg', 'Drama, Music, Slice of Life', 'TV', 'FALL', 13, 76783, 'https://www.youtube.com/watch?v=lAHOb96Nnfw', '2026-08-02 16:08:27', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (918, 'Sound! Euphonium The Movie — May the melody reach you! —', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx98876-krwPsUODyWin.jpg', 'movies', '7.7', 'A compilation film recapping the events from the second season of the anime television series.', 'Kyoto Animation', '2017', 'movie', 'released', '2017-09-30', 98876, 0, NULL, '2026-07-25 16:51:21', '2026-09-02 16:57:33', NULL, 'Drama, Music, Slice of Life', 'MOVIE', 'SUMMER', 1, 12072, 'https://www.youtube.com/watch?v=I4r0wHTyIVM', '2026-08-02 16:08:31', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (919, 'Sound! Euphonium: The Movie - Our Promise: A Brand New Day', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101992-VZSoKfiRXscs.jpg', 'movies', '7.7', 'The next piece begins! Kumiko is now in her second year at Kitauji High School, and with a new year comes new problems. As if making it to Nationals wasn''t hard enough, Kumiko is tasked with mentoring the concert band''s troublesome first years – each with their own distinct personality and problems to solve. With Kumiko busy juggling both the concert band and her new role as senpai, how does her relationship with Shuuichi fit into the picture?

(Source: Shout! Factory)', 'Kyoto Animation', '2019', 'movie', 'released', '2019-04-19', 101992, 0, NULL, '2026-07-25 16:51:21', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101992-ymVmRVjQC1hd.jpg', 'Drama, Music, Slice of Life', 'MOVIE', 'SPRING', 1, 35151, 'https://www.youtube.com/watch?v=p4m7wgSiDhM', '2026-08-08 14:09:50', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (920, 'Tokubetsu-hen Hibike! Euphonium: Ensemble Contest', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx150429-5KvbB5BBt2Yz.jpg', 'series', '7.8', 'Along with the summer brass band competition, the ensemble contest, commonly known as "Ancon," is a place where exciting performances are held. The performance of several people in one group has a charm different from that of a competition.

In order to participate in the Kyoto prefectural tournament of Ancon, a representative team is selected in the school''s preliminary round. However, with over 50 members, the Kitauji High School brass band is facing a variety of problems! Will Kumiko, the newly appointed head of the club, be able to make it through the preliminary rounds?

The days of struggle begin.

(Source: Official Site, translated)', 'Kyoto Animation', '2023', 'series', 'released', '2023-08-04', 150429, 0, NULL, '2026-07-25 16:51:21', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/150429-Fc76D3oIqTdk.jpg', 'Drama, Music, Slice of Life', 'OVA', 'SUMMER', 1, 19070, 'https://www.youtube.com/watch?v=WOZVcPNaapo', '2026-08-02 16:08:56', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (921, 'The Moment You Fall in Love', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx21757-zH78HtS4b0GU.png', 'movies', '6.8', 'Second film starring characters from the HoneyWorks vocaloid group.', 'Qualia Animation', '2016', 'movie', 'released', '2016-12-17', 21757, 0, NULL, '2026-07-25 16:51:23', '2026-09-02 16:57:33', NULL, 'Drama, Romance, Slice of Life', 'MOVIE', 'FALL', 1, 35883, 'https://www.youtube.com/watch?v=lA-T5l5LVl4', '2026-08-08 14:09:53', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (922, 'Our love has always been 10 centimeters apart.', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx98977-CpZkd98fWj32.jpg', 'series', '7.2', 'The moment Miou Aida first met Haruki Serizawa at the Sakuragaoka High School Entrance Ceremony they both felt an unexplainable connection. Despite their completely different personalities, they found themselves walking home together after school every day. As they spend more time together, their feelings for each other grow stronger. Just 10 centimeters apart, but the distance remains...

(Source: Funimation)', 'Lay-duce', '2017', 'series', 'released', '2017-11-25', 98977, 0, NULL, '2026-07-25 16:51:23', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n98977-5qvKUog5OfWu.jpg', 'Drama, Romance, Slice of Life', 'TV', 'FALL', 6, 66766, 'https://www.youtube.com/watch?v=9y9JtkUiuz4', '2026-08-02 16:09:24', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (923, 'Zutto Mae kara Suki deshita.: Kokuhaku Jikkou Iinkai - Kinyoubi no Ohayou', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/n107352-ZdT0yfOgmsh5.jpg', 'series', '6.9', 'A picture drama special bundled with the BD/DVD release of the main film. It focuses on the relationship between Sena and Midori.', NULL, '2016', 'series', 'released', '2016-10-26', 107352, 0, NULL, '2026-07-25 16:51:23', '2026-09-02 16:57:33', NULL, 'Romance', 'SPECIAL', 'FALL', 1, 8587, 'https://www.youtube.com/watch?v=EQbOQJx2ZWE', '2026-08-02 16:09:27', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (924, 'Is It Wrong to Try to Pick Up Girls in a Dungeon?', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20920-MTREwZOG4BAD.jpg', 'series', '7.3', 'Some adventurers delve into the sprawling labyrinths beneath the city of Orario to find fame and fortune. Others come to test their skills against the legions of monsters lurking in the darkness below. However, Bell Cranel’s grandfather told him a different reason: it’s a great place to rescue (and subsequently meet) girls! Now that Bell’s a dungeon delver himself, the ladies he’s encountering aren’t the helpless damsels in distress he’d imagined, and one of them, the beautiful swordswoman Ais Wallenstein, keeps rescuing Bell instead. As embarrassing as that is, it’s nothing compared to what happens when goddesses get involved. Freya, Hephaistos, and Loki, with their powerful Familias, are intimidating enough, but there’s one goddess whose relationship with Bell is certain to spark trouble.

(Source: Sentai Filmworks)', 'J.C.STAFF', '2015', 'series', 'released', '2015-04-04', 20920, 0, NULL, '2026-07-25 16:51:25', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20920-QZeO1gVTQSUZ.jpg', 'Action, Adventure, Comedy, Fantasy, Romance', 'TV', 'SPRING', 13, 390608, 'https://www.youtube.com/watch?v=sbcwRt0y4kY', '2026-08-08 14:29:05', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (925, 'Pokémon: Pikachu''s Vacation', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/5526-H6YvOJIJxU4q.png', 'series', '6.5', 'Ash and his friends arrive at a Pokémon-only park. They set all their Pokémon loose and, after Ash tells Pikachu to watch over Togepi, they enter for a day of fun and relaxation. Unfortunately, it''s not going to turn out the way they had hoped.

(Source: Serebii)', 'OLM', '1998', 'series', 'released', '1998-07-18', 5526, 0, NULL, '2026-07-25 16:51:29', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n5526-wfu7VdeLfQan.jpg', 'Adventure, Comedy, Fantasy', 'SPECIAL', 'SUMMER', 1, 9175, 'https://www.youtube.com/watch?v=1roy4o4tqQM', '2026-08-02 16:09:31', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (926, 'the Garden of sinners Chapter 4: garan-no-dou. (The Hollow Shrine)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx4280-GKUNVjzu5sUO.png', 'movies', '7.5', 'June, 1998: After spending two years in a coma caused by a traffic accident, Shiki Ryougi awakens with amnesia. She is visited by Touko Aozaki, a wizard and proprietor of a studio called Garan no Dou. Shiki has lost not only the memory of her accident, but also any real sense that she''s even alive. Strangely, enigmatic beings begin to attack her...


(Source: Aniplex USA)', 'ufotable', '2008', 'movie', 'released', '2008-05-24', 4280, 0, NULL, '2026-07-25 16:51:31', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4280-A8petxxG2rpf.jpg', 'Action, Mystery, Supernatural, Thriller', 'MOVIE', 'SPRING', 1, 57161, 'https://www.youtube.com/watch?v=Z8e0sce_PC8', '2026-08-29 14:54:33', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (927, 'Overlord IV', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx133844-E32FjKZ0XxEs.jpg', 'series', '8.0', 'The fourth season of Overlord.

E-Rantel, the capital city of the newly established Sorcerer Kingdom, suffers from a dire shortage of goods. Once a prosperous city known for its trade, it now faces a crisis due to its caution—or even fear—of its king, Ainz Ooal Gown. To make amends, Ainz sends Albedo to the city as a diplomatic envoy.

Meanwhile, the cardinals of the Slane Theocracy discuss how to retaliate against Ainz after his attack crippled the Re-Estize Kingdom''s army, plotting for the Baharuth Empire to take over the Sorcerer Kingdom. However, when Emperor Jircniv Rune Farlord El Nix arranges a meeting with the Theocracy''s messengers at a colosseum, he is confronted by none other than Ainz himself.

With their secret gathering now out in the open, the emperor and his guests learn that Ainz has challenged the Warrior King, the empire''s greatest fighter, to a duel. With Ainz''s motivations beyond his comprehension, Jircniv can do nothing but watch as humanity''s future changes before his very eyes.

(Source: MAL Rewrite)', 'MADHOUSE', '2022', 'series', 'released', '2022-07-05', 133844, 0, NULL, '2026-07-25 16:51:46', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/133844-uIaUmh5aJX3M.jpg', 'Action, Adventure, Fantasy', 'TV', 'SUMMER', 13, 174450, 'https://www.youtube.com/watch?v=tNYQjEyTO6s', '2026-08-02 16:09:35', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (928, 'In This Corner (and Other Corners) of the World', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx112135-SZwCaYm8WwR0.png', 'movies', '8.0', 'Suzu is a quiet and ordinary -- if not a bit of clumsy and daydreaming -- girl growing up in the outskirts of the city of Hiroshima in mid-1930s. She loves drawing sketches with pencils -- a hobby she is really good at. Following her parents'' arrangement in 1943, 18-year-old Suzu is married to a young man living in Kure, a neighboring city with a large naval base, in which he works as a civilian secretary for the military tribunal. There she faces a new life, a new family, as well as many new challenges and hardships, particularly with the worsening life conditions due to the Pacific War. Yet Suzu manages to find happiness and peace in her daily life. 

The concept behind the film is to give the perspective of "several more lives" in addition to Suzu''s, so it has a new title to reflect the new theme. It will adapt more scenes from the manga.

The new scenes include Suzu crossing paths with Rin in the fall of 1944 and the winter and spring of 1945. Rin features prominently in the new visual above and the video below. Another new segment will focus on the Makurazaki Typhoon of September 1945, while Suzu is worried for her younger sister Sumi.

(Source: Anime News Network)', 'MAPPA', '2019', 'movie', 'released', '2019-12-20', 112135, 0, NULL, '2026-07-25 16:51:47', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/112135-VtUn87kDAadW.jpg', 'Drama, Slice of Life', 'MOVIE', 'FALL', 1, 6145, 'https://www.youtube.com/watch?v=GZW1fIkMVc8', '2026-08-02 16:09:38', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (929, 'PSYCHO-PASS 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20513-pVQqYhMwBGoh.jpg', 'series', '7.1', 'Taking place one-and-a-half years after Psycho-Pass, having learned the true nature of the Sibyl System, Akane Tsunemori chose to obey the system, believing in both humanity and the legal order. She''s part of a new police section and spends her everyday life facing down criminals. Unbeknownst to Akane, however, a monster who will shake the system to its core is about to appear before her.

(Source: Anime News Network)', 'Tatsunoko Production', '2014', 'series', 'released', '2014-10-10', 20513, 0, NULL, '2026-07-25 16:51:53', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20513-dpjLwKrlNnJf.jpg', 'Action, Psychological, Sci-Fi, Thriller', 'TV', 'FALL', 11, 137625, 'https://www.youtube.com/watch?v=CfQipxKwPbo', '2026-08-08 14:29:19', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (930, 'PSYCHO-PASS: Sinners of the System 2 - First Guardian', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx104382-uUSwPWXZ8f8n.jpg', 'movies', '7.3', '2112; the summer before Akane Tsunemori was assigned to Division One of the Public Safety Bureau''s Criminal Investigation Department. Teppei Sugo, an accomplished pilot of the Defense Force''s 15th Joint Task Force, joins the military operation in Okinawa. Three months later, an unmanned combat drone opens fire on the Ministry of Defense in Tokyo. Enforcer Tomomi Masaoka of CID Division One is dispatched to Sugo''s military base to investigate the truth behind this case.

(Source: Official Website, translated by Edo)', 'Production I.G', '2019', 'movie', 'released', '2019-02-15', 104382, 0, NULL, '2026-07-25 16:51:53', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/104382-5TpwI416Oe6r.jpg', 'Action, Psychological, Sci-Fi, Thriller', 'MOVIE', 'WINTER', 1, 32347, 'https://www.youtube.com/watch?v=MXlw5Bb0CRc', '2026-08-02 16:09:41', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (931, 'Beyond the Boundary -I''LL BE HERE-: Past', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20768-xwQobWzMYTd4.png', 'movies', '7.5', 'This is the first part of a two-part movie. The story is a recap of the TV series.', 'Kyoto Animation', '2015', 'movie', 'released', '2015-03-14', 20768, 0, NULL, '2026-07-25 16:51:55', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n20768-XaSSBUJpLqNy.jpg', 'Drama, Fantasy, Slice of Life, Supernatural', 'MOVIE', 'WINTER', 1, 40660, 'https://www.youtube.com/watch?v=61XEPUaWiQk', '2026-08-08 14:09:56', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (932, 'Beyond the Boundary', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx18153-oDqA9zQzQPOq.png', 'series', '7.4', 'They should never have met. They shouldn''t even exist. But when they come together, the entire world will change. The last surviving member of her clan, Mirai Kuriyama is cursed with the terrifying ability to control and manipulate blood, a power so heretical that she is shunned even by those with the ability to understand her "gift". Akihito Kanbara is only half human, but while the monstrous other half of his lineage seems to have doomed him to a life alone, it has also given him near invulnerability in the form of rapid healing. Alone, their futures seem bleak, but when a chance encounter brings them together, it becomes clear that they share more than just an unexpected bond. Together they share a destiny and a mission that only the two of them together may be strong enough to survive.

(Source: Sentai Filmworks)', 'Kyoto Animation', '2013', 'series', 'released', '2013-10-03', 18153, 0, NULL, '2026-07-25 16:51:55', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/18153-Pw3uKfv6ZNqP.jpg', 'Action, Drama, Fantasy, Slice of Life, Supernatural', 'TV', 'FALL', 12, 276700, 'https://www.youtube.com/watch?v=BnfeVrAAS2k', '2026-08-08 14:29:21', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (933, 'the Garden of sinners Chapter 6: Fairy Tale. (Oblivion Recording)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx5204-6PdYdIXswcEo.png', 'movies', '7.0', 'January, 1999: Apprentice mage Azaka Kokutou, Mikiya''s younger sister, has been ordered by her mentor, Touko Aozaki, to investigate a certain incident in which fairies steal the memories of students at Azaka''s school, Reien Academy. Azaka launches an investigation with the help of Shiki.


(Source: Aniplex USA)', 'ufotable', '2008', 'movie', 'released', '2008-12-20', 5204, 0, NULL, '2026-07-25 16:51:56', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/5204-09vEnPmj98Ba.jpg', 'Action, Mystery, Romance, Supernatural, Thriller', 'MOVIE', 'WINTER', 1, 52400, 'https://www.youtube.com/watch?v=XVAJ1o_fsbY', '2026-08-29 14:54:30', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (934, 'Death Parade', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx20931-bktYqOcxPERi.jpg', 'series', '8.0', 'When two people die at the same time, they’re sent to a place that’s neither heaven nor hell—a lavish bar between worlds where the stakes are high and the rules are simple: if you win you live again, if you die… you’re gone for good.

Decim is the bartender charged with serving the souls who enter Quindecim. He may make a mean cocktail, but his true profession is to play the role of arbiter—a judge who determines whether or not a soul is worthy of reincarnation. To aid in his judgment, the bar’s patrons are forced to play simple games laced with sadistic twists designed to bring their true natures to light. To Decim, judgment has always been black and white—that is—until he meets a mysterious young woman whose fate seems impossible to decide. His indecision shakes the very foundation of the games and raises the biggest question of all: Who is fit to judge the dead?

(Source: Funimation)', 'MADHOUSE', '2015', 'series', 'released', '2015-01-10', 20931, 0, NULL, '2026-07-25 16:52:00', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20931-xDhiTPZmtS3u.jpg', 'Drama, Mystery, Psychological, Supernatural, Thriller', 'TV', 'WINTER', 12, 460683, 'https://www.youtube.com/watch?v=n9lr8jqI-24', '2026-08-08 14:09:58', NULL);
