INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (936, 'BAKI-DOU: The Invincible Samurai', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx176509-GRUa4fzyAM9u.jpg', 'series', '7.5', 'Musashi Miyamoto — the ultimate symbol of strength — descends into an underground fighting arena where the use of weapons is permitted. Underground fighters including Doppo Orochi, Goki Shibukawa and Sea King Retsu square off in succession against Musashi and his godlike strength. It’s sword versus fist in the most heart-pounding and deadly battles yet, where defeat means certain death. 

Be prepared to be blown away by Baki and the other underground fighters as they bravely take on this new battle to determine the strongest fighter in human history. 

(Source: Netflix)', 'TMS Entertainment', '2026', 'series', 'released', '2026-02-26', 176509, 0, NULL, '2026-07-25 16:52:11', '2026-09-02 16:57:33', NULL, 'Action, Sports', 'ONA', 'WINTER', 13, 14913, 'https://www.youtube.com/watch?v=_TYx9iNvk9E', '2026-08-08 14:10:04', NULL);
