INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (944, 'The Disastrous Life of Saiki K. Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx98034-1eQ4F7SKxVas.jpg', 'series', '8.4', 'The disastrous life of the gifted psychic Kusuo Saiki continues, despite his utmost effort to live an ordinary life. Although he has certainly grown accustomed to dealing with his troublesome friends—who are his biggest hurdle to achieving a peaceful life—he still has a long way to go. Also joining the usual oddballs are a few new faces whose shenanigans add to Saiki''s misery, making his dreams of a hassle-free life a distant fantasy.', 'J.C.STAFF', '2018', 'series', 'released', '2018-01-17', 98034, 0, NULL, '2026-07-25 16:52:29', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/98034-PiUB6liaekfW.jpg', 'Comedy, Slice of Life, Supernatural', 'TV', 'WINTER', 24, 186501, 'https://www.youtube.com/watch?v=sbw7QB6nrTc', '2026-08-08 14:10:23', NULL);
