INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (992, 'Zhe Tian Movie: Bei Guan Zhan Wang Teng', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx213664-hGF6TYElYNcy.jpg', 'series', '0.0', 'Ye Fan and Wang Teng, two prodigies of their generation, are destined for a climactic confrontation shaped by fate and rivalry. As the Northern Wang Clan advances with overwhelming force, hidden schemes within the Ji family begin to surface. Ji Ziyue becomes entangled as a pawn in a political marriage, while Ye Fan finds himself surrounded by enemies and pressure from all sides. Amid escalating tensions, the conflict between the Desolate Ancient Sacred Physique and the inheritance of ancient chaotic traditions erupts. In this battle of geniuses, the question remains—who truly possesses the bearing of a future Great Emperor?

(Source: Tencent, translated)', 'Original Force', '2026', 'series', 'released', '2026-04-04', 213664, 0, NULL, '2026-07-25 16:53:34', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Fantasy', 'ONA', NULL, 1, 114, 'https://www.youtube.com/watch?v=vp_3wCEFW_M', '2026-08-08 14:12:53', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (993, 'BanG Dream!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx87435-yHlVTP1HFiXH.png', 'series', '6.8', 'Kasumi Toyama was enthralled by the stars as a young girl, so when she discovers a trail of star-shaped signs one day after transferring to a new school, she can''t help but follow them. They lead her to a shop run by the grandmother of one of her new classmates, and Kasumi finds something that will change her life forever: a star-shaped guitar! And just like that, Kasumi knows that forming a band is her destiny.

Of course, convincing Arisa and her grandmother to sell her the guitar won''t be easy, and finding a group of other girls who want to become musicians will be even harder. But when a girl has stars in her eyes and a starbeat in her heart, there''s nothing that will stop Kasumi from making her fantasies come true!

(Source: Sentai Filmworks)', 'Xebec', '2017', 'series', 'released', '2017-01-21', 87435, 0, NULL, '2026-07-25 16:53:39', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/87435-5sL6SrIBG3K5.jpg', 'Comedy, Drama, Music, Slice of Life', 'TV', 'WINTER', 13, 39558, 'https://www.youtube.com/watch?v=yNMj1ZwB9QY', '2026-08-08 14:12:56', NULL);
