INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1019, 'Fullmetal Alchemist: The Movie - Conqueror of Shamballa', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx430-Fx7lVxpcwArH.jpg', 'movies', '7.1', 'Munich, Germany, 1923. Two years have passed since Edward Elric was dragged from his own world to ours, leaving behind his country, his friends and his younger brother, Alphonse. Stripped of his alchemical powers, he has been all this time researching rocketry together with Alphonse Heiderich, a young man who resembles his own brother, hoping to one day find a way back home. His efforts so far had proven fruitless, but after lending a hand to a troubled gypsy girl, Edward is thrown in a series of events that can wreak havoc in both worlds. Meanwhile, at his own world, Alphonse Elric ventures deeper into the mysteries of alchemy in search for a way to reunite with his older brother.

(Source: Anime News Network)', 'bones', '2005', 'movie', 'released', '2005-07-23', 430, 0, NULL, '2026-07-25 16:54:23', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/430-G07rfvPsD2Zg.jpg', 'Action, Comedy, Drama, Fantasy', 'MOVIE', 'SUMMER', 1, 55523, 'https://www.youtube.com/watch?v=9M49TDkY46s', '2026-08-08 14:14:04', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1020, 'Fullmetal Alchemist: Premium OVA Collection', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/908.jpg', 'series', '6.8', '1. State Alchemists vs Seven Homunculi

A 10 minute film featuring: Ed, Al, Mustang and many other members of the State doing battle with the deadly Homonculi in an alternate reality Amestris.


2. Chibi Party (Enkai-hen)

Short 6 minute Skit drawn in Super Deformed style where every character in the series (including bad guys) are celebrating an "After Party" of the Conqueror of Shambala movie.


3. Kids (Kodomo-hen)

Short 3 minute story which features Edward and his grankids in present day 2005.

(Source: Anime News Network)', 'bones', '2006', 'series', 'released', '2006-03-29', 908, 0, NULL, '2026-07-25 16:54:23', '2026-09-02 16:57:33', NULL, 'Comedy, Fantasy', 'OVA', 'SPRING', 3, 13121, 'https://www.youtube.com/watch?v=vIdwbpsD_44', '2026-08-08 14:14:06', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1021, 'Hagane no Renkinjutsushi: Milos no Seinaru Hoshi Tokubetsu Eizou', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/10842.jpg', 'series', '6.1', 'To mark the July 2 opening of the Fullmetal Alchemist: The Sacred Star of Milos film, the Pia Eiga Seikatsu website posted an exclusive video "interview" with the stars of the film, Edward and Alphonse Elric (as voiced by Romi Park and Rie Kugimiya, respectively). In keeping with the spirit of Hiromu Arakawa''s original manga and the two television anime, the interviewer has trouble early on in figuring out who the "Fullmetal Alchemist" is. (The interview has cameos by the other stars of the anime.) Also includes 3 "Study" sessions with "Professor" Mustang, teaching Winry and Hawkeye about Creta and Milos.', 'bones', '2011', 'series', 'released', '2011-06-16', 10842, 0, NULL, '2026-07-25 16:54:28', '2026-09-02 16:57:33', NULL, 'Comedy, Fantasy', 'SPECIAL', 'SUMMER', 4, 4533, 'https://www.youtube.com/watch?v=EpDMpSzMFbo', '2026-08-08 14:14:09', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1022, 'JoJo''s Bizarre Adventure (TV)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14719-VT5dRzTBSZ0w.jpg', 'series', '7.7', 'Beginning its tale in 19th century England, young aristocrat Jonathan Joestar finds himself locked in bitter rivalry with Dio Brando, a low-born boy who Jonathan''s father took under his wing after the death of Dio''s father. Discontent with his station in life, Dio''s fathomless lust to reign over all eventually leads him to seek the supernatural powers of an ancient Aztec stone mask in the Joestar''s possession—an artifact that will forever change the destiny of Dio and Jonathan for generations to come.

Fifty years later, in 1938 New York City, Jonathan''s grandson Joseph Joestar must take up his grandfather''s mission and master the abilities necessary to destroy the stone mask and its immensely powerful creators who threaten humanity''s very existence, the Pillar Men.

(Source: Anime News Network)', 'david production', '2012', 'series', 'released', '2012-10-06', 14719, 0, NULL, '2026-07-25 16:54:32', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/14719-m7Hv2AxcNNjM.jpg', 'Action, Adventure, Supernatural', 'TV', 'FALL', 26, 469737, 'https://www.youtube.com/watch?v=43qoWFJbWF0', '2026-08-08 14:34:49', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1023, 'HAIKYU!! 3rd Season', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21698-RL71mr1YU5Io.png', 'series', '8.7', 'After the victory against Aoba Jousai High, Karasuno High School, once called “a fallen powerhouse, a crow that can’t fly,” has finally reached the climax of the heated Spring tournament. Now, to advance to nationals, the Karasuno team has to defeat the powerhouse Shiratorizawa Academy. Karasuno’s greatest hurdle is their adversary’s ace, Wakatoshi Ushijima, the number one player in the Miyagi Prefecture, and one of the country’s top three aces.

Only the strongest team will make it to the national tournament. Since this match is the third-year players’ last chance to qualify for nationals, Karasuno has to use everything they learned during the training camp and prior matches to attain victory. Filled with restlessness and excitement, both teams are determined to come out on top in the third season of Haikyuu!!.

[Written by MAL Rewrite]', 'Production I.G', '2016', 'series', 'released', '2016-10-08', 21698, 0, NULL, '2026-07-25 16:54:36', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21698-jVFRIHAENS5B.jpg', 'Comedy, Drama, Sports', 'TV', 'FALL', 10, 357507, 'https://www.youtube.com/watch?v=kJfU5boNUIE', '2026-08-08 14:14:12', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1024, 'HAIKYU!!: VS Failing Marks', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21348-VIKyHcNUWIlb.jpg', 'series', '7.7', 'In this episode, which takes place after the first season, Hinata and Kageyama fail a test and find that the make-up exam conflicts with their training camp.

Note: The OVA was screened at Jump Festa 2015 on November 3, 2015. It was later bundled with the 21st volume of the manga.

(Source: Hummingbird)', 'Production I.G', '2015', 'series', 'released', '2015-11-03', 21348, 0, NULL, '2026-07-25 16:54:36', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21348-Baut72cxKVUq.jpg', 'Comedy, Drama, Sports', 'SPECIAL', 'FALL', 1, 33774, 'https://www.youtube.com/watch?v=LT4BfS57kP0', '2026-08-08 14:14:18', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1025, 'My Hero Academia Season 5 OVA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx149073-ATpEgEZNDheZ.jpg', 'series', '6.8', 'Original animation episodes for the fifth season of Boku no Hero Academia.

Entry includes: 

1) Boku no Hero Academia: HLB (My Hero Academia: HLB) 

HLB stands for “Hero League of Baseball” - it is a baseball league founded by pro-heroes who love baseball!

 It’s game day! The last game of HLB championship is between Gang Orca and Shishido''s two rival agencies. They form a team (“Orcas” and “Lionels”) to compete. In the world of HLB, there is no rule – using their quirks is of course accepted. However, just when the game is about to finish, they are interrupted by a villain. Who will be the winner of HLB!? 

2) Boku no Hero Academia: Warae! Jigoku no You ni (My Hero Academia: Laugh! As if you are in hell)

Deku, Bakugo, and Todoroki participate in internship under the No.1 hero, Endeavor''s agency. One of their tasks these days is to find a villain (“Smiley”) who draws doodles in the city. However, since the urgency is so low, they let other pro-heroes solve this case. One day, Smiley draws a doodle on Endeavor’s house! Being furious, Endeavor himself and the 1-A trio go out to get the villain. However, Smiley’s quirk turns out to be something ridiculous but powerful... It is to make anyone who looks into his eyes laugh hysterically! Can the team capture the villain and stop laughing!? 

(Source: Crunchyroll) 

Note: The ONA had a preliminary showing in theaters from June 16 to June 19 as part of  "Hero Day" 2022.', 'bones', '2022', 'series', 'released', '2022-08-01', 149073, 0, NULL, '2026-07-25 16:54:45', '2026-09-02 16:57:33', NULL, 'Action, Comedy, Sports', 'ONA', 'SUMMER', 2, 20611, 'https://www.youtube.com/watch?v=aeLbz3Y1D0I', '2026-08-08 14:14:21', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1026, 'ONE PIECE in LOVE: ONE PIECE DAY’25 Festival Eve Special', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx197179-ZiG6K2SkSsPU.jpg', 'series', '5.9', 'The special episode “ONE PIECE in LOVE: ONE PIECE DAY’25 Festival Eve Special”, which was surprise-screened at the ONE PIECE DAY’25 DAY1 on Saturday, August 9, 2025. 

This time, the characters of ONE PIECE in LOVE join in on the fun of ONE PIECE DAY’25! The episode also features Hiroshi Kitadani—known for the first ONE PIECE opening theme” We Are!”—making his debut as a voice actor!

(Source: ONE PIECE Official YouTube Channel, edited)

Note: This short briefly mentions some content from the Elbaf arc in the manga.', 'Toei Animation', '2025', 'series', 'released', '2025-08-09', 197179, 0, NULL, '2026-07-25 17:03:23', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/197179-fu2DKwrWOD4u.jpg', 'Comedy', 'SPECIAL', 'SUMMER', 1, 922, 'https://www.youtube.com/watch?v=DMAEZu4h4as', '2026-08-08 14:14:23', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1027, 'One Piece: Episode Of Chopper +: The Miracle Winter Cherry Blossom', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx3848-SCnYGTn34Llt.jpg', 'movies', '7.1', 'The movie is a retelling of the Drum Island arc with new music and animation. Vivi has been removed from the plot while both Nico Robin and Franky, who joined the crew after the Drum Island arc, have been added. The movie also has the Straw Hat''s new ship, the Thousand Sunny. It has been stated that Oda will be creating a new character for this movie, Wapol''s older brother, Mushul, who also appears to be a Devil Fruit user.', 'Toei Animation', '2008', 'movie', 'released', '2008-03-01', 3848, 0, NULL, '2026-07-25 17:03:39', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/3848-LXsSQtSFu4e9.jpg', 'Action, Adventure, Comedy, Fantasy', 'MOVIE', 'SPRING', 1, 16431, 'https://www.youtube.com/watch?v=MrJpZZYdhrU', '2026-08-08 14:14:26', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1028, 'One Piece: The Desert Princess and the Pirates, Adventures in Alabasta', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2107-H8bRuRRbhCIJ.jpg', 'movies', '7.0', 'A retelling of the Alabasta arc. 

Revolution is brewing in the desert country of Alabasta, but the Straw Hats and Princess Vivi know the truth: it''s all a plot cooked up by Crocodile. 

(Source: Netflix)', 'Toei Animation', '2007', 'movie', 'released', '2007-03-03', 2107, 0, NULL, '2026-07-25 17:03:42', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2107-Je0JIEoxx1VF.jpg', 'Action, Adventure, Fantasy', 'MOVIE', 'SPRING', 1, 17480, 'https://www.youtube.com/watch?v=7xwxXAk-Kwg', '2026-08-08 14:14:29', NULL);
