INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1031, 'Pokémon the Series: Diamond and Pearl', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1565-aJC0XivLqQXY.png', 'series', '7.1', 'After defeating Brandon and declining the offer to be a Frontier Brain, Ash sets off to travel through the far away land of Sinnoh. Once he gets there, he meets up with Hikari, a local trainer from the region, and they decide to travel together.', 'OLM', '2006', 'series', 'released', '2006-09-28', 1565, 0, NULL, '2026-07-25 17:04:17', '2026-09-03 16:00:32', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1565-FqJ9UkMhaSk6.jpg', 'Action, Adventure, Comedy, Fantasy', 'TV', 'FALL', 191, 42331, NULL, '2026-09-03 16:00:32', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1032, 'Pokémon: Jirachi Wish Maker', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1121-yGTHBrWFTiBm.jpg', 'movies', '6.5', 'This is the 6th Movie.

Satoshi, Haruka, Takeshi, and Masato come upon the festival of the Wishing Star of Seven Nights. During their enjoyment, the legendary pokemon, Jirachi, decends from the heavens and befriends Masato. Jirachi, with the power to grant any wish, is sought after by many people wanting to claim its power. One man seeks to use its legendary power to revive an ancient pokemon known as Groudon, unaware of the dangers hidden within Jirachi''s powers

(Source: Anime News Network)', 'OLM', '2003', 'movie', 'released', '2003-07-19', 1121, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1121-LhsnfC8GFvrL.jpg', 'Action, Adventure, Comedy, Drama, Fantasy', 'MOVIE', 'SUMMER', 1, 27157, 'https://www.youtube.com/watch?v=q473gvctl-w', '2026-08-08 14:14:40', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1033, 'Pokémon: Destiny Deoxys', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1122-HCkAs0hqlJwK.jpg', 'movies', '6.7', 'Satoshi and his friends travel to LaRousse, where they meet a boy named Tooi who is afraid of Pokemon due to an incident that happened four years earlier. Meanwhile, Deoxys, a Pokemon from space, has reappeared, putting a barrier around the city and kidnapping people. Rayquaza, a Pokemon that lives in the atmosphere, comes to fight it.

(Source: Anime News Network)', 'OLM', '2004', 'movie', 'released', '2004-07-17', 1122, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1122-hGrRYfEr0Nrd.jpg', 'Action, Adventure, Comedy, Fantasy, Sci-Fi, Supernatural', 'MOVIE', 'SUMMER', 1, 30784, 'https://www.youtube.com/watch?v=nKDWO2qY1Pk', '2026-08-08 14:14:37', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1034, 'Pokémon: Lucario and the Mystery of Mew', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b1526-ddJiHHGNikuY.png', 'movies', '7.1', 'This is the 8th Movie.

In the town of Lohta, a festival is thrown praising "Aaron the Wave Leader Hero" who, according to the legend passed down through the town''s generations, stopped a war centuries ago by using the power of "the Tree of the World''s Origin." Satoshi and Pikachu participate in a battle to decide this year''s hero and after their victory, they are chosen as the "Wave Leader Hero." A grand dance party is held in the castle to celebrate the victor, but suddenly the phantom Pokemon Mew appears and takes Pikachu. Soon afterwards, the Wave Leader Pokemon "Lucario" is freed from his centuries-long seal and meets Satoshi. Satoshi must solve the various mysteries of where Pikachu is, what Mew''s after, what the secret of the legend of the Wave Leader is and how it ties in with Lucario''s hidden past as he makes his way to "the Tree of the World''s Origin" with Lucario.

(Source: Anime News Network)', 'OLM', '2005', 'movie', 'released', '2005-07-16', 1526, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1526-r0zmA8mYNJeH.jpg', 'Action, Adventure, Drama, Fantasy', 'MOVIE', 'SUMMER', 1, 31830, 'https://www.youtube.com/watch?v=7vc-FhG682E', '2026-08-08 14:14:43', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1035, 'Pokémon: The Mastermind of Mirage Pokémon', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1527-hpCETiBRDhRO.jpg', 'series', '6.3', 'Dr. Yung, an enigmatic Pokémon scientist, has developed a new Mirage system that uses computer data to resurrect extinct Pokémon, like Kabutops and Armaldo. Professor Oak, Ash and his companions show up at the Mirage Mansion at Dr. Yung''s invitation, and watch a demonstration of the machine''s capabilities. In the middle of a battle between Dr. Yung''s Mirage Pokémon and Ash, the machine goes haywire and a Mirage Aerodactyl swoops in and kidnaps Dr. Yung. A man calling himself "The Mirage Master" appears and announces to everyone that the Mirage System can be used to create Pokémon with absolutely no weaknesses. Ash, Misty, and Professor Oak struggle to stop the madman and escape with their lives.

(Source: Anime News Network)', 'OLM', '2006', 'series', 'released', '2006-04-29', 1527, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1527-CQIZecm59mwO.jpg', 'Action, Adventure, Comedy, Fantasy, Sci-Fi', 'SPECIAL', 'SPRING', 1, 12804, 'https://www.youtube.com/watch?v=KjtIaiMFEeA', '2026-08-08 14:14:46', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1036, 'Pokémon Ranger and the Temple of the Sea', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2201-1B1dS0NLJ3g5.jpg', 'movies', '6.5', 'Satoshi and his friends get lost in an unknown wasteland.  They eventually come across a "Water Pokemon Show" performed by the star of the Mariner Troupe, Hiromi.  Hiromi is a descendant of the troupe of Water People able to communicate with water pokemon, and she tells our heroes the legend that''s been passed down by her people for generations.   According to legend, a temple the Water People built called "The Water Temple Akuusha" rests somewhere in the ocean, and a treasure called "The Water Crown" is hidden there.  It''s said that no one has ever seen this treasure, but that changes when a Pokemon Ranger named Jack Walker (aka Jackie) appears to chase aftert it.

Jackie is on a top secret mission that has him protecting the egg of the leader of the water pokemon, Manaphy. This pokemon, called the "Prince of the Sea," needs to be taken to the Water Temple Akuusha, so Satoshi-tachi and Hiromi decide to help him.  Along the way, a pirate named Phantom attacks our heroes from his great submarine.  Phantom plans to use the Water Crown''s power to help him conquer the world, but he''ll have to solve the mystery of Manaphy''s egg first.  When the Rocket-Dan get into the mix, Jackie uses his Capture Styler to borrow the power of a nearby pokemon to stand up to them.  Satoshi and Pikachu enter the fray, but they still have to contend with the attacks of Phantom''s powerful high tech mecha!  Suddenly, the egg starts to shine with a vivid light, and Manpahy is born!  

What is the mystery of the legendary treasure?  What mysterious powers does Manaphy have?  Can Satoshi-tachi and Jackie complete their top secret mission?  The journey to reach the Water Temple Akuusha has begun!', 'OLM', '2006', 'movie', 'released', '2006-07-15', 2201, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2201-AaINJqkO5zge.jpg', 'Action, Adventure, Fantasy', 'MOVIE', 'SUMMER', 1, 23536, 'https://www.youtube.com/watch?v=jt1Ui72oBlc', '2026-08-08 14:14:49', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1037, 'Pikachu no Obake Carnival', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/5844.jpg', 'series', '5.7', 'Pikachu and his friends have a picnic when they discover a Ghost Festival. The walk in to it, and find out that it is haunted by Ghost Pokemon and other Pokemon such as Koffing, Lickitung, Ditto, and Cubone. Meowth also discovers the Ghost Festival and gets scared out of his mind. Pikachu makes friends with the ghosts, and they work together to make Meowth run out of the Festival.

(Source: Anime News Network)', NULL, '2005', 'series', 'released', '2005-08-01', 5844, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Comedy, Fantasy, Supernatural', 'SPECIAL', 'SUMMER', 1, 2102, 'https://www.youtube.com/watch?v=1roy4o4tqQM', '2026-08-08 14:14:52', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1038, 'Pikachu no Natsumatsuri', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/5845.jpg', 'series', '5.8', 'Summer has arrived, and many Pokemon have set up shops for a summer festival on the beach. Soon the gang will be blessed by a special performance from the pop idol Azumarill, but upon her arrival, she''s kidnapped by the flying Pokemon Skarmory! Pikachu, along with Plusle, Minun, Meowth, Wobbuffet and a number of other Pokemon must now track down the singing beauty; the show must go on!

(Source: Anime-Planet)', NULL, '2004', 'series', 'released', '2004-08-01', 5845, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Fantasy', 'SPECIAL', 'SUMMER', 1, 2307, 'https://www.youtube.com/watch?v=1roy4o4tqQM', '2026-08-08 14:14:54', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1039, 'Pokémon Omega Ruby and Pokémon Alpha Sapphire Animated Trailer', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx20956-MKm6OtgBWGFh.jpg', 'series', '6.5', 'The Pokémon Company streamed the "Mega Special Animation" short inspired by the upcoming Pokémon Omega Ruby and Pokémon Alpha Sapphire games on Sunday. The short features Pokémon undergoing the newly discovered Mega Evolution and Primal Reversion in the Hoenn region.

(Source: Anime News Network)', 'OLM', '2014', 'series', 'released', '2014-11-16', 20956, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20956-L5xad6iSZf2I.png', 'Action, Adventure, Fantasy', 'ONA', 'FALL', 1, 3520, 'https://www.youtube.com/watch?v=Eju1zieC5rM', '2026-08-08 14:14:57', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1040, 'Pokémon: Pikachu''s Island Adventure', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/4910.jpg', 'series', '5.7', 'Pikachu and the other Pok&eacute;mon were at the beach, when a weakened Wynaut approaches them. It tells them that its friends were attacked by Meowth and the other Team Rocket Pok&eacute;mon, as well as an Exploud and a Hariyama, because Meowth wanted to take over their playground, which resides on a nearby island. After hearing Wynaut''s story, Pikachu and the others decide to help them take back their playground, and begin to train them, so that they can rescue their island from the clutches of Meowth.

(Source: Anime News Network)', 'OLM', '2006', 'series', 'released', '2006-08-01', 4910, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Fantasy', 'SPECIAL', 'SUMMER', 1, 2550, 'https://www.youtube.com/watch?v=1roy4o4tqQM', '2026-08-08 14:15:11', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1041, 'Pokémon Chronicles', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2363-hxC1f2VfyYbb.png', 'series', '6.5', 'Episodes of the Pocket Monsters anime which occasionally aired instead of a rerun from the main anime series as part of the Weekly Pokémon Broadcasting Station in Japan. They aired concurrently with Pocket Monsters Advanced from December 3, 2002 to September 28, 2004 in Japan. Outside of Japan, these episodes were only dubbed in the West as part of Pokémon Chronicles.

(Source: Bulbapedia)

Note: The Japanese version comprised 16 episodes while the U.S. version comprised 22 episodes; this page represents the Japanese version. The 6 additional episodes in the U.S. version were taken from previous movies and specials. Episodes 1, 2, and 3 are from Pokémon: The Legend of Thunder!, Episodes 4 and 20 are from Pokémon: Pikachu''s Winter Vacation (2001), and Episode 22 is from Pokémon: Pikachu''s Winter Vacation', 'OLM', '2002', 'series', 'released', '2002-12-03', 2363, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Comedy, Fantasy', 'SPECIAL', 'FALL', 16, 9147, 'https://www.youtube.com/watch?v=xQZHZVMlABs', '2026-08-08 14:15:00', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1042, 'Pokémon Mystery Dungeon: Team Go-Getters Out of the Gate!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2842-CkYZSdbEAj0z.png', 'series', '6.2', 'A human wakes up one day to discover that he has become a Squirtle in a world filled with natural disasters, where he meets Charmander and Chikorita of Team Go-Getters, a Pokemon rescue team. Squirtle joins Team Go-Getters for the task of saving Pichu''s Brother Pikachu from Skarmory, however Gengar and his Team Meanies decide to interfere.

(Source: Anime News Network)', 'OLM', '2006', 'series', 'released', '2006-09-08', 2842, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', NULL, 'Adventure, Fantasy', 'SPECIAL', 'FALL', 1, 4711, 'https://www.youtube.com/watch?v=rAOmQ-foqeg', '2026-08-08 14:15:03', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1043, 'Pokémon: Pichu Bros. in Party Panic', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx6877-7oARGnQDVHZa.png', 'series', '6.0', 'This is an animated cartoon that was released inside the game Pok&eacute;mon Channel.

A half-hour long anime show, broken into five short segments, featuring the Pichu Brothers. Meowth throws a party that the Pichu brothers and their friends are not invited to. After a series of events, they find out they were invited, but their invitations were simply delivered late. They go to Meowth''s Party and hear him sing. The series has a total of five episodes, each on its own channel.

(Source: Wikipedia)', 'OLM', '2003', 'series', 'released', '2003-07-18', 6877, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Fantasy', 'OVA', 'SUMMER', 1, 3666, 'https://www.youtube.com/watch?v=1roy4o4tqQM', '2026-08-08 14:15:06', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1044, 'Pokémon 4D: Pikachu''s Ocean Adventure', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11009-8emGZfVIhwwU.png', 'series', '6.2', 'When Pikachu and friends decide to stop by a tropical island for some rest and relaxation, they got more than they had bargained for after Chatot discovers a Treasure Map! They follow the map to Wailord&rsquo;s Tear, a mysterious place located in a sunken pirate ship. Will Pikachu and friends find the treasure? What mysteries and dangers are in store? Will our pals return safely? Find out in Pikachu&rsquo;s Ocean Adventure! 

(Source: Bulbapedia)', 'OLM', '2006', 'series', 'released', '2006-05-20', 11009, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Fantasy', 'SPECIAL', 'SPRING', 1, 2087, 'https://www.youtube.com/watch?v=idykbk5Iy2Q', '2026-08-08 14:15:09', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1045, 'Pokémon 3D Adventure: Mew wo Sagase!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/11019.jpg', 'series', '6.2', 'Pikachu and Meowth are on a search: a search for the elusive Pok&eacute;mon, Mew. They search everywhere! The sea, the sky, the woods...will they ever find Mew? 

(Source: Bulbapedia)', 'OLM', '2005', 'series', 'released', '2005-03-18', 11019, 0, NULL, '2026-07-25 17:04:17', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Fantasy', 'SPECIAL', 'SPRING', 1, 1956, 'https://www.youtube.com/watch?v=cksY3fTkc_I', '2026-08-08 14:15:59', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1046, 'Pokémon: Pikachu''s Rescue Adventure', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b4792-SJ5mrhQJc7l3.jpg', 'series', '6.2', 'While most of the smaller Pokémon are taking a nap, Togepi suddenly wakes up and, after seeing a group of flying Pokémon, finds itself separated from the rest of the Pokémon. Noticing this, Pikachu, Bulbasaur, Squirtle, Venonat, Marill, and Psyduck go in search of Togepi. It is there that they meet Elekid, who leads them to a group of Exeggcute. However, one such Exeggcute has a missing egg, and believes Togepi to be their missing part. Thus, the gang must travel to find the missing egg, and endure a storm that could blow Togepi and the Exeggcute away.

(Source: Anime News Network)', 'OLM', '1999', 'series', 'released', '1999-07-17', 4792, 0, NULL, '2026-07-25 17:04:19', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n4792-l5DTjO9uzU12.jpg', 'Adventure, Comedy, Fantasy', 'SPECIAL', 'SUMMER', 1, 6133, 'https://www.youtube.com/watch?v=1roy4o4tqQM', '2026-08-08 14:16:05', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1047, 'Yadoking no Ichinichi', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/6385.jpg', 'series', '5.6', 'It consists of nothing but Pok&eacute;mon-speak--similar to the mini-movies that air with each theatrical movie. It''s a short special based on life of the Pok&eacute;mon Slowking. It was never released outside of Japan and Greece, due to it only being a few minutes long. But it was officially dubbed in Russian.

(Source: Bulbapedia and Graffitti studio)', NULL, '2000', 'series', 'released', '2000-01-01', 6385, 0, NULL, '2026-07-25 17:04:19', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n6385-PoDym0lpeZB4.jpg', 'Fantasy, Slice of Life', 'SPECIAL', 'WINTER', 1, 3287, 'https://www.youtube.com/watch?v=5hRrvJ08ZSs', '2026-08-08 14:16:02', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1048, 'Pokémon: Pikachu and Pichu', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/4793.jpg', 'series', '6.4', 'Pikachu meets the Pichu brothers and goes on an adventure through the city with them while trying to get back to the building where the rest of Ash''s Pokémon are.', 'OLM', '2000', 'series', 'released', '2000-07-08', 4793, 0, NULL, '2026-07-25 17:04:21', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4793-au2BwSXdb5H7.jpg', 'Adventure, Comedy, Fantasy', 'SPECIAL', 'SUMMER', 1, 10528, 'https://www.youtube.com/watch?v=1roy4o4tqQM', '2026-08-08 14:16:08', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1049, 'Pokémon: Black & White', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/9107.jpg', 'series', '6.3', 'As with both the Advanced Generation and Diamond & Pearl series before it, the Best Wishes! series begins with only Ash Ketchum, headed off to the Unova region, located far away from Kanto, Johto, Hoenn and Sinnoh, with his Pikachu. After he meets up with the new trainer and rival Trip and the region''s Professor Juniper, he gains traveling companions in Iris, a girl from a town known for its Dragon Pok&eacute;mon, and Cilan, Pok&eacute;mon Connoisseur and the Grass Pok&eacute;mon specialist of the three Straition City Gym Leaders.', 'OLM', '2010', 'series', 'released', '2010-09-23', 9107, 0, NULL, '2026-07-25 17:04:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/9107-zksnKxfONNCz.jpg', 'Action, Adventure, Comedy, Fantasy', 'TV', 'FALL', 84, 32719, 'https://www.youtube.com/watch?v=BAInQ2nBZKg', '2026-08-08 14:16:10', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1050, 'Pokémon the Series: XY', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx19291-jwGqfWIXPtGA.png', 'series', '7.4', 'Satoshi and Pikachu have arrived in Lumiose City of the illustrious Kalos region to capture more Pokémon and continue their journey toward becoming the very best. Meanwhile, a genius inventor named Citron and his little sister Eureka wander the city when they run into Satoshi who quickly challenges them to a battle. However, they are soon caught up in a dangerous incident when Team Rocket, following Satoshi into Kalos, cause a Gaburias to rampage through the city.

Far away in the quiet Vaniville Town, a young girl named Serena slogs through daily Sihorn riding practice at the behest of her mother, a professional Sihorn racer. After practice, she sees the events unfolding in Miare City on television where she recognizes a boy from her childhood. Having left a significant impact on her life, the sight of him stirs in her a desire to meet him again; and so, Serena sets off to Miare City, determined to find the boy from her past.

Pokemon XY follows the group as they travel throughout Kalos in pursuit of their ambitions—Satoshi challenging Pokémon gyms, Citron learning from Satoshi, and Serena searching for what exactly her dream is. Along the way, they meet new friends, face new rivals, and continue to thwart Team Rocket''s schemes, all the while discovering a little about the mysteries of mega evolution.

(Source: MAL Rewrite)', 'OLM', '2013', 'series', 'released', '2013-10-17', 19291, 0, NULL, '2026-07-25 17:04:38', '2026-09-03 16:00:26', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/19291-BmU0qhxgLyPE.png', 'Action, Adventure, Comedy, Fantasy', 'TV', 'FALL', 93, 52618, NULL, '2026-09-03 16:00:26', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1051, 'Dragon Ball', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx223-scE5uJfXqqj8.png', 'series', '7.8', 'Goku Son is a young boy who lives in the woods all alone—that is until a girl named Bulma runs into him in her search for a set of magical objects called the "Dragon Balls." Since the artifacts are said to grant one wish to whoever collects all seven, Bulma hopes to gather them and wish for a perfect boyfriend. Goku happens to be in possession of a dragon ball, but unfortunately for Bulma, he refuses to part ways with it, so she makes him a deal: he can tag along on her journey if he lets her borrow the dragon ball''s power. With that, the two set off on the journey of a lifetime.

They don''t go on the journey alone. On the way, they meet the old Muten-Roshi and wannabe disciple Kuririn, with whom Goku trains to become a stronger martial artist for the upcoming World Martial Arts Tournament. However, it''s not all fun and games; the ability to make any wish come true is a powerful one, and there are others who would do much worse than just wishing for a boyfriend. To stop those who would try to abuse the legendary power, they train to become stronger fighters, using their newfound strength to help the people around them along the way.

(Source: MAL Rewrite)', 'Toei Animation', '1986', 'series', 'released', '1986-02-26', 223, 0, NULL, '2026-07-25 17:08:07', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/223-vyRuUBBYfcUb.jpg', 'Action, Adventure, Comedy, Fantasy, Sci-Fi, Supernatural', 'TV', 'WINTER', 153, 229977, 'https://www.youtube.com/watch?v=ypXYxqz4Cs8', '2026-08-08 14:16:46', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1052, 'Dragon Ball GT', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx225-pzkDUVy7tKxH.png', 'series', '6.3', 'Emperor Pilaf finally has his hands on the Black Star Dragon Balls after years of searching, which are said to be twice as powerful as Earth''s normal ones. Pilaf is about to make his wish for world domination when he is interrupted by Gokuu Son. As a result, Pilaf flubs his wish and accidentally turns Gokuu back into a child.

After the wish is granted, the Black Star Dragon Balls scatter across the galaxy. However, Gokuu discovers that they will cause the Earth to explode unless they are all brought back within a year. Uniting with his granddaughter Pan and a young adult Trunks, Gokuu sets off on an adventure through the universe to find the Black Star Dragon Balls and save his planet from destruction.

(Source: MAL Rewrite)', 'Toei Animation', '1996', 'series', 'released', '1996-02-07', 225, 0, NULL, '2026-07-25 17:08:07', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/225-gMgT7ZPEFvQ7.jpg', 'Action, Adventure, Comedy, Sci-Fi', 'TV', 'WINTER', 64, 127518, 'https://www.youtube.com/watch?v=7hi9f0Hddro', '2026-08-08 14:16:49', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1053, 'Dragon Ball Z: Dead Zone', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/894-9eA7z7CyNMms.jpg', 'movies', '6.2', 'Kami-sama''s old nemesis''s son has come to exact revenge on Kami-sama for winning the title of Earth''s Guardian. After kidnapping Son Gohan and using the dragon balls to gain immortality, he has a final showdown with Goku.

(Source: Anime News Network)', 'Toei Animation', '1989', 'movie', 'released', '1989-07-15', 894, 0, NULL, '2026-07-25 17:08:07', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/894-E53wr4IIwNuJ.jpg', 'Action, Adventure, Sci-Fi', 'MOVIE', 'SUMMER', 1, 30140, 'https://www.youtube.com/watch?v=p288hIQKoS8', '2026-08-08 14:16:52', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1054, 'Dragon Ball Z: The World''s Strongest', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/895-GuuZOIRCBHhI.jpg', 'movies', '6.1', 'The evil Dr. Wheelo has resurrected his brain into a robot and now desires to inhabit the body of the world''s strongest warrior. This means he must face Son Goku and company in a fight for Goku''s life.

(Source: Anime News Network)', 'Toei Animation', '1990', 'movie', 'released', '1990-03-10', 895, 0, NULL, '2026-07-25 17:08:07', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/895-cAESC6fP8PzR.jpg', 'Action, Adventure, Sci-Fi', 'MOVIE', 'SPRING', 1, 26579, 'https://www.youtube.com/watch?v=WB_UdLr29_M', '2026-08-08 14:16:55', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1055, 'Dragon Ball Z: The Tree of Might', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/896.jpg', 'movies', '6.3', 'The Saiyajin named Turlus has come to Earth in order to plant a tree that will both destroy the planet and give him infinite strength. Son Goku and the Z Warriors cannot let this happen and duke it out with the invaders for the sake of the planet.

