INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1078, 'Hidden Leaf Village Grand Sports Festival', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/2248.jpg', 'series', '6.3', 'The genin of Kohona are having a sports day filled with races, obstacle courses and of course the relay and the prize is a paid vacation for the winner. Unfortunately Naruto and his stomach are getting him into trouble again.', NULL, '2004', 'series', 'released', '2004-08-21', 2248, 0, NULL, '2026-07-25 17:08:27', '2026-09-02 16:57:33', NULL, 'Action, Comedy, Fantasy', 'SPECIAL', 'SUMMER', 1, 11664, 'https://www.youtube.com/watch?v=3u4pYwPMpGk', '2026-08-08 14:17:25', NULL);
