INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1083, 'HAIKYU!! TO THE TOP', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx106625-UR22wB2NuNVi.png', 'series', '8.3', 'The fourth season of Haikyuu!!

The Karasuno High School Volleyball Club finally won their way into the nationals after an intense battle for the Miyagi Prefecture Spring Tournament qualifiers. As they were preparing for the nationals, Kageyama is invited to go to All-Japan Youth Training Camp. At the same time, Tsukishima is invited to go to a special rookie select training camp for first-years in Miyagi Prefecture. Hinata feels panic that he’s being left behind as one of the first-years and then decides to show up at the Miyagi Prefecture rookie select training camp anyway... 

(Source: Crunchyroll)', 'Production I.G', '2020', 'series', 'released', '2020-01-11', 106625, 0, NULL, '2026-07-25 17:09:32', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/106625-wab2Mx4NQqPQ.jpg', 'Comedy, Drama, Sports', 'TV', 'WINTER', 13, 289907, 'https://www.youtube.com/watch?v=IZ8iIHpe4Lg', '2026-08-08 14:17:38', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1084, 'Demon Slayer: Kimetsu no Yaiba Swordsmith Village Arc', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx145139-rRimpHGWLhym.png', 'series', '8.1', 'Adaptation of the Swordsmith Village Arc.

Tanjiro’s journey leads him to the Swordsmith Village, where he reunites with two Hashira, members of the Demon Slayer Corps’ highest-ranking swordsmen - Mist Hashira Muichiro Tokito and Love Hashira Mitsuri Kanroji. With the shadows of demons lurking near, a new battle begins for Tanjiro and his comrades.

Notes:

• The first episode has a runtime of ~49 minutes, and received an early premiere in cinemas worldwide as part of a special screening alongside the final two episodes of Kimetsu no Yaiba: Yuukaku-hen.

• The final episode has a runtime of ~52 minutes.', 'ufotable', '2023', 'series', 'released', '2023-04-09', 145139, 0, NULL, '2026-07-25 17:09:34', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/145139-V01Prh6UzfRk.jpg', 'Action, Adventure, Drama, Fantasy, Supernatural', 'TV', 'SPRING', 11, 363634, 'https://www.youtube.com/watch?v=a9tq0aS5Zu8', '2026-08-08 14:17:41', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1085, 'The Disappearance of Nagato Yuki-chan: I Cannot Let Summer Break End', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/21122-S0zCWEDHbdyU.jpg', 'series', '6.5', 'An OVA bundled with the 9th volume of the Nagato Yuki-chan no Shoushitsu manga.

This spin-off of the Haruhi Suzumiya series takes place in the world of the "Disappearance" arc of the original novels, focusing on the high school life (and romance!) of a tentative and bashful Yuki Nagato.', 'Satelight', '2015', 'series', 'released', '2015-10-26', 21122, 0, NULL, '2026-07-25 17:09:40', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21122-qNVibkCM9Y2r.jpg', 'Comedy, Romance', 'OVA', 'FALL', 1, 8417, 'https://www.youtube.com/watch?v=cVVwn4ltzoE', '2026-08-08 14:17:44', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1086, 'The Melancholy of Haruhi-chan Suzumiya', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx5118-aYzs5cWmGCVJ.png', 'series', '7.0', 'A parody series featuring the entire cast of The Melancholy of Haruhi Suzumiya in a smaller form factor.  Among the changes are: Yuki plays eroge, Haruhi is even more obnoxious and loud, Mikuru is even more emotional and Koizumi harbors a deep love for Kyon.  Kyon, on the other hand, is generally the same as ever.', 'Kyoto Animation', '2009', 'series', 'released', '2009-02-13', 5118, 0, NULL, '2026-07-25 17:09:42', '2026-09-02 16:57:33', NULL, 'Comedy, Slice of Life', 'ONA', 'WINTER', 25, 18424, 'https://www.youtube.com/watch?v=Fey8AlhIJCw', '2026-08-08 14:17:47', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1087, 'Nyoron! Churuya-san', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/5957.jpg', 'series', '6.1', 'An anime adaptation of the 4-panel strip manga release: Nyoron Churuya-san. Based on Suzumiya Haruhi''s energetic and ''always up to go'' character, Tsuruya.

Churuya is a girl with a strong passion for smoked cheese. But Kyon and the rest of the crew know this, and they make use of the weakness. They make her do all kinds of things with smoked cheese as a possible reward. But Churuya isn''t aware of this evil plot, thus she maintains the effort for the sake of cheese. Each day is a struggle to get the beloved smoked cheese, but it''s much harder than she could ever imagine!', 'Kyoto Animation', '2009', 'series', 'released', '2009-02-13', 5957, 0, NULL, '2026-07-25 17:09:42', '2026-09-02 16:57:33', NULL, 'Comedy', 'ONA', 'WINTER', 13, 7621, 'https://www.youtube.com/watch?v=Fey8AlhIJCw', '2026-08-08 14:17:49', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1088, 'One-Punch Man', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21087-B5DHjqZ3kW4b.jpg', 'series', '8.3', 'Saitama has a rather peculiar hobby, being a superhero, but despite his heroic deeds and superhuman abilities, a shadow looms over his life. He''s become much too powerful, to the point that every opponent ends up defeated with a single punch.

The lack of challenge has driven him into a state of apathy, as he watches his life pass by having lost all enthusiasm, at least until he''s unwillingly thrust in the role of being a mentor to the young and revenge-driven Genos.', 'MADHOUSE', '2015', 'series', 'released', '2015-10-05', 21087, 0, NULL, '2026-07-25 17:10:11', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21087-sHb9zUZFsHe1.jpg', 'Action, Comedy, Sci-Fi, Supernatural', 'TV', 'FALL', 12, 755729, 'https://www.youtube.com/watch?v=RzmFKUDOUgw', '2026-08-29 14:48:05', NULL);
