INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1090, 'ZOMBIE LAND SAGA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx103871-KEWbn3fkz499.png', 'series', '7.4', 'A typical morning. The usual music. Their normal lives. The peace these seven girls experience will suddenly be destroyed. By the living dead... zombies. A reality that they never wanted a part of, an amazing and terrifying zombie world. They all share one wish: "We want to live." These girls will struggle through this saga, in order to achieve a miracle. MAPPA, Avex Pictures, and Cygames team up to bring you a juicy, 100% original anime. A timeless shocker for all audiences, a brand new style of zombie anime, will soon rise.

(Source: Crunchyroll)', 'MAPPA', '2018', 'series', 'released', '2018-10-04', 103871, 0, NULL, '2026-07-25 17:10:16', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n103871-yXAOJi8trgxh.jpg', 'Comedy, Music, Supernatural', 'TV', 'FALL', 12, 153069, 'https://www.youtube.com/watch?v=O3VO4zinUOI', '2026-08-08 14:17:55', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1091, 'Em-Shade! Shorts Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx169929-JQicusC5CiQ8.jpg', 'series', '7.0', 'The second season of Em-Shade! Shorts mini animations, the shorts were initially broadcasted on television, then uploaded onto the KADOKAWA Anime YouTube channel. 
Additionally, the shorts are available as extras on the Blu-ray and DVD releases of The Eminence in Shadow Season 2.

Notes:

- Volume 1 includes episodes 1-4.

- Volume 2 includes episodes 5-8.

- Volume 3 includes episodes 9-12.', 'Studio PuYUKAI', '2023', 'series', 'released', '2023-10-05', 169929, 0, NULL, '2026-07-25 17:10:18', '2026-09-02 16:57:33', NULL, 'Comedy, Fantasy', 'TV_SHORT', 'FALL', 12, 4899, 'https://www.youtube.com/watch?v=DPpnu0KzSWo', '2026-08-08 14:17:57', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1092, 'BanG Dream! It''s MyGO!!!!!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx163571-Atkvuzh1A1Ip.png', 'series', '8.2', 'The best way to fit in at a new school? Start a band! Anon has just transferred to Haneoka Girls’ Academy where girl bands are all the rage. But she started school late, so there aren’t many girls left to recruit. Then she meets her first friend and Haneoka’s misfit, Tomori, who’s hesitant to join. Still, Anon is determined to persuade Tomori and experience the true power of friendship and music. 

