INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1100, 'Ghost in the Shell: Stand Alone Complex: Tachikomatic Days', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/10870.jpg', 'series', '6.4', 'Tachikoma TV series that aired on Animax. Unlike the previous "Tachikoma na Hibi," which were auxiliary episodes to the main Ghost in the Shell SAC and 2nd GIG, the special version has longer stories based on various Japanese and Orthodox folklore. Later re-released on a BD box with all the Tachikoma shorts.', 'Production I.G', '2007', 'series', 'released', '2007-05-02', 10870, 0, NULL, '2026-07-25 17:10:27', '2026-09-02 16:57:33', NULL, 'Comedy, Mecha, Sci-Fi', 'TV_SHORT', 'SPRING', 12, 2531, 'https://www.youtube.com/watch?v=MQpGKwVs7S0', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1101, 'Ascendance of a Bookworm Part 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113693-3tHbslFxD47R.jpg', 'series', '7.9', 'Anime adaptation of Part 2 (Volume 1 & 2) of Honzuki no Gekokujou.

When Myne learns that the temple is in need of mana for their relics, she sees it as her chance to be cured of her life-threatening mana disorder. After seeing their bountiful library, she throws herself headfirst into the temple''s grasp and begs to join their order. In exchange for her service and her unusually bountiful supply of mana, Myne is given the blue robes of a noble-born apprentice shrine maiden, despite being a commoner. To Myne, all this talk of mana and nobility is trivial, as she now has access to an unlimited supply of books! 
</br>

As Myne transitions into the next phase of her life in this new world, she soon learns that achieving her dream has come at a heavy cost. Noble society is severe, unforgiving, and fueled by politics and neglect. She must now deal with the class conflict between the noble-born blue robes and the common-born grey robes, the High Bishop''s attempts to oust her, and constant behavioral issues from her new retainers. With the help of her family, friends, and the enigmatic High Priest whose loyalties and motives remain unknown, Myne seeks to overcome these obstacles and continue on the path to becoming her ideal self—the ultimate librarian!

(Source: MAL Rewrite, edited)', 'Ajiado', '2020', 'series', 'released', '2020-04-05', 113693, 0, NULL, '2026-07-25 17:10:36', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/113693-i9Wm6xjTlQGQ.jpg', 'Fantasy, Slice of Life', 'TV', 'SPRING', 12, 73744, 'https://www.youtube.com/watch?v=8BQs59MW7tA', '2026-08-08 14:19:02', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1102, 'Welcome to Demon School! Iruma-kun Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx116338-jbuJnLkPMcm7.jpg', 'series', '8.0', 'The second season of Mairimashita! Iruma-kun.

Suzuki Iruma, human and deeply non-aggressive, one day becomes the grandson of the great demon Sullivan. Doted on beyond belief, Iruma starts school where "Grandpa" serves as the chair... and finds, to his surprise, that he enjoys life there with Asmodeus, Clara, and the rest of his demon classmates. But just when Iruma thought he''d fitted in, there''s more trouble ahead! A ring begins to talk, and Iruma... goes bad?! Iruma''s chaotic, demonic life at school continues!

(Source: NHK)', 'Bandai Namco Pictures', '2021', 'series', 'released', '2021-04-17', 116338, 0, NULL, '2026-07-25 17:10:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/116338-LexsWZ3dXsod.jpg', 'Comedy, Fantasy, Supernatural', 'TV', 'SPRING', 21, 103985, 'https://www.youtube.com/watch?v=NxqfMRZfVTA', '2026-08-08 14:19:05', NULL);
