INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1189, 'Mob Psycho 100 II: The First Spirits and Such Company Trip ~A Journey that Mends the Heart and Heals the Soul~', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx109819-71ZeBjJuU3da.png', 'series', '7.6', 'Mob, Reigen, Dimple, and Serizawa, the newest member of the Spirits and Such Consultation Office staff, take a trip up to a secluded hot spring in Zebra Prefecture. Reigen received a request to discover the truth behind strange rumors about the inn.

(Source: Funimation) 

Note: The OVA was screened at an anime event that took place at Kasukabe Citizens Cultural Center in Saitama Prefecture on July 7th, 2019.', 'bones', '2019', 'series', 'released', '2019-09-25', 109819, 0, NULL, '2026-07-25 17:16:27', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/109819-x6X6TbHlXyBr.jpg', 'Action, Comedy, Supernatural', 'OVA', 'SUMMER', 1, 45342, 'https://www.youtube.com/watch?v=nTze7vAdRpM', '2026-08-08 14:23:18', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1190, 'Tokyo Ghoul:re', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx100240-vJNaKd5HwPJ2.jpg', 'series', '6.2', 'Two years have passed since the CCG’s raid on Anteiku. Although the atmosphere in Tokyo has changed drastically due to the increased influence of the CCG, ghouls continue to pose a problem as they have begun taking caution, especially the terrorist organization Aogiri Tree, who acknowledge the CCG’s growing threat to their existence.
The creation of a special team, known as the Quinx Squad, may provide the CCG with the push they need to exterminate Tokyo’s unwanted residents. As humans who have undergone surgery in order to make use of the special abilities of ghouls, they participate in operations to eradicate the dangerous creatures. The leader of this group, Haise Sasaki, is a half-ghoul, half-human who has been trained by famed special class investigator, Kishou Arima. However, there’s more to this young man than meets the eye, as unknown memories claw at his mind, slowly reminding him of the person he used to be.', 'Studio Pierrot', '2018', 'series', 'released', '2018-04-03', 100240, 0, NULL, '2026-07-25 17:16:31', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100240-aHnY7a5EutPU.jpg', 'Action, Horror, Mystery, Psychological, Supernatural', 'TV', 'SPRING', 12, 303358, 'https://www.youtube.com/watch?v=dZ36ToJLHtA', '2026-08-08 14:23:20', NULL);
