INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1301, 'Sound! Euphonium', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20912-SiiG4HPrjQlX.jpg', 'series', '8.0', 'Spring in the first year of high school. Kumiko, a member of the brass band in junior high school, visits the high school brass band club with classmates Hazuki and Sapphire. There, she comes across Reina, her former classmate from junior high. Hazuki and Sapphire decide to join the club, but Kumiko can’t make up her mind. She recollects her experience with Reina at a competition in junior high school.

(Source: Pony Canyon USA)', 'Kyoto Animation', '2015', 'series', 'released', '2015-04-08', 20912, 0, NULL, '2026-07-25 17:22:25', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20912-FbGbJuHlRKm7.jpg', 'Drama, Music, Slice of Life', 'TV', 'SPRING', 13, 149456, 'https://www.youtube.com/watch?v=r_Kk9xhVkB8', '2026-08-08 14:28:59', NULL);
