INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1358, 'Douluo Dalu: 9528', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx206142-ATzxlNEJWaXj.jpg', 'coming', '0.0', 'Tang San and Xiao Wu return to the collapsed Slaughter City, now devastated by the Snow Swan Kiss. They face relentless pursuit from the mutated Slaughter King, only to be saved by a mysterious girl whose rescue conceals dark secrets. Together, Tang San and Xiao Wu must uncover the truth behind Slaughter City''s corruption.', 'D.ROCK-ART', '2027', 'series', 'upcoming', '2027-01-01', 206142, 0, NULL, '2026-07-25 17:25:14', '2026-09-03 15:46:20', NULL, 'Action, Fantasy', NULL, NULL, NULL, 157, NULL, '2026-09-03 15:46:20', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1359, 'Arknights: PERISH IN FROST', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx158895-QPy3ElZBKziT.jpg', 'series', '7.5', 'Oripathy, an incurable disease that slowly crystallizes the bodies of those infected until their deaths.

Rhodes Island is a pharmaceutical company that endeavors to find a cure and solve the problems that follow in the disease''s wake,
and in an attempt to put a stop to the revolt of the terrorist organization known as Reunion Movement whose ultimate goal is the salvation of the Infected,
Rhodes Island has formed a contract with the Yanese city of Lungmen and continues its mission there.

However, Amiya has found herself despondent since their battle against Skullshatterer, unable to accept the fact they were unable to save Misha.

In the meantime, Rhodes Island deploys a reconnaissance squad to an abandoned city discovered in the Lungmen countryside.
There, the squad notices a strange phenomenon unfolding before them…', 'Yostar Pictures', '2023', 'series', 'released', '2023-10-07', 158895, 0, NULL, '2026-07-25 17:25:18', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/158895-GwaXDM5EOIoV.jpg', 'Action, Fantasy', 'TV', 'FALL', 8, 22300, 'https://www.youtube.com/watch?v=G_wEICcHRNs', '2026-08-29 14:45:49', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1360, 'Star Blazers: Space Battleship Yamato 2202', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21730-caiwTjlMlg0R.jpg', 'series', '7.4', 'Three years since the return of the legendary Space Battleship Yamato, Earth has begun rebuilding itself and has made peace with the Gamilans. However, this recovery comes at the cost of utilizing the forbidden Wave Motion technology.

Meanwhile, the notorious former crew members of the Yamato, who have each gone their separate ways, receive a psychic message from the mysterious Goddess Teresa. She urges them to return to their beloved ship and travel to the distant planet Terezart. They are promised a revolutionary power to combat the unprecedented threat of the relentless Gatlantis Empire, who are approaching Earth with all but innocent intentions.

Unable to resist her plea, the crew reassembles and sets sail on another perilous intergalactic voyage, one that will test their sheer courage and versatility in the face of an even greater foe.

(Source: MAL Rewrite)', 'Xebec', '2017', 'series', 'released', '2017-02-25', 21730, 0, NULL, '2026-07-25 17:25:25', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21730-1wEA54xT95HE.jpg', 'Action, Drama, Sci-Fi', 'OVA', 'WINTER', 26, 7544, 'https://www.youtube.com/watch?v=RwOi_I0cEFU', '2026-08-29 14:45:52', NULL);
