INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1365, 'ARGONAVIS from BanG Dream!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx113051-R2V4aqfv0pau.png', 'series', '6.2', 'Ren Nanahoshi is a lonely college student who isn''t good at communicating with others. He remembers the thrill of watching a live band perform when he was young, and spent most of his days searching for his own identity. One day, while singing karaoke alone, two boys named Yuuto and Wataru discover Ren''s singing ability. The two agree: "This is fate. Let''s start a band!" Ren promptly runs away, but fate indeed steps in, and their journey begins.', 'SANZIGEN', '2020', 'series', 'released', '2020-04-11', 113051, 0, NULL, '2026-07-25 17:25:30', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/113051-O0OIEfTcXrQY.jpg', 'Drama, Music', 'TV', 'SPRING', 13, 5516, 'https://www.youtube.com/watch?v=kTDeChfR-zA', '2026-08-29 14:46:11', NULL);
