INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1369, 'Higurashi: When They Cry - GOU', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx114446-H6uxjVi8wBoo.jpg', 'series', '6.9', 'New kid Keiichi Maebara is settling into his new home of peaceful Hinamizawa village. Making quick friends with the girls from his school, he''s arrived in time for the big festival of the year. But something about this isolated town seems "off," and his feelings of dread continue to grow. With a gnawing fear that he''s right, what dark secrets could this small community be hiding?

(Source: Funimation)', 'Passione', '2020', 'series', 'released', '2020-10-01', 114446, 0, NULL, '2026-07-25 17:30:52', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/114446-DTd4xfGx7DJB.jpg', 'Drama, Horror, Mystery, Psychological, Supernatural, Thriller', 'TV', 'FALL', 24, 82056, 'https://www.youtube.com/watch?v=i4GaPCEiHIg', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1370, 'When They Cry Kai', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1889-NqhWV3QwBXZl.jpg', 'series', '8.0', 'Continuing from the first series, Higurashi no Naku Koro ni Kai begins to shed some light on the dark mysteries prevalent in the preceding season. The young group of friends in the town of Hinamizawa continue to enter terrible conflicts with one another in their never ending summer of 1983, often ending with the brutal murder of one of their numbers. Furude Rika, with the help of her spiritual friend Hanyuu, tackles challenges over and over, trying her best to keep their lives from coming to a tragic end. With no end to the torture in sight, Rika must call upon the bonds of friendship and trust among her friends to discover the true villain of this eternal June.', 'NBCUniversal Entertainment Japan', '2007', 'series', 'released', '2007-07-06', 1889, 0, NULL, '2026-07-25 17:30:54', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1889-cZ3RMG35FZSG.jpg', 'Horror, Mystery, Psychological, Supernatural, Thriller', 'TV', 'SUMMER', 24, 89580, 'https://www.youtube.com/watch?v=BPB15-_-nuA', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1371, 'Higurashi no Naku Koro ni: Nekogoroshi-hen', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b2899-6bAiQ0BhSzNW.jpg', 'series', '6.8', 'After losing a bet, Keichi, Mion, Rena, Satoko and Rika parade around the town in costumes. When they come to a fork in the road, they decide to go to Yagouchi, a nearby abandoned village. Once there Keichii and Rena learn the mystery of a strange haunted quarry as they debate whether or not to check it out.', 'Studio DEEN', '2007', 'series', 'released', '2007-08-02', 2899, 0, NULL, '2026-07-25 17:30:54', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2899-hUOu4DOvkqtC.png', 'Comedy, Mystery', 'SPECIAL', 'SUMMER', 1, 17869, 'https://www.youtube.com/watch?v=ZfH0WHJ_-zA', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1372, 'Higurashi no Naku Koro ni Kaku: Outbreak', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/16700.jpg', 'series', '6.8', 'The story is set in the same Hinamizawa village of the previous stories. The village has been completely sealed off due to a mysterious virus in 1983, and Maebara Keiichi and Ryuuguu Rena deal with the outbreak.

(Source: Anime News Network)', 'Studio DEEN', '2013', 'series', 'released', '2013-08-15', 16700, 0, NULL, '2026-07-25 17:30:54', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/16700-dhnYHi9Pmjpn.jpg', 'Action, Mystery, Psychological, Thriller', 'OVA', 'SUMMER', 1, 18568, 'https://www.youtube.com/watch?v=eqxtxw7lgEE', '2026-08-29 14:46:25', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1373, 'Umineko: When They Cry', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx4896-q6l4Bq4ly0tw.jpg', 'series', '6.3', 'Considered as the third installment in the highly popular "When They Cry" series by 07th Expansion, Umineko no Naku Koro ni takes place on the island of Rokkenjima (&#20845;&#36562;&#23798;), owned by the immensely wealthy Ushiromiya family. As customary per year, the entire family is gathering on the island for a conference that discusses the current financial situations of each respective person. Because of the family head''s poor health, this year involves the topic of the head of the family&rsquo;s inheritance and how it will be distributed.

However, the family is unaware that the distribution of his wealth is the least of Ushiromiya Kinzo''s (family head) concerns for this year''s family conference. After being told that his end was approaching by his longtime friend and physician, Kinzo is desperate to meet his life''s true love one last time: the Golden Witch, Beatrice. Having immersed himself in black magic for many of the later years in his life, Kinzo instigates a ceremony to revive his beloved upon his family''s arrival on Rokkenjima. Soon after, a violent typhoon traps the family on the island and a string of mysterious murders commence, forcing the eighteen people on the island to fight for their lives in a deadly struggle between fantasy and reality.

[Written by MAL Rewrite]', 'NBCUniversal Entertainment Japan', '2009', 'series', 'released', '2009-07-02', 4896, 0, NULL, '2026-07-25 17:30:54', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4896-bk5bs5riD1kQ.jpg', 'Drama, Horror, Mystery, Psychological, Supernatural', 'TV', 'SUMMER', 26, 42668, 'https://www.youtube.com/watch?v=dcPNaY3EIUc', NULL, NULL);
