INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1394, 'Pokémon BW: Rival Destinies', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14093-1O75wVFVAiDY.png', 'series', '6.2', 'Satoshi, Iris & Dent continue their travels through the Isshu region. After successfully winning his eighth and final Gym Badge against Homika in Tachiwaki City, Shirona invites everyone to stay at her villa in East Isshu, where old friend Hikari is also staying and where they participate in the Pokémon World Tournament Junior Cup after which Satoshi participates in the Isshu League. Team Rocket, meanwhile, initiate their final plan for the Isshu region-what is their purpose in their desire for the legendary Pokémon Meloetta?', 'TV Tokyo', '2012', 'series', 'released', '2012-06-21', 14093, 0, NULL, '2026-07-25 17:33:40', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Comedy, Fantasy', 'TV', 'SUMMER', 24, 20712, 'https://www.youtube.com/watch?v=7Xc90MFVZus', NULL, NULL);
