INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1502, 'Fate/Grand Order Divine Realm of the Round Table: Camelot - Paladin; Agateram', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx103277-BuAfaC3dKOUp.jpg', 'movies', '7.6', 'The second part in a two-part anime film project adapting the "Sixth Singularity - Divine Realm of the Round Table: Camelot" story from the game.

(Source: Anime News Network)', 'Production I.G', '2021', 'movie', 'released', '2021-05-15', 103277, 0, NULL, '2026-07-25 17:39:00', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/103277-aTpOhNwE5a94.jpg', 'Action, Fantasy', 'MOVIE', 'SPRING', 1, 31119, 'https://www.youtube.com/watch?v=5MkBFxre8jA', '2026-08-29 14:50:39', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1503, 'Fate/Grand Order Final Singularity - Grand Temple of Time: Solomon', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx116756-jIU2HrnEsDjR.jpg', 'movies', '7.6', 'After battling their way through all seven Singularities, the Chaldea Security Organization has finally arrived at the endpoint of the Grand Order: The Final Singularity, Grand Temple of Time: Solomon.

Now is the time to defeat the root of all evil, Solomon, the King of Mages. Now is the time to reclaim the future.

With the final operation looming large, Romani Archaman considers the choices he will soon have to make, Mash Kyrielight dwells on life’s limitations, and Fujimaru prepares to receive a new Mystic Code.

All their many encounters have led to this moment as Fujimaru and Mash at last embark on their final operation...

(Source: Aniplex USA)

Note: Based on the eighth and final chapter of the first arc in Fate/Grand Order, a Japanese smartphone role-playing game from TYPE-MOON’s Fate franchise.', 'CloverWorks', '2021', 'movie', 'released', '2021-07-30', 116756, 0, NULL, '2026-07-25 17:39:04', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/116756-Bb7BkeRMTpaP.jpg', 'Action, Fantasy, Supernatural', 'MOVIE', 'SUMMER', 1, 30927, 'https://www.youtube.com/watch?v=Cf9uMIffDTQ', '2026-08-29 14:50:44', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1504, 'Lord El-Melloi II''s Case Files {Rail Zeppelin} Grace note - A Grave Keeper, a Cat, and a Mage', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx106862-IFmkASZSrcGw.jpg', 'series', '7.0', 'As one of the Lords of the Clock Tower as well as the department head of the Modern Magecraft Theories department, Lord El-Melloi II holds yet another lecture for his diverse array of students. After the post-lecture meeting with other Clock Tower nobility, he throws out a few insults at the fellow Lords that are interested only in their internal power struggle, but he quickly receives a counter-curse in retaliation. On the following day, while in transit with his apprentice Gray, he notices a cat ran over by a car. It''s the stray cat that frequently visited his room as of late. Lord El-Melloi II realizes that this was an attempt to take his own life, and commences a perpetrator hunt along with Gray, Flat and Svin.
</br>(Source: Crunchyroll)', 'TROYCA', '2018', 'series', 'released', '2018-12-31', 106862, 0, NULL, '2026-07-25 17:39:14', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/106862-kGUpoNaRosTX.jpg', 'Drama, Fantasy, Mystery, Supernatural', 'SPECIAL', 'FALL', 1, 26893, 'https://www.youtube.com/watch?v=HYrXaHJkwMg', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1505, 'Lord El-Melloi II’s Case Files {Rail Zeppelin} Grace note -Special Episode-', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx136344-XwEsuW9mmTZB.png', 'series', '7.4', 'A letter is delivered to Lord El-Melloi II informing him of a Clock Tower reunion. One morning, as the reunion''s date draws near, Lord El-Melloi II takes a look in the mirror and reels in shock. He is suddenly a full decade younger! Lord El-Melloi II has become Waver Velvet, his former self! Believing himself to be in the grip of a powerful, magically induced delusion, Lord El-Melloi II immediately begins investigating how this could have happened. On the day of the reunion, he makes his way to the gathering of his contemporaries, planning to confront whoever transformed his body and hoping to reveal their intentions. However, when Touko Aozaki arrives, things take a sudden turn...

(Source: Crunchyroll) 

Note: The special edition was broadcasted in the Fate Project New Year''s Eve TV Special 2021.', 'TROYCA', '2021', 'series', 'released', '2021-12-31', 136344, 0, NULL, '2026-07-25 17:39:14', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/136344-hbzg1Pcos3Za.jpg', 'Drama, Fantasy, Mystery', 'SPECIAL', 'FALL', 1, 14225, 'https://www.youtube.com/watch?v=YsxAPaB4zjo', '2026-08-29 14:50:47', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1506, 'Koyomimonogatari', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21520-nZKCr7PZrv7e.png', 'series', '7.4', 'Third season of the Monogatari Series, part 2/5. Adapts the arcs Koyomi Stone, Koyomi Flower, Koyomi Sand, Koyomi Water, Koyomi Wind, Koyomi Tree, Koyomi Tea, Koyomi Mountain, Koyomi Torus, Koyomi Seed, Koyomi Nothing, and Koyomi Dead from the Koyomimonogatari light novel.

“You’re looking for a horror story? I wish I got one for you." Untold stories… one per month for one year… Taking place between other Monogatari stories, a chapter not yet told surrounds Koyomi Araragi and the strange happenings he gets pulled into over the course of a year. With one episode told per month, the story unravels in this 12 episode-long series of shorts.

(Source: Aniplex)

Premiered on the Japan-exclusive Koyomimonogatari mobile app.', 'Shaft', '2016', 'series', 'released', '2016-01-09', 21520, 0, NULL, '2026-07-25 17:39:16', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21520-iaWBW3LJHil9.jpg', 'Comedy, Mystery, Supernatural', 'ONA', 'WINTER', 12, 85835, 'https://www.youtube.com/watch?v=ox11ksuptoE', NULL, NULL);
