INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1527, 'Tokyo Revengers', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx120120-cWDmnmeEntSe.jpg', 'series', '7.7', 'Takemichi Hanagaki is a freelancer that''s reached the absolute pits of despair in his life. He finds out that the only girlfriend he ever had in his life that he dated in middle school, Hinata Tachibana, had been killed by the ruthless Tokyo Manji Gang.

The day after hearing about her death, he''s standing on the station platform and ends up being pushed over onto the tracks by a herd of people. He closes his eyes thinking he''s about to die, but when he opens his eyes back up, he somehow had gone back in time 12 years.

Now that he''s back living the best days of his life, Takemichi decides to get revenge on his life by saving his girlfriend and changing himself that he''d been running away from.

(Source: Crunchyroll)', 'LIDENFILMS', '2021', 'series', 'released', '2021-04-11', 120120, 0, NULL, '2026-07-25 17:41:25', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/120120-UDYgoHA69peT.jpg', 'Action, Drama, Romance, Supernatural', 'TV', 'SPRING', 24, 438791, 'https://www.youtube.com/watch?v=nYQUVwwD-H4', '2026-08-29 14:52:01', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1528, 'Spice and Wolf II: Wolf and the Amber Melancholy', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx6007-jg9Jtl8Opqy2.jpg', 'series', '7.6', 'Holo, Lawrence, and Nora sit down to have dinner together, but Holo''s animosity toward Nora prevents her from enjoying it. Later, Holo falls ill due to fatigue and is forced to rest for a few days. She dreams and reminisces about her past and her journey so far with Lawrence, realizing her affection for him is intensifying. Lawrence treats Holo''s fever and fatigue by feeding her and balancing the four states, the hot, cold, dry, and wet. Over the course of her sickness, Holo grows closer to Lawrence, but Holo''s aversion to Nora continues to cause problems. Nora visits Holo, however, and makes amends after sharing a joke at Lawrence''s expense.', 'Funimation', '2009', 'series', 'released', '2009-04-30', 6007, 0, NULL, '2026-07-25 17:41:36', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n6007-NKl2kFjFLTe6.jpg', 'Adventure, Fantasy, Romance', 'OVA', 'SPRING', 1, 42657, 'https://www.youtube.com/watch?v=cGGKtSIQhFU', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1529, 'Is It Wrong to Try to Pick Up Girls in a Dungeon? IV', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx129196-eFVs05hMbVSm.jpg', 'series', '7.7', 'The fourth season of Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka.

Intrepid adventurer Bell Cranel has leveled up, but he can’t rest on his dungeoneering laurels just yet. The Hestia Familia still has a long way to go before it can stand toe-to-toe with the other Familias of Orario — but before Bell can set out on his next mission, reports of a brutal murder rock the adventuring community! One of Bell’s trusted allies stands accused of the horrible crime, and it’s up to Bell and his friends to clear their name and uncover a nefarious plot brewing in the dungeon’s dark depths.

(Source: Sentai Filmworks)', 'J.C.STAFF', '2022', 'series', 'released', '2022-07-21', 129196, 0, NULL, '2026-07-25 17:41:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/129196-bs6Z7VXXsyNd.jpg', 'Action, Adventure, Comedy, Fantasy, Romance', 'TV', 'SUMMER', 11, 127879, 'https://www.youtube.com/watch?v=1Z_0xP-bS4Y', '2026-08-29 14:54:10', NULL);
