INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1582, 'Beyblade G Revolution', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/n1668-2GDY5wKoXc6O.jpg', 'series', '6.7', 'After keeping their BitBeasts out of harm''s way, a new world championship tournament is announced, but the defending champions can''t all be on the same team. Their friendship will be tested and tried as each Bladebreaker goes on a quest to prove why they are the best Beyblader around. Tyson, Max, Ray, Kai, and newcomer Daichi, must keep up their winning ways...even if they must face each other. But, after the tournament is over, what awaits them is an old foe, Boris, taking over the BBA and transforming it into BEGA, the Beyblade Entertainment Global Association. To save Beybladers of the entire world from BEGA''s corruption, the Bladebreakers must reunite once again...

(Source: Anime News Network)', 'MADHOUSE', '2003', 'series', 'released', '2003-01-06', 1668, 0, NULL, '2026-07-25 18:35:14', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1668-ghcz3mGjyZLD.jpg', 'Action, Adventure, Comedy, Sci-Fi, Sports', 'TV', 'WINTER', 52, 11509, 'https://www.youtube.com/watch?v=O_ATd7z3QF0', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1583, 'Beyblade the Movie: Decisive Battle! Takao VS Daichi', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1670-D76DiH1UwcMF.png', 'movies', '6.4', 'The Bladebreakers are on a well deserved vacation. But, a hyperactive kid named Daichi continues to pursue Tyson for a rematch after his defeat in the Beyblade World Championships. The Bladebreakers'' vacation eventually takes a turn for the worst once they encounter mysterious Beybladers who claim to be the Dark Spirits sealed inside a strange temple. With Daichi under their control, the Shadow Bladers seek to destroy the world with their Dark BitBeasts. Together, Tyson, Max, Ray, and Kai must save not only Daichi... but the world as well...

(Source: Anime News Network)', 'd-rights', '2002', 'movie', 'released', '2002-08-17', 1670, 0, NULL, '2026-07-25 18:35:14', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Comedy, Sci-Fi, Sports', 'MOVIE', 'SUMMER', 1, 3600, 'https://www.youtube.com/watch?v=2u3CaMyKM0M', NULL, NULL);
