INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1594, 'Natsume''s Book of Friends Season 4', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx11665-nfbt94cwKySE.png', 'series', '8.5', 'Still in possession of his grandmother''s Book of Friends, Natsume spends his days returning the names of yokai to their rightful owners. He has been learning how to deal with the yokai and humans that surround his life, but the time has come for him to deal with something even more difficult — his own past, and future.

(Source: NIS America)', 'Aniplex', '2012', 'series', 'released', '2012-01-03', 11665, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11665-JYylw0x1Qi1H.jpg', 'Drama, Fantasy, Slice of Life, Supernatural', 'TV', 'WINTER', 13, 48926, 'https://www.youtube.com/watch?v=n_Ku789_xVo', '2026-08-29 14:55:38', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1595, 'Natsume''s Book of Friends Season 3', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx10379-lS2Mk6lX4lZr.jpg', 'series', '8.4', 'Takashi Natsume has always been shunned by those around him because of his mysterious ability to see yokai. Eventually, he came into possession of his grandmother Reiko’s “Book of Friends,” and together with his bodyguard Nyanko-sensei he set out to return the names of the yokai contained within it. Since then, he’s found a home with the Fujiwaras and surrounded himself with friends at school. Little does he know he''s about to be dragged unwittingly into further trouble...

(Source: NIS America)', 'Brain''s Base', '2011', 'series', 'released', '2011-07-05', 10379, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10379-QrQ5hQCZzdN1.jpg', 'Drama, Fantasy, Slice of Life, Supernatural', 'TV', 'SUMMER', 13, 48971, 'https://www.youtube.com/watch?v=eGagSxjjA0s', '2026-08-29 14:55:41', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1596, 'Hajime no Ippo: The Fighting! New Challenger', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx5258-Qn6GBiSY57iT.jpg', 'series', '8.5', 'Ippo Makunouchi continues his boxing career and his goal on knowing the meaning of being strong, and the desire on fighting his idol Ichiro Miyata once again. Along him are pro boxers Takamura, Aoki and Kimura that each one of them aspire to their own dreams.

(Source: Anime News Network)', 'MADHOUSE', '2009', 'series', 'released', '2009-01-06', 5258, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/5258-sVUejsZEekdD.jpg', 'Comedy, Drama, Sports', 'TV', 'WINTER', 26, 60207, 'https://www.youtube.com/watch?v=Zs6zqkFWavo', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1597, 'The Tatami Galaxy', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx7785-aTjIhsYva8cJ.jpg', 'series', '8.5', 'When a college dropout stops for a late night bite at a mysterious ramen stand, he crosses paths with a self-proclaimed deity of matrimony. This bizarre meeting sends the young man hurtling through a horrifying flashback to his not-so-glorious college days when the influence of a cruel new friend turned him from a hopeless romantic into a mischievous “black cupid.”


(Source: Funimation)', 'MADHOUSE', '2010', 'series', 'released', '2010-04-23', 7785, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/7785.jpg', 'Comedy, Mystery, Psychological, Romance', 'TV', 'SPRING', 11, 146587, 'https://www.youtube.com/watch?v=fJUuiOptb2A', '2026-08-29 14:55:33', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1598, 'Natsume''s Book of Friends Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx5300-t9N4PoOkPAdS.jpg', 'series', '8.3', 'As with its prequel, Zoku Natsume Yuujinchou is about Natsume Takashi, a boy who has had the ability to see youkai since he was young, and his bodyguard youkai, Madara, nicknamed Nyanko-sensei. Natsume attempts to return names written in his Book of Friends, which he inherited from his grandmother Reiko, to youkai in his village. Throughout these adventures, he meets some youkai that are friendly, some that want to steal the Book of Friends, and some that want to kill him. Natsume learns about himself and his relationship with youkai along the way.

(Source: MAL Rewrite)', 'Aniplex', '2009', 'series', 'released', '2009-01-06', 5300, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/5300-sEIrQMgijOo7.jpg', 'Drama, Fantasy, Slice of Life, Supernatural', 'TV', 'WINTER', 13, 51328, 'https://www.youtube.com/watch?v=mea4xITAo_4', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1599, 'Major S5', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx5028-4cV1ifPbsOht.png', 'series', '8.2', 'After the baseball season was over, Goro returned to Japan. There he learned from Toshi that there is going to be a Baseball World Cup the following year hosted in America.

(Source: AniDB)', 'NHK', '2009', 'series', 'released', '2009-01-10', 5028, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', NULL, 'Comedy, Drama, Romance, Sports', 'TV', 'WINTER', 25, 13615, 'https://www.youtube.com/watch?v=Osxf1KmVuLs', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1600, 'Clannad: After Story', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx4181-zUKE7BZC62OF.png', 'series', '8.8', 'A few months have passed since Tomoya declared his love to Nagisa, and his life keeps moving forward as he continues to meet a variety of new people, expanding his world in the process. While Tomoya''s world continues to expand, his and Nagisa''s relationship is entering a new phase, and neither of them is quite sure where it will take them. Through his relationship with Nagisa, Tomoya begins to understand the meaning and importance of family.

But as Tomoya and Nagisa begin a family of their own, they are faced with many hardships along the way in Clannad: After Story

(Source: Sentai Filmworks, edited)

Note: Includes 2 un-numbered ''extra'' and ''summary'' episodes that aired at the end of the series.', 'Kyoto Animation', '2008', 'series', 'released', '2008-10-03', 4181, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4181.jpg', 'Drama, Romance, Slice of Life, Supernatural', 'TV', 'FALL', 24, 220059, 'https://www.youtube.com/watch?v=IecYMqp1N4k', '2026-08-29 14:55:21', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1601, 'ARIA The ORIGINATION', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx3297-FHuyO7uiefNg.png', 'series', '8.6', 'In Neo Venezia, Akari, Aika, and Alice continue to work diligently toward the day they become full-fledged Prima Undine (a professional tour guide gondolier). The girls have come far since they began their training, and they are slowly forming their own distinctive styles as tour guides for the city.

On the long journey towards their goal, the girls have relied on the advice of their seniors from their respective companies: the patient and understanding Alicia from Aria Company, the strict and proper Akira from Himeya Company, and the clumsy yet caring Athena from Orange Planet Company.

Will the girls be able to blend the advice from their mentors with their personally acquired knowledge of Neo Venezia to become praiseworthy Prima Undines?

Welcome once more to Neo Venezia; the city that personifies warmth and tranquility.', 'Hal Film Maker', '2008', 'series', 'released', '2008-01-08', 3297, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/3297.jpg', 'Fantasy, Sci-Fi, Slice of Life', 'TV', 'WINTER', 13, 36620, 'https://www.youtube.com/watch?v=isUbizchCoI', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1602, 'Mononoke', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2246-WHkSkgyuxfgD.jpg', 'series', '8.2', 'Mononoke is a spin-off of the Bakeneko story arc of Ayakashi: Japanese Classic Horror. It follows the Medicine Seller as he deals with various spirits or "Mononoke" in feudal Japan. Just like in the Bakeneko story, he combats with a series of tools and his vast knowledge of the supernatural on his side, but can only slay the Mononoke when he uncovers its form (Katachi), the truth behind its appearance (Makoto) and the reason for its unusual behavior (Kotowari).

(Source: Wikipedia)', 'Toei Animation', '2007', 'series', 'released', '2007-07-13', 2246, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2246-8DKsjLTMEFJq.png', 'Fantasy, Horror, Mystery, Psychological, Supernatural', 'TV', 'SUMMER', 12, 91355, 'https://www.youtube.com/watch?v=OVDCDT_Lldw', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1603, 'Kaiji - Ultimate Survivor', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx3002-BExanPfxp888.jpg', 'series', '8.2', 'Itou Kaiji is a bum who steals car emblems and slashes tires on what seems to be a regular basis. This routine changes one day when he is paid a visit by a man in a trench-coat. Once the two get talking, it seems that the visitor (Calling himself Endou) is a debt collector. The reason for his visit is an unpaid loan which Kaiji had previously co-signed for a work-mate (Furuhata Takeshi). The original loan was 300,000 yen and once Takeshi had disappeared, the loan then fell on Kaiji.

Kaiji is then told of a way to clear the interest compounded debt (which stood at 3,850,000 yen), which involved getting on a boat with others in his position. Once on the boat the debtors would then have to gamble with loaned money, which would end with a few winning, and others getting into deeper debt and having to work to pay off their debts. After some coercion Kaiji accepts a position on the boat, in order to clear his debt and make a bit of money as well...', 'MADHOUSE', '2007', 'series', 'released', '2007-10-03', 3002, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/3002-HcG6WRNYf5BC.jpg', 'Psychological, Thriller', 'TV', 'FALL', 26, 96995, 'https://www.youtube.com/watch?v=EK1LiaJ-TSU', '2026-08-29 14:57:18', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1604, 'NANA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx877-6BUYEWp8By8j.png', 'series', '8.5', 'Two twenty-somethings seemingly share nothing in common apart from their first name, but a chance meeting on a train bound for Tokyo sets Nana Komatsu and Nana Oosaki on a collision course with destiny. Nana Komatsu, a love-at-first-sight dreamer, aims to find enduring happiness in the big city. Nana Oosaki, neo punk rock vocalist, pursues her burning ambitions of musical stardom and worldwide fame. As their fates increasingly intertwine, they each chase their dreams — until the harsh realities of life in big city Tokyo threaten to tear everything apart.

(Source: Sentai Filmworks)', 'MADHOUSE', '2006', 'series', 'released', '2006-04-05', 877, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/877-5yVMHXHApFzf.jpg', 'Drama, Music, Romance, Slice of Life', 'TV', 'SPRING', 47, 203060, 'https://www.youtube.com/watch?v=Tad-n4Xh3nI', '2026-08-29 14:55:07', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1605, 'MUSHI-SHI', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx457-l6cTtNgI9Bi6.png', 'series', '8.5', 'Neither good nor evil, they are life in its purest form. Vulgar and strange, they have inspired fear in humans since the dawn of time and have, over the ages, come to be known as "mushi." The stories of the Mushi and the people they affect are all linked together by a traveling Mushi-shi, or "Mushi Master," who seeks rare Mushi sightings and uses his shaman-like knowledge of Mushi to help the affected people.

What are the Mushi and what do they want?

(Source: Funimation)', 'Artland', '2005', 'series', 'released', '2005-10-23', 457, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n457-sWOJfqYC7s2I.jpg', 'Adventure, Fantasy, Mystery, Psychological, Slice of Life, Supernatural', 'TV', 'FALL', 26, 191123, 'https://www.youtube.com/watch?v=h371H0KIuPo', '2026-08-29 14:55:04', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1606, 'Welcome to the N-H-K', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1210-2XotjcgqdcaX.jpg', 'series', '8.2', 'Satou’s life – or what’s left of it – is a paranoid mess of conspiracy theories and social anxieties. He’s terrified of the outside world; his apartment is overflowing with the remnants of cheap take-out food; and his retinas have been permanently scarred by a steady diet of internet porn. But maybe it’s not all his fault. After all, the nefarious N-H-K is out there, and they’re determined to turn society’s fringe-dwellers into a brainwashed lot of jobless, hopeless, futureless recluses.

Enter Misaki – a mysterious girl-next-door type who is Satou’s last chance to beat down his inner demons and venture out into the light of day. She’s ready to help him overcome his crippling phobias, but Satou would rather cower in his existential foxhole and pretend to work on the demo for his virtual sex game.

He’s afraid to face the world. She’s strangely desperate to fix a total stranger. Maybe together they can be normal.

(Source: Funimation)', 'GONZO', '2006', 'series', 'released', '2006-07-10', 1210, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1210-M5oFyKfKm2zT.jpg', 'Comedy, Drama, Psychological, Romance, Slice of Life', 'TV', 'SUMMER', 24, 201607, 'https://www.youtube.com/watch?v=awEVT7CtkFc', '2026-08-29 14:55:10', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1607, 'ARIA The NATURAL', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx962-hMxjrjZYObAw.png', 'series', '8.1', 'Akari Mizunashi continues her training to become a Prima Undine (a professional tour guide gondolier) along with her friends Aika and Alice in the peaceful city of Neo Venezia. Despite the fact that these three girls are from competing companies, they are constantly together, learning more about how to become better tour guides and more about the mysteries of Neo Venezia.

As the group continues to meet interesting and unforgettable people through their daily routines, they will also come closer to the secrets that make the enigmatic and ever beautiful city of Neo Venezia so warm and alive.

Welcome back to Neo Venezia: the city where miracles can be created by hand.', 'Hal Film Maker', '2006', 'series', 'released', '2006-04-03', 962, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/962.jpg', 'Fantasy, Sci-Fi, Slice of Life', 'TV', 'SPRING', 26, 24633, 'https://www.youtube.com/watch?v=tH4RPUZHHMc', '2026-08-29 14:55:01', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1608, 'Hellsing Ultimate', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx777-F6547pSAR2Zd.jpg', 'series', '8.1', 'Hellsing, a secret organization of the British government, has long been battling supernatural threats to keep the people safe from creatures of the night. The current leader, Integra Wingates Hellsing controls her own personal army to eliminate the undead beings, but even her highly trained soldiers pale in comparison to her most trusted vampire exterminator, a man by the name of Alucard, who is actually a powerful vampire himself. Along with Integra''s mysterious butler and Alucard''s new vampire minion, Seras Victoria, The Hellsing Organization must face not only regular ghouls and vampires, but a rivaling secret organization from the Vatican, and Millennium, an enigmatic group of madmen spawned by a certain war over 50 years ago...

A bloody battle between monsters is about to begin, the dead are dancing, and all hell is singing...', 'MADHOUSE', '2006', 'series', 'released', '2006-02-10', 777, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/777-XzPjBZdSRtDT.jpg', 'Action, Horror, Supernatural', 'OVA', 'WINTER', 10, 182389, 'https://www.youtube.com/watch?v=7CQKMDFAKMk', '2026-08-29 14:54:53', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1609, 'Samurai Champloo', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx205-7tHVFu6dPBm9.png', 'series', '8.4', 'Let''s break it down. Mugen''s a reckless sword-slinger with a style that''s more b-boy than Shaolin. He''s got a nasty streak that makes people want to stick a knife in his throat. Then there''s Jin, a deadbeat ronin who speaks softly but carries a big blade. He runs game old-school style, but he can make your blood spray with the quickness. When these roughnecks bring the ruckus, it ain''t good for anybody, especially them. Enter Fuu, the ditzy waitress who springs her new friends from a deadly jam. All she wants in return is help solving a riddle from her past. She and the boys are tracking the scent, but there''s 99 ways to die between them and the sunflower samurai.

(Source: Funimation)', 'Manglobe', '2004', 'series', 'released', '2004-05-20', 205, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/205-L7WpOOWUmVjh.jpg', 'Action, Adventure, Comedy', 'TV', 'SPRING', 26, 275642, 'https://www.youtube.com/watch?v=xWKzbhAUeZE', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1610, 'Hajime no Ippo: The Fighting!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx263-ivVyn9xAgwSZ.png', 'series', '8.7', 'Makunouchi Ippo has been bullied his entire life. Constantly running errands and being beaten up by his classmates, Ippo has always dreamed of changing himself, but never has the passion to act upon it. One day, in the midst of yet another bullying, Ippo is saved by Takamura Mamoru, who happens to be a boxer. Ippo faints from his injuries and is brought to the Kamogawa boxing gym to recover. As he regains consciousness, he is awed and amazed at his new surroundings in the gym, though lacks confidence to attempt anything. Takamura places a photo of Ippo''s classmate on a punching bag and forces him to punch it. It is only then that Ippo feels something stir inside him and eventually asks Takamura to train him in boxing. Thinking that Ippo does not have what it takes, Takamura gives him a task deemed impossible and gives him a one week time limit. With a sudden desire to get stronger, for himself and his hard working mother, Ippo trains relentlessly to accomplish the task within the time limit. Thus Ippo''s journey to the top of the boxing world begins.', 'MADHOUSE', '2000', 'series', 'released', '2000-10-04', 263, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/263-8Zejtdb3r2bI.jpg', 'Comedy, Drama, Sports', 'TV', 'FALL', 75, 141016, 'https://www.youtube.com/watch?v=Y_f8MCOVHJA', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1611, 'Rurouni Kenshin OVA: Trust & Betrayal (Tsuioku-hen)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx44-MG5I672UbWAy.png', 'series', '8.5', 'In the days before the Japanese Revolution, Hiko Seiijuro, a wandering master swordsman and hermit, encounters a bandit raid on a slave wagon. Hiko kills the raiding bandits in hopes of saving as many lives as possible, but only manages to spare one life from the massacre. Hiko leaves the child, advising him to go to the nearby village and have them take care of him. 

A few days later, as Hiko comes back to check upon the child he saved, he is shocked to see the child had created graves, both for the slaves he befriended and the bandits who killed them. Seeing potential in the young one, Hiko takes the child under his wing, names him Kenshin, meaning "heart of sword," and teaches him about the art of swordsmanship under the Hiten Mitsuruugi Ryu.

Struggling in a constant challenge with his ideal beliefs reflecting against the harshness of reality, Tsuiokuhen tells the melancholic and dark story of Himura Kenshin as one of the most feared assassins of the Japanese Revolution: the Hitokiri Battousai.

(Source: MAL Rewrite)', 'Studio DEEN', '1999', 'series', 'released', '1999-02-20', 44, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/44-C4I2Dy8MMyy0.jpg', 'Action, Drama, Romance', 'OVA', 'WINTER', 4, 46822, 'https://www.youtube.com/watch?v=MhKyFMKVtBk', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1612, 'GTO: Great Teacher Onizuka', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx245-NcQAyTipUMeO.jpg', 'series', '8.4', 'Onizuka is a reformed biker gang leader who has his sights set on an honorable new ambition: to become the world''s greatest teacher... for the purpose of meeting sexy high school girls. Okay, so he''s mostly reformed.

However, strict administrators and a class of ruthless delinquents stand between Onizuka and his goal and they will use any means, however illegal or low, to drive the new teacher away. Perfect, because Onizuka''s methods won''t be found in any teaching manual; he cares about the difference between legal and illegal activities about as much as he cares for the age difference between himself and a high school girl.

So get ready for math that doesn''t add up, language you''d be slapped for using, and biology that would make a grown man blush... unless of course, you''re the Great Teacher Onizuka.

 Note: Episode 1 has an airtime of 48 minutes.', 'Studio Pierrot', '1999', 'series', 'released', '1999-06-30', 245, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/245-sIPMF9vNDnaJ.jpg', 'Comedy, Drama, Slice of Life', 'TV', 'SUMMER', 43, 172748, 'https://www.youtube.com/watch?v=HS2n3-e_0PE', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1613, 'Slam Dunk', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx170-cmD8A0vZsp6g.jpg', 'series', '8.3', 'Hanamichi Sakuragi, an entering Shohoku high school freshman holds a record for being rejected by 50 girls during middle school. His nearly 2 meters height and bright red hair causes most students to write him off as a delinquent. 

One day, a girl named Haruko Akagi approaches Hanamichi without any fear. When she asks Hanamichi: "do you like basketball?" Hanamichi falls head over heels for the girl of his dreams. Without missing a beat, Hanamichi tells her he loves basketball, and the two head to the gymnasium where Hanamichi learns about the slam dunk. He also learns of Rukawa, one of the country&rsquo;s top basketball prospects, also a freshman at Shohoku.

(Source: Funimation)', 'Toei Animation', '1993', 'series', 'released', '1993-10-16', 170, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/170-hCgzytQLmZdX.jpg', 'Comedy, Drama, Slice of Life, Sports', 'TV', 'FALL', 101, 72218, 'https://www.youtube.com/watch?v=l4nP-Zm9YAs', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1614, 'Yu Yu Hakusho: Ghostfiles', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx392-z90299zIvYmx.png', 'series', '8.3', 'Urameshi Yusuke, 14 years of age, is about as troublesome and violent as teenagers come. He is constantly ditching school, causing trouble, and getting into numerous fights everyday. One day however, he does the unexpected, sacrificing himself to save a young child. Such an action, was never ever expected, especially coming from someone as troublesome as Urameshi Yusuke. The afterlife is not prepared for Yusuke, as they never thought he would make such a sacrifice. Nowhere to go, and dead, Yusuke becomes a ghost and must earn his way back into existence.

Yusuke is "employed" by Koenma, who is in charge while his father and ruler of the afterlife, King Enma, is away. Under Koenma''s command, Yusuke helps to stop menacing demons that threaten the lives of people everywhere; whether by stealing priceless and invaluable items and destructive weapons, or by wreaking havoc on humans everywhere.

Throughout Yusuke''s journey, he is usually joined by; his arch-rival, and local bully, Kuwabara Kazuma. He is also joined by two demons named Hiei and Kurama, whom are ex-convicts of the afterlife that managed to escape from Koenma.

This group of unlikely allies goes on to participate and struggle in battles that have outcomes that determine the fate of humanity!

(Source: AniDB)', 'Studio Pierrot', '1992', 'series', 'released', '1992-10-10', 392, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/392-nbB6cBnhHOFb.jpg', 'Action, Adventure, Comedy, Supernatural', 'TV', 'FALL', 112, 156467, 'https://www.youtube.com/watch?v=UuRNnGmwVc4', '2026-08-29 14:56:58', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1615, 'Mobile Police Patlabor 2: The Movie', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1096-O4Nz0aBmMSxH.jpg', 'movies', '8.1', 'The date is 2002, three years after the events of PATLABOR 1 &ndash; Mobile Police. The destruction of a United Nations Labor team in South East Asia begins the build-up to a deadly terrorist plan that threatens to send shockwaves throughout Japan''s military. With evidence of an impending military takeover, the scattered members of the original SVD (Special Vehicle Division) must gather to defend the city against danger. To make matters worse, the mastermind behind the operation is none other than Nagumo''s former teacher and ex-lover Tsuge. 

(Source: Anime News Network)', 'Production I.G', '1993', 'movie', 'released', '1993-08-07', 1096, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1096-itEd3O4eF4de.jpg', 'Drama, Mecha, Mystery, Sci-Fi', 'MOVIE', 'SUMMER', 1, 15466, 'https://www.youtube.com/watch?v=bRYWHzTVkow', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1616, 'Romeo''s Blue Skies', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2559-JURloxu6nxV8.jpg', 'series', '8.0', 'Romeo, a young boy living in the Alps of Italian Switzerland, signs a contract with a shady individual to pay for his sick father''s doctor, who will take him across the mountains to Italy, to Milan, where he will be sold as a chimney sweep''s helper. Thus begins Romeo''s journey, amidst abuse and violence, during which he will form lasting and deep bonds with other child chimney sweeps, coming to form a fraternity called "The Black Brothers," who will all learn to help each other in times of need.', 'Nippon Animation', '1995', 'series', 'released', '1995-01-15', 2559, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2559-Wb2uVa1uES0W.jpg', 'Adventure, Drama, Slice of Life', 'TV', 'WINTER', 33, 13848, 'https://www.youtube.com/watch?v=p7ER0ZJSdWE', '2026-08-29 14:56:56', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1617, 'Dear Brother', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx795-HJhtGq0Hql2r.jpg', 'series', '7.8', 'Before leaving her cram school, Nanako Misonō asks one of the teachers if they can become pen-pals. The teacher, Takehiko Henmi, is reluctant at first, but eventually accepts the offer. The story is narrated through the letters sent from Nanako as she enters Seiran, a renowned private high school for girls only. There she encounters many difficulties as an ordinary middle-class girl invited to the prestigious Sorority, the most traditional and sophisticated club on campus.. 

(Source: AnimeNewsNetwork)', 'Tezuka Productions', '1991', 'series', 'released', '1991-07-14', 795, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/795-2tIUrMnmce27.png', 'Drama, Psychological', 'TV', 'SUMMER', 39, 21434, 'https://www.youtube.com/watch?v=FA9k1KM2jt4', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1618, 'Tomorrow''s Joe 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2921-PxFepBRCGD0K.jpg', 'series', '8.8', 'Yabuki Joe is left downhearted and hopeless after a certain tragic event. In attempt to put the past behind him, Joe leaves the gym behind and begins wandering. On his travels he comes across the likes of Wolf Kanagushi and Goromaki Gondo, men who unintentionally fan the dying embers inside him, leading him to putting his wanderings to an end. His return home puts Joe back on the path to boxing, but unknown to himself and his trainer, he now suffers deep-set issues holding him back from fighting. In attempt to quell those issues, Carlos Rivera, a world renowned boxer is invited from Venezuela to help Joe recover.', 'Tokyo Movie Shinsha', '1980', 'series', 'released', '1980-10-13', 2921, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2921-8cz7wULNyEgs.jpg', 'Action, Drama, Slice of Life, Sports', 'TV', 'FALL', 47, 21386, 'https://www.youtube.com/watch?v=hJ5KjrjfD40', '2026-08-29 14:56:52', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1619, 'Legend of the Galactic Heroes', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx820-x5dNLNFeKb8B.png', 'series', '8.8', 'For decades, the Galactic Empire has been locked in an interstellar war with the Free Planets Alliance, a conflict that involves thousands of spaceships and millions of soldiers on both sides. Two new commanders enter the conflict with great hopes: Imperial Admiral Reinhard von Lohengramm and the FPA''s Yang Wen-Li. As they deal with superiors and subordinates, maneuver through complicated political arrangements, plot strategies, and win battles, each will be tested, and ultimately, changed, by the reality of war. 

(Source: Anime News Network)', 'Kitty Film', '1988', 'series', 'released', '1988-01-08', 820, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/820-FcKc3kvg60z8.jpg', 'Drama, Sci-Fi', 'OVA', 'WINTER', 110, 83594, 'https://www.youtube.com/watch?v=Ou37P25tjJY', '2026-08-29 14:55:44', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1622, 'The Ideon: Be Invoked', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx2761-3hWAkJ69gBKL.jpg', 'movies', '8.1', 'The epic conclusion to the Ideon saga, featuring what was meant to be the final 5 episodes of the TV series. The Solo Ship and its crew continue their intense battle with the Buff Clan leading to a final battle that will determine the fate of all life in the universe.

This movie features the last episode of the TV series Space Runaway Ideon (39), and four more episodes (40-43) that were meant to air on TV, but never did since the show was cancelled.

This movie was the second part of a double feature along with "The Ideon: A Contact".

(Source: Anime News Network)', 'Sunrise', '1982', 'movie', 'released', '1982-07-10', 2761, 0, NULL, '2026-07-25 18:40:10', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2761-SYo9ltVd1OiG.jpg', 'Drama, Mecha, Sci-Fi', 'MOVIE', 'SUMMER', 1, 5780, 'https://www.youtube.com/watch?v=aOOGVSK20h8', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1623, 'Bakuman. 3', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx12365-G5nFzWm2mIwz.png', 'series', '8.3', 'Moritaka Mashiro and Akito Takagi have come a long way since they started making manga in middle school, but trials still await them as they head towards their goal of getting an anime adaptation for one of their manga. As they continue to grow as artists and as people, they will be faced with new friends, new rivals, and new hurdles to overcome.

(Source: Anime News Network)', 'J.C.STAFF', '2012', 'series', 'released', '2012-10-06', 12365, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/12365-icejvUdmnD8D.jpg', 'Comedy, Drama, Romance, Slice of Life', 'TV', 'FALL', 25, 58298, 'https://www.youtube.com/watch?v=-P1znat5sK8', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1624, 'Nichijou - My Ordinary Life', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx10165-tw8Cz7K9tfVJ.png', 'series', '8.3', 'Nichijou primarily focuses on the daily antics of a trio of childhood friends—high school girls Mio Naganohara, Yuuko Aioi and Mai Minakami—whose stories soon intertwine with the young genius Hakase Shinonome, her robot caretaker Nano, and their talking cat Sakamoto. With every passing day, the lives of these six, as well as of the many people around them, experience both the calms of normal life and the insanity of the absurd. Walking to school, being bitten by a talking crow, spending time with friends, and watching the principal suplex a deer: they are all in a day''s work in the extraordinary everyday lives of those in Nichijou. 

(Source: MAL Rewrite)', 'Kyoto Animation', '2011', 'series', 'released', '2011-04-03', 10165, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10165-1O0xQsic1qpB.jpg', 'Comedy, Slice of Life', 'TV', 'SPRING', 26, 238528, 'https://www.youtube.com/watch?v=CD6VdVDVDXI', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1625, 'Space Brothers', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx12431-vL6wmxLsTzzS.png', 'series', '8.3', 'Mutta''s life has hit rock bottom. He''s been fired, blackballed from his profession and now he''s had to move back in with his parents. Meanwhile, his kid brother Hibito has been literally riding a rocket and training to be an astronaut. The same career Mutta once dreamed of. So, is it ever too late to go after your dreams? Through a little coercing and a bit of covert activity, Mutta''s family and friends can get his resume on the right desk, but from that point on it will be up to Mutta himself. Does he have what it takes to turn his life around and put his footprint on the moon? The first step on the highway to the stars is always the hardest, and in a job where crash and burn isn''t just a euphemism, it will be the biggest risk Mutta''s ever taken. But with the best support team ever, maybe he''ll find what he needs to rekindle the spark inside him and light the biggest candle of them all! 


(Source: Sentai Filmworks)', 'A-1 Pictures', '2012', 'series', 'released', '2012-04-01', 12431, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/12431-L8FNRD2Ylvei.jpg', 'Comedy, Sci-Fi, Slice of Life', 'TV', 'SPRING', 99, 48747, 'https://www.youtube.com/watch?v=HMm725pwSp8', '2026-08-29 14:57:23', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1626, 'Kaiji - Against All Rules', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx10271-Aep4woDDbXdU.jpg', 'series', '8.2', 'Several months after the events of the first season, Kaiji, with his appendages reattached and his debt now run up to 9.5 million yen, is still desperately seeking the elusive big score that will cancel all of his markers. Unbeknownst to him, Hyodo’s company, the Teiai Corporation, is actively searching for Kaiji, and have sent Kaiji’s old “friend” Endoh, who entered him in the high stakes games in the past, to find him. 


The two meet when Kaiji chances to walk in front of Endoh’s car at a stop light, and thinking that he has found the answer to his prayers, Kaiji gets in the car with him. While Kaiji and Endoh are “happy” to see one another, and both want to see Kaiji’s debt repaid, their means to that goal couldn’t be more different.


Instead of leading Kaiji to the big score, Endoh delivers him drugged and docile to the Teiai Corporation’s secret underground labor camp where Kaiji will have an opportunity to repay his debt… with 15 years of hard labor. 


(Source: Sea Slugs)', 'MADHOUSE', '2011', 'series', 'released', '2011-04-06', 10271, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10271-ecaOzC2DntBL.jpg', 'Psychological, Thriller', 'TV', 'SPRING', 26, 53358, 'https://www.youtube.com/watch?v=EK1LiaJ-TSU', '2026-08-29 14:57:20', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1627, 'Bakuman. 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx10030-EsnaZOM25Jcc.png', 'series', '8.1', 'After the decision to serialize Moritaka and Akito has been made, they are introduced to Miura, their new manager. At first, the two thought it was a joke, but Hattori gives them a pep talk before leaving. While Miura doesn''t seem like a bad person, he is given to rudeness and seems to be worried about the duo''s future. In addition, the duo are given three assistants to work on their manuscript, and with the assistance of Ogawa, an experienced assistant, their work progresses well. 

At the start of the new year, Moritaka and Akito both attend Shonen Jack''s New Year Party. There, they meet Hiramaru Kazuya, said to be a genius of a whole different level from Eiji.', 'J.C.STAFF', '2011', 'series', 'released', '2011-10-01', 10030, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10030-QiRMSckmsboa.jpg', 'Comedy, Drama, Romance, Slice of Life', 'TV', 'FALL', 25, 62459, 'https://www.youtube.com/watch?v=8rqSJ2X4nBA', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1628, 'Bunny Drop', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx10162-w4SG5oQSQwMn.jpg', 'series', '8.1', 'Going home from his grandfather''s funeral, thirty-year-old Daikichi is floored to discover that the old man had an illegitimate child with a younger lover. The rest of his family is equally shocked and embarrassed by this surprise development, and not one of them wants anything to do with the silent little girl, Rin Kaga. In a fit of anger, Daikichi decides to take her in himself. As Daikichi nurtures Rin, he started to understand the struggle while at the same time the joy of parenting.

(Source: Anime News Network)', 'Production I.G', '2011', 'series', 'released', '2011-07-08', 10162, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10162-CHoa4mll25WM.png', 'Slice of Life', 'TV', 'SUMMER', 11, 101011, 'https://www.youtube.com/watch?v=PlWk-96JHz4', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1629, 'Kamisama Kiss', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx14713-RyZ7bA7CdvGw.jpg', 'series', '8.1', 'Nanami Momozono is alone and homeless after her dad skips town to evade his gambling debts and the debt collectors kick her out of her apartment. So when a man she''s just saved from a dog offers her his home, she jumps at the opportunity. But it turns out that his place is a shrine, and Nanami has unwittingly taken over his job as a local deity! 

Nanami has all kinda of new responsibilities she doesn''t understand, dangers she''s unaware of, and a cranky ex-familiar who''s... actually pretty hot. What''s a new-fledged godling to do? 

(Source: VIZ Media)', 'TMS Entertainment', '2012', 'series', 'released', '2012-10-02', 14713, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/14713-t6RcaL0IqwlW.jpg', 'Comedy, Fantasy, Romance, Supernatural', 'TV', 'FALL', 13, 166784, 'https://www.youtube.com/watch?v=HzCba_fi-to', '2026-08-29 14:57:15', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1630, 'Chihayafuru', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx10800-hofcUL0YEL7O.png', 'series', '8.0', 'Chihaya Ayase  has spent most of her life supporting her sister’s model career. When she meets a boy named Arata Wataya, he thinks Chihaya has potential to become a great karuta player. As Chihaya dreams of becoming Japan''s best karuta player, she is soon separated from her karuta playing friends. Now in high school, Chihaya still plays karuta in the hope that she will one day meet her friends again. 

(Source: Crunchyroll)', 'MADHOUSE', '2011', 'series', 'released', '2011-10-05', 10800, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10800-hcHzj4rkDQzG.jpg', 'Drama, Romance, Slice of Life, Sports', 'TV', 'FALL', 25, 121864, 'https://www.youtube.com/watch?v=Y8U-E8hldHk', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1631, 'Star Blazers: Space Battleship Yamato 2199', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx12029-qIY5Bkh4sFKx.png', 'series', '8.0', 'The year is 2199. The human race has been crushed in their war with the Gamilos, driven into underground cities by the invader''s assault. Scientists estimate they have only a year left. The young officers Susumu Kodai and Daisuke Shima receive a mysterious capsule from a ship that made an emergency landing on Mars and return with it to Earth. It contains humanity''s last hope: the planet Iscandar on the other side of the Magellan Galaxy has the technology to defeat the Gamilos and restore the planet. The space battleship Yamato is entrusted with this task, but they have only one year before humanity ends.

(Source: Anime News Network)', 'Xebec', '2012', 'series', 'released', '2012-04-06', 12029, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/12029-iAyPj5JOcvsp.jpg', 'Action, Drama, Sci-Fi', 'OVA', 'SPRING', 26, 30816, 'https://www.youtube.com/watch?v=GYWvOBTIIps', '2026-08-29 14:57:32', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1632, 'Major: World Series', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx11917-053ZcENZWJxS.png', 'series', '8.0', 'According to Weekly Shonen Sunday, a new OVA of manga "Major" was announced to be released in December. The World Series chapter, which was skipped in the TV series, will be animated. This OVA will be the final anime of Major.

(Source: Scan of WSS)', 'SynergySP', '2011', 'series', 'released', '2011-12-16', 11917, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', NULL, 'Comedy, Drama, Sports', 'OVA', 'WINTER', 2, 8408, 'https://www.youtube.com/watch?v=kDjRT6mSj3c', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1633, 'Kids on the Slope', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx12531-m8q2U1lA6V90.jpg', 'series', '8.0', 'The beginning of summer, 1966. 

Because of his father''s job situation, freshman high school student Kaoru Nishimi moves by himself from Yokosuka to Kyushu to live with relatives. Until then, Kaoru was an honor roll student who tended to keep to himself, but meeting notorious bad boy Sentaro Kawabuchi starts to change him. Through his devil-may-care classmate, Kaoru learns the attractions of jazz and finds the first person he can call a "friend". He also discovers how much fun it is to play music with a pal. 

Other characters include Sentaro''s kind childhood chum, Ritsuko, who is the daughter of a record shop owner; the mysterious upperclassman, Yurika; and Brother Jun, the much-admired leader among their peers. Set against the backdrop of a seaside town with a scent of American culture, this series is a drama about young people coming into their own, crossing each other''s paths, and finding friendship, love, and music! 

(Source: Official Website)', 'Tezuka Productions', '2012', 'series', 'released', '2012-04-13', 12531, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/12531-S7FaZwnZPCWQ.jpg', 'Drama, Music, Romance, Slice of Life', 'TV', 'SPRING', 12, 95431, 'https://www.youtube.com/watch?v=fpJSOUCSWGI', '2026-08-29 14:57:35', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1634, 'Hidamari Sketch x Honeycomb', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx11239-JysRplnD2e0P.jpg', 'series', '8.0', 'The fourth season of Hidamari Sketch.

Studying at the Yamabuki Arts High School has been a dream-come-true for Yuno, and she''s learned so much already! And not just from her instructors, but from her friends and neighbors who''ve become her second family and made the Hidamari Apartments such a safe and nurturing home. But as the day of her "big sisters" Sae and Hiro''s graduation draws slowly closer, it''s time for Yuno to start seriously taking on the same role for Nazuna, Nori and the other budding young artists who''ve entered Hidamari''s protective cocoon. And it''s also time to tackle some really challenging artistic assignments. That doesn''t mean there won''t still be time for fun with Miyako and all the others, but it''s definitely time to pencil in her plans for the future. And sometimes that means you have to put the art before the course! 

(Source: Sentai Filmworks)', 'Aniplex', '2012', 'series', 'released', '2012-10-05', 11239, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11239-IH1qkMFp2tgR.jpg', 'Comedy, Slice of Life', 'TV', 'FALL', 12, 8950, 'https://www.youtube.com/watch?v=00t2d69wDzY', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1635, 'From the New World', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx13125-2EDZb8ahshQc.png', 'series', '8.0', 'Following a sudden outbreak of psychokinesis in 0.1% of the population, a rapid transformation swept the world. The godlike ability to manipulate matter remotely turned many power wielders to violence, inciting a long period of upheaval. Finally, after a chaotic era shaped by the rise and fall of oppressive regimes, the psychic humans were able to achieve a fragile peace by isolating their society, creating a new world bound by complex rules.

In the town of Kamisu 66, 12-year-old Saki Watanabe has just awakened to her powers and is relieved to rejoin her friends—the mischievous Satoru Asahina, the shy Mamoru Itou, the cheerful Maria Akizuki, and Shun Aonuma, a mysterious boy whom Saki admires—at Sage Academy, a special school for psychics. However, unease looms as Saki begins to question the fate of those unable to awaken to their powers, and the children begin to get involved with secretive matters such as the rumored Tainted Cats said to abduct children.

Shinsekai yori tells the unique coming-of-age story of Saki and her friends as they journey to grow into their roles in the supposed utopia. Accepting these roles, however, might not come easy when faced with the dark and shocking truths of society, and the impending havoc born from the new world.

(Source: MAL Rewrite)', 'A-1 Pictures', '2012', 'series', 'released', '2012-09-29', 13125, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/13125.jpg', 'Drama, Horror, Mystery, Psychological, Sci-Fi, Supernatural', 'TV', 'FALL', 25, 176005, 'https://www.youtube.com/watch?v=WtWiMTDhCUo', '2026-08-29 14:57:40', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1636, 'Daily Lives of High School Boys', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx11843-ui2jBcuQUqnl.jpg', 'series', '8.0', 'Tadakuni, Hidenori, and Yoshitake are students at the all-boys academy, Sanada North High School. This is a tale about just that—their daily lives as students. Winning the basketball tournament? Finding true love? You won''t find any of that here. Whether it''s sparking random arguments while hanging out with friends, meeting that one weird co-worker at a part-time job, or even letting imaginations run wild on a windy afternoon, we''ve all experienced the show''s ordinary but true-to-life themes at one point or another. 


(Source: NIS America)', 'Sunrise', '2012', 'series', 'released', '2012-01-10', 11843, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11843-2GxMdvjHLn6v.jpg', 'Comedy, Slice of Life', 'TV', 'WINTER', 12, 191718, 'https://www.youtube.com/watch?v=BsQj0RYzW98', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1637, 'Magical Girl Lyrical Nanoha: The Movie 2nd A''s', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx10153-8xp0PkSWLHHK.jpg', 'movies', '8.0', 'Sequel of Mahou Shoujo Lyrical Nanoha The Movie 1st.', 'Seven Arcs', '2012', 'movie', 'released', '2012-07-14', 10153, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', NULL, 'Action, Drama, Mahou Shoujo, Sci-Fi', 'MOVIE', 'SUMMER', 1, 7515, 'https://www.youtube.com/watch?v=lXWiKIY0xFQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1638, 'Initial D Fifth Stage', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/15059.jpg', 'series', '7.9', 'Taking place in the sacred land of street running Kanagawa, once more Takumi Fujiwara will show his driving skills on his now legendary Hachi-roku.', 'SynergySP', '2012', 'series', 'released', '2012-11-04', 15059, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n15059-xvUhYlh52ucH.jpg', 'Action, Drama, Sports', 'TV', 'FALL', 14, 41530, 'https://www.youtube.com/watch?v=erl__gso0fM', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1639, 'Penguindrum', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx10721-lNEbDPX24qzn.jpg', 'series', '7.9', 'Once you make a decision, does the universe conspire to make it happen? Is destiny a matter of chance, a matter of choice or the complex outcome of thousands of warring strands of fate? All twins Kanba and Shoma know is that when their terminally ill sister Himari collapses at the aquarium, her death is somehow temporarily reversed by the penguin hat that she had asked for. It''s a provisional resurrection, however, and it comes at a price: to keep Himari alive they need to find the mysterious Penguin Drum. In order to do that, they must first find the links to a complex interlocking chain of riddles that has wrapped around their entire existence, and unravel the knots that tie them to mystifying diary and a baffling string of strangers and semi-acquaintances who all have their own secrets, agendas and "survival strategies." And in order for Himari to live, someone else''s chosen destiny will have to change. It''s a story of love, fate, life, death... and Penguins! 

(Source: Sentai Filmworks)', 'Brain''s Base', '2011', 'series', 'released', '2011-07-08', 10721, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10721-tN8SLwirGDAB.jpg', 'Drama, Mystery, Psychological, Supernatural', 'TV', 'SUMMER', 24, 83458, 'https://www.youtube.com/watch?v=J-Yq5hePg4c', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1640, 'Hyouka', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx12189-zj5AWUYO53Fv.jpg', 'series', '7.9', 'Energy-conservative high school student Houtarou Oreki ends up with more than he bargained for when he signs up for the Classic Literature Club at his sister''s behest—especially when he realizes how deep-rooted the club''s history really is. Begrudgingly, Oreki is dragged into an investigation concerning the 45-year-old mystery that surrounds the club room.

Accompanied by his fellow club members, the knowledgeable Satoshi Fukube, the stern but benign Mayaka Ibara, and the ever-curious Eru Chitanda, Oreki must combat deadlines and lack of information with resourcefulness and hidden talent, in order to not only find the truth buried beneath the dust of works created years before them, but of other side cases as well.

Based on the award-winning Koten-bu light novel series, and directed by Yasuhiro Takemoto of Suzumiya Haruhi no Shoushitsu, Hyouka shows that normal life can be full of small mysteries, be it family history, a student film, or even the withered flowers that make up a ghost story.

(Source: MAL Rewrite)', 'Kyoto Animation', '2012', 'series', 'released', '2012-04-23', 12189, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/12189-TG0peUcKFqur.jpg', 'Mystery, Romance, Slice of Life', 'TV', 'SPRING', 22, 347141, 'https://www.youtube.com/watch?v=9nfs-qYVv0o', '2026-08-29 14:57:54', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1641, 'Kimi ni Todoke: From Me to You Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx9656-vckh2wNj3FwY.jpg', 'series', '7.9', 'The second season of Kimi ni Todoke.

Sawako Kuronuma and her friends have just begun their second year of high school and they are in the same class together again. To make matters more interesting a male student newly transferred into their class is seated right next to Kuronuma and has taken an interest in her. What hurdles will Sawako and Kazehaya face next?

Note: Includes episode 0, "Kataomoi/A Crush".', 'Production I.G', '2011', 'series', 'released', '2011-01-12', 9656, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/9656-CE0RW5otDH1X.jpg', 'Comedy, Drama, Romance, Slice of Life', 'TV', 'WINTER', 13, 119356, 'https://www.youtube.com/watch?v=9aRQlHYaluU', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1642, 'Tiger & Bunny', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx9941-ixTUsgXCg2AI.jpg', 'series', '7.8', 'Sternbild City is home to people called "Next," who use their special abilities to protect the people as superheroes. These heroes solve cases and save lives so they can wear sponsor logos or acquire "hero points." Their activities are documented on the popular program "Hero TV," which picks the "King of Heroes" in a yearly ranking. The veteran hero Wild Tiger has always preferred to work alone, but now he''s been assigned the rookie Barnaby Brooks Jr., who has a different perspective on being a superhero.

(Source: Anime News Network)', 'Sunrise', '2011', 'series', 'released', '2011-04-03', 9941, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/9941-HJ5P0MYayd59.jpg', 'Action, Comedy, Mecha, Mystery', 'TV', 'SPRING', 25, 49485, 'https://www.youtube.com/watch?v=Pb7yeVfX-4U', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1643, 'Macross Frontier: The Wings of Farewell', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx7222-O7mOS8vlnIO4.jpg', 'movies', '7.8', 'The sequel film to Macross Frontier: Itsuwari no Utahime.

Picking up from where the previous movie left off, Ranka''s star career flourishes while Sheryl''s health rapidly deteriorates after collapsing during a live performance. At the same time, separate factions are maneuvering behind the scenes seeking to control the Vajra horde by utilizing the singing abilities of the two songstresses. As the entire Macross Frontier fleet begins to wage the final war on the Vajra, Alto finally makes a choice between Ranka and Sheryl.

(Source: Anime News Network)', 'Satelight', '2011', 'movie', 'released', '2011-02-26', 7222, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/7222-aUdPuhquUdyI.jpg', 'Action, Mecha, Music, Romance, Sci-Fi', 'MOVIE', 'WINTER', 1, 7604, 'https://www.youtube.com/watch?v=Y6fnfv_MB3Q', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1644, 'The Pet Girl of Sakurasou', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx13759-xNf0gJK4Axt2.jpg', 'series', '7.8', 'The first time he saw her, it was love at first sight. Unfortunately for Sorata Kanda, "she" was a cat named Hikari and his school''s rules forbid keeping pets in the regular dorms. As a result, Sorata is banished to the infamous Sakura Hall alongside other troublesome and unusual students like Jin, overzealous playboy, Ryuunosuke, the reclusive hermit, and Mashiro, a brilliant artist who''s so unfocused and clueless about the real world that dorm supervisor Ms. Sengoku assigns Sorata the task of taking care of her along with his ever-growing collection of stray cats!

(Source: Sentai Filmworks)', 'J.C.STAFF', '2012', 'series', 'released', '2012-10-09', 13759, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n13759-nBjdu6f8aLbz.jpg', 'Comedy, Drama, Romance, Slice of Life', 'TV', 'FALL', 24, 273173, 'https://www.youtube.com/watch?v=ab4fs9No18g', '2026-08-29 14:58:03', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1645, 'Magi: The Labyrinth of Magic', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14513-HuUdrFFYftA7.jpg', 'series', '7.8', 'This story is about the flow of fate and the battle to keep the world on the right path. Aladdin is a boy who has set out to explore the world after being trapped in a room for most of his life. His best friend is a flute with a djinn in it named Ugo. Soon enough, Aladdin discovers he is a Magi, a magician who chooses kings, and he was born to choose kings who will follow the righteous path, battling against those who want to destroy fate. Follow his adventures as he meets others from 1001 Arabian Nights, like Ali Baba and Sinbad, and fights to keep the balance of the world in check!', 'A-1 Pictures', '2012', 'series', 'released', '2012-10-07', 14513, 0, NULL, '2026-07-25 18:55:01', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/14513-DDBxCumOyPIa.jpg', 'Action, Adventure, Fantasy', 'TV', 'FALL', 25, 229309, 'https://www.youtube.com/watch?v=xTit5k75uvE', '2026-08-29 14:58:06', NULL);
