INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1649, 'Carnival Phantasm', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx10012-MNLVctKXaIAf.jpg', 'series', '7.7', 'Carnival Phantasm is an adaption of the manga "Take Moon" by Type-Moon''s Eri Takenashi, to celebrate Type-Moon''s 10th Anniversary.

Carnival Phantasm shows parodies and new stories loosely based on Type-Moon''s original works like Melty Blood, Fate/Stay Night, Tsukihime, and more.', 'Lerche', '2011', 'series', 'released', '2011-08-14', 10012, 0, NULL, '2026-07-25 18:55:03', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10012-U5a5plRViPJF.jpg', 'Comedy, Supernatural', 'OVA', 'SUMMER', 12, 58802, 'https://www.youtube.com/watch?v=jMoyJZaZFe4', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1650, 'Gosick', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx8425-Bn14ayPjnq9o.jpg', 'series', '7.7', 'Kazuya Kujou is a foreign student at Saint Marguerite Academy, a luxurious boarding school in the Southern European country of Sauville. Originally from Japan, his jet-black hair and dark brown eyes cause his peers to shun him and give him the nickname "Black Reaper," based on a popular urban legend about the traveler who brings death in the spring.

On a day like any other, Kujou visits the school''s extravagant library in search of ghost stories. However, his focus soon changes as he becomes curious about a golden strand of hair on the stairs. The steps lead him to a large garden and a beautiful doll-like girl known as Victorique de Blois, whose complex and imaginative foresight allows her to predict their futures, now intertwined.

With more mysteries quickly developing—including the appearance of a ghost ship and an alchemist with the power of transmutation—Victorique and Kujou, bound by fate and their unique skills, have no choice but to rely on each other.

(Source: MAL Rewrite)', 'bones', '2011', 'series', 'released', '2011-01-08', 8425, 0, NULL, '2026-07-25 18:55:03', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/8425-Lf6WLBHfOdRQ.jpg', 'Drama, Mystery, Romance', 'TV', 'WINTER', 24, 123046, 'https://www.youtube.com/watch?v=QMFLC-SKtFs', '2026-08-29 14:58:20', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1651, 'Hidamari Sketch x SP', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx11237-bpOKNBsD5nAU.jpg', 'series', '7.7', 'Even though studying at a prestigious art school like Yamabuki is hard work, the girls who live at the Hidamari Apartments always manage to squeeze in time for a little fun and exploration. And when they actually get a day off? Watch out world! Yuno, Sae, Hiro, Miyako and new students Nori and Nazuna return to create another masterpiece of life as art, with all new adventures that include swimming, pajama parties, trips to the art museum and even an all-you-can-eat diner courtesy of the landlady! Of course, there&rsquo;s always a little housework that has to be squeezed in, but with a pinch of resourcefulness and a dash of creativity, even the most onerous of chores can be turned into something magical. 

(Source: Sentai Filmworks)', 'Shaft', '2011', 'series', 'released', '2011-10-30', 11237, 0, NULL, '2026-07-25 18:55:04', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11237-rRw7LjABVHUI.jpg', 'Comedy, Slice of Life', 'SPECIAL', 'FALL', 2, 6147, 'https://www.youtube.com/watch?v=00t2d69wDzY', NULL, NULL);
