INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1684, 'The Legend of Luoxiaohei', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx102663-gYYp2lg0ehVG.png', 'series', '7.4', 'The story begins on a rainy night, when a homeless little black cat is brought home by a young girl Luo Xiaobai. She names the cat Luo Xiaohei. However, Luo Xiaohei is no ordinary cat: he is a supernatural entity that hosts several small creatures called Heixiu. As Luo Xiaohei new life soon threatened by the mysterious Diting, who commands three winged wolves.', 'HMCH', '2011', 'series', 'released', '2011-03-17', 102663, 0, NULL, '2026-07-25 18:55:04', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Comedy, Slice of Life, Supernatural', 'ONA', NULL, 28, 3115, 'https://www.youtube.com/watch?v=Ps0O9l2CvOM', '2026-08-08 14:32:38', NULL);
