INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1710, 'Blue Exorcist', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx9919-nXS7JOZrWHfS.jpg', 'series', '7.3', 'This world consists of two dimensions joined as one, like a mirror. The first is the world in which the humans live, Assiah. The other is the world of demons, Gehenna. Ordinarily, travel between the two, and indeed any kind of contact between the two, is impossible. However the demons can pass over into this world by possessing anything that exist within it. Satan the god of demons, but there''s one thing that he doesn''t have, and that''s a substance in the human world that is powerful enough to contain him!! For that purpose he created Rin, his son from a human woman, but will his son agree to his plans? Or will he become something else...? An exorcist?', 'Aniplex', '2011', 'series', 'released', '2011-04-17', 9919, 0, NULL, '2026-07-25 18:55:06', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/9919-S5idQm3GbZ80.jpg', 'Action, Fantasy, Supernatural', 'TV', 'SPRING', 25, 457313, 'https://www.youtube.com/watch?v=0HHNeeXrysA', '2026-08-08 14:35:41', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1711, 'Kuroko''s Basketball Specials', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/15487.jpg', 'series', '7.3', 'Animated bloopers, based on the extra section of the original manga series, included with the BD/DVD series for Kuroko no Basket (both limited and normal editions).', 'Production I.G', '2012', 'series', 'released', '2012-07-27', 15487, 0, NULL, '2026-07-25 18:55:06', '2026-09-02 16:57:33', NULL, 'Comedy, Sports', 'SPECIAL', 'SUMMER', 9, 14183, 'https://www.youtube.com/watch?v=nb7e5_4CGag', '2026-08-08 14:34:58', NULL);
