INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (1713, 'Inazuma Eleven GO the Movie: The Ultimate Bonds Gryphon', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b10999-csB5JL9s2NfJ.png', 'movies', '7.2', 'The Raimon team has been invited by Fifth Sector strangely to a soccer camp. When they agree, things go out of hand since it was revealed that Fifth Sector wants to eliminate them once and for all in the island called God Eden. Now, the Raimon team needs to train harder, to be able to show that they have the strength to fight back and prove Fifth Sector''s doings wrong.

(Source: Inazuma Eleven Wikia)', 'OLM', '2011', 'movie', 'released', '2011-12-23', 10999, 0, NULL, '2026-07-25 18:55:06', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10999-oqw2yq6bT2AL.jpg', 'Sports, Supernatural', 'MOVIE', 'FALL', 1, 6716, 'https://www.youtube.com/watch?v=pwh9v1csEHM', '2026-08-08 14:35:03', NULL);
