INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2003, 'Oban Star-Racers', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1212-XURZJSnTS6Xi.png', 'series', '7.2', 'Eva''s birthday has just passed, and she hasn''t heard from her father. Despising the Boarding School she attends, she escapes using her Rocket Bike that she just completed. Taking on the alias "Molly," Eva sneaks with the Earth team to Alwas for the Great Race because the winner of the race gets any one wish granted. Little does the Earth Team know what danger awaits them...', 'Hal Film Maker', '2006', 'series', 'released', '2006-04-12', 1212, 0, NULL, '2026-07-25 18:55:31', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1212-TpKyX1cca1TZ.jpg', 'Adventure, Mecha, Sci-Fi', 'TV', 'SPRING', 26, 11040, 'https://www.youtube.com/watch?v=Ue6PDYrMXV4', NULL, NULL);
