INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2005, 'Final Fantasy VII: Advent Children', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b317-ay0Rw7kxgLVD.jpg', 'movies', '7.2', 'Two years after the end of Final Fantasy VII the world is starting to get back on it''s feet and is working towards a new future. However, there is a new threat from a new illness called Geo-stigma, and three men that seem to be seeking Jenova. Cloud and his friends from the orginal game must once again reunite to combat the new threat.

(Source: Anime News Network)', 'Square Enix', '2005', 'movie', 'released', '2005-09-14', 317, 0, NULL, '2026-07-25 18:55:31', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n317-I8gaZ4rexNQX.jpg', 'Action, Fantasy, Sci-Fi', 'MOVIE', 'FALL', 1, 28816, 'https://www.youtube.com/watch?v=tvAa9TpPE1w', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2006, 'Hell Girl', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx228-J2J1CI4jfyeC.jpg', 'series', '7.2', 'Somewhere in the vast sea of the Internet, there''s a website that can only be accessed at the stroke of midnight. Known as the Jigoku Tsushin, rumor has it that if you post a grudge there, the Jigoku Shoujo will appear and drag whoever torments you into the inferno. Very little is known about the girl - all we know for sure is that she lives with her equally enigmatic grandmother, that three magical straw dolls accompany and serve her, and that whenever a posting on the Jigoku Tsushin moves her, she becomes the Jigoku Shoujo.', 'Aniplex', '2005', 'series', 'released', '2005-10-05', 228, 0, NULL, '2026-07-25 18:55:31', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/228-bTVYNn7irPjd.jpg', 'Drama, Horror, Mystery, Psychological, Supernatural', 'TV', 'FALL', 26, 76333, 'https://www.youtube.com/watch?v=Zo5wuctIMWk', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2007, 'Oh! My Goddess Specials', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/1003.jpg', 'series', '7.2', 'Due to the recent events that happened at the end of season 1, the Goddesses are having some stability problems with their body systems. The always adult-looking Urd becomes a little girl and has a fateful encounter with a boy, whereas little Skuld becomes an adult and wants to experiment adulthood together with Keiichi.

Episodes 25 and 26 of Aa! Megami-sama! (TV) that aired separately from it''s season 1 original broadcast.', 'AIC', '2005', 'series', 'released', '2005-09-22', 1003, 0, NULL, '2026-07-25 18:55:31', '2026-09-02 16:57:33', NULL, 'Comedy, Romance, Supernatural', 'SPECIAL', 'FALL', 2, 4490, 'https://www.youtube.com/watch?v=9Hx9eNTSPaM', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2008, 'Tsubasa RESERVoir CHRoNiCLE 2nd Season', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx969-5p26f5cQ6dku.jpg', 'series', '7.1', 'Syaoran, Sakura, Kurogane, Fai and Mokona''s journey through to different world''s continue as they search for Sakura''s feathers. The fated journey slowly becomes more complicated for our travelers, as they find themselves diving deeper into more dangerous worlds. Takes place immediately after the first season. Based on the manga by CLAMP.', 'Bee Train', '2006', 'series', 'released', '2006-04-29', 969, 0, NULL, '2026-07-25 18:55:31', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/969-IGENhLYpqNKT.jpg', 'Adventure, Drama, Fantasy, Mystery, Romance', 'TV', 'SPRING', 26, 16572, 'https://www.youtube.com/watch?v=4TepNFIV8ts', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2009, 'Basilisk', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx67-aBz3s2hBTtdH.jpg', 'series', '7.1', 'The heirs to the Kouga and Iga ninja clans, Gennosuke and Oboro, hoped the unsteady truce between their tribes would last—but fate denies the lovers, thrusting their people into war after centuries of peace. The terms are set on two scrolls. One bears a list of Kouga warriors. The other holds a list of those who fight for Iga. The names found on these scrolls can only be crossed out in blood. 

(Source: Crunchyroll)', 'GONZO', '2005', 'series', 'released', '2005-04-13', 67, 0, NULL, '2026-07-25 18:55:31', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n67-7sRsHP9kG3Jt.jpg', 'Action, Adventure, Drama, Romance', 'TV', 'SPRING', 24, 33415, 'https://www.youtube.com/watch?v=vvPSjXWx_QQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2010, 'Noein: To Your Other Self', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx584-KBhhNX2H9LBw.png', 'series', '7.1', 'In the near future, a violent battle takes place between the dimension La''cryma (protector of humanity) and the dimension Shangri-La, bent on the annihilation of all space-time. A group known as the Dragon Calvary is dispatched through space and time, searching for the only thing that can stop the invasion: the Dragon''s Torque.

In the present, twelve-year old Haruka and her friend Yuu, are contemplating running away from home when they meet a member of the Dragon Calvary named Karasu (Crow). He believes that Haruka possesses the Dragon''s Torque and claims to be Yuu from fifteen years in the future...

(Source: DVD Complete Series Box Set)', 'Satelight', '2005', 'series', 'released', '2005-10-12', 584, 0, NULL, '2026-07-25 18:55:31', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/584-9MkFFMHfDiIK.jpg', 'Adventure, Drama, Psychological, Sci-Fi, Slice of Life', 'TV', 'FALL', 24, 24479, 'https://www.youtube.com/watch?v=o4wCKA9wiPg', '2026-08-29 14:39:01', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2011, 'Tsubasa RESERVoir CHRoNiCLE', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx177-tU0wjdXRw5u8.png', 'series', '7.1', 'During an excavation at the mysterious ruins in Clow Country, Syaoran discovers his childhood friend Princess Sakura appear on the site with wings that disperse into many feathers. As the feather''s disappear to different dimensions, so does Sakura''s memory. In attempts to save Sakura''s life and restore her memory, Syaoran travels through to another world to find a solution. There''s only one thing left he can do. Travel through to different dimensions to collect Sakura''s feathers. Helping out with the quest is Kurogane, an exiled ninja from Japan Country who wishes to return to his world, the runaway magician, Fay, who desires to jump between each world never to return to his own and the white meat-bun shaped creature, Mokona.', 'Bee Train', '2005', 'series', 'released', '2005-04-09', 177, 0, NULL, '2026-07-25 18:55:32', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/177-IHqN2HjMaQnN.jpg', 'Adventure, Fantasy, Romance', 'TV', 'SPRING', 26, 37392, 'https://www.youtube.com/watch?v=FsgJYZeKk78', '2026-08-29 14:39:04', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2012, 'Twin Princesses of the Wonder Planet', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1886-GVUaVlMBg7Ba.png', 'series', '6.9', 'Fine and Rein are sent to the Royal Wonder Academy on the Royal Wonder Planet in order to study to become better princesses. They plan to make many friends, but unfortunately, the competition and cold nature of the students and teachers make things impossible. The twins also become Universal Princesses when touching the legendary Soleil Bell, releasing two angels named Pyupyu and Kyukyu to help aid them. Unfortunately, an evil force manifested in a painting doesn''t seem to be satisfied about the Universal Princesses... 

(Source: Anime News Network)', 'Hal Film Maker', '2006', 'series', 'released', '2006-04-01', 1886, 0, NULL, '2026-07-25 18:55:32', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1886-znjX3y8O1I2t.jpg', 'Adventure, Comedy, Fantasy, Mahou Shoujo, Romance', 'TV', 'SPRING', 52, 1846, 'https://www.youtube.com/watch?v=rw2FxIMSKvI', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2014, 'Kamichu!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx489-NKvW3coa4Q8D.png', 'series', '7.1', 'What would you do if you suddenly became a god?

When little Yurie, a junior high school student, discovers that she is a god, she is beside herself in indecision and asks her friends. Thus begins her new life exploring what it means to be a god and her struggle to properly fulfill all the responsibilities it entails. From finding stray gods to dealing with Martians, her life is about to become more than ordinary.

(Source: Geneon Entertainment)', 'Brain''s Base', '2005', 'series', 'released', '2005-06-28', 489, 0, NULL, '2026-07-25 18:55:32', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/489-Z8X2HPZx5usN.jpg', 'Comedy, Slice of Life, Supernatural', 'TV', 'SUMMER', 12, 18389, 'https://www.youtube.com/watch?v=_gsjSSSOE-c', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2015, 'Soukyuu no Fafner: RIGHT OF LEFT - single program', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx560-dXVJeuipvBRF.png', 'series', '7.1', 'Yumi Ikoma and Ryou Masaoka are children who have been selected to take part in a top secret mission, to be the pilots of the first Fafner combat units; the last chance of survival for the human race. The enemy is ruthless, remorseless and is able to read the minds of humans. Therefore, the details of this mission are kept a secret even from the personnel involved. The young pilots must use all their courage and faith in order to survive and complete their mission or the fate of mankind would be compromised.

(Source: Anime News Network)', NULL, '2005', 'series', 'released', '2005-12-30', 560, 0, NULL, '2026-07-25 18:55:32', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/560-41gMfZ0C8e9m.jpg', 'Drama, Mecha, Sci-Fi', 'SPECIAL', 'WINTER', 1, 4393, 'https://www.youtube.com/watch?v=Tkerd7gbavY', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2016, 'Utawarerumono Short Episodes', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/1830.jpg', 'series', '7.1', 'DVD specials of comedic events that occurred during the story of Utawarerumono. The specials are included in the DVD box special disc.', NULL, '2006', 'series', 'released', '2006-08-23', 1830, 0, NULL, '2026-07-25 18:55:32', '2026-09-02 16:57:33', NULL, 'Action, Comedy, Drama, Fantasy', 'SPECIAL', 'SUMMER', 4, 3263, 'https://www.youtube.com/watch?v=dkgftUswd4M', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2017, 'Kemonozume', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1454-fyg2zIQz5Qsj.png', 'series', '7.1', 'A race of cannibal monsters called the Shokujinki exists and it is the job of the Kifuuken, an elite group of beast-hunters, to stop them. Toshihiko Momota, an expert swordsman and son of the Kifuuken organization''s leader, unexpectedly falls in love at first sight with a beautiful girl named Yuka. However, the couple''s relationship is much more complicated than it seems at first glance, for Yuka is a Shokujinki.', 'MADHOUSE', '2006', 'series', 'released', '2006-08-05', 1454, 0, NULL, '2026-07-25 18:55:32', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n1454-2pwRbckIiPiT.jpg', 'Action, Horror, Romance, Supernatural', 'TV', 'SUMMER', 13, 21451, 'https://www.youtube.com/watch?v=hgJgE69p6e8', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2018, 'Onegai My Melody: Kuru Kuru Shuffle!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b4114-DVX9UQdHHePT.jpg', 'series', '7.1', 'A continuation of Onegai My Melody.', 'Studio Comet', '2006', 'series', 'released', '2006-04-02', 4114, 0, NULL, '2026-07-25 18:55:32', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4114-UfcIyYxnaFPb.jpg', 'Comedy, Fantasy, Mahou Shoujo', 'TV', 'SPRING', 52, 2037, 'https://www.youtube.com/watch?v=Lq-GJkMpSMc', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2019, 'Pani Poni Dash!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b490-KSxEkqG6QICq.jpg', 'series', '7.0', 'The 11 year old Miyamoto Rebecca becomes the new teacher of a classroom which is full of weirdos. Despite her cute looks she''s a little beast and can be pretty sarcastic and offensive. The school is not safe anymore now that she''s in charge of a class and her students, Himeko, Ichijou, Rei and a white rabbit who took a liking to Rebecca help her to rough up the school and the neighbour-class with its teacher "ojii-chan".

(Source: Anime News Network)', 'Shaft', '2005', 'series', 'released', '2005-07-04', 490, 0, NULL, '2026-07-25 18:55:32', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/490-dHSzVziqtq8s.jpg', 'Comedy', 'TV', 'SUMMER', 26, 17493, 'https://www.youtube.com/watch?v=UcsY80mMiQo', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2020, 'Shakugan no Shana', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx355-tB52QB38leMs.png', 'series', '7.0', 'He had thought his normal days would last forever, until they were ended abruptly by an encounter with a girl with red hair and eyes. He named her Shana.

Not long after he enters high school, Sakai Yuji&rsquo;s normal days come to an end. He sees something bizarre on his way home: people are frozen in a strange fire, and a monster that looks like a large doll is attacking them. Just when he''s about to be killed, a girl in a dark cloak wielding a large sword appears, and slices the monster in half. Although Yuji survives the strange encounter, the girl informs him of a desolate truth: " ''You'' don''t exist anymore."

She calls herself a Flame Haze who hunts "Guze no Tomogara"; intruders from another world. She explains to him that he is a "Torch", a substitute of Yuji whose &ldquo;existence&rdquo; has already been devoured. She also told him that he is a special Torch, "Mystes", which contains a precious item in it. When he looks at his chest, he sees within himself a faint flame, just as she said.

It is in this way that his eternal struggle alongside the girl begins. 

(Source: AnimeNfo)', 'J.C.STAFF', '2005', 'series', 'released', '2005-10-06', 355, 0, NULL, '2026-07-25 18:55:34', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/355-HYE6kTOrxZpG.jpg', 'Action, Comedy, Drama, Fantasy, Romance, Supernatural', 'TV', 'FALL', 24, 96401, 'https://www.youtube.com/watch?v=uFsKKFLc7zk', '2026-08-29 14:39:12', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2021, 'Simoun', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx879-Y1AMwyonCMQf.jpg', 'series', '7.0', 'In the peaceful theocracy of Simulicram, everyone is born female. At age 17, each maiden undergoes a special ceremony where she chooses her sex. However, only Pairs of maiden priestesses can synchronize with the ancient flying ships known as Simoun needed to defend Simulicram. These Pairs refrain from undergoing the ceremony as long as they wish to keep piloting their Simoun.

Aer is recruited to be a Simoun pilot after a terrifying attack by an enemy nation decimates the squadron known as Chor Tempest. To earn her wings she needs to find her way into the heart of Neviril, Regina of Chor Tempest. But Neviril''s heart still belongs to her previous Pair, lost in the battle when she attempted a forbidden Simoun maneuver.

(Source: Media Blasters)', 'Studio DEEN', '2006', 'series', 'released', '2006-04-03', 879, 0, NULL, '2026-07-25 18:55:34', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/879-87TegB6ZPbJE.jpg', 'Drama, Fantasy, Romance', 'TV', 'SPRING', 26, 12069, 'https://www.youtube.com/watch?v=SIvDblCCD2Y', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2022, 'Brave Story', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b1681-G12LPkws93Ub.jpg', 'movies', '7.0', 'When 11 year old Wataru''s father leaves home and his mother is taken ill to hospital, he decides to change his fate by travelling through the door shown to him by his friend Mitsuru. In a land of magic and monsters, Wataru must summon all his courage and embark on a journey with several comrades to meet the Goddess of Destiny and change this "mistaken fate".

(Source: Anime News Network)', 'GONZO', '2006', 'movie', 'released', '2006-07-08', 1681, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:41:57', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1681-mRibcfxIyCaV.jpg', 'Action, Adventure, Fantasy, Supernatural', 'MOVIE', 'SUMMER', 1, 9811, NULL, '2026-09-03 16:41:57', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2023, 'Zegapain', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx878-E65KwO2LaQhp.jpg', 'series', '7.0', 'Kyo, an avid swimmer tries his best to keep the high school swimming club going, which is pretty hard when he''s the only member. Facing the prospect of the club being closed by the student council, he tries to enlist beautiful Misaki to act in a promo video, shot by his good friend Ryoko, in a bid to start a recruitment drive. She agrees but only if he pilots a mecha under the wing of Celebrum, a resistance organisation fighting to destroy Deutera Areas formed on Earth by the aliens Gards-orm. He agrees but finds it all strangely familiar as if he''s done it before...

(Source: Anime News Network)', 'Sunrise', '2006', 'series', 'released', '2006-04-06', 878, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:00', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/878-e4s5Rr7OrMhC.jpg', 'Action, Mecha, Romance, Sci-Fi', 'TV', 'SPRING', 26, 9426, NULL, '2026-09-03 16:42:00', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2024, 'Gaiking: Legend of Daiku-Maryu', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1845-qkImnNGNZ1SV.jpg', 'series', '7.0', 'A boy, Tsuwabaki Daiya found a black fire in an ocean when he and his father were in a small boat. A big monster came out of the fire, and the father and the crews were disappeared into the sea. When he was about to become the next victim, a large mecka dragon appeared and saved him.

5 years later since then, Daiya becomes a junior high school student. A big monster reappear, and he meets the mecha dragon,"Daiku Maryu". The head of the dragon separates from the body, and it turns into the body of a super robot, Gaiking. He gets in Gaiking, fights against the monster, and beats it.

He learns that there is an enemy that plots to conquer the world, and he leaves for another world, Darius, to stop the plot. 

(Source: AnimeNfo)', NULL, '2005', 'series', 'released', '2005-11-12', 1845, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:05', NULL, 'Action, Mecha, Sci-Fi', 'TV', 'FALL', 39, 1836, NULL, '2026-09-03 16:42:05', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2025, 'Oh! My Goddess (TV)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx50-OdzAFLX6X6Hf.png', 'series', '7.0', 'Keiichi Morisato is looking forward to university life. But in reality, he has no luck in anything, and he has trouble with clubs, love, etc. The truth is that he has an unlucky star above his head. One day, Keiichi is stuck watching the dorm while his sempai are away, and has a mountain of chores to do to boot. But Keiichi is a good-natured person, and is set about doing his duties. As he is about to finish his final chore, he makes a phone call to his sempai. But the words that came through the receiver are, ''Goddess Help Line.'' Shortly afterwards, a beautiful goddess named Belldandy appears in front of him from the mirror of his room.', 'AIC', '2005', 'series', 'released', '2005-01-07', 50, 0, NULL, '2026-07-25 18:55:34', '2026-09-02 16:57:33', NULL, 'Comedy, Romance, Supernatural', 'TV', 'WINTER', 24, 25642, 'https://www.youtube.com/watch?v=fohHBnpCoeI', '2026-08-29 14:39:15', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2026, 'Bartender', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1589-w7J6h6DdE3NT.png', 'series', '7.0', 'Genius bartender, Sasakura Ryuu makes the most incredible cocktails anyone has ever tasted. Seeking his "Glass of God", individuals from all different walks of life visit his bar. With both a compassionate ear and a godly drink, Ryuu helps people with their problems.

(Source: Anime News Network)', 'Palm Studio', '2006', 'series', 'released', '2006-10-15', 1589, 0, NULL, '2026-07-25 18:55:34', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1589-u7jza0OrNy7T.jpg', 'Drama, Slice of Life', 'TV', 'FALL', 11, 25716, 'https://www.youtube.com/watch?v=JsD9s5YaalA', '2026-08-29 14:39:18', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2027, 'Looking Up at the Half-Moon', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx587-Y2r6jh7QNccg.png', 'series', '7.0', 'After contracting hepatitis A, Ezaki Yuuichi has been confined to a hospital away from his friends and family, much to his displeasure. To relieve his boredom, he has taken to sneaking out of the hospital, usually putting himself on the receiving end of a beating from his nurse. Upon meeting a girl his age also staying in the hospital, he is immediately captivated by her beauty. Akiba Rika''s personality is not quite as captivating as her beauty however. In fact, she is rather selfish, moody, and bossy. But as the two spend more time with each other, they become closer, sharing the ordinary joys and trials of a budding teenage romance, even when darkened with impending tragedy - for Rika''s condition does not leave her much longer to live.

[Written by MAL Rewrite]', 'Group TAC', '2006', 'series', 'released', '2006-01-13', 587, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:20', NULL, 'Comedy, Drama, Romance', 'TV', 'WINTER', 6, 19259, NULL, '2026-09-03 16:42:20', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2028, 'Mahoraba ~HeartfuL days~', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx519-GS6gb1XtiIDg.png', 'series', '7.0', 'Shiratori Ryuushi is a young artist-in-training, about to start studying at a vocational school. Arriving at his new lodgings, Narutakisou, he finds himself the focus of attention for the collection of weirdos that inhabit the place. He also meets and falls for the landlady, Aoba Kozue, who seems to be both lovely and charming. However, Kozue is not what she seems to be... in fact, she''s more.

(Source: Anime News Network)', 'J.C.STAFF', '2005', 'series', 'released', '2005-01-10', 519, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:24', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/519-QnSlolwR60Rx.jpg', 'Comedy, Drama, Romance', 'TV', 'WINTER', 26, 5847, NULL, '2026-09-03 16:42:24', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2029, 'Yomigaeru Sora: Rescue Wings', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b798-w1FtgXZvXIqX.png', 'series', '7.0', 'Kazuhiro Uchida is transferred to a rescue centre located in a small town while training to become a fighter pilot. Initially, Kazuhiro thinks negatively about his new occupation, due to the difficult missions and the harsh discipline he receives from his seniors. However, over the course of his training, he begins to accept the job for what it is and becomes a true member of the rescue force.

(Source: Anime News Network)', 'J.C.STAFF', '2006', 'series', 'released', '2006-01-09', 798, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:28', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/798-k3eYjtLyBIot.jpg', 'Drama', 'TV', 'WINTER', 12, 4484, NULL, '2026-09-03 16:42:28', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2030, 'The Third: The Girl with the Blue Eye', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b944-yqJOuaRagwJJ.jpg', 'series', '7.0', 'In the distant future, because of an interplanetary war that had continued on for centuries, civilizations were ruined. Human beings have lost everything, and only 1/5th of the population survived. A strange breed of humans, ''''The Third'''' is said to have appeared just after the war. They possess a third eye, as their name suggests, that appear as oval-shaped red pupils called "space eyes'''' over their conventional two eyes. Using them, they can control computer systems and so on, and as such, rule the world by their superior power over technology.

In this world, there is a young woman named Honoka; she is a "jack-of-all-trades" sellsword, and she accepts any job except murder. One day, she happens to find and rescue a young man named Ikus in the desert. Entering his world, and accepting a job from him, the adventure begins for Honoka and Ikus.

(Source: BestAnime, modified)', 'Xebec', '2006', 'series', 'released', '2006-04-14', 944, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:32', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/944-tF2EOd6ZzBEv.jpg', 'Action, Adventure, Sci-Fi', 'TV', 'SPRING', 24, 4619, NULL, '2026-09-03 16:42:32', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2031, 'Gun x Sword', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx411-row6MWWNQDzH.jpg', 'series', '6.9', 'Van, a lanky and apathetic swordsman, is on a journey to kill the murderer of his fianc&eacute;. The only characteristic he has to go by is that the murderer has a claw for an arm, hence the murderer being referred to as The Claw Man. During his travels, Van happens to pass through the city of Evergreen, which is defending itself from bandits who aim to rob the city of its treasury. It is in this city that Van meets Wendy Garret, a timid young girl who is looking for her kidnapped brother. When the city pleads for Van''s assistance to defend it, he refuses, claiming it has nothing to do with him and thus leaves the city on its own to deal with the peril. Soon after, Van comes across the raiding bandits himself and they eventually tick off the swordsman to a degree where he takes action against them for his own personal vendetta. Surprisingly, Van learns that the bandits had ties with The Claw Man, and in kidnapping Wendy''s brother for a reason they did not disclose. After the bandits are dealt with easily, Van and, much to his chagrin, Wendy continue the journey in search of The Claw Man. Little do they know, however, that The Claw Man is involved with something more atrocious than either could fathom.

[Written by MAL Rewrite]', 'AIC A.S.T.A.', '2005', 'series', 'released', '2005-07-04', 411, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:36', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/411-rBfeZNwDqeMt.jpg', 'Action, Adventure, Drama, Mecha, Sci-Fi', 'TV', 'SUMMER', 26, 15931, NULL, '2026-09-03 16:42:36', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2032, 'Freedom', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1747-CSVhuCff8Ui7.png', 'series', '6.9', 'In the year 2041, mankind created their first space colony on the moon. But after a freak cataclysm devastated human civilisation on Earth, the republic of the moon built a domed megalopolis known as Eden. Now in the year 2267, a boy called Takeru spends his time engaging in hover-craft races against rival street gangs, unaware that he is about to embark in the journey of unearthing Eden''s origin.

(Source: Anime News Network)

Note: Episode 7 has a runtime of 48 minutes.', 'Sunrise', '2006', 'series', 'released', '2006-11-24', 1747, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:40', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1747-sBfACAVQY42w.jpg', 'Action, Adventure, Sci-Fi', 'OVA', 'FALL', 7, 6812, NULL, '2026-09-03 16:42:40', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2033, 'Solty Rei', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx152-Dhq9vohv6AaN.jpg', 'series', '6.9', 'In a future-based disaster-ridden city with an enormous gap between the rich and the poor, it is hard to tell which humans are walking around with cybernetic body parts. This makes Roy Revant''s job as a renegade bounty hunter/bodyguard-for-hire even more difficult. When a young girl with unbeliveable strength rescues him from a particularly dangerous criminal, Roy realizes that perhaps help can be found in the strangest of places. Joining together with a few others, they engage in a battle to find out the truth behind the giant conglomerates that are supposedly serving mankind and making life better.

Solty, an android who has lost her memory, has escaped and is being hunted by the RUC Security Bureau. She encounters the bounty hunter Roy and he adopts her as his daughter after being hired as a bodygaurd for Miranda.

(Source: Anime News Network)', NULL, '2005', 'series', 'released', '2005-10-06', 152, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:43', NULL, 'Action, Sci-Fi', 'TV', 'FALL', 24, 6684, NULL, '2026-09-03 16:42:43', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2034, 'ARIA The NATURAL: Sono Futatabi Deaeru Kiseki ni...', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx5244-tDxgLsUhQIBi.jpg', 'series', '6.9', 'Short episode entitled "Sono Futatabi Deaeru Kiseki ni...", which can be also considered as "Aria the Natural" episode 0.', 'Hal Film Maker', '2006', 'series', 'released', '2006-05-07', 5244, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:47', NULL, 'Fantasy, Sci-Fi, Slice of Life', 'SPECIAL', 'SPRING', 1, 5723, NULL, '2026-09-03 16:42:47', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2035, 'Rec', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx710-yfZvLjJ8qvwZ.jpg', 'series', '6.9', 'Fumihiko Matsumaru is an average salaryman with no girlfriend. He invited his colleague Miss Tanaka to a movie but was stood up. Right at the time he was about to toss tickets into a trash can, a cute girl appeared and asked him not to waste those two tickets. After movie and dinner, he escorted her home and found they live in the same neighborhood, yet unfortunately her apartment caught on fire hours later. Having nowhere else to stay, rookie seiyuu Aka Onda moved to Matsumaru''s place, and the two had started a "more than friend but not yet lovers" relationship under the same roof while keeping this secret from their employers.

(Source: Anime News Network)', 'Shaft', '2006', 'series', 'released', '2006-02-03', 710, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:51', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/710-27R6oM7rWdIV.jpg', 'Comedy, Drama, Romance', 'TV_SHORT', 'WINTER', 9, 24417, NULL, '2026-09-03 16:42:51', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2036, 'My-Otome', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx99-NOVuOiWoqpMb.jpg', 'series', '6.9', 'Arika Yumemiya has traveled far in search of her goal: the prestigious Gualderobe Academy. This is the school where young girls are trained to become Otomes, protectors of royal leaders throughout the lands. Here, Arika makes plenty of friends, but some enemies know something about her past that she does not. Nevertheless, her spirit and determination will keep pushing her forward.

Adapted from its predecessor, Mai-HiME, this series is not a direct sequel, but an alternate universe setting featuring some of the Mai-HiME cast (though with different personalities).

(Source: Anime News Network)', 'Sunrise', '2005', 'series', 'released', '2005-10-07', 99, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:54', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99-CLgA6Iy0Sq4v.jpg', 'Comedy, Drama, Fantasy', 'TV', 'FALL', 26, 8885, NULL, '2026-09-03 16:42:54', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2037, 'Tsubasa Reservoir Chronicle the Movie: The Princess in the Birdcage Kingdom', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/807.jpg', 'movies', '6.9', 'In their continuing journey to find the feathers that are the fragments of Sakura''s lost memory, Syaoran, Kurogane, Fai, and Sakura move through time and space with Mokona. Here, they visit the "Land of the Birdcage," a seemingly peaceful country where people and birds live together, each person having a bird companion. After a boy named Koruri confuses Syaoran and Sakura for "bodyguards" and attacks them, they learn that the king of the country possesses a mysterious power. Princess Tomoyo, Koruri, and the other oppressed citizens, having had their birds taken from them, live in hiding within the forest. In order to take back Sakura''s feather, Syaoran and the others stand up against the scheming king.

(Source: Anime News Network)', 'Production I.G', '2005', 'movie', 'released', '2005-08-20', 807, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:42:58', NULL, 'Adventure, Fantasy', 'MOVIE', 'SUMMER', 1, 7324, NULL, '2026-09-03 16:42:58', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2038, 'Doubutsu no Mori', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx2950-CclgYXpqfbGh.jpg', 'movies', '6.9', 'Ai is a self-reliant girl that moves to Animal Village. She makes friends with the various villagers as she settles into the village. One night as she walked along the beach, she finds a message in the bottle. It sets her off on a quest of planting pine trees around the village to fulfill a miracle on the eve of the Winter Festival.

(Source: Anime News Network)', 'OLM', '2006', 'movie', 'released', '2006-12-16', 2950, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:01', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n2950-ofFPxTARVPyh.jpg', 'Slice of Life', 'MOVIE', 'FALL', 1, 8346, NULL, '2026-09-03 16:43:01', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2039, 'Sonic X: The Metarex Saga', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx129610-s1WG5PfQqyzq.jpg', 'series', '6.9', 'Sonic activates Chaos Control in his battle against Dark Oak, most formidable enemy he''s faced thus far, to scatter the Chaos Emeralds across the galaxy. Meanwhile, Tails, Amy, and Cream encounter a spaceship that''s crash-landed to their planet during a meteor shower.

Note: The listed airing dates are from the original US broadcast. Due to poor ratings in Japan, the series cancelled airing after the first 52 episodes, and only received its first local airing in 2020.', 'TMS Entertainment', '2005', 'series', 'released', '2005-09-10', 129610, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:05', NULL, 'Action, Adventure, Comedy, Fantasy, Mecha, Sci-Fi', 'TV', 'FALL', 26, 4216, NULL, '2026-09-03 16:43:05', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2040, 'My-Otome Zwei', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx1609-xh1ASMghVp7k.png', 'series', '6.9', 'My-Otome Zwei takes place one year after the events of My-Otome. Arika is now a full-fledged Otome (though still under the tutelage of Miss Maria) and Nagi is incarcerated in a prison somewhere in Aries. The various nations are at peace with one another and plan to hold S.O.L.T. (Strategic Otome Limitation Talks) to discuss limiting the numbers of Otome.

A mission to destroy a meteor threatening to collide with Earl sets into motion a chain of events which result in a mysterious shadowy figure attacking Garderobe and several Otome as well as a new, more powerful version of Slave appearing across the planet. To make matters worse, Queen Mashiro disappears following an argument with Arika. The series follows Arika''s search for Mashiro as well as Garderobe''s attempts to uncover the truth behind the shadowy figure.

(Source: Wikipedia)', NULL, '2006', 'series', 'released', '2006-11-24', 1609, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:09', NULL, 'Action', 'OVA', 'FALL', 4, 3540, NULL, '2026-09-03 16:43:09', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2041, 'Ayakashi: Samurai Horror Tales', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx586-alDXEdRVYNU1.png', 'series', '6.9', 'A collection of three classic Japanese horror stories: "Yotsuya Kaidan," the story of a wife betrayed by her husband who seeks vengeance even in death. "Tenshu Monogatari," the story of forbidden love between a goddess and a human, and "Bakeneko," the story of a mysterious cat monster with a vendetta against a certain family.', 'Toei Animation', '2006', 'series', 'released', '2006-01-13', 586, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:13', NULL, 'Horror, Psychological, Supernatural', 'TV', 'WINTER', 11, 17949, NULL, '2026-09-03 16:43:13', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2042, 'FLAG', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1299-Zz8fUhhwDQDd.png', 'series', '6.9', 'In the mountainous Asian country of Uddiyana a civil war rages. No end lay in sight for the war-torn nation until a lone photographer snapped an iconic image that would come to be known simply as "Flag." Hope arises as the many factions involved begin an approach to peace, rousing the call for a ceasefire behind the featured flag.

When an unknown guerilla sect steals this symbol of unity, a U.N. Special Development Command unit is dispatched using the latest in military technology, a transforming bipedal exoskeleton known as the HAVWC system. Recruited to document this mission is a war-time journalist, the author of the "Flag" photograph, Saeko Shirasu.

Witness the trials and triumphs of a peacekeeping taskforce behind the camera''s view-finder as they take their first steps towards the recovery of the road to peace and discover the truth behind a struggle.

(Source: Bandai Entertainment)', 'The Answer Studio', '2006', 'series', 'released', '2006-06-16', 1299, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:17', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1299-41FpA7NwaTPW.jpg', 'Action, Adventure, Drama, Mecha', 'ONA', 'SUMMER', 13, 8449, NULL, '2026-09-03 16:43:17', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2043, 'Full Metal Panic! The Second Raid: Zenyasai - Scene 00', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx6291-L4tafRNxmM44.png', 'series', '6.9', 'Sousuke, Kurz and Melissa are deployed to the Republic of Manistan in Central Asia to eradicate a growing civil war between rebels and the Manistani military. 

(Source: Wikipedia)', 'Kyoto Animation', '2005', 'series', 'released', '2005-07-06', 6291, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:20', NULL, 'Action, Adventure, Mecha', 'SPECIAL', 'SUMMER', 1, 8981, NULL, '2026-09-03 16:43:20', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2044, 'Pumpkin Scissors', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1538-8KjoV3x9Jhlk.jpg', 'series', '6.9', 'Alice Malvin commands a military propaganda unit, but she idealistically yearns to cut through the deception. When she uncovers a super-soldier program known as The Invisible Nine, she finds herself trapped in a web of deadly secrets. Malvin turns to an unlikely ally—Randel Orland, a hulking veteran who may hold the key to unlocking the mysteries of The Invisible Nine. 

(Source: Crunchyroll)', 'GONZO', '2006', 'series', 'released', '2006-10-03', 1538, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:24', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n1538-SWBgaU80YPXK.jpg', 'Action, Comedy, Drama', 'TV', 'FALL', 24, 8820, NULL, '2026-09-03 16:43:24', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2045, 'La Corda D''Oro: Primo Passo', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1579-P7iLCX8zNEuO.png', 'series', '6.9', 'Hino Kahoko is a student whose school is divided into two branches - the Normal Branch, in which students wear grey uniforms, and the Music Branch, in which the students wear white. The school''s tradition is a music competition, but it it more common that students from the Music Branch are chosen to compete. Kahoko is surprised one day to encounter a fairy named Lili. Solely because she is the only student to see him, she is the only student from the Normal Branch to be in the competition.

Kahoko doesn''t have any musical knowledge, until Lili grants her a magic violin, one that anyone can play if they believe they can truly do it. Kahoko must now face the trials of the competition, her competitors, and her peers.', 'Yumeta Company', '2006', 'series', 'released', '2006-10-02', 1579, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:28', NULL, 'Comedy, Drama, Music, Romance', 'TV', 'FALL', 25, 11741, NULL, '2026-09-03 16:43:28', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2046, 'Final Fantasy VII: Advent Children - Venice Film Festival Footage', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/6152.jpg', 'series', '6.9', 'Advent Children Special Edition is the 25 minute version of the movie which was shown at the 62nd Venice Film Festival in 2005. Available as dvd bonus on 2-disc special edition.', NULL, '2005', 'series', 'released', '2005-09-14', 6152, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:32', NULL, 'Action, Drama, Fantasy, Sci-Fi', 'SPECIAL', 'FALL', 1, 2100, NULL, '2026-09-03 16:43:32', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2047, 'Arms Alchemy', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1536-IkwAKpAiioIv.png', 'series', '6.9', 'The story begins when high school student Kazuki Muto is killed one night saving a mysterious girl from a monster, only to wake up in his school dorm, believing it to have been a dream. However, he soon finds out that dream wasn''t a dream at all when a giant serpentine monster attacks him and his sister. Tokiko Tsumura, the girl he saved, explains that the monster is a homunculus. Kazuki had been attacked and killed by it when he was rescuing her. However, she, feeling responsible for him, revived him by placing a Kakugane medallion in his chest, serving as a replacement heart.

The Kakugane, as Tokiko explains, is an alchemical device that, when activated, takes a certain form based on the Kakugane''s user, forming a unique Buso Renkin. The Buso Renkin is the only thing that can destroy a homunculus monster. Using this, Kazuki creates his own Buso Renkin (the "Sunlight Heart", a huge lance). Along with Tokiko and her own Buso Renkin (the "Valkyrie Skirt", an execution scythe), Kazuki joins the fight against the homunculi and their master.', 'Xebec', '2006', 'series', 'released', '2006-10-05', 1536, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:35', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1536-SUxbhDyLbASP.jpg', 'Action, Comedy, Fantasy, Supernatural', 'TV', 'FALL', 26, 26806, NULL, '2026-09-03 16:43:35', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2048, 'Air', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx101-x3YmfrzYZ9kM.jpg', 'series', '6.8', 'Yukito Kunisaki is on a journey in search of the Winged Maiden who was bound to the sky centuries ago, after hearing an old childhood tale from his mother. As Yukito shows his puppet show to people in an attempt to make some money, he finds himself in a small town in which he did not expect to stay very long. However, when he meets an unusual girl named Misuzu, things take a drastic turn as he is invited to stay with her.

By staying in the quaint town, Yukito soon becomes friends with the locals. As he gets to know them better, he learns of their problems and decides to help, putting his search for the Winged Maiden on hold. With his search on hold, and his growing attachment to Misuzu and the small town, will Yukito ever find the Winged Maiden, or is she closer than he thought?

[Written by MAL Rewrite]

Note: Includes episode 13, Soushuuhen (Summary).', 'Kyoto Animation', '2005', 'series', 'released', '2005-01-07', 101, 0, NULL, '2026-07-25 18:55:34', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101-svfB4pd7QpT5.jpg', 'Drama, Romance, Slice of Life, Supernatural', 'TV', 'WINTER', 13, 51786, 'https://www.youtube.com/watch?v=1qSIXDGyXuQ', '2026-08-29 14:39:10', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2049, 'Air in Summer', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/656.jpg', 'series', '6.8', 'An extension of the summer-arc in the Air TV-series, showing more of what happened during Kanna''s, Ryuya''s and Uraha''s journey to find Kanna''s mother.', 'Kyoto Animation', '2005', 'series', 'released', '2005-08-28', 656, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:44', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/656-6lTE6rxaVO1T.jpg', 'Comedy, Drama, Romance, Supernatural', 'SPECIAL', 'SUMMER', 2, 8730, NULL, '2026-09-03 16:43:44', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2050, 'Ginga Densetsu Weed', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/915-Y7tGnj7BJVZq.png', 'series', '6.8', 'A dog named Weed happens to hear that he is the son of Gin, The great leader of Ohu, Who lead the dogs of Ohu to victory in a fight against monsterous bear Akakabuto. Weed wants to find his father no matter of what. On a way to his father Weed meets many friends and enemies.

(Source: Anime News Network)', NULL, '2005', 'series', 'released', '2005-11-03', 915, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:48', NULL, 'Action, Adventure, Drama', 'TV', 'FALL', 26, 2962, NULL, '2026-09-03 16:43:48', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2051, 'Karas', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/389.jpg', 'series', '6.8', 'The world of the humans and the world of the demons (y&#333;kai) have overlapped one another, leaving humans to walk the streets of life as they normally would, while demons walk, hidden from the naked eye, down the very same streets. A seemingly young woman named Yurine and her servant, the Karas (from the Japanese word for "Crow"), have long maintained order and balance between the overlapped worlds, ultimately keeping the demons from interrupting the lives of humans. However, humans have come to forget and jest at the existence of demons, and no longer understand the privilege it is to live without fear. Disgusted by this arrogance, an old Karas turns his back on the laws he had once upheld, and in his human form, named Eko, he creates an army of Mikura, or mechanized demons, to ready an attack on the human race.

A young man named Otoha inherits the powers of the Karas and takes his place at the side of Yurine, who claims that his soul called out for her while he lived the life of a human. They live in the world of the demons. It is now up to Otoha to prove himself as a Karas, and restore the balance that Eko threatens to upset.

Meanwhile, a superstitious police officer named Sagisaka and his rational new recruit, Kure, follow the trail of the murders dealt by Eko''s Mikura, as well as the trail of a rogue Mikura named Nue. The prophecy unfolds from here into a grave revelation for all in the city.

(Source: Wikipedia)', 'Tatsunoko Production', '2005', 'series', 'released', '2005-03-25', 389, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:51', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/389-z6fmdtqkjitx.jpg', 'Action, Fantasy, Sci-Fi', 'OVA', 'SPRING', 6, 11377, NULL, '2026-09-03 16:43:51', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2052, 'Skating Rink Kaleidoscope', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/476.jpg', 'series', '6.8', 'With $10 billion worth of beauty (or so she says), Sakurano Tazusa is a contestant for the selection of the Japanese representative at the winter Olympics'' figure skating competition. However, her ability is questionable in the eyes of the media and public, as she constantly falls during critical moments in her competitions. During a particular fall, at the same time, a Canadian teen by the name of Pete Pumps perishes as an accident occurs during an air stunt. Before being allowed to pass on into the after life, Pete possess'' Tazusa supposedly for a hundred days, living on in her body. Despite the discontent and anger Tazusa faced having her body and privacy invaded by this Canadian ghost, she moves her focus onto improving herself in hopes to be selected for the Olympics.', 'Karaku', '2005', 'series', 'released', '2005-10-09', 476, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:43:57', NULL, 'Drama, Romance, Sports, Supernatural', 'TV', 'FALL', 12, 8409, NULL, '2026-09-03 16:43:57', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2053, 'Gallery Fake', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx364-kLB2uJHqXodf.jpg', 'series', '6.8', 'Fujita Reiji is the owner of an art gallery, Gallery Fake. He deals with fake items, and is also familiar with the black market. However, he has a special talent for art, and used to work for the Metropolitan Museum of Art in New York as a curator.

(Source: Anime News Network)', 'Tokyo Movie', '2005', 'series', 'released', '2005-01-08', 364, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:44:02', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/364-xC6aMsxz01Ka.jpg', 'Mystery', 'TV', 'WINTER', 37, 4433, NULL, '2026-09-03 16:44:02', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2054, 'IGPX 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1410-pTZlJ70Vxkt7.jpg', 'series', '6.8', 'Team Satomi has just been deemed as the winners for the IG-2 lower league and now join the top IG-1 competition. But it''s not going to be easy. Young pilots Takeshi, Liz, Amy, and River are going to have to be a team to be number 1, however one thing leads to another with these four. Most important of all, their opponents overwhelm Team Satomi in every aspect, including strategy and skill, as well as funding. One thing is for sure, this is not going to be an easy year for "Team Satomi."', NULL, '2006', 'series', 'released', '2006-05-20', 1410, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:44:05', NULL, 'Mecha, Sci-Fi, Sports', 'TV', 'SPRING', 13, 2416, NULL, '2026-09-03 16:44:05', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2055, 'Kinnikuman II Sei: ULTIMATE MUSCLE 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx5968-EVCZg2ilzba8.jpg', 'series', '6.8', 'Mantaro has made it to the semifinal match of the Chojin Cup. He must now fight Ricardo in a soccer field to advance to the last match. Kevin Mask is also in the semifinals, and must defeat Ilioukhine in an aerial field to advance. These three matches will determine who wins the Chojin Cup.

(Source: Anime News Network)', NULL, '2006', 'series', 'released', '2006-01-04', 5968, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:44:09', NULL, 'Action, Comedy, Sci-Fi, Sports', 'TV', 'WINTER', 13, 1984, NULL, '2026-09-03 16:44:09', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2056, 'Black Jack: Futari no Kuroi Isha', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/1983.jpg', 'movies', '6.8', 'The mega-corporate Daedalus Group is under attack by a small group of activists known as the Ghost of Icarus. While taking care of some of the victims of the bombing, Black Jack encounters Dr. Kiriko, also known as Death Incarnate, who just like him, asks his patients huge sums of money but instead of saving them, he offers them a painless death. When the activist group requests both doctors&rsquo; collaboration, Black Jack finds himself caught in a spiral of life, death and treason while trying to save his patients'' lives and avoid the breaking of a biological war that could destroy humanity.

(Source: Anime News Network)', NULL, '2005', 'movie', 'released', '2005-12-17', 1983, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:44:13', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n1983-OFaTRKiHwg9I.jpg', 'Drama', 'MOVIE', 'FALL', 1, 1512, NULL, '2026-09-03 16:44:13', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2057, 'Fullmetal Alchemist: Reflections', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/664.jpg', 'series', '6.8', 'A reflection on what happened during the FMA TV series.', 'bones', '2005', 'series', 'released', '2005-03-19', 664, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:44:17', NULL, 'Adventure, Comedy, Drama, Fantasy', 'SPECIAL', 'SPRING', 1, 9833, NULL, '2026-09-03 16:44:17', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2058, 'Top wo Nerae! & Top wo Nerae 2! Gattai Movie!!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1911-nVl9IQnszHAN.png', 'movies', '6.8', 'This double feature comprises of Gunbuster and Die Buster (aka Gunbuster 2) condensed them into a single theatrical release told in two parts with a musical intermission in between. The first part, Gunbuster the Movie, condenses the six episodes of the original OVA into a 95-minute moviefeaturing a new 5.1 audio remix and a redub by the original Japanese cast. The second part, Die Buster the Movie, mixes large chunks of the second OVA series with a few altered or newly-animated scenes to create a truncated take on Nono''s story. 

(Source: Anime News Network)', NULL, '2006', 'movie', 'released', '2006-10-01', 1911, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:44:20', NULL, 'Action, Comedy, Drama, Mecha, Sci-Fi', 'MOVIE', 'FALL', 2, 3983, NULL, '2026-09-03 16:44:20', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2059, 'Pale Cocoon', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/770.jpg', 'series', '6.8', 'A future where the continuity of history has broken off, a world of enormous ruins that continues endlessly. Oceans and continents have vanished, existing only within the archives brought up from the remains. Ura works in the Archive Excavation Department, which restores and analyzes the data left behind. One day, he finds a disturbing visual record...

(Source: Anime News Network)', 'Studio Rikka', '2005', 'series', 'released', '2005-12-10', 770, 0, NULL, '2026-07-25 18:55:34', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/770-RE1wPVTRDfLW.jpg', 'Drama, Sci-Fi', 'OVA', 'WINTER', 1, 16665, 'https://www.youtube.com/watch?v=2gx0MJWeOTs', '2026-08-29 14:39:07', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2060, 'Kirarin Revolution', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1516-w5aomgJd74Ar.jpg', 'series', '6.8', 'Kirari Tsukishima, a gluttonous 14-year-old beauty, is a girl who does not care about idols and the entertainment world because her mind is occupied by food. Her obsession with food only causes her to be clueless about love. 

One day, after saving a turtle that is stranded in a tree, Kirari meets with a handsome and gentle boy named Seiji, who gives her ticket to a SHIPS (a popular idol group) concert to show his gratitude for her saving his pet. Kirari then storms off to the concert and runs into another boy, who tears up her ticket and warns her to stay away from Seiji because she and Seiji live in different worlds. The outraged Kirari then sneaks into the concert, only to discover that Seiji and the boy who tore her ticket, named Hiroto, are actually members of SHIPS. 

Finally understanding the meaning of "different worlds" (Seiji is a popular idol while she is an average middle school student), Kirari refuses to give up. Filled with determination to be with Seiji, she declares that she will also become an idol.', 'SynergySP', '2006', 'series', 'released', '2006-04-07', 1516, 0, NULL, '2026-07-25 18:55:34', '2026-09-03 16:44:28', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1516-xBV6FIRXoAJt.jpg', 'Comedy, Drama, Music, Romance', 'TV', 'SPRING', 153, 7534, NULL, '2026-09-03 16:44:28', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2061, 'Kino''s Journey', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx486-xXUgNOEBuxGs.jpg', 'series', '8.1', 'Based on a hit light novel series by Keiichi Sigsawa, the philosophical Kino''s Journey employs the time-honored motif of the road trip as a vehicle for self-discovery and universal truth. Deeply meditative and cooler than zero, the series follows the existential adventures of the apt marksman Kino along with talking motorcycle Hermes as they travel the world and learn much about themselves in the process. Imaginative, thought-provoking, and sometimes disturbing, Kino''s journey is documented in an episodic style with an emphasis on atmosphere rather than action or plot, though still prevalent.', 'A.C.G.T.', '2003', 'series', 'released', '2003-04-08', 486, 0, NULL, '2026-07-25 18:55:38', '2026-09-03 16:44:32', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/486-cDPgzYdzHNEq.jpg', 'Adventure, Drama, Fantasy, Psychological, Slice of Life', 'TV', 'SPRING', 13, 95175, NULL, '2026-09-03 16:44:32', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2062, 'Hajime no Ippo: The Fighting! - Mashiba vs Kimura', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx265-6H1q2JBs7tB7.jpg', 'series', '8.1', 'Kimura finally has his championship match. It takes place at the annual champion carnival. But now he must face the intense champion, Mashiba for the Junior Lightweight championship.

(Source: Anime News Network)', 'MADHOUSE', '2003', 'series', 'released', '2003-09-05', 265, 0, NULL, '2026-07-25 18:55:38', '2026-09-03 16:44:37', NULL, 'Comedy, Sports', 'OVA', 'FALL', 1, 29614, NULL, '2026-09-03 16:44:37', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2063, 'Princess Tutu', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx721-9tJpM47RBPJm.jpg', 'series', '8.1', 'In a fairy tale come to life, the clumsy, sweet, and gentle Ahiru (Japanese for ''duck'') seems like an unlikely protagonist. In reality, Ahiru is just as magical as the talking cats and crocodiles that inhabit her town - for Ahiru really is a duck! Transformed by the mysterious Drosselmeyer into a human girl, Ahiru soon learns the reason for her existence. Using her magical egg-shaped pendant, Ahiru can transform into Princess Tutu - a beautiful and talented ballet dancer whose dances relieve people of the turmoil in their hearts. With her newfound ability, Ahiru accepts the challenge of collecting the lost shards of her prince''s heart, for long ago he had shattered it in order to seal an evil raven away for all eternity.

Princess Tutu is a tale of heroes and their struggle against fate. Their beliefs, their feelings, and ultimately their actions will determine whether this fairy tale can reach its "happily ever after."

Note: Princess Tutu aired in two parts. The first part included 13 25-minute-long episodes, while the second part consisted of 24 12-minute-long episodes with a 25-minute-long final episode for a total of 38 episodes.', 'Hal Film Maker', '2002', 'series', 'released', '2002-08-16', 721, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/721-ekK3UsayhBl3.jpg', 'Drama, Fantasy, Mahou Shoujo, Mystery, Psychological, Romance', 'TV', 'SUMMER', 38, 46157, 'https://www.youtube.com/watch?v=z4_OOcdWQSo', '2026-08-29 14:39:54', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2064, 'Beck: Mongolian Chop Squad', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx57-4wTOlaVSgKoy.png', 'series', '8.0', 'Tanaka Yukio, better known by his nickname Koyuki is a 14 year old who feels disconnected from life in general. Through the act of saving a mismatched dog, he meets guitarist Minami Ryuusuke, and becomes involved in Ryuusuke''s new band BECK. Koyuki''s life starts to change as the band struggles towards fame.', 'MADHOUSE', '2004', 'series', 'released', '2004-10-06', 57, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/57-fLzMIA5ZXvwp.jpg', 'Comedy, Drama, Music, Slice of Life', 'TV', 'FALL', 26, 81159, 'https://www.youtube.com/watch?v=GNgReTHy1EA', '2026-08-29 14:39:57', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2065, 'Hajime no Ippo: The Fighting! - Champion Road', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx264-YQJiFF9LDiUr.png', 'series', '8.0', 'As the new Champion, Ippo must protect his title against some of the best boxers available.

Makunouchi Ippo is the new Featherweight champion of Japan and is now ready for his first title defense. His opponent, the former Jr. Featherweight champion and a medical student, Sanada Kazuki. In addition to this feud, Sanada is being coached by Kamogawa''s former rival, Hama Dankichi. What makes things worse is that Sanada works at the same hospital where Kumi is a nurse at and everybody at the hospital wants Sanada to win. Not only does Ippo have to defend his title, he has to reclaim his love.

(Source: Anime News Network)', 'MADHOUSE', '2003', 'series', 'released', '2003-04-18', 264, 0, NULL, '2026-07-25 18:55:38', '2026-09-03 16:44:48', NULL, 'Comedy, Sports', 'SPECIAL', 'SPRING', 1, 34015, NULL, '2026-09-03 16:44:48', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2066, 'Initial D 4th Stage', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b18-r7IirVmwP89u.jpg', 'series', '8.0', 'Takumi Fujiwara and brothers Keisuke and Ryousuke Takahashi have formed "Project D," a racing team aimed at bringing their driving skills to their full potential outside their prefecture. Using the internet, Project D issues challenges to other racing teams and posts results of their races. Managed by Ryousuke, the team has Takumi engaging in downhill battles with his AE86, while Keisuke challenges opponents uphill. Among their rivals are the Seven-Star Leaf (SSR) and Todo-juku.', 'OB Planning', '2004', 'series', 'released', '2004-04-17', 18, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/18-aiibhi4BrZeR.jpg', 'Action, Drama, Sports', 'TV', 'SPRING', 24, 50218, 'https://www.youtube.com/watch?v=T0HCsCYVM-Y', '2026-08-29 14:57:46', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2067, 'Major S1', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx627-B0V5aoDfwtz0.png', 'series', '8.0', 'Honda Shigeharu is a Major League batter on the rise. His son Gorou is a Little League pitcher who one day hopes to follow in his father''s footsteps. Hoshino Momoko is Gorou''s schoolteacher and the first woman Shigeharu has been interested in since the death of Gorou''s mother. The destinies of these three individuals will become intertwined as father and son experience both heartbreak and triumph on the baseball diamond. But when an unspeakable tragedy visits the family, it will take everything they have to pick up the pieces and reclaim their dreams.

(Source: Anime News Network)', 'Studio Hibari', '2004', 'series', 'released', '2004-11-13', 627, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/627-jIPZjL2FkTpu.jpg', 'Comedy, Drama, Sports', 'TV', 'FALL', 26, 22950, 'https://www.youtube.com/watch?v=kDjRT6mSj3c', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2068, 'Planetes', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx329-4xwXdazRA7Ph.png', 'series', '8.0', 'In the year 2075, mankind has reached a point where journeying between Earth, the moon and the space stations is part of daily life. However, the progression of technology in space has also resulted in the problem of the space debris, which can cause excessive and even catastrophic damage to spacecrafts and equipment. This is the story of Technora''s Debris Collecting section, its EVA worker, Hachirota "Hachimaki" Hoshino, and the newcomer to the group, Ai Tanabe.

(Source: Anime News Network)', 'Sunrise', '2003', 'series', 'released', '2003-10-04', 329, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/329-BwJy0rauT2k4.jpg', 'Drama, Romance, Sci-Fi, Slice of Life', 'TV', 'FALL', 26, 63948, 'https://www.youtube.com/watch?v=igmZSI3kILY', '2026-08-29 14:39:48', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2069, 'Haibane Renmei', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx387-dS4aJivu0zPB.png', 'series', '8.0', 'A dream of falling from the sky... and then birth. Rakka is born from a large cocoon into the Old Home, greeted by a group of girls with small wings on their backs and shining halos above their heads. Soon Rakka&rsquo;s own wings grow, a halo is placed on her head and she is told that she must work in the nearby town of Grie. She soon realizes that the town and the entire world they live in are confined behind the Wall, a tall, impenetrable wall that none except the mysterious Toga are allowed to exit. 

(Source: Anime News Network)', 'Radix', '2002', 'series', 'released', '2002-10-10', 387, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/387-2ogrNTbIYy2T.jpg', 'Drama, Fantasy, Mystery, Psychological, Slice of Life', 'TV', 'FALL', 13, 99693, 'https://www.youtube.com/watch?v=B2yKFMPgXmA', '2026-08-29 14:39:37', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2070, 'Azumanga Daioh', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx66-ZqYQWl6LsfeI.png', 'series', '7.9', 'Ten year old child prodigy, Chiyo Mihama, is finding it tough fitting in at high school with the girls five years her elder: Osaka (dimwitted with a weird take on the world), Tomo (a powder keg that goes off at a moment’s notice), Kagura (the competitive athlete of the bunch), Yomi (the hothead), and Sakaki (timid and obsessed with a love of animals that isn’t reciprocated). Together with their teacher, they navigate the rough waters and fun times of high school.

(Source: Sentai Filmworks)', 'J.C.STAFF', '2002', 'series', 'released', '2002-04-09', 66, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/66-9q6Y6bMBwqrX.jpg', 'Comedy, Slice of Life', 'TV', 'SPRING', 26, 108513, 'https://www.youtube.com/watch?v=kTDVKvKU-eI', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2071, 'R.O.D -THE TV-', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx209-d0WO2JHIfzTu.png', 'series', '7.9', 'Five years have passed since the occurrence of the incident known as the "Human Annihilation Mission." In Japan, a novelist is dealing with writer''s block after her friend has gone missing. In Hong Kong, three sisters, masters in the use of paper, run their own detective agency to solve cases that involve books. When these people are brought together, a bond greater than blood is formed - a bond that will be sorely tested by the evil powers intent on taking over the world.

Join Anita, Maggie, Michelle, and Nenene as they travel the globe in order to save the world from the evil mastermind, Mr. Carpenter! Of course, that''s if they can find the time to put down the books they''re reading...

(Source: RightStuf)', 'J.C.STAFF', '2003', 'series', 'released', '2003-09-01', 209, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/209.jpg', 'Action, Drama, Mystery, Sci-Fi', 'TV', 'FALL', 26, 17264, 'https://www.youtube.com/watch?v=AuXdmxrg0yo', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2072, 'Ojamajo Doremi Na-i-sho', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1376-LH3Sw7ZAJMjs.png', 'series', '7.9', 'Na-i-sho is a 13 episode OVA series with episodes taking place during the ~motto~ season. It is a bit more mature than the TV seasons, and looks to develop each of the five witches romantically. Hana is back to a baby, and the mahou shop is a bakery. 

(Source: Anime News Network)', 'Toei Animation', '2004', 'series', 'released', '2004-06-26', 1376, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n1376-cNRyH1lRlXCz.jpg', 'Comedy, Drama, Fantasy, Mahou Shoujo, Slice of Life', 'OVA', 'SUMMER', 13, 3897, 'https://www.youtube.com/watch?v=_t4zm6EnraQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2073, 'Ojamajo Doremi Dokkaan!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx353-OPqNN0mZ6onZ.jpg', 'series', '7.9', 'Hana now becomes a peer of the Ojamajo. When Majotourbillon''s spirit revives, the witches now have to break her curse. From the help from Pao-chan, Doremi, Hana, and the other witches are able to defeat the curses. 

(Source: Anime News Network)', 'Toei Animation', '2002', 'series', 'released', '2002-02-03', 353, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/353-tTjmRsQf41CE.jpg', 'Comedy, Drama, Fantasy, Mahou Shoujo, Slice of Life', 'TV', 'WINTER', 51, 6033, 'https://www.youtube.com/watch?v=_t4zm6EnraQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2074, 'Gungrave', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx267-vGNmfjvWb1Qq.png', 'series', '7.5', 'After a tragic scene with the murder of his friends, Brandon Heat follows his only friend Harry McDowel into Millennion, the largest mafia syndicate. While Harry McDowel is striving for power, Brandon is only staying in Millennion to see the girl he loves whose custody was gained by the leader of Millennion, Big Daddy. But as the years pass and Brandon proves loyal to Millennion, Brandon learns the true purpose and passion of Millennion, and that''s when true conflict arises.

(Source: Anime News Network)', 'MADHOUSE', '2003', 'series', 'released', '2003-10-07', 267, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/267-hm9sSMK4Krls.jpg', 'Action, Drama, Sci-Fi', 'TV', 'FALL', 26, 41662, 'https://www.youtube.com/watch?v=EI8SLFZ_bdg', '2026-08-29 14:39:59', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2075, 'Gankutsuou: The Count of Monte Cristo', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx239-eldiiZxky1Ul.png', 'series', '7.9', 'Gankutsuou is an anime loosely based on the novel The Count of Monte Cristo by Alexandre Dumas. It tells the story of Albert Morcerf, a young aristocrat who happens to befriend a wealthy nobleman, The Count of Monte Cristo, through a series of bizarre events. Fascinated by the Count''s charm, Albert invites him to meet his friends and family, all of whom happen to be part of the upper class society of Paris, France. Unfortunately, little does Albert realize that the Count has ulterior motives in mind.

(Source: MAL Rewrite)', 'GONZO', '2004', 'series', 'released', '2004-10-06', 239, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/239-QZ7bh97wgpMn.jpg', 'Drama, Mystery, Sci-Fi, Supernatural, Thriller', 'TV', 'FALL', 24, 59079, 'https://www.youtube.com/watch?v=kwjWBnWjWbc', '2026-08-29 14:39:51', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2076, 'Hajime no Ippo: The Fighting! - Boxer''s Fist', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/12069-8iXSMYNyflIV.jpg', 'series', '7.9', 'A special episode included in the DVDs. It tells how Takamura started boxing.', 'MADHOUSE', '2003', 'series', 'released', '2003-03-21', 12069, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', NULL, 'Comedy, Drama, Sports', 'SPECIAL', 'SPRING', 1, 15696, 'https://www.youtube.com/watch?v=F6kuCWVJ8Ns', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2077, 'Crayon Shin-chan: Fierceness That Invites Storm! The Adult Empire Strikes Back', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2450-0Iwi4jr32Xe8.jpg', 'movies', '7.8', 'As the 21st century approaches, a new 20th-century museum has opened in town, for the adults to relive their childhood. However, the owners of the museum seem to have other plans for it. The adults start to behave strangely, and one morning, they abandon their children for the 20th-century museum. Shinnosuke, along with his friends, must now rescue his parents and stop the world from returning to the 20th century before they get captured.

(Source: Anime News Network)', NULL, '2001', 'movie', 'released', '2001-04-21', 2450, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2450-qwf7Fuv9BMQZ.jpg', 'Comedy, Slice of Life', 'MOVIE', 'SPRING', 1, 4638, 'https://www.youtube.com/watch?v=MUlNumVQpFU', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2078, 'Initial D 3rd Stage', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx187-QyCAlBGY3EWw.jpg', 'movies', '7.8', 'Takumi is approached by RedSuns leader Ryosuke Takahashi and offered to join him in forming a professional racing team. Before coming up with an answer to the proposal, Takumi seeks retribution by issuing a rematch to Emperor leader Kyouichi Sudou, who previously defeated him due to an engine failure. He is also challenged by Kai Kogashiwa, a second-generation street racer whose father was once a fierce rival of Takumi''s father Bunta.', 'Studio DEEN', '2001', 'movie', 'released', '2001-01-13', 187, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/187-EPd7ahDZZHyg.jpg', 'Action, Drama, Romance, Sports', 'MOVIE', 'WINTER', 1, 50100, 'https://www.youtube.com/watch?v=YfdONLhaEBM', '2026-08-29 14:39:23', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2079, 'Hikaru no Go', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx135-egPcTb3lAnbu.jpg', 'series', '7.8', 'With a two-tone hairstyle and a streak of immaturity, Hikaru Shindou finds an old Go board with a hidden surprise - trapped within the Go Board is Fujiwara-no-Sai, the ghost of an ancient Go master! In the blink of an eye, Sai becomes part of Hikaru''s consciousness and soon begins to learn the true essence behind this ancient game of skill and strategy.

(Source: VIZ Media)', 'Studio Pierrot', '2001', 'series', 'released', '2001-10-10', 135, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/135-MabC9U5gTP8S.jpg', 'Comedy, Sports, Supernatural', 'TV', 'FALL', 75, 27613, 'https://www.youtube.com/watch?v=2bzlTRi9K4c', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2080, 'Full Metal Panic? Fumoffu', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx72-dalTPVFKaOuZ.png', 'series', '7.7', 'It''s back-to-school mayhem with Kaname Chidori and her war-freak classmate Sousuke Sagara as they encounter more misadventures in and out of Jindai High School. But when Kaname gets into some serious trouble, Sousuke takes the guise of Bonta-kun - the gun-wielding, butt-kicking mascot. And while he struggles to continue living as a normal teenager, Sousuke also has to deal with protecting his superior officer Teletha Testarossa, who has decided to take a vacation from Mithril and spend a couple of weeks as his and Kaname''s classmate.

(Source: Anime News Network)', 'Kyoto Animation', '2003', 'series', 'released', '2003-08-26', 72, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/72-bmvzb8rQunld.png', 'Action, Comedy, Romance', 'TV', 'SUMMER', 12, 45199, 'https://www.youtube.com/watch?v=rYHyGKZdw2o', '2026-08-29 14:39:26', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2081, 'Interstella 5555: The 5tory of the 5ecret 5tar 5ystem', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx731-aoWO30cMR4yO.jpg', 'movies', '7.7', 'This film is a visual companion piece to "Discovery", an album by Daft Punk. It tells the story of a band of four extraterrestrial musicians who are kidnapped and brought back to Earth by an evil manager. Their only hopes lie with a space pilot from their home planet who, after receiving a distress call broadcasted during the abduction, seeks out to rescue them.', 'Toei Animation', '2003', 'movie', 'released', '2003-05-28', 731, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/731-HQOXhlc4oG9r.jpg', 'Adventure, Drama, Music, Sci-Fi', 'MOVIE', 'SPRING', 1, 20298, 'https://www.youtube.com/watch?v=EMroa1WgofA', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2082, 'Saint Seiya: The Hades Chapter - Sanctuary', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1257-tZuA879PQLZe.png', 'series', '7.7', 'Hades is planning to take over the world, to achieve that goal, he sends out deceased Gold Saints to take Athena''s head. Seiya and the other Bronze Saints come to help but their help isn''t appreciated by the remaining Gold Saints that are still alive.

(Source: Anime News Network)', NULL, '2002', 'series', 'released', '2002-11-09', 1257, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1257-VzGNktNWGzF0.jpg', 'Adventure, Sci-Fi', 'OVA', 'FALL', 13, 11937, 'https://www.youtube.com/watch?v=42Bp50xpeWY', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2083, 'The Twelve Kingdoms', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx153-pLhZPQCYk7hl.png', 'series', '7.7', 'Nakajima Youko is your average somewhat timid high school student. One day, a strange man named Keiki appears before her, swearing allegiance. Before she could properly register what was happening, demon-like creatures attack Youko and her friends, after which they are pulled into a different world. A world unlike what she has ever known. Separated from Keiki, Youko and her friends must do whatever they can if they wish to survive in this new world.', 'Studio Pierrot', '2002', 'series', 'released', '2002-04-09', 153, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/153-69eJS2eBYxus.jpg', 'Action, Adventure, Fantasy, Supernatural', 'TV', 'SPRING', 45, 40346, 'https://www.youtube.com/watch?v=cHyqJuD2a3s', '2026-08-29 14:39:29', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2084, 'Wolf''s Rain OVA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/1023.jpg', 'series', '7.7', 'After leaving Jagara''s keep, the story concludes as Kiba, Tsume, Hige, Toboe, Blue and Cheza struggle to finish their journey to Rakuen (Paradise), accompanied by the humans Hubb, Cher and Quent. Darcia confronts the protagonists at last. The secrets of his mysterious existence and Cheza''s true form are revealed in this finale.

(Source: Anime News Network)', 'bones', '2004', 'series', 'released', '2004-01-23', 1023, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', NULL, 'Adventure, Drama, Psychological, Sci-Fi, Supernatural', 'OVA', 'WINTER', 4, 12019, 'https://www.youtube.com/watch?v=AXoTxTizh2o', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2085, 'Texhnolyze', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx26-ADSztyHBNO39.jpg', 'series', '7.6', 'In a man-made underground society, descendants of a banished generation vie for control of the crumbling city of Lux. Ichise, an orphan turned prize fighter, loses a leg and an arm to satisfy an enraged fight promoter. On the brink of death he is taken in by a young woman doctor and used as a guinea pig for the next evolution of Texhnolyze. With his new limbs, Ichise is taken under the wing of Oonishi, a powerful leader of Organ, an organization with some hold on Lux. As Ichise is drawn deeper into a war for territorial control of the city, he learns of his possible future from the young girl prophet Ran, who guides him from the shadows in his darkest times. With the explosion of the warfare, Ichise must uncover the truth about Lux and fight for his survival as he realizes his destiny.

(Source: Anime News Network)', 'MADHOUSE', '2003', 'series', 'released', '2003-04-17', 26, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/26-FWJgAONj7etr.jpg', 'Action, Drama, Psychological, Sci-Fi', 'TV', 'SPRING', 22, 83869, 'https://www.youtube.com/watch?v=Z19QTGvwg9I', '2026-08-29 14:39:32', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2086, 'Mind Game', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx875-kvQVUKDPcAKl.png', 'movies', '7.6', 'Audiences will begin to grasp what they are in for early on, as loser Nishi, too wimpy to try to save his childhood sweetheart from gangsters, is shot in the butt by a soccer-playing psychopath, projecting Nishi into the afterlife. In this limbo, God - shown as a series of rapidly changing characters - tells him to walk toward the light. But Nishi runs like hell in the other direction and returns to Earth a changed man, driven to live each moment to the fullest.

(Source: Shout! Factory)', 'Studio 4°C', '2004', 'movie', 'released', '2004-08-07', 875, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/875-yXbiRS7ayxlG.jpg', 'Adventure, Comedy, Psychological, Romance', 'MOVIE', 'SUMMER', 1, 29920, 'https://www.youtube.com/watch?v=Ptup0pp6mOE', '2026-08-29 14:39:35', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2087, 'Looking for the Full Moon', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx122-seEUpu2fDTtF.jpg', 'series', '7.6', 'Twelve-year-old Kouyama Mitsuki was devastated when she was diagnosed with a malignant tumor of the throat. She had made a promise to the boy she loves that she would one day become a singer, but her illness made singing impossible. To make matters even worse, two angels of death, Takuto and Meroko, appeared to Mitsuki and informed her that she only had one year left to live. This news provides an even greater motivation for Mitsuki to fulfill her dreams, and with a little bit of divine intervention, she begins her quest to become a professional singer so she can be reunited with Eichi before time runs out. 

(Source: Anime News Network)', 'Studio DEEN', '2002', 'series', 'released', '2002-04-06', 122, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/122-JLidxTMPRE7r.jpg', 'Comedy, Drama, Mahou Shoujo, Music, Romance, Supernatural', 'TV', 'SPRING', 52, 21861, 'https://www.youtube.com/watch?v=7L2DIzGuPPw', '2026-08-29 14:39:40', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2088, 'Motto! Ojamajo Doremi', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx352-QY0OK1NrlhMR.jpg', 'series', '7.6', 'After the losing of magical ability to become witches, they once again become them. But, now they have to go through tests from the Witches of the Witch World. They also meet a new member, from New York, U.S. comes Momoko (the yellow Ojamajo). 

(Source: Anime News Network)', 'Toei Animation', '2001', 'series', 'released', '2001-02-04', 352, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/352-fz2gpoVDCSA7.jpg', 'Comedy, Drama, Fantasy, Mahou Shoujo, Slice of Life', 'TV', 'WINTER', 50, 6536, 'https://www.youtube.com/watch?v=OOMEDE2BHwM', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2089, 'School Rumble', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx24-FY8Y08LrROKE.png', 'series', '7.6', 'Tsukamoto Tenma is an ordinary 2nd year high school student who has fallen in love with one of her classmates, Karasuma Ooji. However, currently she is unable to confess her feelings to him. To make things worse, she found out that Karasuma is transferring to another school in a year. On the other hand, Tenma''s other classmate, Harima Kenji (who is a delinquent) is also in love with Tenma. Not being able to confess his feelings, Harima gets depressed day by day.

(Source: Anime News Network)', 'Studio Comet', '2004', 'series', 'released', '2004-10-05', 24, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/24-THD6AYmlVPIb.jpg', 'Comedy, Romance, Slice of Life', 'TV', 'FALL', 26, 58739, 'https://www.youtube.com/watch?v=d7-B2b4wKPs', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2090, 'Kaleido Star', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx427-nzHOyyTX2jLO.jpg', 'series', '7.6', 'Sora, a young girl from Japan, comes to America in search of her dream. She wants, with all her heart, to be a member of the Kaleido Stage, a world famous circus, with a combination of musicals, acrobatics and magical effects. With the help of her friends, she struggles to make this dream come true.', 'GONZO', '2003', 'series', 'released', '2003-04-03', 427, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/427-JGvVUBiJTgWY.jpg', 'Comedy, Drama, Sports, Supernatural', 'TV', 'SPRING', 51, 18398, 'https://www.youtube.com/watch?v=eVIoB8fAnYI', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2091, 'Paranoia Agent', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx323-ZGkUcJOn4ngy.png', 'series', '7.6', 'An elementary school kid dubbed with the title "shounen bat" or "lil slugger" has been going around attacking people with his bent, golden bat. Now, two detectives are investigating so they can stop this kid from making any more attacks, but they will find out soon enough... that this case is much more than they expected. 

(Source: Anime News Network)', 'MADHOUSE', '2004', 'series', 'released', '2004-02-03', 323, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/323-tQCOVrhiRgeU.jpg', 'Drama, Mystery, Psychological, Supernatural, Thriller', 'TV', 'WINTER', 13, 128969, 'https://www.youtube.com/watch?v=eCEkZP2pGQw', '2026-08-29 14:39:43', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2092, 'Noir', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx272-lRHGmGHUZMr2.jpg', 'series', '6.9', 'Mireille Bouquet is a professional assassin, and a very good one at that. But when she follows up an e-mail from a young Japanese girl named Yumura Kirika, inviting her to take "a pilgrimage to the past", her life becomes even more dangerous than it already is. Now, with a haunting melody invoking the memory of an event long past, Mireille and Kirika decide to work together to find the truth about a thousand year old organization that has controlled both of their lives since before they were born. And the only clue in their search, the only thing Kirika remembers about herself, becomes their working codename: a name designating an ancient fate, of two maidens who reign over death--Noir. 

(Source: Anime News Network)', 'Bee Train', '2001', 'series', 'released', '2001-04-06', 272, 0, NULL, '2026-07-25 18:55:38', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n272-FvZK2wFXEuay.jpg', 'Action, Drama, Mystery', 'TV', 'SPRING', 26, 29898, 'https://www.youtube.com/watch?v=jcx6upBbaS0', '2026-08-29 14:39:46', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2093, 'Yakitate!! Japan', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx28-QuKcZpUjTXzV.png', 'series', '7.5', 'Kazuma Azuma wants to make bread. Not just any kind of bread, though. He wants to make a bread that represents Japan itself and can stand toe-to-toe with rice as a national food. Thanks to his legendary "Hands of the Sun," unnaturally warm hands that allow dough to ferment faster, Kazuma''s bread is like a slice of Heaven.

And when the Pantasia Rookie Competition arrives, everyone will get a taste of his skill! Along with his friend Kawachi (who''s only in it for the dough), he’ll go up against koala karate masters, Harvard bread scientists, samurai with rolling-pin swords, and more! Can Kazuma create bread like naan other and bake his way to glory, or should he quit before he''s toast?

(Source: Right Stuf)', 'Sunrise', '2004', 'series', 'released', '2004-10-12', 28, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/28-XGCH1SoNhyiC.jpg', 'Comedy', 'TV', 'FALL', 69, 19902, 'https://www.youtube.com/watch?v=dKJhB0nSBjw', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2094, 'Madlax', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx252-VPLN6O7v18RC.png', 'series', '7.5', 'In the country of Gazth-Sonika, civil war rages. There, a mercenary called Madlax plies her trade, with almost supernatural skill. In the seemingly peaceful country of Nafrece, Margaret Burton lives a tranquil life. As separate as their lives may seem, the two are connected by ties of mystery, and by a holy book that is also sought by the shadowy organisation, Anfan. As Margaret and Madlax follow the path of their destiny, they come ever closer to uncovering the truth - with no guarantee that it is a truth they can bear to learn.

(Source: Anime News Network)', 'Bee Train', '2004', 'series', 'released', '2004-04-05', 252, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/252-VhuaDuAJowmp.jpg', 'Action, Drama, Mystery, Psychological, Supernatural', 'TV', 'SPRING', 26, 11606, 'https://www.youtube.com/watch?v=z8i39c1_Md4', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2095, 'Hikaru no Go: Hokuto Hai e no Michi', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx645-pyWfd1NkNDdB.png', 'series', '7.5', 'Hikaru is given a phone call asking him to appear in the Japan/China/Korea Junior''s Tournament but he finds out he will have to take place in a preliminary tournament to choose Japan''s three contestants. Upon discussing this with Akira, he discovers that Akira has already been chosen for the tournament and will not be taking place in the preliminaries. Hikaru then decides not to visit Akira''s Go Salon until he takes his place on the team with Akira. That may be tougher than originally planned, as not only does Hikaru have to battle with old friends for one of two coveted spots, but he may have a new challenger, in a promising player from the Kansai Go Institute. 

(Source: Anime News Network)', 'Studio Pierrot', '2004', 'series', 'released', '2004-01-03', 645, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Sports, Supernatural', 'SPECIAL', 'WINTER', 1, 4693, 'https://www.youtube.com/watch?v=4m2bSej0HxQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2096, 'InuYasha the Movie 3: Swords of an Honorable Ruler', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx451-t0IlENS6jPDG.png', 'movies', '7.5', 'Izayoi and Inu no Taishou, Inuyasha''s parents, are having problems with a human named Setsuna no Takemaru. Sou''unga a magical sword that has been sealed away for 700 years is found. Now everyone is after the sword and its powers but it seems the sword has something else in mind.

(Source: Anime News Network)', NULL, '2003', 'movie', 'released', '2003-12-20', 451, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Drama, Fantasy', 'MOVIE', 'FALL', 1, 17131, 'https://www.youtube.com/watch?v=u_iiFP0-tEc', '2026-08-29 14:40:19', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2097, 'Banner of the Stars II', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx397-mngW4FJxfPTl.png', 'series', '7.5', 'Due to a lack of ambassadors for the recently-conquered worlds the rapidly advancing fleet of the Bebaus brothers leave behind, Lafiel is appointed Territorial Ambassador of the planet Lobnas II. Upon arriving to the planet Jinto and Lafiel discover that the planet was used by the United Mankind as a prison planet and now has a million prisoners on the only inhabited island. The prisoners are parted in three blocks. The western where women are housed, the eastern belongs to the men and the central is mixed under the restriction that all prisoners living there are sterilized. The women in the western sector want to emigrate from the planet of fear for the men and when they do the men in the east rebel, overthrowing the guards and capturing Jinto to try to stop the emigration of the women. At the same time an enemy fleet heads toward the system forcing Lafiel to abandon Jinto.

(Source: Anime News Network)', 'Sunrise', '2001', 'series', 'released', '2001-07-11', 397, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/397-rYgIAMrsMm6P.jpg', 'Action, Romance, Sci-Fi', 'TV', 'SUMMER', 10, 5602, 'https://www.youtube.com/watch?v=eaiEfm8TWdo', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2098, 'Cromartie High School', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx114-VqL7lYKqdBR6.png', 'series', '7.5', 'Is this the real life? Is this just fantasy?

The only thing for certain is that for Kamiyama, Cromartie High School is his reality. And what a surreal reality it is.

Because this is where the toughest, meanest (and often dumbest) students are sent to do time. At Cromartie, purple-mohawked bruisers and pencil-chomping street thugs are just part of every day life. And so is a 400-pound gorilla. And a macho brute named Freddie who travels with his own theme music. And, of course, Mechazawa, the student voted most likely to need an oil change. So pack your bags, put on your best tough-guy swagger, and get a lesson in insanity from the hilarious losers at Cromartie High. This is one class you won''t ever want to cut.

(Source: Discotek)', 'Production I.G', '2003', 'series', 'released', '2003-10-03', 114, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/114.jpg', 'Comedy', 'TV_SHORT', 'FALL', 26, 36767, 'https://www.youtube.com/watch?v=-WAwM2-WyfY', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2099, 'R.O.D - READ OR DIE', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx208-yOpLH6XOw2sc.jpg', 'series', '7.5', 'Yomiko Readman is a lovable, near-sighted bibliomaniac working as a substitute teacher at a Japanese high school. Her real identity, however, is that of a secret agent for the British Library Special Operations Division. Her codename: "The Paper." The moniker denotes her supernatural ability to freely manipulate paper into any object she can imagine, including tools and weapons in her fight against the powerful and self-serving IJIN (Great Historical Figure) Army! Along with her partner, the enigmatic "Ms. Deep," Yomiko travels across the world in attempt to solve the mystery behind the reincarnation of historical figures and their attempt to control the world.

(Source: RightStuf)', 'Studio DEEN', '2001', 'series', 'released', '2001-05-23', 208, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/208-wXy2XjpIEy4E.jpg', 'Action, Drama, Mystery, Sci-Fi', 'OVA', 'SPRING', 3, 19902, 'https://www.youtube.com/watch?v=ZjduRoWgrao', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2100, 'Rurouni Kenshin OVA: Reflection (Seiso-hen)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx401-onwFZh9JNmBl.png', 'series', '7.5', 'Kenshin’s history of death and destruction has left him known throughout all of Japan as the sword-bearing master assassin. Seeking retribution for his past, Kenshin wanders further away to a place he can call home. Although creating a time of peace through his actions, Kenshin continues to distance himself from the ones he loves. Kenshin’s wife, Kaoru, anxiously waits for the moment of his return. Will Kenshin ever return to his wife before she passes away from waiting?

(Source: Aniplex of America)', 'Studio DEEN', '2001', 'series', 'released', '2001-12-03', 401, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/401-XmgxPxn31gOY.jpg', 'Drama, Romance', 'OVA', 'FALL', 2, 14144, 'https://www.youtube.com/watch?v=rRIW72k0n5g', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2101, 'Hanada Shounen-shi', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2004-oLBclDWKkroa.png', 'series', '7.5', 'Young Ichiro Hanada lives with his parents and grandfather in a quiet rural town. He is a little brat who constantly teases his sister, insults his mother, fights with everybody, and eats a lot.

Ichiro has a near-death experience when he is hit by a truck, and when he wakes up he can see and talk to spirits. The spirits of people who have just died but who cannot pass on yet seek him out. They have some unresolved issue in their lives that is holding them back, and Ichiro must help them out.', 'MADHOUSE', '2002', 'series', 'released', '2002-10-01', 2004, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2004-Udh8FHfvDgvU.jpg', 'Comedy, Drama, Slice of Life, Supernatural', 'TV', 'FALL', 25, 5176, 'https://www.youtube.com/watch?v=dnKssCH3ckc', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2102, 'The Prince of Tennis', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx22-yEguU9EmxkjK.png', 'series', '7.5', 'Echizen Ryoma is a young tennis prodigy who has won 4 consecutive tennis championships but who constantly lies in the shadow of his father, a former pro tennis player. He joins the Seishun Gakuen junior highschool, one of the best tennis schools in Japan, and there along with his teamates he learns to find his own type of tennis in an attempt to defeat his biggest obstacle of all: his father as well as himself.

(Source: Anime News Network)', 'Production I.G', '2001', 'series', 'released', '2001-10-10', 22, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/22-wVJjA9tGMt4k.jpg', 'Action, Comedy, Sports', 'TV', 'FALL', 178, 35787, 'https://www.youtube.com/watch?v=H0aHXo8q85g', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2103, 'Fruits Basket', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx120-Z5i1sw1xboQP.jpg', 'series', '7.5', 'Tohru Honda is 16 year old orphaned girl who gets invited to live in the house of her classmate, the handsome boy Sohma Yuki, and his cousins, 16 year old Kyo and 27 year old Shigure. However, these young men and parts of the rest of their family (both close and distant) hold a curse; if they are hugged by the opposite gender, they transform into animals of the Chinese Zodiac. Everyday is an adventure for sweet Tohru, as she gets to know everyone in the large family better (especially Yuki and Kyo), in both common and bizarre situations. But, the Sohma Family curse is certainly no laughing matter... it also holds horrible cruelty and heartbreak.', 'Studio DEEN', '2001', 'series', 'released', '2001-07-05', 120, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/120-PautbsS8uEAe.jpg', 'Comedy, Drama, Romance, Slice of Life, Supernatural', 'TV', 'SUMMER', 26, 98047, 'https://www.youtube.com/watch?v=DPEQxuMKGfE', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2104, 'Mujin Wakusei Survive', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx709-VbLR6kLmYRxv.jpg', 'series', '7.5', 'In the future, most of mankind lives in artificial space colonies, climate-controlled and completely safe. The orphan girl Luna, selected to receive a scholarship at the prestigious Soria Academy, finds herself in quite different circumstances. An excursion gone terribly awry leads to Luna and her classmates being stranded on an uninhabited planet. Without any experience of untamed nature, the motley crew is faced with a challenging struggle to stay alive until rescue comes. If it comes...

(Source: Anime News Network)', 'MADHOUSE', '2003', 'series', 'released', '2003-10-16', 709, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/709-yZhiELkWfzZQ.jpg', 'Action, Adventure, Fantasy, Sci-Fi, Slice of Life', 'TV', 'FALL', 52, 9610, 'https://www.youtube.com/watch?v=Aw8-IHYEgpw', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2105, 'Last Exile', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx97-Loi1Ppy4quXy.jpg', 'series', '7.4', 'It''s the dawn of the Golden Age of Aviation on planet Prester, and retro-futuristic sky vehicles known as vanships dominate the horizon. Claus Valca &ndash; a flyboy born with the right stuff &ndash; and his fiery navigator Lavie are fearless racers obsessed with becoming the first sky couriers to cross the Grand Stream in a vanship. But when the high-flying duo encounters a mysterious girl named Alvis, they are thrust into the middle of an endless battle between Anatoray and Disith &ndash; two countries systematically destroying each other according to the code of chivalric warfare. Lives will be lost and legacies determined as Claus and Lavie attempt to bring peace to their world by solving the riddle of its chaotic core.

(Source: Funimation)', 'GONZO', '2003', 'series', 'released', '2003-04-07', 97, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97-kaw3UsKX7IkQ.jpg', 'Action, Adventure, Sci-Fi', 'TV', 'SPRING', 26, 35209, 'https://www.youtube.com/watch?v=SQYDIG4g9ik', '2026-08-29 14:40:22', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2106, 'Wolf''s Rain', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx202-w2OLL3j8WmDm.jpg', 'series', '7.4', 'In some distant future, it''s common knowledge that all wolves have been extinct for 200 years. However, it seems this is false as wolves have not disappeared but rather have taken human form. Kiba, a lone wolf, wanders into a city, trying to sniff out the Lunar Flowers that are supposed to lead whoever follows the scent to paradise. The source of the smell is Cheza, a girl who sleeps in what appears to be suspended animation in a lab. She and the wolves are drawn to each other, and Kiba hopes to find paradise once he finds the source of the scent of Lunar Flowers. However, once Kiba finds Cheza, she is kidnapped by a mysterious person called Darcia, and his search begins anew. Before he leaves the city, he meets 3 other wolves, Tsume, Hige and Toboe. All four wolves have very different personalities and ideas, and their friendliness towards each other is a little rough around the edges. However, they soon band together to continue to search for paradise. 

(Source: Anime News Network)', 'bones', '2003', 'series', 'released', '2003-01-07', 202, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/202-3Ud0fKK0ithq.jpg', 'Action, Adventure, Drama, Fantasy, Mystery, Sci-Fi', 'TV', 'WINTER', 26, 60365, 'https://www.youtube.com/watch?v=iqFpI__mdTI', '2026-08-29 14:40:16', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2107, 'Sgt. Frog', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx516-ofBmeR4TcbKb.jpg', 'series', '7.4', 'Keroro is a frog-like alien sent from his home planet on a mission to conquer Earth. But when his cover is blown, his battalion abandons him and he ends up in the home of the Hinata family. There, he''s forced to do household chores and sleep in a dark basement that was once supposedly a prison cell haunted by the ghost of an innocent girl. He even spends his free time assembling Gundam model kits. During his stay, Keroro meets up with subordinates who were also stranded during their failed invasion. 

(Source: Anime News Network)', 'Sunrise', '2004', 'series', 'released', '2004-04-03', 516, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/516-kgoFaO4d13bt.jpg', 'Comedy, Sci-Fi', 'TV', 'SPRING', 358, 17239, 'https://www.youtube.com/watch?v=rsP2V0xrXKg', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2108, 'InuYasha the Movie 2: The Castle Beyond the Looking Glass', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx450-7uVVkg9N3uMF.png', 'movies', '7.4', 'Inuyasha and company have finally destroyed Naraku. And each start to go in their separate ways. Sango going to find her younger brother Kohaku; Miroku back to his old home; Inuyasha, Kagome and Shippou go to gather the rest of the Shikon shards. Unfortunately this peace is not to last. Shortly afterwards the full moon rises, and just keeps rising each night bringing with it the promise of danger. Kagura and Kanna go in search of a mirror, where locked inside is the ruler of the eternal night, Kaguya. To set her free they must gather five items and drop them into the five lakes of Fuji. Setting her free means the worst danger for Inuyasha and the others. Who are forced to face this new threat.

(Source: Anime News Network)', 'Sunrise', '2002', 'movie', 'released', '2002-12-21', 450, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Drama, Fantasy, Romance', 'MOVIE', 'FALL', 1, 17999, 'https://www.youtube.com/watch?v=u_iiFP0-tEc', '2026-08-29 14:40:13', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2109, 'Detective School Q', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx407-W9afaUJfEsoR.png', 'series', '7.4', 'Kyuu is your average boy with a knack for logic and reasoning. Desiring to become a detective, he finds out about the existence of the Dan Detective School (DDS); a famed school where students are allowed to bear arms. Together with Megu, a girl with photographic memory, the martial arts master Kinta, the genius programmer Kazuma and the mysterious Ryuu, Kyuu tackles many well planned out crimes, always seeking the truth.', 'Studio Pierrot', '2003', 'series', 'released', '2003-04-15', 407, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/407-OfInblist1dh.jpg', 'Comedy, Drama, Mystery', 'TV', 'SPRING', 45, 7475, 'https://www.youtube.com/watch?v=4S_o9Zu4kH8', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2110, 'Crayon Shin-chan: Arashi wo Yobu Appare! Sengoku Daikassen', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/3744.jpg', 'movies', '7.4', 'Shin-chan and his family travel to Samurai''s Era by accident and try to save the Princess'' city by helping in the war.', 'Shin-Ei Animation', '2002', 'movie', 'released', '2002-04-20', 3744, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Comedy', 'MOVIE', 'SPRING', 1, 2437, 'https://www.youtube.com/watch?v=aclXKoZ3B9E', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2111, 'Genshiken', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx240-YaEXxztQRFix.jpg', 'series', '7.4', 'Sasahara Kanji is a college freshman who decides to join a student society to share his hidden thoughts on manga, anime and gaming.

When he first visited Genshiken, short for "Gendai Shikaku Bunka Kenkyuu Kai" (Society for the Study of Modern Visual Culture), his groundless pride was destroyed by the plotting of Madarame, a sophomore student in Genshiken, but he still couldn''t admit that he is an otaku.

However, as he participates in society activities such as visiting dojin (private publishing) shops and anime festivals, and hangs out with other society members Kosaka (a hardcore otaku despite his extreme eccentricities and good looks), Kosaka''s girlfriend Kasuga Saki (who isn''t really an otaku), Ohno (a cosplayer) and the others, he opens his mind and resolves that he will make his way into the otaku world. With their help, Sasahara slowly adjusts to otaku life in Genshiken.

(Source: AnimeNfo)', 'Palm Studio', '2004', 'series', 'released', '2004-10-10', 240, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/240-FbZV9cTu6ixW.jpg', 'Comedy, Slice of Life', 'TV', 'FALL', 12, 41050, 'https://www.youtube.com/watch?v=L26YR6N0vqQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2112, 'Gunslinger Girl', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx134-f3dmmMOijYdn.png', 'series', '7.1', 'Officially, the Social Welfare Agency is a government sponsored corporation that''s in the business of saving lives. In reality, it''s an agency on the fringe of technology. They give terminal patients another shot at life using cybernetic implants. This conditioning process then shapes the patient into an efficient machine for handling all of the government''s dirty work.

(Source: Funimation)', 'MADHOUSE', '2003', 'series', 'released', '2003-10-08', 134, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/134-tg9PX9ry53fz.jpg', 'Action, Drama, Psychological, Sci-Fi', 'TV', 'FALL', 13, 43020, 'https://www.youtube.com/watch?v=CejBW6wNtME', '2026-08-29 14:40:10', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2113, 'Gunbuster 2: Diebuster', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx1002-W7vQj8WSzAxf.jpg', 'series', '7.4', 'While Gunbuster''s final mission destroyed the space monsters'' star system, the intergalactic war still continues. Earth''s only hope lies in the hands of "TOPLESS", an elite mecha group with children possessing supernatural powers and new Buster Machines. Among their ranks is a rookie named Nono and the ace pilot Lal''C - whom Nono looks at as a "big sister". Together with their teammates Nicholas and Chiko they must aim for the top and protect all of mankind from the wrath of the space monsters. 

(Source: Anime News Network)', 'Gainax', '2004', 'series', 'released', '2004-10-03', 1002, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1002-hya3XcLe14eS.jpg', 'Action, Comedy, Mecha, Sci-Fi', 'OVA', 'FALL', 6, 25801, 'https://www.youtube.com/watch?v=KK0p822kPDo', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2114, 'Ashita no Nadja', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1946-MLn2pjGSGhHJ.png', 'series', '7.4', 'This story takes place about one hundred years ago. Nadja is a bright, cheerful girl who was raised in an orphanage near London, England. Nadja was entrusted to the orphanage when she was a baby. So she thought her father and mother were dead. But before her thirteenth birthday, she found out that her mother might be alive.

Nadja sets out on a journey to find her mother! With all of Europe as the stage, Nadja''s exciting adventure begins!', 'Toei Animation', '2003', 'series', 'released', '2003-02-02', 1946, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1946-uwfg4bMXy33Y.jpg', 'Adventure, Drama, Romance', 'TV', 'WINTER', 50, 10793, 'https://www.youtube.com/watch?v=QKzioWeSmmo', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2115, 'Haré+Guu Deluxe', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/254.jpg', 'series', '7.4', 'After the events in the city, Har&eacute; and family come back to the Jungle. But it is never calm for Har&eacute; as he first must deal with an unstable substitute teacher, then with some big news: Weda is pregnant. The answer to how and who will change his family forever. Poor Har&eacute;, now has to deal with a father in addition to his drunk mother and Guu, and soon a sibling too.

(Source: Anime News Network)', 'Shin-Ei Animation', '2002', 'series', 'released', '2002-08-25', 254, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Comedy', 'OVA', 'SUMMER', 6, 2505, 'https://www.youtube.com/watch?v=pYyBKXzgagQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2116, 'Shaman King', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx154-hSYv4EtcBE1p.png', 'series', '7.4', 'Shamans possess mysterious powers that allow them to commune with gods, spirits, and even the dead…and Manta Oyamada''s about to learn all about them, because his class just welcomed a new transfer student: Yoh Asakura, a boy from way off in Izumo…and a shaman in training!

(Source: Kodansha USA)', 'Xebec', '2001', 'series', 'released', '2001-07-04', 154, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/154-3rztL7uTSDqM.jpg', 'Action, Adventure, Comedy, Drama, Supernatural', 'TV', 'SUMMER', 64, 59489, 'https://www.youtube.com/watch?v=rV8RZrZskdk', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2117, 'Metropolis', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx522-4Sp8QlrufkG5.jpg', 'movies', '7.4', 'In the great city of Metropolis, severe community structures and prejudice dominate a world where humans and robots live together. Unrest and violence increase with each new day.

Searching for the scientist Dr. Laughton, suspected to violate human rights by trading organs, the Japanese detective Shunsaku Ban and his nephew Kenichi arrive at Metropolis. In the scientist''s laboratory, Kenichi discovers a girl without any memory of her past life. He decides to help her, so they run away together. His uncle follows him and penetrates the dark secrets of the city to find Duke Red, the man ruling from the shadows. Meanwhile, Kenichi desperately tries to protect the mysterious girl from the people hunting her. However, Duke Red and his adoptive son have their own deep reasons for chasing the girl. These reasons are connected to her true identity and the struggle for the domination of Metropolis...

[Written by MAL Rewrite]', 'MADHOUSE', '2001', 'movie', 'released', '2001-05-26', 522, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/522-I1641XiLfZ2v.jpg', 'Adventure, Drama, Romance, Sci-Fi', 'MOVIE', 'SPRING', 1, 34068, 'https://www.youtube.com/watch?v=lj9ruL8B310', '2026-08-29 14:40:06', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2118, 'Gakuen Alice', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b74-QZI9kO7eesrb.jpg', 'series', '7.4', 'Sakura Mikan and Imai Hotaru are best friends, and Mikan is shocked to find that Hotaru is transferring to a school in Tokyo for gifted students like her - Alice Academy. Mikan hears rumors that the students are like prisoners there, and worried what would happen to Hotaru, she runs away to head to the school herself. She finds out all the wonderful things about this school. And she heads into a great adventure!!', 'Group TAC', '2004', 'series', 'released', '2004-10-30', 74, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/74-ICuJYGEfSvPR.jpg', 'Comedy, Drama, Fantasy, Supernatural', 'TV', 'FALL', 26, 18135, 'https://www.youtube.com/watch?v=VoRdYFVQcL0', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2119, 'Haré+Guu', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/253.jpg', 'series', '7.3', 'Har&eacute; was a happy boy living out his days in the jungle with his mother, but then one day Guu showed up and became a member of their household. Throughout the series he faces many hardships as he tries to keep Guu out of trouble in the jungle.

(Source: Anime News Network)', 'Shin-Ei Animation', '2001', 'series', 'released', '2001-04-03', 253, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Comedy', 'TV', 'SPRING', 26, 8793, 'https://www.youtube.com/watch?v=V-AiGlgHUk8', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2120, 'Maria Watches Over Us: Printemps', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx444-wfacv45uwRN3.jpg', 'series', '7.3', 'The second season of Maria-sama ga Miteru.

The spring term is beginning for the students at Lillian Girls'' Academy. Friends are reunited, but for the Yamayuri Council, it''s a bittersweet time. Yoko, Eriko, and Sei are busy preparing to depart Lillian while Sachiko, Rei, and Shimako are doing their best to ensure that their dear sisters receive a memorable commencement.

Sei''s departure will leave a sizable hole in the White Roses, and filling it won''t be easy. But is there anyone who could appeal to Shimako enough to become the next Rosa Gigantea en bouton?

(Source: RightStuf)', 'Studio DEEN', '2004', 'series', 'released', '2004-07-04', 444, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n444-GkJJwQ2iTvbF.jpg', 'Drama, Romance', 'TV', 'SUMMER', 13, 6560, 'https://www.youtube.com/watch?v=vxxO7UnLUzQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2121, 'New Getter Robo', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2978-wybJCsj1WaIh.jpg', 'series', '7.3', 'Humanity is under attack by demonic creatures called Oni. Unable to fight back by any other means, the scientist Dr. Saotome creates a series of giant robots that harness the mysterious power of Getter Rays, giving them the strength necessary to fight the Oni. The strongest of these is Getter Robo, and Saotome must enlist three very different men to pilot it - martial artist Ryoma Nagare, criminal leader Hayato Jin, and monk Benkei Musashibou. Together, the Getter Team fights to end the Oni menace forever.

(Source: Anime News Network)', 'Brain''s Base', '2004', 'series', 'released', '2004-04-09', 2978, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Horror, Mecha, Sci-Fi', 'OVA', 'SPRING', 13, 4697, 'https://www.youtube.com/watch?v=u-9NK7wUIRE', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2122, 'The Big O II', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx129608-fKarGt6WZ9Mb.jpg', 'series', '7.3', 'Continuation of The Big O.

Notes:
 
- Originally planned as a 26-episode series, low viewership in Japan reduced production to the first 13.

- Positive international reception resulted in a second season consisting of the remaining 13 episodes; co-produced by Cartoon Network, Sunrise, and Bandai Visual.', 'Sunrise', '2003', 'series', 'released', '2003-01-02', 129608, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/129608-cwFOM9wIFjNr.jpg', 'Action, Mecha, Mystery, Psychological, Sci-Fi', 'TV', 'WINTER', 13, 4471, 'https://www.youtube.com/watch?v=GOzphFKZAFk', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2123, 'InuYasha the Movie 4: Fire on the Mystic Island', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx449-B9HGKZFh0wUC.jpg', 'movies', '7.3', 'The mysterious island of Houraijima has reappeared after 50 years, and with its reappearance has brought the attack of four gods, the Shitoushin, who have their eyes set on the powers that protect and sustain the island. Now it''s up to Inuyasha and his friends, along with Sesshoumaru, to find a way to defeat the powerful Shitoushin.

(Source: Anime News Network)', 'Sunrise', '2004', 'movie', 'released', '2004-12-23', 449, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Drama, Fantasy, Romance', 'MOVIE', 'FALL', 1, 16362, 'https://www.youtube.com/watch?v=u_iiFP0-tEc', '2026-08-29 14:40:28', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2124, 'Black Jack (TV)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2213-wemXPc8z0r6a.jpg', 'series', '7.3', 'Black Jack is an "unregistered" doctor with a clouded, mysterious past. He works with his little assistant Pinoko (who has a massive crush on the doctor), dealing with medical cases not very well known, which can be strange, dangerous, or not known at all. But he is a genius, and can save almost any of his patients'' life (as long as they have the money for it, that is), and is known to many around the world, especially to those of medicine and science. He''s a man of science himself, and does not believe much until he has seen it, yet it is many times he is surprised by love and nature often overpowering the science he bases his life in.  

(Source: Anime News Network)', 'Tezuka Productions', '2004', 'series', 'released', '2004-10-11', 2213, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n2213-gsOGinazFbAh.jpg', 'Drama', 'TV', 'FALL', 61, 8315, 'https://www.youtube.com/watch?v=HUmf8mdW2z0', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2125, 'Initial D BATTLE STAGE', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/821.jpg', 'series', '7.3', 'There are many street races in the Initial D Series. This OAV has no plot other than to collect all the street races into one stage. The dialog during the original races is left in.', 'OB Planning', '2002', 'series', 'released', '2002-05-15', 821, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Action, Sports', 'OVA', 'SPRING', 1, 10160, 'https://www.youtube.com/watch?v=jb9fhv_yoX4', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2126, 'Tetsujin 28', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b2337-5bWtfDud2VHi.png', 'series', '7.3', 'In post-WWII Japan, Prof. Shikishima has built up Shikishima Industries to be a technological powerhouse, working on developing robots. However, at the heart of their success lurks a dark secret from the war, something that cost the life of Prof. Kaneda, the mentor of Prof. Shikishima. Now Kaneda''s son, Shoutarou, is about to learn the truth, and it will change him forever.

(Source: Anime News Network)', 'Palm Studio', '2004', 'series', 'released', '2004-04-08', 2337, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Adventure, Mecha, Sci-Fi', 'TV', 'SPRING', 26, 3647, 'https://www.youtube.com/watch?v=dm5EkZjjSDo', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2127, 'InuYasha the Movie: Affections Touching Across Time', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx452-8Gc0rCcsXwLj.png', 'movies', '7.3', '200 years ago, InuYasha''s father sealed away a powerful demon from China named Hyoga... A Shikon Jewel shard awakens Hyoga''s son, Menomaru, inspiring him to absorb the remains of his father''s power to take control of the world! It''s now up to InuYasha and his friends to stop this nearly invincible foe!

(Source: VIZ Media)', 'Sunrise', '2001', 'movie', 'released', '2001-12-22', 452, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Comedy, Drama, Fantasy, Romance', 'MOVIE', 'FALL', 1, 18649, 'https://www.youtube.com/watch?v=u_iiFP0-tEc', '2026-08-29 14:40:30', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2128, 'Fantastic Children', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx455-3w3RYYgHUuDm.png', 'series', '7.3', 'A group of enigmatic white-haired children has been spotted at different times and places in Europe for over 500 years. Always with the appearance of 11-year-olds, they behave far more mature than they should be, never grow old, and seem to have supernatural power. What they have been seeking is a girl, and the only clue they have is a picture with a crescent moon. Now, in the year of 2012, an athletic boy named Tohma is about to be involved in this centuries-long mystery.

(Source: Anime News Network)', 'Nippon Animation', '2004', 'series', 'released', '2004-10-05', 455, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/455-WjU2gqCFaYNA.jpg', 'Adventure, Drama, Fantasy, Mystery, Romance, Sci-Fi', 'TV', 'FALL', 26, 9955, 'https://www.youtube.com/watch?v=z5kZ4Q6b0vs', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2129, 'Zatch Bell!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b250-w0c2KefXfW2i.png', 'series', '7.3', 'Takamine Kiyomaro, a depressed don''t-care-about-the-world guy, was suddenly given a little demon named Gash Bell to take care of. Little does he know that Gash is embroiled into an intense fight to see who is the ruler of the demon world. All of the demons have to pick a master on Earth and duke it out with other demons until one survives. Needless to say, Kiyomaro becomes Gash''s master, and through their many battles, Kiyomaro learns the importance of friendship and courage.', 'Toei Animation', '2003', 'series', 'released', '2003-04-06', 250, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/250-JpXhinXPqpNE.jpg', 'Adventure, Comedy, Supernatural', 'TV', 'SPRING', 150, 28182, 'https://www.youtube.com/watch?v=RtpQ_05RsjY', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2130, 'Baki the Grappler', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx287-goNFQRZPze2g.jpg', 'series', '7.2', 'Baki Hanma is a young fighter who yearns to follow in the footsteps of his father, Yujiro, and become the strongest fighter in the world. Through that he trains tirelessly and fights constantly to hone his skills and develop his body to achieve these goals. Many intense battles lay ahead of Baki as he goes about his quest to be the best and ultimately take the title of "King" from his father.', 'Group TAC', '2001', 'series', 'released', '2001-01-09', 287, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/287-iCmAPCmck31R.jpg', 'Action, Sports', 'TV', 'WINTER', 24, 38493, 'https://www.youtube.com/watch?v=xniBk7zAKMY', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2131, 'Mobile Suit Gundam Seed', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx93-pp8SI0zpA8EJ.jpg', 'series', '7.2', 'C.E. 71: In the midst of war between the Naturals (OMNI) and Coordinators (ZAFT), a unit from ZAFT is dispatched to hijack the Earth Alliance''s newly developed mobile suits on the neutral colony of Heliopolis. Orb Civilian Coordinator Kira Yamato attends the technical college on Heliopolis. After ZAFT hijacks 4 of the 5 mobile suits, Kira stumbles upon the last one, Strike, forced to pilot it to save his and his friend''s lives. During this confusion, Kira also reunites with his childhood Coordinator friend, Athrun Zala, who ironically turns out to be a ZAFT soldier and one of the hijackers at Heliopolis. Having control of Strike, Kira joins the Earth Alliance boarding the ship known as Archangel, to protect his friends while despairing over becoming the enemy of his childhood friend and people.

Note: An HD remaster was broadcasting starting on December 23, 2011 with two recap episodes cut, including new and updated animation, conversion to 16:9, and updated music.', 'Sunrise', '2002', 'series', 'released', '2002-10-05', 93, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/93-KZlqRAri1Os5.jpg', 'Action, Drama, Mecha, Sci-Fi', 'TV', 'FALL', 50, 31423, 'https://www.youtube.com/watch?v=Gsj6ToFTGgc', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2132, 'Grappler Baki Maximum Tournament', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/551.jpg', 'series', '7.2', 'Baki, a great grappler needs to live up to his name being the son of the the greatest grapplers of all time: Hanma Yujiro. At the Shinshinkai Organization''s private arena, anything goes and the odds are always stacked against you. Current champion of the urderground tournament he fight to defend his title against the worlds strongest and best martial artists, including "the beast" his own father Yujiro.

(Source: Anime News Network)', NULL, '2001', 'series', 'released', '2001-07-24', 551, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Action, Sports', 'TV', 'SUMMER', 24, 22920, 'https://www.youtube.com/watch?v=ekTgTfzWoyo', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2133, 'Full Metal Panic!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx71-Fi08vs7xNBMW.png', 'series', '7.2', 'Sousuke Sagara, a seventeen year old military specialist working for the secret organization MITHRIL, has been assigned to protect the latest "Whispered" candidate Kaname Chidori. To complete this task Sousuke will have to deal with enemies from his past as well as the occasional panty thief. Unfortunately for Sousuke, the toughest part of his mission isn''t only protecting Miss Chidori but also getting used to living an average High School students life, no easy task for someone raised on the battlefield.

(Source: Anime News Network)', 'GONZO', '2002', 'series', 'released', '2002-01-08', 71, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/71-vSM3St7ZNwju.png', 'Action, Comedy, Mecha, Sci-Fi', 'TV', 'WINTER', 24, 95310, 'https://www.youtube.com/watch?v=6GzFzmONrTE', '2026-08-29 14:40:25', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2134, 'Jungle wa Itsumo Hare nochi Guu FINAL', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/255.jpg', 'series', '7.2', 'Har&eacute;''s family receives a video letter from Weda''s home in the city. Witnessing how sad and lonely Weda''s mother and Bel are without her, Weda decides to take Har&eacute; and Guu back to the city for a while. After Har&eacute; complains about being bored and lonely without his friends in the jungle (as part of his plot to persuade his mother to take him back), Weda decides to send him to a private school in the city, where he instanly falls in love with a pretty girl named Rita. But, of course, Guu wants part of the action too.

(Source: Anime News Network)', 'Shin-Ei Animation', '2003', 'series', 'released', '2003-12-21', 255, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', NULL, 'Comedy', 'OVA', 'WINTER', 7, 2004, 'https://www.youtube.com/watch?v=3_06C6fjgfA', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2135, 'Michi', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx7616-pex9BSx9aD9I.jpg', 'series', '7.2', 'The My Road series - Scarlet Road (2002), White Road (2003), Indigo Road (2006), and the most recent instalment Lemon Road (2008) - can be read as meditations on loss and mourning. These poetic films tell their story through motif, character expression, music and montage and require repeated viewing for one to absorb the subtly evoked layers of meaning.


(Source: Midnight Eye)', NULL, '2002', 'series', 'released', '2002-01-01', 7616, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/7616-ArMjWmucCrjo.jpg', 'Drama', 'OVA', NULL, 4, 1507, 'https://www.youtube.com/watch?v=RJCiRrd-lXE', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2136, 'Windy Tales', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1524-ewkmUaqAzVQ2.png', 'series', '7.2', 'Nao, an 8th grader, is one of the only two members of a Digital Camera Club, where she also serves as the manager. It''s a mystery that she shoots nothing else but the skies and clouds. One day, she finds a cat on a rooftop where she usually shoots her camera. It''s a cat that knows how to manipulate the flow of a wind. Shocked to find a strange animal, Nao loses her footing and falls off from the rooftop!

Miki is the other member of the club, and also Nao''s best friend. Taiki is the teacher who taught the cat how to manipulate the flow of a wind. Ryoko is a girl who has a huge crush on Taiki. And there''s Jun, who helps Nao and Miki look for a cat that can fly. Then, there''s Yukio, who is the widow of Taiki''s deceased brother.

On the outskirts of this big city, a town off the "Wind Handlers," has been formed - and a mysterious Wind Festival is about to begin...

(Source: Production I.G)', 'Production I.G', '2004', 'series', 'released', '2004-09-11', 1524, 0, NULL, '2026-07-25 18:55:41', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1524-JHVU1QpKL0xr.jpg', 'Drama, Fantasy, Slice of Life, Supernatural', 'TV', 'FALL', 13, 10316, 'https://www.youtube.com/watch?v=vAIpxcDmwUk', '2026-08-29 14:40:02', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2137, 'Mermaid Melody: Pichi Pichi Pitch Pure', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1110-hW9GxIpSC9Te.png', 'series', '7.2', 'After the final battle against Gaito, Sara had given her life to remain with him. The sea world is now at peace, but only with six mermaid princesses.

While Caren, Noel, and Coco have returned to their kingdoms, it should be time for Lucia, Hanon, and Rina to do the same. After all, Mitsuki Tarou is leaving for Germany, and Doumoto Kaito is heading to Hawaii. Lucia is devestated, and when things couldn''t get any worse, Kaito is lost at sea! Worst of all, a strange angel named Michel has appeared, wanting the mermaids to join him. But on the lighter side, Sara''s spirit tells Lucia of Sara''s successor, a young mermaid named Seira. The mermaids are in for another adventure!', 'Actas', '2004', 'series', 'released', '2004-04-05', 1110, 0, NULL, '2026-07-25 18:55:43', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1110-6rJhdF6HwXv9.jpg', 'Adventure, Comedy, Fantasy, Mahou Shoujo, Music, Romance', 'TV', 'SPRING', 39, 10211, 'https://www.youtube.com/watch?v=fWa6UZ7iCdQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2138, 'Hellsing', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b270-S2ProngvO6BU.jpg', 'series', '7.2', 'Hellsing follows the antiheroic vampire, Alucard, and a police girl-turned-vampire, Seras Victoria, two vampires employed by the vampire-extermination group of England, the Hellsing Organization. Slowly but surely, through their active duty, they find a new breed of vampires beginning to arise.

(Source: Anime News Network)', 'GONZO', '2001', 'series', 'released', '2001-10-11', 270, 0, NULL, '2026-07-25 18:55:43', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/270-wzSdgMsCRvtl.jpg', 'Action, Horror, Supernatural', 'TV', 'FALL', 13, 142480, 'https://www.youtube.com/watch?v=6fKWGqIqylo', '2026-08-29 14:54:56', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2139, 'There She Is!!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/6505.jpg', 'series', '7.2', 'The plot revolves around Doki, a female rabbit, meeting, falling in love with, and chasing Nabi, a male cat, in a world where love between the two species is socially unacceptable. The theme of the short is that all love can be accepted and has a chance. Nabi attempts to cure Doki''s infatuation for him, but after seeing the extent of her love, he gives in and finds something he can appreciate in her.

(Source: Wikipedia)', NULL, '2003', 'series', 'released', '2003-04-20', 6505, 0, NULL, '2026-07-25 18:55:43', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/6505-pIGdhVqkXZhs.jpg', 'Comedy, Romance', 'ONA', NULL, 5, 5727, 'https://www.youtube.com/watch?v=maiEiPOvjeA', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2140, 'Mazinkaiser', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1064-LZyEvupm6y8G.jpg', 'series', '7.2', 'In one of their epic battles, the Mazinger Team suffers a crushing defeat at the hands of Dr. Hell and his minions after Mazinger Z is stolen and its pilot, the legendary Kouji Kabuto, is rendered missing in action. Just when Dr. Hell''s second-in-command Baron Ashura uses Mazinger Z against our heroes, Kouji makes a surprise return in Mazinkaiser - an all-new Mazinger with heavier armor and deadlier attacks.

(Source: Anime News Network)', 'Brain''s Base', '2001', 'series', 'released', '2001-09-25', 1064, 0, NULL, '2026-07-25 18:55:43', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n1064-GhOiVOj8rOoJ.jpg', 'Action, Mecha, Sci-Fi', 'OVA', 'FALL', 7, 4715, 'https://www.youtube.com/watch?v=3X-oi71OQNI', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2141, 'Bobobo-bo Bo-bobo', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1050-qQAPEPu1kNKP.jpg', 'series', '7.2', 'Bo Bobo is a man with the incredible power of hearing the voices of hair and using his own to fight. He uses his power to fight off the Margarita Empire and all of Emperor Tsuru Tsuruiina''s minions who are stealing the hair off of anyone they find to power up their emperor. 

(Source: Anime News Network)', 'Toei Animation', '2003', 'series', 'released', '2003-11-08', 1050, 0, NULL, '2026-07-25 18:55:43', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1050.jpg', 'Adventure, Comedy, Sci-Fi', 'TV', 'FALL', 76, 21107, 'https://www.youtube.com/watch?v=T_xQcOcqhNQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2142, 'Zipang', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx29-0PsnJVadMG7k.jpg', 'series', '7.2', 'Mirai, an improved Kongou-class Aegis guided missile destroyer, is one of the newest and most advanced ships in the entire Japanese Self Defense Force (SDF). Her crew, also one of the newest, is lead by Capt. Umezu Saburo and Executive Officer Kadomatsu Yosuke. While running scheduled training exercises one day, Mirai encounters a fierce storm that throws their navigation systems into temporary disarray. After a few minutes of recovery, the crew is shocked to discover that they''ve been transported back in time to June 4, 1942&mdash;The Battle of Midway, during World War II. Letting history take its course for this battle, they manage to avoid the conflict firsthand and make a vow to remain annonymous, changing history as little as possible. However, when the crew comes across the dying Lt. Commander Kusaka Takumi, XO. Kadomatsu''s instincts to save lives takes over, changing the course of history more than he could''ve imagined.

(Source: Anime News Network)', 'Studio DEEN', '2004', 'series', 'released', '2004-10-07', 29, 0, NULL, '2026-07-25 18:55:43', '2026-09-02 16:57:33', NULL, 'Action, Sci-Fi', 'TV', 'FALL', 26, 6499, 'https://www.youtube.com/watch?v=isiV3tYW3IM', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2143, 'Hungry Heart: Wild Striker', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx17-6kqIbdUk3dgi.png', 'series', '7.2', 'Kyosuke Kano has lived under the shadow of his successful brother Seisuke all his life who is a professional soccer player. Tired of being compared and downgraded at, he abandoned playing soccer until a boy from his new highschool discovered him and asked him to join their team. Kyosuke joins it and befriends two other first year players named Rodrigo and Sakai with the dream of becomming professional soccer players themselves.

(Source: Anime News Network)', 'Nippon Animation', '2002', 'series', 'released', '2002-09-11', 17, 0, NULL, '2026-07-25 18:55:43', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/17-2drlTPxc3WTh.png', 'Comedy, Slice of Life, Sports', 'TV', 'FALL', 52, 4837, 'https://www.youtube.com/watch?v=AHQZwB_w8VU', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2144, 'The Gokusen', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b242-gR6cc2RIa7BJ.png', 'series', '7.2', 'Kumiko "Yankumi" Yamaguchi enters Shirokin High School to become a math teacher. She''s assigned as the homeroom teacher for class 2-4, populated by a gang of delinquents.  At first, the class tries everything to rattle her cage, but to no avail. In a short period of time, Yankumi gains the respect of the class. But what the school doesn''t know is that she''s the heir to the Oedo Group, a powerful yakuzan clan. So while Yankumi struggles to excel in her career as a teacher, she must also keep her yakuza background a secret.

(Source: Media Blasters)', 'MADHOUSE', '2004', 'series', 'released', '2004-01-06', 242, 0, NULL, '2026-07-25 18:55:43', '2026-09-02 16:57:33', NULL, 'Comedy, Drama, Slice of Life', 'TV', 'WINTER', 13, 11514, 'https://www.youtube.com/watch?v=lzrEYgFqv-I', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2145, 'Mermaid Melody: Pichi Pichi Pitch', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx521-UDVg2syjOAwz.jpg', 'series', '7.1', 'As the mermaid princess of the North Pacific (one of the seven mermaid kingdoms), Lucia entrusts a magical pearl to a boy who falls overboard a ship one night. Lucia must travel to the human world to reclaim her pearl and protect the mermaid kingdoms. Using the power of music Lucia is able to protect herself and the mermaid kingdoms from a growing evil force.', 'SynergySP', '2003', 'series', 'released', '2003-04-05', 521, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/521-F4oMuJO8xTBO.jpg', 'Adventure, Comedy, Fantasy, Mahou Shoujo, Music, Romance', 'TV', 'SPRING', 52, 18853, 'https://www.youtube.com/watch?v=NPhKKH9pnSc', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2146, 'You''re Under Arrest: Fast & Furious', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/2014.jpg', 'series', '7.1', 'Aa! Megami-sama creator, Kosuke Fujishima, is back with the second season of Taiho Shichauzo (You''re Under Arrest). Same characters, two policewomen, the gentle Miyuki and the wild Natsumi teamed up together in Bokuto police station`s traffic division.

Other characters including Kenichi, the motorcycle cop who has a feeling for Miyuki; Yoriko with her gossip and Aoi, a transvestite. They all ready to take on harmless criminals and costumed weirdos... You think you can have a better police station?

(Source: AniDB)', 'Studio DEEN', '2001', 'series', 'released', '2001-04-07', 2014, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', NULL, 'Action, Comedy', 'TV', 'SPRING', 26, 3222, 'https://www.youtube.com/watch?v=86G1cGR616k', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2147, 'Magical Girl Lyrical Nanoha', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx76-wRwZobrx9MPj.jpg', 'series', '7.1', '3rd grader Takamachi Nanoha stumbled upon an injured talking ferret after hearing his telepathic cries for help. The ferret turned out to be Yuuno, an archeologist and mage from another world who had accidentally scattered the dangerous Jewel Seeds throughout Earth. Without the strength to collect the Jewel Seeds, Yuuno had resumed a ferret form and needed someone else to take on the task for him. He gave a red jewel to Nanoha explaining to her with this she could transform and use magic to combat the monsters that threatened them due to the Jewel Seeds. But the monsters are the least of their worries, as Yuuno and Nanoha are not the only ones out to collect the Jewel Seeds.', 'Seven Arcs', '2004', 'series', 'released', '2004-10-03', 76, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n76-3QGPwccscSaE.jpg', 'Action, Comedy, Drama, Fantasy, Mahou Shoujo, Sci-Fi', 'TV', 'FALL', 13, 28851, 'https://www.youtube.com/watch?v=npAfCvmmPHM', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2148, 'Love You Baby', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx102-nacpPTHmjvXJ.png', 'series', '7.1', 'Katakura Kippei is in every way a high school playboy. Spending his days flirting with any female he can see, responsibility is the last thing on his mind. Life takes an unexpected turn for him as one day he returns home to find himself with the fulltime task of caring for his 5 year old cousin. Kippei''s aunt Miyako had disappeared, appearing to have abandoned his cousin, Yuzuyu. With Kippei''s lack of responsibility and knowledge of childcare and Yuzuyu''s injured heart with the disappearance of her mother, their time together is in for a bumpy ride. Based on the manga by Maki Youko.', 'TMS Entertainment', '2004', 'series', 'released', '2004-04-03', 102, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/102-hPGDYNMJ0LIi.jpg', 'Comedy, Drama, Romance', 'TV', 'SPRING', 26, 14805, 'https://www.youtube.com/watch?v=4d8giOI2ZDI', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2149, 'Captain Tsubasa', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b2116-ajWg3wcwvb2q.jpg', 'series', '7.0', 'Tsubasa Ozora moves to the town Nankatsu to increase his skills as a soccer player. He is challenged by the Super Goalkeeper Genzo Wakabayashi. He then agree to compete and see who was the best soccer player there.

(Source: Anime News Network)', 'Tsuchida Productions', '1983', 'series', 'released', '1983-10-13', 2116, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2116-DccGEDGnsqcu.jpg', 'Action, Sports', 'TV', 'FALL', 128, 17723, 'https://www.youtube.com/watch?v=Km71i8CG6QA', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2150, 'Patapata Hikousen no Bouken', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/708.jpg', 'series', '7.1', 'Jane''s mother dies when she is born, and her father, a rich English aristocrat, soon remarries to a woman with a son, William, who despises his new father and brother. George and Jane grow up with a dream to make a flying machine. George believes the distant Asian sands hold a secret: a mysterious cerulean sand which can make machines fly. He goes on an expedition to find it, and soon is reported executed for treason. William disappears too. After she recieves an unsigned letter holding a handful of pale-blue sand which floats in the air, Jane is sure her brother is alive and leaves to the East to find him and prove him innocent. There are many mysteries to unravel in store for Jane and her new friends on her journey. But perhaps a mystery should forever remain a mystery... 

(Source: Anime News Network)', 'Telecom Animation Film', '2002', 'series', 'released', '2002-01-05', 708, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', NULL, 'Adventure, Sci-Fi', 'TV', 'WINTER', 26, 2836, 'https://www.youtube.com/watch?v=f5rVBYUcvzo', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2151, 'GetBackers', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx132-DBhi3KQASjLU.png', 'series', '7.1', 'Ban Mido and Ginji Amano run a freelance business of recovering anything lost or stolen from a client—and they claim a 100% success rate. They call themselves the GetBackers, and they''re a super powered duo whose job lands them in dangerous predicaments. Although they have many adventures on their recovery quests, each has a mysterious past that rears its ugly head at the most inoportune moments. It''s wild and crazy and one awesome anime ride!

(Source: Sentai Filmworks)', 'Studio DEEN', '2002', 'series', 'released', '2002-10-05', 132, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/132-C7Ms6vrtWfu4.jpg', 'Action, Comedy, Drama, Mystery', 'TV', 'FALL', 49, 20173, 'https://www.youtube.com/watch?v=Och-uZvtJ0A', '2026-08-29 14:41:21', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2152, 'Super GALS', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1728-yPtJchXDmoie.png', 'series', '7.1', 'Sporting designer clothes, make-up, and nails, Ran Kotobuki is the very picture of a trendy, young Shibuya girl, but don''t let that fool you. This girl comes from a family of cops, and she&rsquo;s ready to lay you out flat if you even think about causing trouble in her town! At least, she will... when she&rsquo;s not distracted with karaoke, shopping, and dodging her homework. Join Ran and her friends as they defend the streets of Shibuya and attempt to shop their way into the history books as the most famous Gals ever!

(Source: RightStuf)', 'Studio Pierrot', '2001', 'series', 'released', '2001-04-01', 1728, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1728-eoyFGr7VhXXo.jpg', 'Comedy, Slice of Life', 'TV', 'SPRING', 52, 7581, 'https://www.youtube.com/watch?v=Bq_9sV8ni3E', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2153, 'Chrono Crusade', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx60-nWs0N9upSorj.png', 'series', '7.1', 'The year is 1928 A.D. The place is New York, U.S.A. The economic prosperity brought forth after the Great War also heightened the presence of something far darker and much more sinister: the demonic Sinners. The Magdalene Order is an organization that tries to counter this force. Two of its exorcists are Rosette Christopher and her assistant, Chrono. Both appear out of place in an organization like this, and they are in a quest to find Rosette''s missing brother, Joshua. Their relationships, secrets and fates can only be revealed in time...

(Source: Anime News Network)', 'GONZO', '2003', 'series', 'released', '2003-11-24', 60, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/60-qiQMlaoG6mqL.jpg', 'Action, Romance, Supernatural', 'TV', 'FALL', 24, 33613, 'https://www.youtube.com/watch?v=rXFBasb4xwI', '2026-08-29 14:41:18', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2154, 'Cat Soup', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b601-ti6XlGiU2tUA.jpg', 'series', '7.1', 'Cat Soup is an extremely difficult film to describe, due to its awesome surrealism and almost nonexistant dialogue. It is more a work of art than an anime. There are many underlying themes, such as the transcience of man''s existence, but it can be enjoyed without understanding any of them. The plot, though simple, isn''t necessarily understandable without being explained. The main character, a cat named Nyatto, embarks upon a journey to save his sister''s soul, which was ripped in two when Nyatto tried to save her from Death. She trails after him, brain-dead. They encounter many brilliant, mind-bending situations, beginning with a disturbing magic show.

(Source: Anime News Network)', 'J.C.STAFF', '2001', 'series', 'released', '2001-02-21', 601, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/601-jTlPnUQJXdey.jpg', 'Comedy, Horror, Psychological', 'OVA', 'WINTER', 1, 28205, 'https://www.youtube.com/watch?v=wRu-jX4tASQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2155, 'Scrapped Princess', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b167-qwMN7Wmlen5s.jpg', 'series', '7.1', 'Pacifica Cassul is a kindhearted girl living on the run, for prophecy has named her the poison that would destroy the world. Known as the Scrapped Princess, she’s the target of countless followers of a powerful religion. But even when it seems like the whole world is out to get her, she always has her two adoptive siblings - Shannon and Raquel. Together they travel the countryside, making new friends and battling countless foes. Bit by bit, they uncover the incredible truth behind the prophecy and its ties to mysterious events from 5,000 years ago. With the fate of the world in her naïve hands, Pacifica and her siblings must learn who to trust and take on enemies of godly power. But for all their struggle, should such a poison be allowed to live?

(Source: Funimation)', 'bones', '2003', 'series', 'released', '2003-04-08', 167, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/167-r3FIz2E7WNJS.jpg', 'Adventure, Comedy, Drama, Fantasy, Mecha, Sci-Fi', 'TV', 'SPRING', 24, 19581, 'https://www.youtube.com/watch?v=EcSNA1Izdg4', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2156, 'Time of Shura', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx340-2796ZUvGdBMg.jpg', 'series', '7.1', 'Legends tell of an invincible martial art known as Mutsu Enmei-Ryu, an unarmed style that allows the user to defeat any number of armed opponents using incredible speed and strength. This is the story of three generations of those who bear the name Mutsu, and their encounters and battles with the strongest fighters of their era.

(Source: Anime News Network)', 'Studio Comet', '2004', 'series', 'released', '2004-04-06', 340, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', NULL, 'Action', 'TV', 'SPRING', 26, 4265, 'https://www.youtube.com/watch?v=HMHTEIWo5zs', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2157, 'RahXephon', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx165-TBPrUsYj4SUL.jpg', 'series', '7.1', 'In the year 2012 Japan was invaded by the Mu. Human-like beings from another dimension with blue blood.

In the year 2015 Tokyo is attacked by invaders, who are repelled by a humanoid weapon called a Dolem. During the chaos, Ayato Kamina meets Reika Mishima, a classmate.

During that same day, he is attacked by government officials but a woman named Haruka comes to his rescue, informing him that she was sent to get him by the Organization TERRA, and that Tokyo had been sealed in a time rift where time flows one third as fast as the outside world.

He flees from Haruka onto a train where he sees Reika once more. Arriving at the Room of Rah, he follows her to a tremendous egg where the Dolem RahXephon is hatched from, and upon her singing his mother appears atop the Dolem that had stopped the TERRA Invasion. In the battle Ayato''s mother is injured, and Ayato flees Tokyo Jupiter with Haruka upon seeing his mother''s blue blood.', 'bones', '2002', 'series', 'released', '2002-01-21', 165, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/165-HD5hnoHOeJt0.png', 'Drama, Mecha, Music, Mystery, Psychological, Romance, Sci-Fi', 'TV', 'WINTER', 26, 29429, 'https://www.youtube.com/watch?v=-l8OT9jwyvs', '2026-08-29 14:41:32', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2158, 'Macross Zero', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx194-WGTjEMUnjGaW.jpg', 'series', '7.0', 'Taking place one year before the Zentraedi arrive on Earth, Macross Zero chronicles the final days of the war between the U.N. Spacy and anti-U.N. factions. After being shot down by the anti-U.N.''s newest fighter plane, ace pilot Shin Kudo finds himself on the remote island of Mayan, where technology is almost non-existent. While Shin stays on the island to heal his wounds, the tranqulity of the island is shattered by a battle that involves the UN''s newest fighter - the VF-0.

(Source: Anime News Network)', 'Satelight', '2002', 'series', 'released', '2002-12-21', 194, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/194-51br90sWs28b.jpg', 'Action, Adventure, Drama, Mecha, Romance, Sci-Fi', 'OVA', 'WINTER', 5, 10834, 'https://www.youtube.com/watch?v=JD604uxnjx4', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2159, 'Astro Boy (2003)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx971-zUOKQLxg0pL2.jpg', 'series', '7.0', 'Atom is a robotic boy that posses super human powers and an artificial intelligence system that is unparalleled to any robot. His creator, Dr. Tenma, created him to replace his late son, Tobio. Dr. Tenma soon destroys his laboratory, after the creation of Atom, and shuts down Atom. Soon after, Dr. Ochanomizu, the head of the Ministry of Science revives Atom, and tries to give him a normal life as a 6th grade student that helps the police agency keep renegade robots and bigot humans from causing harm. Atom faces extreme racism for being a robot, and he must discover the truth about his creator Dr. Tenma.

(Source: Anime News Network)', 'Tezuka Productions', '2003', 'series', 'released', '2003-04-06', 971, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/971-WjQ8lXLMGiRs.jpg', 'Action, Adventure, Mecha, Sci-Fi', 'TV', 'SPRING', 50, 7764, 'https://www.youtube.com/watch?v=YbYmyrWnIzc', '2026-08-29 14:41:30', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2160, 'Initial D to the Next Stage: Project D e Mukete', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx12725-CcU0ICZWAbi0.png', 'series', '7.0', 'A special that comes with the Fourth Stage DVD-BOX. It is comprised of a recap from First Stage to Third Stage, along with staff commentary and sneak preview of the making of the Fourth Stage.', 'A.C.G.T.', '2003', 'series', 'released', '2003-03-22', 12725, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', NULL, 'Action, Drama, Sports', 'SPECIAL', 'SPRING', 1, 3620, 'https://www.youtube.com/watch?v=erl__gso0fM', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2161, 'Samurai 7', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx166-aKHPMNS3oGQW.jpg', 'series', '7.0', 'In the far distant future, on a planet that might have been called "earth", there was a war between samurai who mechanized their bodies. After the long war, people enjoyed a modest peace.

Facing starvation and abductions at the hands of fearsome mechanized bandits (Nobuseri), the farmers of Kanna Village make the dangerous choice to hire samurai for protection. The village''s water priestess, Kirara, her younger sister, Komachi, and a heartbroken villager, Rikichi, set off to hire willing samurai with nothing to offer but rice from their meager harvests. Through dangerous encounters and a bit of luck, seven samurai of varying specialties and experience are gathered for an epic battle against the bandits and the merchants that influence them.

Note: Samurai 7 is based loosely upon Kurosawa Akira''s famous movie "Seven Samurai"/"Shichinin no Samurai".</.i>', 'GONZO', '2004', 'series', 'released', '2004-06-12', 166, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/166.jpg', 'Action, Mecha, Sci-Fi', 'TV', 'SUMMER', 26, 22007, 'https://www.youtube.com/watch?v=ECOq6aydx1k', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2162, 'Kyo Kara Maoh! - God (?) Save Our King!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx251-Ayui0ECuDPEe.png', 'series', '7.0', 'Yuri Shibuya was living a pretty normal life. That changed the day he was dunked into a toilet after an attempt to save a classmate from a gang of bullies. Instead of just getting a good soaking, he''s pulled in. The next thing he knows, he''s in a world that vaguely resembles medieval Europe. If that''s not odd enough, he''s told that he is to be the next Maoh, just because he has black hair and black eyes. The Maoh is the King of the Mazoku, who are coexisting not-so-peacefully with the humans in this world. Much to his subjects'' dismay, he''s totally different from the rulers they''re accustomed to. He''s kind, considerate, a believer in justice, and not willing to use violence to solve conflicts. Not exactly someone they want running a country on the very brink of war. Now, Yuri has to deal with trying to become a good Maoh, while at the same time attempting to adapt to this lands'' customs and culture, all in a world where the tension between the humans and Mazoku is reaching its peak.

(Source: Anime News Network)', 'Studio DEEN', '2004', 'series', 'released', '2004-04-03', 251, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', NULL, 'Adventure, Comedy, Fantasy', 'TV', 'SPRING', 78, 20132, 'https://www.youtube.com/watch?v=lQz3Vnw5Ko8', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2163, 's-CRY-ed', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx168-kXxD2Cse752Y.png', 'series', '7.0', 'A strange environmental phenomenon 22 years ago in the Kanazawa prefecture caused the land to split and protrude upwards reaching unprecedented heights, creating the secluded area known as The Lost Ground. Kazuma is a young mercenary who lives in the Lost Ground, looking for any work he can find to sustain his livelihood within the harsh environment. He is one of the few people that are gifted with the Alter ability, which allows him to plaster his right arm and torso with a metallic alloy. When this mercenary encounters HOLY, an order whose purpose is to suppress and capture what they call Native Alter Users, and one of the elite members of HOLY, Ryuho, an epic rivalry begins.

(Source: Anime News Network)', 'Sunrise', '2001', 'series', 'released', '2001-07-04', 168, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/168-9lhbODk2tBHJ.jpg', 'Action, Adventure, Sci-Fi', 'TV', 'SUMMER', 26, 16026, 'https://www.youtube.com/watch?v=JQqQiEluNzU', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2164, 'Figure 17: Tsubasa & Hikaru', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1126-VaQhM48ppOC9.png', 'series', '7.0', 'Tsubasa Shiina is a 10-year-old girl who recently moved to Hokkaido to live with her father. In school, she is very quiet and unsociable with her classmates. Then one night, she witnesses a UFO crash in the forest near her home. She rushes to the scene and finds the pilot, codenamed "D.D.", in a barely stable condition. Also in the scene is a Maguar, a hideous alien that hatched aboard D.D.''s ship. As the Maguar is close to taking Tsubasa''s life, an alien lifeform fuses with her body to form the Riberus battle armor Figure 17, which shortly destroys the alien threat. The life form takes the name Hikaru and turns into an identical twin of Tsubasa. As time passes, Tsubasa becomes more open to everyone around her, thanks to her new twin sister Hikaru. However, with Maguar eggs scattered all over Hokkaido, their ability to form Figure 17 is needed to eliminate all hatched Maguars until backup from D.D.''s home planet arrives on Earth.

(Source: Anime News Network)', 'OLM', '2001', 'series', 'released', '2001-05-27', 1126, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1126-W2BJKUQkc9gn.png', 'Sci-Fi, Slice of Life', 'TV', 'SPRING', 13, 5208, 'https://www.youtube.com/watch?v=eic3BjdIT5g', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2165, 'Galaxy Angel A', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/653.jpg', 'series', '7.0', 'Their mission is to locate and retrieve the mysterious Lost Technology, even though these girls have never been known to stick to their mission. Milfeulle, Forte, Ranpha, Mint, and Vanilla are back for another round of hilarity. The Galaxy Angels have sworn to protect the galaxy one planet at a time. Now with some competition with the newly-formed Twin Star Brigade, they continue to find themselves in the center of chaos... though usually they''re the ones at fault for its cause.

(Source: Anime News Network)', 'MADHOUSE', '2002', 'series', 'released', '2002-10-06', 653, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', NULL, 'Comedy, Sci-Fi', 'TV', 'FALL', 26, 2678, 'https://www.youtube.com/watch?v=r1XFff0Ji1w', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2166, 'Rozen Maiden', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx64-JsxXAcf3ZKo1.png', 'series', '7.0', 'Sakurada Jun spends his days online, ordering whatever he takes a liking to, only to return it before the payment is due. Due to psychological trauma from school, Jun generally keeps contact with people as little as possible. One day he finds instructions online that tell him to put his order into his desk drawer. Rubbing it off as a joke, Jun mindlessly does so only to find that his order instantly disappears from his drawer. A package suddenly appears, containing a beautiful antique doll. When wound up, this doll comes to life. Sadly for Jun, this doll Shinku views Jun as an equivalent for a servant. Despite the constant demands Jun now receives from Shinku, she slowly helps him overcome his fears of human contact as well as protect him from the deadly battles that come into his life due to her appearance.', 'Nomad', '2004', 'series', 'released', '2004-10-08', 64, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/64-dL4Ec6MxFlQw.jpg', 'Action, Comedy, Drama, Supernatural', 'TV', 'FALL', 12, 39066, 'https://www.youtube.com/watch?v=EtBxEYU1GFQ', '2026-08-29 14:41:27', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2167, 'Stellvia of the Universe', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113-LVBTWnBDpKb1.jpg', 'series', '7.0', 'The year is 2356 A.D. - 189 years after a distant supernova caused a global catastrophe that wiped out 99% of the world population. To keep track on all space activities, mankind has built colossal space stations called "foundations" all over the Solar System. After passing the Space Academy entrance exams, Shima Katase embarks to the Earth-based foundation Stellvia to fulfill her dream of seeing the galaxy and to prevent another interstellar catastrophe from destroying Earth.

(Source: Anime News Network)', NULL, '2003', 'series', 'released', '2003-04-03', 113, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/113-VWcPzVDpR0xI.jpg', 'Action, Mecha, Romance, Sci-Fi', 'TV', 'SPRING', 26, 6550, 'https://www.youtube.com/watch?v=iaL5M6j_E-A', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2168, 'Twin Spica', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx344-JGnFQAXW7Tob.jpg', 'series', '7.0', 'When Kamogawa Asumi was just a baby, her mother was grievously injured when a rocket crashed to the ground. Five years later, having been in a coma all the time, Asumi''s mother finally dies, and the little girl struggles to come to terms with the death of a mother she barely remembers. In the midst of her turmoil, she meets "Lion-san", a strange figure wearing a lion mask and claiming to be a ghost. Lion-san helps Asumi to bury her mother''s ashes, and finally, Asumi reaches her own decision: "When I grow up, I''m going to be a rocket pilot."

(Source: Anime News Network)', 'Group TAC', '2003', 'series', 'released', '2003-11-01', 344, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', NULL, 'Drama, Sci-Fi, Supernatural', 'TV', 'FALL', 20, 3239, 'https://www.youtube.com/watch?v=AVUeBhvx6mI', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2169, 'Yu-Gi-Oh! GX', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b482-c14JwoMTmKAU.png', 'series', '7.0', 'Duel Academy, one of the most prestigious schools in Duel Monsters history. There, students learn the fundamentals of becoming not just duelists, but large business owners.

Judai Yuki is a new student with only one thing on his mind: to become the next King of Games. Judai meets several friends, teachers, and even enemies at the large Dueling school. There, he''ll have to face off against several different dorms&mdash;Slifer Red, Ra Yellow, and Obelisk Blue&mdash;to become the number one duelist. Will Judai be able to pass all of them?

Based on Kazuki Takahashi''s world-famous anime and manga, <cite>Yu-Gi-Oh!</cite>.', 'Toei Animation', '2004', 'series', 'released', '2004-10-06', 482, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/482-3qmtAqhroz78.jpg', 'Action, Comedy, Fantasy', 'TV', 'FALL', 180, 47044, 'https://www.youtube.com/watch?v=cW2CkUqnBG0', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2170, 'Yokohama Kaidashi Kikou: Quiet Country Cafe', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b976-UFu2ce0hl6O8.png', 'series', '7.0', 'In the near-future Japan, global warming has brought the large city Yokohama underwater, and only the hills remain above the ocean surface. What used to be one of the largest cities in Japan now feels like a small town. Basically, the existence of the island country itself has been threatened. However, there is no feeling of desperation, devastation, nor hopelessness. People are enjoying laid-back lives, and they seem to appreciate each other''s company, enjoying the quiet and peaceful time together.

This is especially so with Alpha, a carefree young woman who runs a cafe, named Cafe Alpha. She enjoys her life immersing herself in the beautiful nature all around her. There is nothing more precious to her than spending quality time with her kind friends. Oh, the fulfillment and the joy she finds in life... it all indicates her to be a compassionate human being, but she is not quite a human. She is actually a type A7M2 robot.

One day, upon hearing a radio forecast warning an approaching typhoon, her old friend who lives close by invites her to the gas station he runs, worried that her old cafe may not withstand the typhoon. Indeed, the passing of typhoon leaves Alpha with her cafe severely damaged. That''s when she decides to go on a journey to raise money to rebuild her cafe, and also to see the outside world away from her friends and the comfort of a peaceful life.

(Source: AniDB)', 'Ajiado', '2002', 'series', 'released', '2002-12-18', 976, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/976-FHnTU865cxDe.jpg', 'Adventure, Drama, Sci-Fi, Slice of Life', 'OVA', 'WINTER', 2, 10162, 'https://www.youtube.com/watch?v=Mkc8j_G8vcw', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2171, 'Vandread: The Second Stage', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx181-MSG4LgXhyRhA.jpg', 'series', '7.0', 'Though Hibiki and crew defeated a super-huge battleship of the earth in the last of the first stage, they noticed five battleships further aiming at Mejeiru and Tarahk. And, crew of NIRVANA learnt Tarahk and Mejeiru which were their home had been faced to the crisis of Karitori (reaping). Travel to their home is speed up so that they may inform of the crisis. On the way, current information of the earth having been brought by girl Misty who had come to travel with them was worse than they can imagine. Hibiki and crew noticed a true fight was in the future. VANDREAD is finally changed into final system by the attack of the enemy who becomes violent more and more. Can they save their home? And, what happens to the relations between Hibiki and Dita?

(Source: AnimeNfo)', 'GONZO', '2001', 'series', 'released', '2001-10-05', 181, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/181-BNKtTi7Pe893.jpg', 'Action, Comedy, Mecha, Romance, Sci-Fi', 'TV', 'FALL', 13, 8264, 'https://www.youtube.com/watch?v=_5Jbge0OYrk', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2172, 'Steamboy', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx565-XWjoGw6sOoqo.png', 'movies', '7.0', 'Ray is a young inventor living in the U.K. in the middle of the 19th century. Shortly before the first ever Great Exhibition, a marvelous invention called the "Steam Ball," behind which a menacing power is hidden, arrives at his door from his grandfather Lloid in the U.S. Meanwhile the nefarious O''Hara Foundation has sent men to aquire the Steam Ball so that they can use its power towards their own illicit ends.

(Source: Anime News Network)', 'Sunrise', '2004', 'movie', 'released', '2004-07-17', 565, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/565-0fk7u9S1hI4z.jpg', 'Action, Adventure, Drama, Sci-Fi', 'MOVIE', 'SUMMER', 1, 20588, 'https://www.youtube.com/watch?v=bI7-bx8QqZ8', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2173, 'Digimon Adventure 02: Revenge of Diaboromon', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/2398.jpg', 'movies', '7.0', 'After the events of 02, everything is finally getting back to normal. That is, until a strangely familiar icon starts showing up on computer systems around the Japan. And not just computer systems... TVs, mobile phones, video games; anything with a screen with online capabilities. And this icon seems to be looking for somone... Yagami Taichi, and Ishida Yamato, who defeated it several years before. Yes, it turns out that this jellyfish digimon is in fact Diablomon, the Virus-type Digimon that was defeated in the second movie. But this time, he''s learned to make himself physical, and is sending thousands of copies of himself into the real world.

Koushiro and Ken devise a plan to rid the world of the virus once and for all, but it''ll take the help of all the Destined, past and present. Once again, it''s a race against time to put a stop to Diablomon''s plot... but even that is cloaked in shadow.

Will the revival of Omagamon be enough to stop Diablomon a second time, or will the millions of copies prove enough of a power boost to shrug off the "Digimon Champion of Justice"? Of course, he hasn''t seen the new breed of Chosen, nor the new techniques. It''s a fight to the finish, with the destruction of Tokyo resting on the line. 

(Source: AniDB)', 'Toei Animation', '2001', 'movie', 'released', '2001-03-03', 2398, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Comedy, Drama, Sci-Fi', 'MOVIE', 'SPRING', 1, 12452, 'https://www.youtube.com/watch?v=qc5grmiZmIE', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2174, 'Angelic Layer', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx52-i6aTXaa4w1QA.png', 'series', '7.0', 'From the moment twelve-year-old Misaki Suzuhara first arrives in Tokyo to live with her aunt, she finds herself swept away by the amazing world of Angelic Layer – a fast-paced high-tech game where dolls called “Angels” are controlled by the thoughts of their operator, or “Deus”. Discovering that her new friends are as interested in Angelic Layer as she is, Misaki builds her own Angel, Hikaru, and begins competing in battles where will and determination count far more than size and strength. The competitions are going to be fierce and, with the national championships looming on the horizon, you can bet that not everyone Misaki meets will be on her side. Can Misaki handle the pressure of non-stop competition while struggling to adapt to life in an unfamiliar city?

(Source: Sentai Filmworks)', 'bones', '2001', 'series', 'released', '2001-04-01', 52, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/52-K8t761OqZHdP.jpg', 'Comedy, Drama, Sci-Fi, Sports', 'TV', 'SPRING', 26, 11463, 'https://www.youtube.com/watch?v=u_euSY74UCQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2175, 'Kaleido Star: New Wings Extra Stage', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx428-Urdr4P2f26hc.png', 'series', '7.0', 'Sora Naegino has finally consolidated herself as Kaleido Stage''s greatest star ever, and a new star starts to shine as Rosetta Passel is selected to participate in the next attraction in a main role. But when things start to go wrong in the rehearsals, Rosetta starts to question her abillity to take the role, as her own capacity to remain in Kaleido Stage. Meanwhile, Fool also struggles with his demons from the past.', 'GONZO', '2004', 'series', 'released', '2004-09-24', 428, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/428-msWCFpML22ti.jpg', 'Drama, Fantasy, Sports', 'OVA', 'FALL', 1, 3074, 'https://www.youtube.com/watch?v=TIkyggFMcMw', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2176, 'The Animatrix', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b1303-Y09OcK2V0KmJ.jpg', 'series', '7.0', '1. Final Flight of the Osiris

The crew of the Osiris discover an army preparing to invade Zion. While one crew member races inside the Matrix to get the message to Zion, the others try desperately to buy her enough time while fighting off an onslaught of Sentinels they can''t possibly defeat.

2-3. The Second Renaissance Part 1 and 2

Humans have created the ultimate AI, which is just as smart as they are. But complications arise when these robots and the humans try to exist peacefully, and eventually all-out war breaks out. The humans ultimately lose the war, and become trapped in the Matrix as seen in the live-action films.

4. Kid''s Story

A young man discovers that his world isn''t real, that it''s a computer-generated fantasy land created by robots using humans for energy. He escapes with the help of the hacker Neo. Based on the Matrix trilogy. 

5. Program

Cis and Duo engage in battle in a virtual recreation of Feudal Japan. 

6. World Record

While running the fastest race in his life, a champion track star breaks free of his computer-generated world for a small period of time. When he goes back to the real world, he has no memories and is placed in a nursing home. Based on the Matrix trilogy.

7. Beyond

While looking for her lost pet, a young woman meets up with some kids in Tokyo to play in a "haunted house", which is really a glitch in their computer world. Based on the Matrix trilogy.

8. Detective Story

A detective named Ash is called upon by a mysterious organization to hunt down the notorious hacker Trinity.

9. Matriculated

A group of scientists capture a robot and place it in a surreal fantasy world. When the robot''s friends come in and kill most of the scientists, however, the robot and the last scientist remaining face isolation in the computer-generated world. Based on the Matrix trilogy.

(Source: Anime News Network)', 'MADHOUSE', '2003', 'series', 'released', '2003-06-03', 1303, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1303-l14Hy7nlMzRD.jpg', 'Action, Drama, Psychological, Sci-Fi', 'OVA', 'SUMMER', 9, 21464, 'https://www.youtube.com/watch?v=94fPVqJqBGA', '2026-08-29 14:41:24', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2177, 'Cosmic Baton Girl Comet-san', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2036-75UrWW8wbyTR.png', 'series', '7.0', 'In a magical part of the galaxy, the prince of the Tambourine star world has been betrothed to marry one of two princesses; but Comet, the princess of the Harmonica star world, couldn''t care less. Thus, much to her dismay, when the prince flees to Earth to escape his fate, Comet is sent to find him and return. Now, with the power of the stars and a magical locket, Comet sets out on an adventure to find the prince, have fun, and experience the life of an earthling first hand.', 'Nippon Animation', '2001', 'series', 'released', '2001-04-01', 2036, 0, NULL, '2026-07-25 18:55:44', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2036-2kCQkmqYInGL.jpg', 'Adventure, Comedy, Mahou Shoujo, Sci-Fi', 'TV', 'SPRING', 43, 2552, 'https://www.youtube.com/watch?v=-5NTLwW4DYA', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2178, 'Berserk', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx33-PSwfE5B0gejI.jpg', 'series', '8.4', 'Set during a time that very much resembles Europe during the Middle Ages, Berserk is a story of revenge set in the castle town of Midland. Recently, the town has seen the rise of a wicked king, who uses demonic minions to control and victimise his subjects.

However, when a lone soldier enters the town calling himself the Black Swordsman and armed to the teeth, many sense that the king''s days of unchecked oppression are over. Soon, the Black Swordsman is plying his trade by hunting down the king''s evil servants, giving no quarter, and preparing to exact his vengeance on the king.

(Source: MVM Entertainment)', 'OLM', '1997', 'series', 'released', '1997-10-07', 33, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/33-g7HwYRVm0ZkN.jpg', 'Action, Adventure, Drama, Fantasy, Horror, Supernatural', 'TV', 'FALL', 25, 181486, 'https://www.youtube.com/watch?v=odIwkGztmcc', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2179, 'Revolutionary Girl Utena', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b440-r4l3N5WGgUOZ.jpg', 'series', '8.3', 'Just after Utena''s parents died, she was consoled by a prince who gave her a ring with a rose crest on it. Utena was so impressed by the Prince that she vowed to become one herself one day. A few years later, Utena is attending Ohtori Academy where she gives all the teachers headaches because she dresses in a boy''s uniform so she can be like the prince she met long ago. 

After Utena''s friend is insulted by a member of the Student Council, Utena fights in a duel for her friend''s honor. Utena''s rose crest allows her to enter the dueling arena, where Utena wins the duel and becomes engaged to the Rose Bride. Unknowingly, Utena is pulled into a series of duels with other members of the Student Council for the possession of the Rose Bride. As she becomes fond of Anthy, the Rose Bride, she must fight to keep her friend safe and to discover the horrifying secret behind Ohtori Academy.

(Source: Anime News Network)', 'J.C.STAFF', '1997', 'series', 'released', '1997-04-02', 440, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/440-0Gzds5AlVDN6.jpg', 'Action, Drama, Fantasy, Mystery, Psychological, Romance', 'TV', 'SPRING', 39, 79384, 'https://www.youtube.com/watch?v=GWuP4aLDU8M', '2026-08-29 14:41:57', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2180, 'Initial D 1st Stage', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b185-GvXiR8AKTmdn.jpg', 'series', '8.2', 'High school student Takumi Fujiwara works as a gas station attendant during the day and a delivery boy for his father''s tofu shop early in the morning. Little does he know that his precise driving skills and his father''s modified Toyota Sprinter AE86 Trueno make him the best amateur road racer on Mt. Akina''s highway. Because of this, racing groups from all over the Gunma prefecture issue challenges to Takumi to see if he really has what it takes to be a road legend.

(Source: Anime News Network)', 'Studio Comet', '1998', 'series', 'released', '1998-04-19', 185, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/185-Z724xydTic8N.jpg', 'Action, Drama, Sports', 'TV', 'SPRING', 26, 114626, 'https://www.youtube.com/watch?v=sQArIPVsz78', '2026-08-29 14:42:00', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2181, 'Cardcaptor Sakura', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx232-ERyKCNNPJJeh.png', 'series', '8.1', 'One day, Kinomoto Sakura, a 4th grader stumbles upon the mysterious book of Clow. Upon opening it and reading the name of The Windy aloud, Sakura scatters the cards to the winds. Sakura is elected and appointed by Keroberos, Guardian of the Cards to capture the remaining cards. With her friend Tomoyo and rival Syaoran, Sakura begins an adventure that will forever change her.', 'MADHOUSE', '1998', 'series', 'released', '1998-04-07', 232, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/232-jnE0kGIWIRIS.jpg', 'Comedy, Drama, Fantasy, Mahou Shoujo, Romance', 'TV', 'SPRING', 70, 101518, 'https://www.youtube.com/watch?v=W8pQIpheFSw', '2026-08-29 14:42:03', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2182, 'Initial D 2nd Stage', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b186-eygBSoYwLCYt.jpg', 'series', '8.1', 'Following his victory over RedSuns leader Ryosuke Takahashi, AE86 driver Takumi Fujiwara is challenged by the Lancer EVO-based "Emperor," a group known for taking decals of racing teams they defeat, cutting them up and placing them on their cars like a fighter plane kill board. Takumi''s undefeated streak is on the line as his AE86 is virtually no match against the more powerful and more agile four-wheel-drive EVOs of the Emperor team. 

(Source: Anime News Network)', 'Pastel', '1999', 'series', 'released', '1999-10-15', 186, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n186-R2K9rwXRPhi9.jpg', 'Action, Drama, Sports', 'TV', 'FALL', 13, 59451, 'https://www.youtube.com/watch?v=-F3WCRKYYgI', '2026-08-29 14:42:06', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2183, 'Cardcaptor Sakura the Movie 2: The Sealed Card', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx372-fTXJwelrAAC6.png', 'movies', '8.1', 'During the summer holidays, Sakura and her class are preparing to present a play at the annual Nadeshiko Festival. The unexpected arrival of Syaoran (and Meiling) give Sakura the courage to finally reciprocate her feelings. But as the cards begin to disappear one by one, Sakura discovers a single cards still remains. One with power equal to all hers... It is during this summer that Sakura faces her final battle.', 'MADHOUSE', '2000', 'movie', 'released', '2000-07-15', 372, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/372-oZ03Sv6taLVk.jpg', 'Drama, Fantasy, Mahou Shoujo, Romance', 'MOVIE', 'SUMMER', 1, 24982, 'https://www.youtube.com/watch?v=JaKyVQmkXiA', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2184, 'Serial Experiments Lain', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx339-xF2wp1NQuQ4r.png', 'series', '8.0', 'We''re all connected... There is the world around us, a world of people, tactile sensation, and culture. There is the wired world, inside the computer, of images, personalities, virtual experiences, and a culture all of its own. The day after a classmate commits suicide, Lain, a 14-year-old girl, discovers how closely the two worlds are linked when she receives an e-mail from the dead girl: I just abandoned my body. I still live here...

Has the line between the real world and the wired world begun to blur?

(Source: Geneon Entertainment)', 'Triangle Staff', '1998', 'series', 'released', '1998-07-06', 339, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/339-Lh0tuuwRLRgI.jpg', 'Drama, Mystery, Psychological, Sci-Fi, Supernatural', 'TV', 'SUMMER', 13, 247358, 'https://www.youtube.com/watch?v=lpv7Wv-sDAo', '2026-08-29 14:42:09', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2185, 'Turn A Gundam', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx95-5okHk1B0VKro.jpg', 'series', '8.0', 'This story is set thousands of years in the future. The people of Earth have forgotten the space wars of the past, reverting back to a pre-industrial existence. But the lunar settlers known as the Moonrace, who have retained their high technology, now plan to seize their mother planet for themselves. As the war of the worlds begins, a young Moonrace citizen named Loran Cehack, pilot of the legendary Turn A Gundam, struggles to bridge the gap between humanity''s long-separated branches.

(Source: GundamOfficial)', 'Sunrise', '1999', 'series', 'released', '1999-04-09', 95, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/95-kLBJfcuG0Yb7.jpg', 'Action, Adventure, Drama, Mecha, Sci-Fi', 'TV', 'SPRING', 50, 21197, 'https://www.youtube.com/watch?v=FMUOENME8Zc', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2186, 'Trigun', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx6-wd4saT1JzStH.jpg', 'series', '8.0', 'Vash the Stampede is a wanted man with a habit of turning entire towns into rubble. The price on his head is a fortune, and his path of destruction reaches across the arid wastelands of a desert planet. Unfortunately, most encounters with the spiky-haired gunslinger don''t end well for the bounty hunters who catch up with him; someone almost always gets hurt - and it''s never Vash.

Oddly enough, for such an infamous fugitive, there''s no proof that he''s ever taken a life. In fact, he''s a pacifist with a doughnut obsession who''s more doofus than desperado. There''s a whole lot more to him than his reputation lets on - Vash the Stampede definitely ain''t your typical outlaw.

(Source: Funimation)', 'MADHOUSE', '1998', 'series', 'released', '1998-04-01', 6, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/6-4pIR2RY8AHZ0.jpg', 'Action, Adventure, Comedy, Drama, Sci-Fi', 'TV', 'SPRING', 26, 168473, 'https://www.youtube.com/watch?v=bJVyIXeUznY', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2187, 'Rurouni Kenshin', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx45-DEFgZRCxiGmF.png', 'series', '7.9', 'Himura Kenshin is a vagabond with a dark past and sunny disposition. Not a ronin but a rurouni, he was never a samurai, but an assassin of utmost skill in the Meiji restoration, who in the turning point of the war simply walked away. His travels lead him to Tokyo in the 11th year of the Meiji era, where he befriends a female Kendo master, a former thief, a brawler and a doctor all with their own secrets. Together they fight off the enemies surfacing from the dark past that Kenshin cannot escape. 

(Source: Anime News Network)', 'Studio Gallop', '1996', 'series', 'released', '1996-01-10', 45, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/45-JVUpMKU0HzRW.jpg', 'Action, Adventure, Comedy, Drama, Romance', 'TV', 'WINTER', 94, 89071, 'https://www.youtube.com/watch?v=V83Kxuvt9Jc', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2188, 'The King of Braves: GaoGaiGar Final', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1382-MRfbe0Tuegcr.jpg', 'series', '7.9', 'Following Gutsy Galaxy Guard`s victory over the Zonder Empire and the 31 Primevals, a new threat makes their appearance on Earth. GGG - with Guy Shishio and the newly-constructed GaoFighGar - team up with their French counterpart Chasseur to battle the evil organization BioNet. Among Chasseur`s ranks is Renais Cardiff Shishioh - a former BioNet cyborg with the relentless pursuit of destroying those who took away her humanity. But as GGG and Chasseur fight the BioNet, GGG`s bases around the world are suddenly attacked, and the recently-discovered "Q-Parts" and the original Gao Machines are stolen by Mamoru Amami, who has been abducted and cloned by an even greater threat known as the "Eleven Kings of Sol." Evicted from Earth by the United Nations, GGG must now travel to the far reaches of the galaxy to battle the Eleven Kings of Sol and save Mamoru before it`s too late.

(Source: Anime News Network)', NULL, '2000', 'series', 'released', '2000-01-21', 1382, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1382-LRkNrpM92ttC.jpg', 'Adventure, Drama, Mecha, Sci-Fi', 'OVA', 'WINTER', 8, 3617, 'https://www.youtube.com/watch?v=fDbbZWQrX1Q', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2189, 'Revolutionary Girl Utena: The Adolescence of Utena', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx441-JbPY7EiWIeaL.jpg', 'movies', '7.9', 'In a loose retelling of the Revolutionary Girl Utena TV series, Utena Tenjou arrives at Ohtori Academy, only to be immediately swept up in a series of duels for the hand of her classmate Anthy Himemiya and the power she supposedly holds. At the same time, Utena reunites with Touga Kiryuu, a friend from her childhood who seems to know the secrets behind the duels. Utena must discover those secrets for herself, before the power that rules Ohtori claims her and her friends, new and old. 

(Source: Anime News Network)', 'J.C.STAFF', '1999', 'movie', 'released', '1999-08-14', 441, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/441-CozxZcqqO6hp.jpg', 'Drama, Fantasy, Mystery, Psychological, Romance', 'MOVIE', 'SUMMER', 1, 21678, 'https://www.youtube.com/watch?v=6h9lzMP0Tns', '2026-08-29 14:41:38', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2190, 'FLCL', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx227-qOB9ZhVvNnqO.jpg', 'series', '7.9', 'Naota is a detached sixth grader afflicted by the pangs of puberty. He''s fooling around with his brother''s ex-girlfriend when a crazed girl on a motor scooter runs him over, brains him with a bass guitar, and moves into his house. This pink-haired girl, Haruko - who claims she''s an alien - hurls Naota into the middle of a mega-corporation''s secret agenda. Oh, and now giant battling robots shoot from his skull. Mix in mind-bending animation and tunes that echo through your cerebellum to top off the trip that will have you falling hard for FLCL.

(Source: Funimation)', 'Gainax', '2000', 'series', 'released', '2000-04-26', 227, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/227.jpg', 'Action, Comedy, Mecha, Sci-Fi', 'OVA', 'SPRING', 6, 203503, 'https://www.youtube.com/watch?v=t7Gz5XXgGhw', '2026-08-29 14:41:49', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2191, 'Vampire Hunter D: Bloodlust', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx543-MAeWIDl4TwuG.png', 'movies', '7.8', 'The story revolves around D, the infamous "dunpeal" (born of a vampire father and a human mother) outcast and renowned vampire hunter. His prowess at hunting the creatures of the night allowing his acceptance among humans, he is called upon to locate Charlotte Elbourne, the lovely daughter of an affluent family who has been mysteriously kidnapped.

When the sun sets, the hunt goes on! Charlotte`s father offers a rich bounty, be she dead or alive, a task D willingly accepts, even with notorious Markus brothers and their gang of bounty hunters seeking the prize as well. Amidst the chase and unknown to all lurks a sinister evil which has been secretly manipulating their every move and has set a chilling trap that none will expect and few will survive. With the tables turned and the secrets revealed, the hunters could quickly become the hunted!

(Source: AniDB)', 'MADHOUSE', '2000', 'movie', 'released', '2000-08-25', 543, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/543-jQdmjf48M0Lf.jpg', 'Action, Adventure, Drama, Fantasy, Horror, Romance, Sci-Fi', 'MOVIE', 'SUMMER', 1, 53756, 'https://www.youtube.com/watch?v=44xT9LSrgJ4', '2026-08-29 14:41:41', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2192, 'Kodocha', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx1486-S1lSoaOlGBxQ.jpg', 'series', '7.8', 'Sana Kurata has a charmed life. Not only is her mother is a famous, award-winning writer, but she''s the star of the hit TV comedy "Child''s Toy" while still in the fifth grade. But Sana''s biggest concern is Akito Hayama, a pint-sized hellion who''s organized the boys in their grade-school class into a mass of unending noise and violence. With the help of Rei, her manager, chauffeur and "pimp," Sana is determined to win back control of the classroom from her new arch-enemy. But as her crusade continues, Sana moves further into Akito''s life, and finds that he might not be entirely bad...or entirely safe.

(Source: Anime News Network)', 'Studio Gallop', '1996', 'series', 'released', '1996-04-05', 1486, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1486-W6WAxncTM5Gc.jpg', 'Comedy, Drama, Romance', 'TV', 'SPRING', 102, 20080, 'https://www.youtube.com/watch?v=gv6POE9lYgs', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2193, 'Legend of the Galactic Heroes Gaiden: A Hundred Billion Stars', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/n3371-rgefk9MUco58.png', 'series', '7.8', 'Prequel to the original series, focusing on Reinhard and his steps up the chain of command in the Galactic Empire.
A collection of independent short stories taking place prior to the Overture to a New War, some of which are adapted from the novel and some of which are completely original.', 'Artland', '1998', 'series', 'released', '1998-02-09', 3371, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n3371-z1z3S9dkuGV6.jpg', 'Action, Sci-Fi', 'OVA', 'FALL', 24, 7552, 'https://www.youtube.com/watch?v=Ou37P25tjJY', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2194, 'The Slayers Next', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx535-xCRCSK8YG89S.png', 'series', '7.8', 'Let the forces of evil tremble in fear (along with wealthy merchants and innocent bystanders)... THE SLAYERS ARE BACK! Join the not-so-heroic adventures of Lina Inverse--the super-cute sorceress who steals from the rich and keeps it for herself! Along with her sword-swinging (but dumber than dirt) sidekick, Gourry, her hyper-enthusiastic protégé, Amelia, and the tormented and overly-serious golem, Zelgadis, there''s nothing Lina can''t do!

(Source: Software Sculptors)', 'E&G Films', '1996', 'series', 'released', '1996-04-05', 535, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/535-PJsBUqnCqyZM.jpg', 'Adventure, Comedy, Fantasy', 'TV', 'SPRING', 26, 12831, 'https://www.youtube.com/watch?v=1cYtZa4HMYI', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2195, 'Sailor Moon Sailor Stars', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx996-lHMuAdqP4ReE.jpg', 'series', '7.7', 'Like the R Season, SailorStars is divided into two arcs:

The first arc solves some conflicts from the SuperS season, and also sees the return of the Outer Senshi, Haruka, Michiru, Setsuna, and Hotaru (now reborn as a child).

The second arc is the actual plot from the manga. Usagi bids farewell to Mamoru, who is going to America to study abroad. In his place comes the Three Lights, an idol trio consisting of three boys, Seiya, Taiki, and Yaten. The new enemy is Galaxia, a woman who desires to rule the entire galaxy by collecting the Star Seeds of humans. Three new Senshi appear, the Sailor Starlights, who also intend to stop Galaxia without Sailormoon''s help.', 'Toei Animation', '1996', 'series', 'released', '1996-03-09', 996, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/996-tnBVKjzxjqj4.jpg', 'Action, Adventure, Comedy, Drama, Fantasy, Mahou Shoujo, Romance', 'TV', 'SPRING', 34, 23920, 'https://www.youtube.com/watch?v=rnxwNyb101A', '2026-08-29 14:41:44', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2196, 'Getter Robo: Armageddon', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx978-Tv9paCO7uQhJ.png', 'series', '7.7', 'Sent to jail after being accused of murdering Getter Robo creator Dr. Saotome, Ryoma Nagare must once again team up with his former comrades and pilot Getter Robo when Saotome returns from the dead and threatens humanity by unleashing his greatest creation - the Shin Dragon. Their efforts, however, are in vain as they fail to stop a nuclear warhead from hitting Shin Dragon, resulting in a massive Getter Ray contamination that wipes out 99% of the planet''s population. Thirteen years after this great catastrophe, mankind continues to fight for survival against the Invaders. Out of the remains of the nuclear blast comes Shin Getter, piloted by the artificial human Go. With remnants of the Japanese military by his side, Go - along with co-pilots Kei and Gai - must use Shin Getter to exterminate the Invaders once and for all.

(Source: Anime News Network)', 'Brain''s Base', '1998', 'series', 'released', '1998-08-25', 978, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/978-Eh5jBmAncg3i.jpg', 'Action, Adventure, Horror, Mecha, Sci-Fi', 'OVA', 'SUMMER', 13, 8045, 'https://www.youtube.com/watch?v=JbUKDQYLqIU', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2197, 'InuYasha', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx249-jVBkyLnBvnRE.png', 'series', '7.7', 'Kagome Higurashi, an average ninth grader, gets pulled into an ancient well by a demon, bringing her 500 years in the past to the feudal era. There, she meets Inuyasha, a half-demon who seeks the Shikon Jewel to make himself a full-fledged demon. With Inuyasha and new friends, Kagome''s search for the Jewel of Four Souls begins...

(Source: VIZ Media)', 'Kyoto Animation', '2000', 'series', 'released', '2000-10-16', 249, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/249-9ufXhmXxncry.jpg', 'Action, Adventure, Comedy, Fantasy, Romance', 'TV', 'FALL', 167, 172393, 'https://www.youtube.com/watch?v=UCFBsLagBPk', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2198, 'Mobile Suit Gundam: The 08th MS Team', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx81-qBgqd932d9lW.jpg', 'series', '7.7', 'UC 0079 - After the success of Operation Odessa, more and more Earth Federation soldiers are sent to earth to free it from the hands of the Principality of Zeon. As Zeonic troops retreat to unknown parts of the world, it''s up to the Earth Federation Ground Force to find them and exterminate them. 


Ensign Shiro Amada is made leader of the 08th MS Team, leading a team of Ground Type Gundams into battle. His mission: to distract the enemy and find a mysterious new Zeon weapon. But can he complete it when he falls in love with a Zeon pilot, named Aina Sahalin? 


(Source: Otakufreakmk2, copyedited by Kolokotronis)', 'Sunrise', '1996', 'series', 'released', '1996-01-25', 81, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/81-RNLTCGp3auov.jpg', 'Adventure, Drama, Mecha, Romance, Sci-Fi', 'OVA', 'WINTER', 12, 23664, 'https://www.youtube.com/watch?v=HJVC_d1tMLc', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2199, 'Legend of the Galactic Heroes Gaiden: Spiral Labyrinth', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/n3665-cX3SS5lcumOZ.png', 'series', '7.7', 'A prequel to Legend of Galactic Heroes, focusing more on Yang Wen-li; how he became the hero of El Facile and how he handled a couple of assignments he received afterward. Spiral Labyrinth also continues with the background of Reinhard and Kircheis where the first Gaiden left off.

A collection of independent short stories taking place prior to the Overture to a New War, some of which are adapted from the novel and some of which are completely original.', 'Artland', '1999', 'series', 'released', '1999-12-24', 3665, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/3665-Gej5lD6g105b.jpg', 'Drama, Sci-Fi', 'OVA', 'WINTER', 28, 6607, 'https://www.youtube.com/watch?v=Ou37P25tjJY', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2200, 'Jin-Roh: The Wolf Brigade', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx570-xyP4IO7i3ua2.jpg', 'movies', '7.6', 'In a very different Tokyo from the one we know today, the totalitarian government rules with an iron fist. But a group called "the Sect" is staging demonstrations and challenging the government''s martial law. Constable Fuse of the Capital Police''s Special Unit is on a mission to stop a Sect demonstration when he encounters a girl in the sewers under Tokyo.

When he fails to shoot as ordered, he is put on trial, questioned, and "re-conditioned" as a soldier. But the dead girl haunts him, both in his dreams and in the face of her sister, whom Fuse has befriended. But Fuse has made himself a target for some very powerful men... And as the world comes crashing down around him, Fuse is continually challenged to decide what is real and what is right.

(Source: Discotek)

Note: The film received an early premiere at the Fantasia Film Festival on August 6, 1999.', 'Production I.G', '2000', 'movie', 'released', '2000-06-03', 570, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/570-nk4Dc162QGNT.jpg', 'Action, Drama, Psychological, Romance, Thriller', 'MOVIE', 'SPRING', 1, 56229, 'https://www.youtube.com/watch?v=tmmoBsMw5w0', '2026-08-29 14:41:46', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2201, 'The King of Braves: GaoGaiGar', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx890-opmekyhFfZO9.jpg', 'series', '7.6', 'In the year 2005, a race of alien monsters called Zonders emerge from underground and launch a series of attacks on the city of Tokyo. The only defense against these creatures is the secret agency known as the Gutsy Geoid Guard (or 3G) and their ultimate weapon, the awesome giant robot GaoGaiGar. GaoGaiGar''s pilot, Guy Shishio, is a former astronaut who was nearly killed two years before when the Zonders first crashed to earth. Guy''s life was spared when a mysterious robot lion called Galeon pulled him from the burning shuttle and brought him to Earth. Guy''s father, Leo, then used Galeon''s technology to rebuild his shattered son as a cyborg, in the hopes that he could stop the aliens when they appear. Now, with Galeon as its core, GaoGaiGar fights to protect Earth. He is aided by a team of transforming robots and by a young boy named Mamoru, who has the power to purify the Zonders'' cores, and seems to be connected to the mysterious Galeon.

(Source: Anime News Network)', 'Sunrise', '1997', 'series', 'released', '1997-02-01', 890, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/890-LV6teY9Xj3yY.jpg', 'Adventure, Mecha, Sci-Fi', 'TV', 'WINTER', 49, 8931, 'https://www.youtube.com/watch?v=fDbbZWQrX1Q', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2202, 'Kindaichi Shounen no Jikenbo (TV)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2076-vT2rhZTMroej.jpg', 'series', '7.6', 'Kindaichi Hajime may look dumb, but he is one of the smartest you will ever see. He encounters mysteries after mysteries with his good friend, Miyuki, and he swears to solve them in the name of his grandfather, which was a great detective.

(Source: Anime News Network)', 'Toei Animation', '1997', 'series', 'released', '1997-04-07', 2076, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2076-KnWNSODMRuVM.jpg', 'Mystery', 'TV', 'SPRING', 148, 8883, 'https://www.youtube.com/watch?v=WCcUBBoWPD0', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2203, 'MASTER Keaton (OVA)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b1910-xd6efTNc4TW9.png', 'series', '7.6', 'Taichi Keaton is a man of many talents: father, historian, frequent traveler, negotiator, archaeologist, former survival instructor, and all while working as an insurance investigator for Lloyd''s of London. While his methods may seem a bit unorthodox, he gets the job done when needed, but not without a little something to learn or teach in the process. Through all of his adventures, some people call him a quack. Those who know him well call him a master of life...  

(Source: Anime News Network)', 'MADHOUSE', '1999', 'series', 'released', '1999-12-21', 1910, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', NULL, 'Adventure, Mystery', 'OVA', 'WINTER', 15, 3517, 'https://www.youtube.com/watch?v=NSKRIJn7Uu8', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2204, 'His and Her Circumstances', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx145-vcSv07afgy6c.png', 'series', '7.6', 'Miyazawa Yukino is the perfect student. Kind, intelligent, pretty and modest, it''s unbelievable that such a person could exist. Little did everyone know Yukino''s perfection was just a facade. An act to fulfill her desire for praise and admiration. Her life took a turn however, as a newcomer to their school Arima Soichiro topped the exam rankings. Arima is more than just intelligent, he''s also kind, handsome and modest, an unbelievable person who can actually exist. Even worse luck, Arima found out Yukino''s secret, blackmailing her to help him out. Their odd relationship soon develops into friendship and eventually into love. But can their love prevail through the many problems that come their way?', 'Gainax', '1998', 'series', 'released', '1998-10-02', 145, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/145-RQJdx77yqxnq.jpg', 'Comedy, Drama, Romance, Slice of Life', 'TV', 'FALL', 26, 66577, 'https://www.youtube.com/watch?v=cyGEjyyTjiM', '2026-08-29 14:41:35', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2205, 'Ojamajo Doremi Sharp', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b351-d77vjiz5qpni.png', 'series', '7.5', 'Upon re-entering the witch world the girls accidentally come by a Blue rose field and witness the birth of the future witch queen: Hana-chan. Due to witnessing her birth the girls are then put in charge of baby Hana-chan and must raise her of their "mothers".

But will four ten year old girls be able to raise a baby when they''re still children themselves?! Can Pop finally catch up with her older clumsy sister? Will Majorika finally turn back to normal?', 'Toei Animation', '2000', 'series', 'released', '2000-02-06', 351, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/351-l6wjsgC3EXUr.jpg', 'Comedy, Drama, Fantasy, Mahou Shoujo, Slice of Life', 'TV', 'WINTER', 49, 7676, 'https://www.youtube.com/watch?v=lU-ykaYhBLs', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2206, 'Remi, Nobody''s Girl', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/2829.jpg', 'series', '7.5', 'Remy, a cheerful and tender-hearted girl, lives with her mother in a French country town. One day her father returns to the town after a long period working away from home in a city. Her father tells Remy that she isn''t their real daughter, and Remy is almost sold to an evil slave trader. It is Vitalis, a strolling entertainer, who helps Remy. Vitalis discovers her talent for singing and decides to take her in with his troupe.

(Source: Anime News Network)', 'Nippon Animation', '1996', 'series', 'released', '1996-09-01', 2829, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2829-Y2Rb0UVNb75c.jpg', 'Adventure, Drama, Slice of Life', 'TV', 'FALL', 23, 5702, 'https://www.youtube.com/watch?v=k3BJRgT-lvM', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2207, 'The Slayers Try', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1172-lNafo4vTzqho.png', 'series', '7.5', 'In search of fame, fortune, and foreign food, Lina Inverse sets sail on a collision course for the new world! What she finds there are vengeful enemies, a bunch of high-and-mighty dragon lords, and a new quest to save the world from destruction. What’s a girl gotta do for a little vacation?

(Source: Software Sculptors)', 'E&G Films', '1997', 'series', 'released', '1997-04-04', 1172, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1172-IGUBci9bALF8.jpg', 'Adventure, Comedy, Fantasy', 'TV', 'SPRING', 26, 9835, 'https://www.youtube.com/watch?v=p6s1D2VojvU', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2208, 'Outlaw Star', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx400-CJ2duQT3dCX1.png', 'series', '7.5', 'Gene Starwind is a jack-of-all-trades responsible for odd jobs and bounty hunting with his partner, Jim Hawking. Stuck on a rundown planet, he’s going nowhere fast. But when a bodyguard job goes sideways, he finds himself the proud owner of the Outlaw Star and on an adventure to find the mysterious Galactic Leyline. Facing pirates and dangers galore, can he survive the journey through space?

(Source: Crunchyroll)', 'Sunrise', '1998', 'series', 'released', '1998-01-08', 400, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/400-rkltKfdzW10w.jpg', 'Action, Adventure, Comedy, Sci-Fi', 'TV', 'WINTER', 24, 35816, 'https://www.youtube.com/watch?v=IOqZlvL_PDA', '2026-08-29 14:41:55', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2209, 'Cardcaptor Sakura: The Movie', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx371-sdrIzrI5qXl3.jpg', 'movies', '7.4', 'It''s winter vacation and Sakura wins a trip to Hong Kong. Kero, skeptic of her luck in lotteries, questions whether she was merely lucky or was she summoned to Hong Kong upon inevitability. As Sakura strolls through Hong Kong''s Bird Street, she senses an evil force calling to her. On chasing two strange birds, she is lead to a phantom world where she learns she was actually made to come to Hong Kong by a woman, Madoushi, who apparently wants revenge on Clow Reed. With Syaoran''s mother, Yelan''s help and the guidance from Clow Reed''s voice, she must fight Madoushi and rescue her friends and loved ones, who have been captured.', 'MADHOUSE', '1999', 'movie', 'released', '1999-08-21', 371, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/371-w6r3ky6l7LCQ.jpg', 'Comedy, Fantasy, Mahou Shoujo', 'MOVIE', 'SUMMER', 1, 21527, 'https://www.youtube.com/watch?v=j8FSrgUoj90', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2210, 'KochiKame', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx3545-rhUDPxf7DsBQ.png', 'series', '7.4', 'Ryoutsu, being an underpayed policeman, is always coming up with ways to make some quick money. But in the end, his plans which are ridiculous from the beginning always go wrong and land him in big trouble with the Buchou.', 'Studio Gallop', '1996', 'series', 'released', '1996-06-16', 3545, 0, NULL, '2026-07-25 18:55:48', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/3545-qknCrUs3pDXc.jpg', 'Comedy, Slice of Life', 'TV', 'SUMMER', 344, 5773, 'https://www.youtube.com/watch?v=PpKUfuVLod8', '2026-08-29 14:41:52', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2211, 'Baby and Me', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1485-OCWnMpSaAe5j.jpg', 'series', '7.4', 'Two months ago, Takuya Enoki''s mother passed away in an accident leaving him to take care of his baby brother, Minoru, while their father works the long hours of a Japanese "salaryman". Takuya must sacrifice playtime and childhood to take care of his brother and do the responsibilities an adult would have: cooking, sewing, and scolding while trying to find it in his heart to love the brother who is causing him so much grief.

(Source: Anime News Network)', 'Studio Pierrot', '1996', 'series', 'released', '1996-07-11', 1485, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1485-E5Z38jYkjGzR.jpg', 'Comedy, Drama, Slice of Life', 'TV', 'SUMMER', 35, 5421, 'https://www.youtube.com/watch?v=7oThvRuRAsE', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2212, 'Ghost Stories', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1281-1D6fuMnHwor0.png', 'series', '7.4', 'Kids and ghosts. When young Satsuki finds an old book of spells from her passed away mother, she gains the power to fight ghosts that are haunting her new school. With the help of her friends, and of a really wicked devil cat, she must protect everyone around her or be haunted for ever more. 

(Source: Anime News Network)', 'Studio Pierrot', '2000', 'series', 'released', '2000-10-22', 1281, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1281-QjxPqVZpNYDs.jpg', 'Horror, Mystery, Supernatural', 'TV', 'FALL', 19, 78459, 'https://www.youtube.com/watch?v=kOi5SpwDQR4', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2213, 'The Big O', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx567-iWOJNRu4begJ.png', 'series', '7.4', 'Paradigm City is a place without a past. 40 years ago, something happened that wiped the memories of everyone in it. Unfortunately, the people of Paradigm City were very busy before then, making Megadueses (giant robots) and monsters. People who were born after the memory wipe are gaining/recovering memories of the past and using them to build newer threats. With the help of The Big O (a faithful giant robot), his butler Norman and the android Dorothy, Roger Smith keeps Paradigm City safe. As problems mount and more memories surface, Roger''s past and Paradigm''s future begin to become suspect...', 'Sunrise', '1999', 'series', 'released', '1999-10-13', 567, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/567-F55BUpK3HLQs.jpg', 'Action, Mecha, Mystery, Psychological, Sci-Fi', 'TV', 'FALL', 13, 28104, 'https://www.youtube.com/watch?v=GOzphFKZAFk', '2026-08-29 14:42:17', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2214, 'Yokohama Shopping Log', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/975-EDNYnBJCctSD.jpg', 'series', '7.4', 'This is not so much a story as it is a slice of life. Or rather, it is a look into portions of the life of a girl named Alpha, together with the people around her. Alpha runs a little cafe on the outskirts of Yokohama. There are almost no customers, but Alpha does not mind at all since she has the occasional company of the old man who runs the gasoline stand down the road, as well as that of his grandson Takahiro. This is a Yokohama of the future, when the sea covers most of the land and roads have disappeared under sand or water. Alpha is in fact a robot, looking after the cafe during her owner''s indefinite leave of absence.

(Source: AniDB)', 'Ajiado', '1998', 'series', 'released', '1998-05-21', 975, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/975-6Fcen4DGT5vD.jpg', 'Sci-Fi, Slice of Life', 'OVA', 'SPRING', 2, 20851, 'https://www.youtube.com/watch?v=qoC9ibZAcbw', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2215, 'Magical DoReMi', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx350-iRi1NOntsTnG.jpg', 'series', '7.4', 'Doremi Harukaze, 3rd grade student at Misora Elementary School, claims to be the world''s unluckiest pretty girl. Fascinated by witchcraft, she is drawn into a mysterious shop where she meets Majo Rika and is able to deduce that this lady is in fact a real witch. Being exposed by a human triggers a curse that transforms witches into magical frogs. To regain her original body, Rika must turn Doremi into a witch by teaching her how to use magic. Thrilled by this odd development, Harukaze becomes a witch apprentice. Unfortunately, her two best friends, Hazuki Fujiwara and Aiko Senoo, discover that Doremi has become a magic user. Afraid that Harukaze might become a magical frog too, Majo Rika recruits both Hazuki and Aiko and makes them witch apprentices too. The trio has lots of adventures as they try to triumph the necessary trials to become real witches.

(Source: Anime News Network)', 'Toei Animation', '1999', 'series', 'released', '1999-02-07', 350, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/350-oGY6MInyVjpO.jpg', 'Comedy, Drama, Fantasy, Mahou Shoujo, Slice of Life', 'TV', 'WINTER', 51, 20801, 'https://www.youtube.com/watch?v=OOMEDE2BHwM', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2216, 'Dog of Flanders', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2623-PQhbDjaUfnpd.jpg', 'movies', '7.4', 'Set in 19th-century Belgium, this classic tale, based on the Flemish novel by Oui''da, celebrates the affectionate bond between an innocent boy and his faithful dog. The stunning animation, a masterful combination of traditional and computer-aided animation, captures the natural splendor of the Flanders countryside and recreates the spirit of this classic story that has captivated audiences world wide for more than 130 years. In fact, the popularity of The Dog Of Flanders led the local Belgian government of Flanders to dedicate a statue to Nello and Patrash in 1985, immortalizing their devotion to each other. 

(Source: AniDB)', 'Nippon Animation', '1997', 'movie', 'released', '1997-03-15', 2623, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2623-0yW6KqklcIiE.jpg', 'Drama, Slice of Life', 'MOVIE', 'SPRING', 1, 6455, 'https://www.youtube.com/watch?v=UDKi4tlkSV0', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2217, 'Hidamari no Ki', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx2694-dwv7yXbOb8n2.png', 'series', '7.4', 'A story set in the mid-1800''s about a young doctor who has been trained in Western-style medicine and a young samurai who is trying to live up to the old traditions of his class and culture. The story is actually based upon real people - the doctor, Ryo-an, was Tezuka''s great grandfather.

During the Second Year of Ansei (1855) in Edo''s Koishigawa are two young men, Manjiro Ibutani and Ryoan Tezuka. Ibutani is a low-ranking samurai who is a gifted swordsman and has a straightforward and strong sense of justice. Tezuka has a more carefree attitude. He has an eye for the ladies, but he is passionate about becoming a doctor. The two opposite characters come of age during the backdrop of the turbulent end of the Tokugawa Period (1600-1868 CE).

(Source: AnimeNfo)', 'MADHOUSE', '2000', 'series', 'released', '2000-04-05', 2694, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n2694-Ui6A4TXJI4ow.jpg', 'Drama', 'TV', 'SPRING', 25, 3388, 'https://www.youtube.com/watch?v=c2bZ6mF3bWw', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2218, 'MASTER Keaton', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1483-LXbJYimBXUmF.png', 'series', '7.3', 'Taichi Keaton is a half-British half-Japanese archeologist and SAS veteran of the Falklands War. He solves mysteries and investigates insurance fraud for Lloyd''s around the world.

(Source: Anime News Network)', 'MADHOUSE', '1998', 'series', 'released', '1998-10-06', 1483, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1483-pVF4OSzVuKI5.jpg', 'Adventure, Drama, Mystery', 'TV', 'FALL', 24, 10530, 'https://www.youtube.com/watch?v=NSKRIJn7Uu8', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2219, 'Neon Genesis Evangelion: Death & Rebirth', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx31-3zRThtzQH62E.png', 'movies', '7.3', 'Compilation recap movie for the series Shin Seiki Evangelion. Due to the struggling production of the movie ''End of Evangelion'' delaying the film a month before it was set to release, this film was announced to ''hold fans over''.

During the early 21st century a meteorite crashed into Antarctica. After scientists went to study the crash a gigantic explosion followed, classified as the ''Second Impact''. Shinji Ikari is a fourteen year-old boy who has come to Toyko3, a city that also serves as a fortress, to meet up with his father who left him many years ago. The city also happens to be under siege by monstrous creatures called ''Angels'' at the time of his arrival. Somehow Shinji finds himself in Evangelion Unit 01, and manages to synchronize with the giant robot. Shinji is told to become its permanent pilot, and is thrown into combat as the city''s last defense for fighting off the angels. However, as Shinji fights, he begins to realize the truth behind the Angels, the Second Impact, man''s struggle against God and what he truly is afraid of. 

(Source: Anime News Network)

Note: Exists in several versions: (with most appearing on the Japanese 2015 Blu-ray Boxset)

• Evangelion: DEATH & REBIRTH, released theatrically on March 15, 1997 - 2-part feature, the first 2/3rds titled ''Death'' consisting of a recap of the TV series with new/re-drawn animation added in, and the later 1/3rd titled ''Rebirth'' consisting of the first 28 minute rough cut of End of Evangelion.

• Death(True), aired on TV channel WOWOW on January 2, 1998 - re-edited version of ''Death'' by director Masayuki, with most of the new animation cut (as it was moved to the "Directors Cut" of Episodes 21-24), but with some new shots added. Later released on the ''ARCHIVES OF EVANGELION'' DVD Boxset.

• Death(True)², released on March 7, 1998 - a further edited down version of Death(True), but with some new animation added. Regarded as this film''s ''definitive'' release, this is the version opted to be licensed by Netflix.

• Revival of Evangelion, released theatrically on March 8, 1998 - Theatrical double feature consisting of Death(True)² + 4 minute intermission + End of Evangelion.

For simplicity''s sake, we are only counting the first theatrical release in this entry.', 'Gainax', '1997', 'movie', 'released', '1997-03-15', 31, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/31-pYM5NdKIRa5h.jpg', 'Drama, Mecha, Psychological, Sci-Fi', 'MOVIE', 'WINTER', 1, 60972, 'https://www.youtube.com/watch?v=sZwPBcnOk5c', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2220, 'Vision of Escaflowne', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx182-YzZtZWMZCSFf.png', 'series', '7.3', 'High school student Hitomi is transported from Earth to the magical world of Gaea, where she meets boy prince Van Fanel, and is caught up in his quest to unite the countries of Gaea against the ominous Zaibach empire. On the way, she discovers an hidden ability and strives to unravel layers of mystery surrounding Van, his past, and the giant machine known as Escaflowne. 

(Source: Anime News Network)', 'Sunrise', '1996', 'series', 'released', '1996-04-02', 182, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/182-jYvvtYE14yi4.jpg', 'Adventure, Fantasy, Mecha, Romance', 'TV', 'SPRING', 26, 40116, 'https://www.youtube.com/watch?v=YNTYLr3PF-A', '2026-08-29 14:42:14', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2221, 'You''re Under Arrest! (TV)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1372-Q1B078xXbu2c.png', 'series', '7.3', 'Tokyo Highway Patrolwomen Natsumi and Miyuki get off to a bad start when Miyuki busts Natsumi for reckless moped driving on her way to work. Things get worse when they find out they''re going to be partners!

A continuation of the OVA series, the adventures of Tokyo policewomen Natsumi and Miyuki continue in the You''re Under Arrest TV series. It''s back to Bokuto Precinct, where demented felons and bashful (but hunky) policemen abound, and where the cutest girl in the office... isn''t a girl.

(Source: Rightstuf)', 'Studio DEEN', '1996', 'series', 'released', '1996-10-05', 1372, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1372-DIm7PIn23odp.jpg', 'Action, Comedy', 'TV', 'FALL', 47, 13148, 'https://www.youtube.com/watch?v=86G1cGR616k', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2222, 'Martian Successor Nadesico', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx218-qBfbgiJIR5rv.jpg', 'series', '7.3', 'Akito doesn''t want to fight. Despite a childhood spent on the anime Gekiganger 3, a Mecha show, he''d rather cook than pilot a Mecha. Fate intervenes when his home on Mars is destroyed, and he is transported instantly to the Earth, mysteriously. He has questions no one can answer fully, but follows a girl from a chance meeting in hopes to discover any. The girl, Yurika, is captain of the private battleship Nadesico, and in order to follow her, he enlists as their cook. Possessing the nanite implants that allow to control mechas, he''s a handy backup pilot for the mechas of the Nadesico. He joins a crew bent on revenging Mars and composed of misfits, otakus, and ditzes. But in reality they are handpicked experts. They take their own private war back to Mars to face the harsh reality that life may not always be like a Giant Mecha Series.

(Source: Anime News Network)', 'Xebec', '1996', 'series', 'released', '1996-10-01', 218, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/218-CTDP41ygFQpU.jpg', 'Action, Comedy, Mecha, Romance, Sci-Fi', 'TV', 'FALL', 26, 17051, 'https://www.youtube.com/watch?v=kejcHP1AI8M', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2223, 'Mobile Suit Gundam Wing: Endless Waltz', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx91-YkrzbtuWZThG.png', 'series', '7.2', 'After Colony 196 - One year has passed since the war between Earth and its colonies ended. Heero, Duo, Trowa and Quatre bid farewell to their Gundams and jettison them to the sun. Relena Darlian is now the deputy minister of the Earth Sphere Unified Nation. But as the Gundam pilots are adjusting to the peace on Earth, Relena is kidnapped and a new threat appears, led by Marimeia Khushrenada - daughter of the late dictator Treize Khushrenada and heir to the Barton Foundation. To make matters more complicated, Gundam Nataku pilot Wufei has sided with this faction. The Gundam pilots must recover their mobile suits and once again engage in battle before Marimeia''s forces succeed on their bid for global domination.

(Source: Anime News Network)', 'Sunrise', '1997', 'series', 'released', '1997-01-25', 91, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n91-kLkJ0iJHHutY.jpg', 'Action, Drama, Mecha, Sci-Fi', 'OVA', 'WINTER', 3, 9250, 'https://www.youtube.com/watch?v=90REc5yGl40', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2224, 'Banner of the Stars', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx396-Lgdv4FWS5c1J.jpg', 'series', '7.3', 'Three years after their adventure, Lafiel becomes captain on the brand new assault ship Basroil and Jinto finishes his training to become a supply officer and joins Lafiels crew. They set out to join a large fleet with the mission of defending the strategically important Laptic Gate from a force 15 times larger than their own. And to bring even more worries, their new fleet commander is from the Bebous family, a family notorious for their "Spectacular Insanity". 

(Source: Anime News Network)', 'Sunrise', '2000', 'series', 'released', '2000-04-14', 396, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/396-rMh3OJifKec8.jpg', 'Action, Romance, Sci-Fi', 'TV', 'SPRING', 13, 8625, 'https://www.youtube.com/watch?v=eaiEfm8TWdo', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2225, 'Shin Seiki GPX Cyber Formula SIN', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1395-Re2tukLzSHyX.png', 'series', '7.3', 'After Aoi Zip Formula was banned for one year from Cyber Formula racing due to cheating, Jotaro Kaga, alias Bleed Kaga, returns for the 17th Cyber Formula World Grand Prix. However his old car is no match for the returning champion Hayato Kazami, whose skill has improved tremendously, and his Nu-Asurada AKF-0. An old face, Kyoshiro Nagumo, appears suddenly to him and offers him the Ogre AN-21: a prototype to the Bio-Computer operated Al-Zard series created by the developers of the Asurada, and an ultimate racing machine that only a few can drive. Kaga must now master this car, confront his own inner demons and, most importantly, defeat his longtime rival Hayato in what is possibly Kaga''s last and greatest Cyber Formula season.

(Source: Anime News Network)', 'Sunrise', '1998', 'series', 'released', '1998-12-21', 1395, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', NULL, 'Drama, Sci-Fi, Sports', 'OVA', 'WINTER', 5, 1280, 'https://www.youtube.com/watch?v=X6M9bGJu13s', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2226, 'Now and Then, Here and There', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx160-t5rKPAhZoznO.jpg', 'series', '7.3', 'Shu is a typical Japanese boy, but has an unbeatable, optimistic and determined attitude. However, when he sees a mysterious girl with strange eyes named Lala-Ru up on a smokestack, he is soon pulled into a strange desert world. Shu soon discovers the true terrors of war, which includes genocide, brutal torture, hunger, thirst, and child exploitation. Now Shu is trying to save Lala-Ru, as well as his hard earned, and often relunctant, new friends from the insane dictator, Hamdo. Whether Shu can possibly accomplish saving those he cares about while still holding up to his values remains to be seen. 

(Source: Anime News Network)', 'AIC', '1999', 'series', 'released', '1999-10-14', 160, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/160-LbiEyoQyuDaL.jpg', 'Adventure, Drama, Fantasy, Sci-Fi', 'TV', 'FALL', 13, 43049, 'https://www.youtube.com/watch?v=lWbWGbFb5Rk', '2026-08-29 14:42:11', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2227, 'Crest of the Stars', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx290-Bf2q1HYyKbNG.png', 'series', '7.3', 'Based on a science fiction novel series, Crest of the Stars (Seikai no Monsho) is the first installment in this sci-fi saga. The story follows Jinto, whose world was taken over by the largest empire in the galaxy: the Abh. Jinto''s father, the planet''s prime minister, handed their world over to the Abh in exchange for a standing in the Abh Empire. As a result, Jinto became a prince and was shipped off for an Abh Education. There he meets a princess of the Abh Empire, Lafiel, whom he quickly befriends despite her cold exterior. The Abh Empire is plunged into war soon after and the story continues from there...

(Source: Anime News Network)

Note: The last episode aired with a runtime of ~40 minutes as opposed to the standard 24 minute long episode.', 'Sunrise', '1999', 'series', 'released', '1999-01-02', 290, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/290-JQTwwUpBJy3a.jpg', 'Action, Romance, Sci-Fi', 'TV', 'WINTER', 13, 15631, 'https://www.youtube.com/watch?v=USfnl9odiJ8', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2228, 'City Hunter: Goodbye My Sweetheart', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1478-xW2v7RWLlJcJ.png', 'series', '7.3', 'Ryo Saeba (aka the City Hunter), is a private detective in the city of Tokyo. Together with sidekick Kaori Makimura, Ryo is hired by actress Emi Makaze to find her long lost brother. The woman''s brother turns out to be "The Professor", a dillusional ex-soldier who''s planing to destroy the Shinjuku district of Tokyo. Kaori is assigned to guard Emi, but they both get caught up in the Professor''s scheme. The City Hunter must save them, without allowing downtown Tokyo to be destroyed.

(Source: Anime News Network)', 'Sunrise', '1997', 'series', 'released', '1997-04-25', 1478, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1478-zixGGSc3fTVy.jpg', 'Action, Adventure, Comedy', 'SPECIAL', 'SPRING', 1, 2549, 'https://www.youtube.com/watch?v=5CCJdrgCClU', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2229, 'Shoubushi Densetsu Tetsuya', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx3369-N4fANXl5ehw3.jpg', 'series', '7.3', 'In the year 1947, the people of Shinjuku are down on their luck. With little money to buy food or necessities, some resort to gambling in order to survive. Traveling Tetsuya chooses to spend his time at Mahjong parlors where he is wiping the floor clean with his adversaries. However, when Tetsuya meets the intensely skilled Boushu-san, he realizes that his skills are still lacking.

(Source: Anime News Network)', NULL, '2000', 'series', 'released', '2000-10-07', 3369, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', NULL, 'Sports', 'TV', 'FALL', 20, 4144, 'https://www.youtube.com/watch?v=kPd0FmQKh1c', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2230, 'You''re Under Arrest! The Motion Picture', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2013-E5l2Xf9KTAgk.jpg', 'movies', '7.2', 'The hard-working men and women of the Bokuto Traffic Corps are back on the scene,​ but this time they''ve got more to worry about than everyday traffic violations! During a routine arrest,​ they recover a secret document detailing step-by-step instructions to terrorists on how to wipe Tokyo off the map! Even the precinct station isn''t safe from the bloodthirsty murderers that want this information,​ or from the rogue who wrote it.​

Can Miyuki and Natsume rally their fellow officers in time to save themselves and the city?​!

(Source: ADV Films)', 'Studio DEEN', '1999', 'movie', 'released', '1999-04-29', 2013, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', NULL, 'Action, Comedy, Drama', 'MOVIE', 'SPRING', 1, 3540, 'https://www.youtube.com/watch?v=86G1cGR616k', '2026-08-29 14:42:20', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2231, 'Infinite Ryvius', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx593-LrgjfzlPADYF.jpg', 'series', '7.2', 'The year is AD 2225. Kouji Aiba and Aoi Housen are serving as astronauts in-training in Liebe Delta which is located on the edge of the Geduld Sea. When saboteurs with unknown intents suddenly strike during a routine dive procedure, the space station plummets into the Geduld, a plasma field that links all the planets like a nervous system and crushes any ship that strays too far into it. With all the adults onboard killed, the young astronauts will have to survive this long journey home in midst of the growing tension amongst each other. Meanwhile the organizers of the sabotage look on and prepare to attack once more.', 'Sunrise', '1999', 'series', 'released', '1999-10-06', 593, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/593-cXeyj6YXU24n.jpg', 'Drama, Mecha, Psychological, Sci-Fi', 'TV', 'FALL', 26, 12985, 'https://www.youtube.com/watch?v=lTQuutHV1Y0', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2232, 'Ah! My Goddess: The Movie', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx304-p9BSB5gOwZRO.jpg', 'movies', '7.2', 'For centuries, a god named Celestin has been imprisoned on the moon for betraying the kingdom of Yggdrasil. Released by the fairy Morgan Le Fey, Celestin travels to Earth to reunite with his former pupil, the goddess Belldandy. Things go awry as Celestin erases Belldandy''s memories of her boyfriend Keiichi and uses her as a catalyst to wreak havoc on Earth and Yggdrasil.', 'AIC', '2000', 'movie', 'released', '2000-10-21', 304, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/304-9kJAo9F0Pnco.jpg', 'Drama, Romance, Supernatural', 'MOVIE', 'FALL', 1, 7431, 'https://www.youtube.com/watch?v=m-FFXfnpEt4', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2233, 'Black Jack: The Movie', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b1521-maDvpcEJAbQi.jpg', 'movies', '7.2', 'Jo Carol Brane attempts to hire Dr. Black Jack on a breed of superhumans that have the strength, intellectual, athletic, and artistic skills with great excel in different fields, only to later find out that they start deteriorating after some period of time and causing an untimely death. Jo needs Dr. Black Jack''s help on finding a cure.

(Source: Anime News Network)', 'Tezuka Productions', '1996', 'movie', 'released', '1996-11-30', 1521, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n1521-tYYDE7puIKYp.jpg', 'Drama, Mystery, Thriller', 'MOVIE', 'FALL', 1, 4228, 'https://www.youtube.com/watch?v=WZOLdrXMg0A', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2234, 'Crayon Shin-chan: Jungle That Invites Storm', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/8362.jpg', 'movies', '7.2', 'The Nohara family is on a cruise heading towards a tropical island when suddenly the ship is invaded by a large group of monkeys. The simians capture all adults and take them to a nearby isle while leaving all children behind. It is up to Shin-chan and his friends to find and save the grown-ups.

(Source: Anime News Network)', NULL, '2000', 'movie', 'released', '2000-04-22', 8362, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Comedy, Slice of Life', 'MOVIE', 'SPRING', 1, 3658, 'https://www.youtube.com/watch?v=K5g266s8Cwc', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2235, 'After War Gundam X', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx92-QICvHYE9HKyq.png', 'series', '7.2', 'When one space colony declared its independence from the Earth Federation, the devastating 7th Space War, an all-out war between Earth and space, resulted. The Federation responded to the Space Revolutionary Army with mobile suits, called Gundams. However, the Space Revolutionary forces played their trump card and dropped hundreds of space colonies onto the Earth, plunging the planet into a seven-year-long nuclear winter. The Federation collapsed, but the Space Revolutionary Army was unable to invade the Earth in the aftermath of the colony drop. Fifteen years have passed. The year is now After War 0015, and a New Federation has sprung up on Earth to restore order. In space, the colonial leaders have been rebuilding their own forces as well. By chance, fifteen-year-old Garrod Ran has discovered an old Federation mobile suit, the Gundam X, and now he uses it to help out the Vulture ship Freeden in its struggle to keep the powers that be from repeating the mistakes of the past.', 'Sunrise', '1996', 'series', 'released', '1996-04-05', 92, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/92-BjCXeUSzsW3Q.jpg', 'Adventure, Drama, Mecha, Sci-Fi', 'TV', 'SPRING', 39, 11126, 'https://www.youtube.com/watch?v=M1rWkAjgLp8', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2236, 'Jigoku Sensei Nube', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/2012.jpg', 'series', '7.2', 'Nube is a clumsy, easygoing, and very kind teacher, but he has a secret under his glove on the left hand. He has a monster hand, and he also has the ability to sense ghosts and evil spirits. So he protects his dear students from these evil spirits with his monster hand, proving to be very powerful.

(Source: Anime News Network)', 'Toei Animation', '1996', 'series', 'released', '1996-04-13', 2012, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2012-8BtBvNe85st0.jpg', 'Adventure, Comedy, Horror, Romance', 'TV', 'SPRING', 49, 6726, 'https://www.youtube.com/watch?v=s94P7jmEspQ', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2237, 'Daa! Daa! Daa!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/233.jpg', 'series', '7.2', 'Miyu is an 8th grade girl, whose parents have been hired by NASA. They take off to America leaving Miyu with Mr. Saionji. Later, Mr. Saionji decides to go on a 1 year long trip to India leaving Miyu alone with his son, Kanata. More complications rise when an Alien baby and his babysitter pet crashes/lands in their house. To make things worse, alien baby starts calling Miyu and Kanata Mom and Dad, also showing ESP power and floating around.

(Source: Anime News Network)', 'J.C.STAFF', '2000', 'series', 'released', '2000-03-28', 233, 0, NULL, '2026-07-25 18:55:50', '2026-09-02 16:57:33', NULL, 'Comedy, Sci-Fi', 'TV', 'SPRING', 78, 5081, 'https://www.youtube.com/watch?v=RVdfo8cqPyM', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2238, 'Crayon Kingdom of Dreams', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b4651-3zo9cw2VAZrc.jpg', 'series', '7.2', 'The civilians of the Crayon Kingdom have always view their Princess Silver as a twelve-year old girl with a beautiful smile. However, unknown to them, the princess has 12 bad habits. This has created much distress to the Chameleon Prime Minister and the Crayon ministers for it would be embarassing if this gets out. One day, a party was held to celebrate Princess Silver''s twelvth birthday. The princess was trying to seek her Prince Charming that she forgot to take notice of her bad habits. One of the boys at the party was so angry that he changed Silver''s parents, the King and Queen, into stone. In order to break the curse and save her parents, Silver decided to set on a journey to locate the boy. Together with her companions, Silver begins her adventure.', 'Toei Animation', '1997', 'series', 'released', '1997-09-07', 4651, 0, NULL, '2026-07-25 18:55:51', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4651-fiym4yy0lZPg.jpg', 'Adventure, Comedy, Fantasy, Mahou Shoujo', 'TV', 'FALL', 70, 2313, 'https://www.youtube.com/watch?v=mWYbZPASnBE', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2239, 'Angel of Legend', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/5251.jpg', 'series', '7.2', 'Angel Densetsu is a story about Seiichirou Kitano, a kind and naive boy with the heart of an angel, but the sinister looks of a devil. This causes many misunderstandings, leading people to assume that he is a villain or heroin addict, and results in a career as the head thug, or "school guardian" at his new school.

(Source: Anime News Network)', 'Toei Animation', '1996', 'series', 'released', '1996-12-13', 5251, 0, NULL, '2026-07-25 18:55:51', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n5251-b3DVe686OFAM.jpg', 'Action, Comedy', 'OVA', 'WINTER', 2, 13623, 'https://www.youtube.com/watch?v=5ToYp_EJs40', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2240, 'Kamikaze Kaitou Jeanne', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx142-gcfapg9oM7Qv.jpg', 'series', '7.1', 'A normal looking high school girl on the outside, Kusakabe Maron is actually the reincarnation of Jeanne d'' Arc. With the help of the angel, Fin Fish, Maron works as the thief Jeanne at night to seal the demons that reside in pieces of artwork, preying upon the weak hearts of the owners. She is branded as a thief due to the fact that the artworks disappear after she seals the demons. One day, a new neighbor and classmate appears, as well as a rival in her night job, the thief Sinbad. With her own best friend being the detective''s daughter, out to capture her and the appearance of her new rival, Maron''s work is anything but easy.', 'Toei Animation', '1999', 'series', 'released', '1999-02-13', 142, 0, NULL, '2026-07-25 18:55:51', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/142-hNFax75P14AQ.jpg', 'Action, Adventure, Comedy, Drama, Fantasy, Mahou Shoujo, Mystery, Romance, Supernatural', 'TV', 'WINTER', 44, 11060, 'https://www.youtube.com/watch?v=dzmc_4BMbBM', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2241, 'Tenchi Muyo! In Love', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/n1006-A3i2EkdddUYv.png', 'movies', '7.1', 'The demonic space criminal Kain has escaped from prison and destroyed the Galaxy Police headquarters. To ensure that the Jurai will not stop him, Kain travels back to 1970 to eliminate Tenchi''s mother before he is even born. Now, Tenchi and the gang must travel to the past to stop him before he ceases to exist. 

(Source: Anime News Network)', 'AIC', '1996', 'movie', 'released', '1996-04-20', 1006, 0, NULL, '2026-07-25 18:55:51', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n1006-TkltpSRSM2wp.jpg', 'Action, Comedy, Romance, Sci-Fi', 'MOVIE', 'SPRING', 1, 5064, 'https://www.youtube.com/watch?v=64god8mkykM', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2242, 'Shin Seiki GPX Cyber Formula SAGA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b1394-aHsNABOX0rgH.jpg', 'series', '7.1', 'After his disappointing loss in the last round of the 14th Cyber Formula World Grand Prix, which causes him the championship, Hayato Kazami decides that he needs a change and switches over to the Sugo Garland SF-03 for the 15th Cyber Formula World Grand Prix while he waits for the newest Asurada design. However, his hope to make up for the past year''s letdown is made difficult when Aoi ZIP Formula undergoes a major restructuring and brings in Kyoshiro Nagumo as the new president of the team. The new car that he brought to the team, driven by newcomer Phil Fritz, is seemingly unbeatable...

(Source: Anime News Network)', 'Sunrise', '1996', 'series', 'released', '1996-08-01', 1394, 0, NULL, '2026-07-25 18:55:51', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1394-WSQVrXlK5FUZ.jpg', 'Drama, Sci-Fi, Sports', 'OVA', 'SUMMER', 8, 1275, 'https://www.youtube.com/watch?v=X6M9bGJu13s', NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (2243, 'Rurouni Kenshin The Movie', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx46-Steq4sQpA6fq.png', 'movies', '7.1', 'The war against the Tokugawa Shogunate ended years ago. But there are some who are not happy with the outcome. Shigure Takimi watched his friends and family get slashed down in the name of freedom and prosperity. Now he and a band of desperate rebels have sworn to settle one final score. Only one man stands in their way: Kenshin Himura. But when Shigure discovers Kenshin''s true identity as the Hitokiri Battousai, his fight becomes a personal vendetta.

(Source: Anime News Network)', 'Studio Gallop', '1997', 'movie', 'released', '1997-12-20', 46, 0, NULL, '2026-07-25 18:55:51', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n46-xV61YAKDm0lT.jpg', 'Action, Drama', 'MOVIE', 'FALL', 1, 9109, 'https://www.youtube.com/watch?v=eAA1ZDSCWjI', NULL, NULL);
