INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3143, 'Mairimashita! Iruma-kun: If Episode of Mafia', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx207251-9HLT5632FOMw.jpg', 'coming', '0.0', 'In this brand-new spinoff of the runaway hit series, Iruma is a dirt-poor but kind young boy who grows up in a ruthless city slum. One day, Iruma gives a severely injured old man his last loaf of bread and nurses the stranger back to health—only to find out that the elder gent is none other than Don Sullivan, leader of the Babel Mafia! Soon after, Don Sullivan comes back, whisks Iruma away, and begs the boy to become his grandson. And just like that, the curtains rise on Iruma’s chaotic new life as the next in line to a gigantic gang of—dare we saydemonic mafiosos!

(Source: Kodansha USA)', NULL, '2027', 'series', 'upcoming', '2027-01-01', 207251, 0, NULL, '2026-07-25 19:21:42', '2026-09-03 15:46:26', NULL, 'Action, Comedy', 'TV', 'WINTER', NULL, 3757, NULL, '2026-09-03 15:46:26', NULL);
