INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3183, 'Overlord', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20832-vUNm5zrYWifc.jpg', 'series', '7.7', 'The story takes place in the year 2138 when virtual reality gaming is booming. Yggdrasil, a popular online game is quietly shut down one day. However, the protagonist Momonga decides to not log out. Momonga is then transformed into the image of a skeleton as "the most powerful wizard." The world continues to change, with non-player characters (NPCs) beginning to feel emotion. Having no parents, friends, or place in society, this ordinary young man Momonga then strives to take over the new world the game has become.

