INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3191, 'HELLSING: THE DAWN', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/11077.jpg', 'series', '6.8', 'It is September 1944 and World War II is raging in Europe. To get an advantage on the field, Nazis are experimenting with artificial vampire technologies, they are still far away from achieving their initial goal, but even the intermediate stages of such researches are possesing a great threat to The anti-German coalition. In an attempt to stop the Nazi project and to protect England and The Allies current head of the Hellsing House, Sir Arthur Hellsing, is sending his best agents&mdash;Walter C. Dornes and Alucard&mdash;into German-occupied Poland where monstrous experiments are being conducted.

Hellsing: The Dawn Specials can be found on the bonus discs, bundled with Hellsing Ultimate Limited Edition volumes starting from volume 8.', 'Graphinica', '2011', 'series', 'released', '2011-07-27', 11077, 0, NULL, '2026-07-26 13:04:07', '2026-09-03 16:19:02', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11077-97jUdM80FK2K.jpg', 'Action, Horror, Supernatural', 'SPECIAL', 'SUMMER', 3, 25365, NULL, '2026-09-03 16:19:02', NULL);
