INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3201, 'The Night is Short, Walk on Girl', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97917-bHtHhWkIsdR5.jpg', 'movies', '8.1', 'A black haired girl is walking around the streets of Kyoto, from the night scene of Pontocho to a second-hand book fair in Shimogamo, then off to a college fair. The main character that has a romantic feeling for her secretly follows her around and looks for the opportunities to run into her in a manner that seems like a coincidence. Unfortunately for him, she is not interested in love yet, so she does not notice his feelings. What awaits these two characters are a series of crazy incidents caused by bizarre individuals, such as a person who introduces himself as Tengu, the god of second-hand books, or a money lender, who collects young men''s underwear and lives on a three story barge.

(Source: Sugoi Japan, edited)', 'Science SARU', '2017', 'movie', 'released', '2017-04-07', 97917, 0, NULL, '2026-07-26 13:04:54', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97917-uCZnoaPrgOrf.jpg', 'Comedy, Romance', 'MOVIE', 'SPRING', 1, 52150, 'https://www.youtube.com/watch?v=tmeU9GFJW3I', '2026-08-29 14:55:30', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3202, 'The Tatami Time Machine Blues', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx137819-oAlpXHXPkNFV.png', 'series', '8.1', 'Spin-off of Yojouhan Shinwa Taikei.

It is August 12th. After the remote control to his boarding house''s only air conditioning unit is inadvertently destroyed by spilled cola, "I" devises a plan to return to yesterday in a time machine to recover the remote before it breaks. However, his friend Ozu cannot resist playing with past events, even when it means bringing the universe to the brink of destruction. Now "I" finds himself racing through time to avoid disaster.

(Source: Disney+)

Note: Released in Japan as a standalone film on September 30, 2022 with the same content as episodes 1-5. The anime has an earlier episodic release on Disney+ starting September 14, 2022 and with an exclusive episode 6.', 'Science SARU', '2022', 'series', 'released', '2022-09-14', 137819, 0, NULL, '2026-07-26 13:04:54', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/137819-cMk7KwtDMGE3.jpg', 'Comedy, Mystery, Psychological, Romance, Sci-Fi', 'ONA', 'SUMMER', 6, 25417, 'https://www.youtube.com/watch?v=nIc2dKhgJt4', '2026-08-29 14:55:27', NULL);
