INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3214, 'Mobile Police Patlabor: WXIII', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1290-EpimlnTcvT2i.png', 'movies', '6.3', 'When the level of Labor accidents begin to escalate around Tokyo Bay, police detectives Kusumi and Hata are assigned to investigate. What they discover leads to a series of government cover-ups, conspiracy concerning a new biological weapon entitled WXIII-Wasted Thirteen and a tragic, personal connection to Hata. The only hope to stop this threat is to cooperate with the military and lead WXIII into a showdown with the Labors of Special Vehicle Division 2. 

(Source: Anime News Network)

This Movie is a Side Story that takes place in between Patlabor Movie 1 and 2', 'MADHOUSE', '2002', 'movie', 'released', '2002-03-30', 1290, 0, NULL, '2026-07-26 13:05:08', '2026-09-03 16:20:49', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1290-mXuwA7p2aO2R.jpg', 'Mecha, Sci-Fi', 'MOVIE', 'SPRING', 1, 6157, NULL, '2026-09-03 16:20:49', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3215, 'Mini Pato', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx2733-B98BwsfbAdLy.jpg', 'series', '5.8', 'Comprised of 3 episodes that act simultaneously as a parody of other mecha anime and expand of the technology used in the Patlabor Series.

 

Episode 1 is a brief introduction to the weaponry carried by the Ingram, how it was designed and why it is the way it is. 

Episode 2 looks at the design and maintenance of the Ingram 98 AV in SVU2 and takes a swipe at the marketing forces behind them (as in merchandising for the series). 

Episode 3 is the only one to attempt to expand on a very minor point raised in the original TV show and just how SVU2 is actually funded.', 'Production I.G', '2002', 'series', 'released', '2002-03-30', 2733, 0, NULL, '2026-07-26 13:05:08', '2026-09-03 16:20:53', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2733-acGX4IDZkFX1.jpg', 'Comedy, Mecha, Sci-Fi', 'OVA', 'SPRING', 3, 1491, NULL, '2026-09-03 16:20:53', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3216, 'Yuu☆Yuu☆Hakusho Picture Drama', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/6964.jpg', 'series', '6.0', 'Yu Yu Hakusho Blu-ray Box Set will contain a picture drama with a new story that takes place after the final episode of the anime adaptation of Togashi Yoshihiro''s shounen manga.', NULL, '2009', 'series', 'released', '2009-10-27', 6964, 0, NULL, '2026-07-26 13:05:10', '2026-09-03 16:20:56', NULL, 'Action, Comedy', 'SPECIAL', 'FALL', 1, 4008, NULL, '2026-09-03 16:20:56', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3217, 'Yu Yu Hakusho: The Movie', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx882-3TdRv5W4DZaS.jpg', 'movies', '6.4', 'Yusuke Urameshi is not exactly what you''d call an angel. In fact, some might call him down right devilish. But when he dies in an accident trying to save a child, he finds himself in the Spirit World. Unfortunately for Yusuke, his name is not listed in the Book of Enma, which means it was one big mistake! So he should return from the Spirit World, but must pass a few tests first, and become a detective of the spiritual world.

So now Yusuke works in the Spirit World as a half-dead, half-alive agent for Koenma, son of the ruler of the Spirit World. This position does have its disadvantages, especially when you''re trying to enjoy your summer vacation and Koenma gets kidnapped! So now Yusuke must interrupt his summer fun to find Koenma and trade the Golden Seal of King Enma for his life. But if someone other then King Enma has the Golden Seal there will be chaos in the Spirit World! What''s a half-dead spirit detective to do?

With the aide of his closest allies, Yusuke sets off for Magma Valley, to save the life of the one who saved his, and find out who''s at the bottom of this evil conspiracy.

(Source: AnimeNfo)', 'Studio Pierrot', '1993', 'movie', 'released', '1993-07-10', 882, 0, NULL, '2026-07-26 13:05:10', '2026-09-02 16:57:33', NULL, 'Action, Adventure, Comedy', 'MOVIE', 'SUMMER', 1, 8486, 'https://www.youtube.com/watch?v=1BJR5cJz_ZU?t=8', '2026-08-29 14:57:04', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3218, 'Yu Yu Hakusho: Nightmare Hakusho', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx12455-EvQfYISlqB7X.jpg', 'series', '6.1', 'A four part OVA series about Yusuke''s weird dreams.', NULL, '1993', 'series', 'released', '1993-01-01', 12455, 0, NULL, '2026-07-26 13:05:10', '2026-09-02 16:57:33', NULL, 'Comedy', 'OVA', NULL, 4, 3643, 'https://www.youtube.com/watch?v=1BJR5cJz_ZU', '2026-08-29 14:57:01', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3219, 'Yu Yu Hakusho OVA: "Two Shots" and "All or Nothing"', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b102631-9VAe1wl7pIGc.png', 'series', '7.2', 'Special included in the 25th anniversary Blu-ray box set.

The special will cover the "Two Shot" bonus chapter from the manga''s seventh volume, which tells the story of how Kurama and Hiei met, as well as the manga''s penultimate chapter "All or Nothing." which shows the main characters reuniting to solve a hostage crisis in the spirit world.', 'Studio Pierrot', '2018', 'series', 'released', '2018-10-26', 102631, 0, NULL, '2026-07-26 13:05:10', '2026-09-03 16:21:00', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/102631-ksj6NOCUBPcd.jpg', 'Action, Adventure, Comedy, Supernatural', 'SPECIAL', 'FALL', 1, 7894, NULL, '2026-09-03 16:21:00', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3220, 'Mr. Tonegawa: Middle Management Blues', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101161-CrSXo1LfBx0D.jpg', 'series', '6.9', 'Teiai Group is one of Japan''s largest firms. Yukio Tonegawa, a man with a larger-than-life presence and sharp intellect, works as the right-hand man of Chairman Kazutaka Hyodo. One day, the chairman commands Tonegawa to spearhead "Game of Death," an evil project that employs debtors. He rallies his direct reports and scrambles to form Team Tonegawa, only to encounter a barrage of challenges from the erratic chairman and his disloyal employees, ultimately leading to his demotion.

Team Tonegawa is bombarded with an onslaught of wide-ranging problems! "Mr. Tonegawa - Middle Management Blues -" is a spinoff of "Kaiji," the hit manga series that boasts a total circulation of over 20 million printed copies.

(Source: Nippon TV)

Note: Episode 14-15, parts of 18, and parts of 20-23 of this entry adapts the Kaiji spin-off manga Ichinichi Gaishutsuroku Hanchou.', 'MADHOUSE', '2018', 'series', 'released', '2018-07-04', 101161, 0, NULL, '2026-07-26 13:05:12', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n101161-t9qcVEqlU7P1.jpg', 'Comedy, Drama, Psychological', 'TV', 'SUMMER', 24, 15307, 'https://www.youtube.com/watch?v=alnDkQQ_Y-A', '2026-08-29 14:57:07', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3221, 'THE FIRST SLAM DUNK', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx128207-SWpfVJMRfQ9X.jpg', 'movies', '8.7', 'Shohoku''s “speedster” and point guard, Ryota Miyagi, always plays with brains and lightning speed, running circles around his opponents while feigning composure. Born and raised in Okinawa, Ryota had a brother who was three years older. Following in the footsteps of his older brother, who was a famous local player from a young age, Ryota also became addicted to basketball.

In his second year of high school, Ryota plays with the Shohoku High School basketball team along with Sakuragi, Rukawa, Akagi, and Mitsui as they take the stage at the Inter-High School National Championship. And now, they are on the brink of challenging the reigning champions, Sannoh Kogyo High School.

(Source: GKIDS)', 'Toei Animation', '2022', 'movie', 'released', '2022-12-03', 128207, 0, NULL, '2026-07-26 13:05:14', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/128207-NogeWbSs2SpJ.jpg', 'Sports', 'MOVIE', 'FALL', 1, 31559, 'https://www.youtube.com/watch?v=0GGMhcs2v8Q', '2026-08-29 14:57:10', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3222, 'Chihayafuru 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14397-k2mzAGlUthAb.jpg', 'series', '8.3', 'Now in their second year of high school, Chihaya and her friends share all the fun and worries that come with welcoming underclassmen to the team as they face tough rival schools. The passion of the Mizusawa Karuta Club burns hotter than ever, but with the same refreshing, youthful mood carrying over from the first season.

(Source: Crunchyroll)', 'MADHOUSE', '2013', 'series', 'released', '2013-01-12', 14397, 0, NULL, '2026-07-26 13:05:16', '2026-09-03 16:21:04', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/14397-pJUA9iF0p4JY.jpg', 'Drama, Romance, Slice of Life, Sports', 'TV', 'WINTER', 25, 56686, 'https://www.youtube.com/watch?v=GKuHlE7-H00', '2026-09-03 16:21:04', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3223, 'Kamisama Hajimemashita OVA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx18661-HkN94pt43WUQ.jpg', 'series', '7.8', 'Two OVA episodes bundled with the 16th volume of the manga.


One of the included episodes will be based on the story from the 15th volume, while the other will contain an all-new original story.

(Source: Anime News Network)', 'TMS Entertainment', '2013', 'series', 'released', '2013-08-20', 18661, 0, NULL, '2026-07-26 13:05:17', '2026-09-03 16:21:07', NULL, 'Comedy, Fantasy, Romance, Supernatural', 'OVA', 'SUMMER', 2, 25088, NULL, '2026-09-03 16:21:07', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3224, 'Kamisama Kiss◎', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20801-2wtvmLpaM8hY.jpg', 'series', '8.2', 'The second season of Kamisama Hajimemashita

Nanami Momozono and her familiars Tomoe and Mizuki have survived quite a few challenges since Nanami took up the mantle of Mikage Shrine''s patron god. Naturally, the wind god Otohiko comes to invite Nanami to the Divine Assembly in Izumo, the home of the gods, and Nanami chooses to take Mizuki with her, leaving Tomoe to pose as her at school. However, she has an ulterior motive for attending the Divine Assembly: to discover the whereabouts of the missing Lord Mikage, the former god of the shrine.

After her adventures in Izumo, Nanami meets Botanmaru, a tengu child looking for someone she knows all too well—tengu turned goth idol Shinjirou Kurama. Botanmaru needs Shinjirou, their prince, to return home to Mount Kurama and stop the tyranny of Jirou, who has taken over the rule of their hometown. However, Nanami soon discovers a force much darker than Jirou is at work on the mountain.

As a fledgling god becoming more accustomed to divinity, Nanami finds herself dealing with a tengu rebellion, her blooming feelings for Tomoe, and a strange man with ties to both Tomoe''s past and Nanami''s future.

(Source: MAL Rewrite)', 'TMS Entertainment', '2015', 'series', 'released', '2015-01-06', 20801, 0, NULL, '2026-07-26 13:05:17', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20801-XpbvG91zj2fl.jpg', 'Comedy, Fantasy, Romance, Supernatural', 'TV', 'WINTER', 12, 91831, 'https://www.youtube.com/watch?v=ZMNdV7y7q1A', '2026-08-29 14:57:12', NULL);
