INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3249, 'Magi: Adventure of Sinbad', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21394-yauvzIHGAoZv.jpg', 'series', '7.7', 'Fifteen years before the events of Magi, a brave and handsome young man named Sinbad set sail and started his adventure. The future High King of Seven Seas gradually matured through various encounters and farewells, taking him towards kingship step by step.

(Source: Anime News Network)', 'Lay-duce', '2016', 'series', 'released', '2016-04-16', 21394, 0, NULL, '2026-07-26 13:06:05', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21394-wQkxIEAup8aT.jpg', 'Action, Adventure, Fantasy', 'TV', 'SPRING', 13, 117828, 'https://www.youtube.com/watch?v=ckdGtN-3GiE', '2026-08-29 14:58:12', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3250, 'Fate/Grand Carnival', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx127149-7dzvudxMb9ep.jpg', 'series', '7.5', 'Series focused on parodies and stories based on Fate/Grand Order.

Episodes:

1) The First Singularity Party 

As more and more Servants join Chaldea, maintaining resources for so many is becoming a problem. And so, a cruel order has been given... 

2) The Second Singularity Party 

Jeanne d’Arc Alter needs a serious amount of QP because of reasons, so she heads to the Kabukicho Singularity, the glittering gem of the nightlife scene, where she begins working at CLUB M. There, she hopes to become the best in town! However, she must first contend with a slew of troublesome customers, as well as the Four Elite hosts. 

3) The Third Singularity Party

"The Security Organization for the Preservation of Humanity, Fenis Chaldea." 

Here, a large number of Servants gather, proudly spending their days under the command of their Master. However, the Servants face a secret problem... They are divided by a sense of inequality. Longer waits between deployment, levels never being raised...
Reality hits the Servants hard, and frustrations gradually build up. In order to correct such disparities, one Servant steps up...

4) The Fourth Singularity Party, MAX Bond Channel

"I feel like Master''s been more cold to me recently." 

Ereshkigal feels some distance building between herself and Master. In order to increase her appeal, Dumuzid suggests something out of the ordinary: to use a video sharing platform called "ServantTube"! 

 Will Ereshkigal become a famous streamer and grab Master''s attention?

(Source: Aniplex)

Note: 1st Season released June 2, 2021 while 2nd Season released October 13th, 2021.

The first episode of "Season One" was pre-aired on the Fate Project New Year''s Eve TV Special 2020 program.', 'Lerche', '2021', 'series', 'released', '2021-06-02', 127149, 0, NULL, '2026-07-26 13:06:12', '2026-09-02 16:57:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/127149-GM94EEdeNcWh.jpg', 'Comedy, Fantasy, Supernatural', 'OVA', 'SPRING', 4, 21747, 'https://www.youtube.com/watch?v=8jXsIzO8_2s', '2026-08-29 14:58:18', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3251, 'Seitokai Yakuindomo Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx20448-nJph1HFaaL2u.jpg', 'series', '7.5', 'They say that the more things change, the more they stay the same, and those words could not be more true for the student council of Ousai Private Academy. Though an entire year has passed—bringing the senior members to their final year of high school—not much has changed. President Shino Amakusa is just as perverted as ever, Secretary Aria Shichijou still refuses to put on a pair of panties, Treasurer Suzu Hagimura has yet to grow an inch, and Vice President Takatoshi Tsuda is still stuck as the straight man to their crazy antics.

Of course, limiting the fun to a four-way might get a little stale; although the group still messes around with the Judo Club and the Newspaper Club, more girls have come to get in on the excitement. Takatoshi''s sister Kotomi, a new student at Ousai, is as perverse as the president, while Uomi, the aloof student council president of the nearby Eiryou High School, fits right in with the insanity at Ousai. With loads of absurdity and sexual humor that keeps on coming, Takatoshi needs to harden up if he is going to keep up with all the madness around him.

(Source: MAL Rewrite)', 'GoHands', '2014', 'series', 'released', '2014-01-04', 20448, 0, NULL, '2026-08-08 15:57:29', '2026-09-03 16:17:43', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20448-EzLC468PXSiN.jpg', 'Comedy, Slice of Life', 'TV', 'WINTER', 13, 55373, NULL, '2026-09-03 16:17:43', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3252, 'Sekai Ichi Hatsukoi - The World''s Greatest First Love', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx9926-AhRNkKBBbsNq.png', 'series', '7.0', 'Onodera Ritsu has just transferred from his father''s publishing company to Marukawa Shoten. Assigned to the shoujo manga division, he crosses path with the person he''d least expected to meet. Takano Masamune is the editor-in-chief of the division Ritsu''s been assigned to, and the two seem get off on the wrong foot right from the very start when Takano unexpectedly kisses him. However, there is more to than what meets the eye: Takano is actually Saga, Ritsu''s senpai and high school love, whom Ritsu had thought to have played him for a fool by taking his affections for granted when he confessed and summarily dumped him.', 'Studio DEEN', '2011', 'series', 'released', '2011-04-09', 9926, 0, NULL, '2026-08-08 15:57:31', '2026-09-03 16:21:57', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/9926-6ip6IrbvtFkT.jpg', 'Comedy, Romance', 'TV', 'SPRING', 12, 34196, NULL, '2026-09-03 16:21:57', NULL);
