INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3255, 'Beelzebub: Sakigake!! Beel to Shinsengumi', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/13067.jpg', 'series', '6.2', 'Short specials included in the DVDs (volumes 7-13) of Beelzebub.', 'Studio Signpost', '2011', 'series', 'released', '2011-12-21', 13067, 0, NULL, '2026-08-08 15:57:36', '2026-09-03 16:16:38', NULL, 'Action, Comedy, Supernatural', 'SPECIAL', 'WINTER', 7, 1182, NULL, '2026-09-03 16:16:38', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3256, 'Beelzebub: Hirotta Akachan wa Daimaou!?', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/9120.jpg', 'series', '6.9', 'The story follows the "strongest juvenile delinquent", Oga Tatsumi, a first year in "Ishiyama High" the school for delinquents. One day while sleeping next to a river he sees a man floating down it, he pulls him to shore and the man splits in half revealing a baby boy. This boy is the son of the demon king and he has been chosen as the one to raise it with the baby''s demon maid Hilda. The story follows his life with the child and at the delinquent school.

(Source: Wikipedia)', 'Studio Signpost', '2010', 'series', 'released', '2010-10-23', 9120, 0, NULL, '2026-08-08 15:57:36', '2026-09-03 16:16:41', NULL, 'Action, Comedy, Supernatural', 'SPECIAL', 'FALL', 1, 7325, NULL, '2026-09-03 16:16:41', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3257, 'Aikatsu! 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx20181-7Guz6yHESWQY.jpg', 'series', '7.7', 'Starlight Academy is facing a predicament thanks to the rise of the new rival idol training school, Dream Academy. The Dream Academy''s "cool beauty" Seira Otoshiro is a major new idol with talent in rock music and perfect pitch, while Kii Saekusa is a genius who enrolls in the academy''s producer course.

The two academies face off for the honor of training the top idol.

(Source: Anime News Network)', 'Sunrise', '2013', 'series', 'released', '2013-10-03', 20181, 0, NULL, '2026-08-08 15:57:38', '2026-09-03 16:16:45', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20181-C00qIlSy6S6e.png', 'Music', 'TV', 'FALL', 51, 4050, NULL, '2026-09-03 16:16:45', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3258, 'Aikatsu Friends!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx101043-zlDZ74rVpVPo.jpg', 'series', '7.1', '"Let''s go, together! Head for the goal, Diamond Friends!!"

The new anime will have a theme of "Aikatsu with your friends!" and will center on a new protagonist named Aine Yuuki, who is good at making friends, and is enrolled in Star Harmony Academy''s general education track. She befriends Mio Minato, the school''s top idol, and becomes an idol herself.

(Source: Anime News Network)', 'Bandai Namco Pictures', '2018', 'series', 'released', '2018-04-05', 101043, 0, NULL, '2026-08-08 15:57:38', '2026-09-03 16:16:48', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101043-fUBNXfvhBHEt.jpg', 'Music', 'TV', 'SPRING', 50, 5440, 'https://www.youtube.com/watch?v=jinurWYblbg', '2026-09-03 16:16:48', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3259, 'Aikatsu Stars!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx21648-n3I3CuDNiCXr.png', 'series', '7.6', 'Aikatsu Stars! features the protagonist Yume Nijino. Yume aims to become a top idol, and she enrolls in the Yotsuboshi Gakuen. This academy has a special group called the S4, who are the top four active idols in the school. Yume and the other first-year students aim to become a part of the S4.

