INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3260, 'Aikatsu on Parade!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx111082-T2wx2iPk9jHS.png', 'series', '6.9', 'Raki Kiseki is a second-year middle school student who transfers to Star Harmony Academy to become an idol. However, when she uses an Aikatsu Pass she received from her big sister (an Aikatsu engineer), something mysterious happens. Lots of doors appeared before her, and when she opens them, she meets Aikatsu idols she never knew before, such as Yume Nijino. Raki vows to design her own premium dress and perform in it on stage.

(Source: Anime News Network)', 'Bandai Namco Pictures', '2019', 'series', 'released', '2019-10-05', 111082, 0, NULL, '2026-08-08 15:57:38', '2026-09-03 16:16:54', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/111082-w4AEfiWpL4hz.jpg', 'Music, Slice of Life', 'TV', 'FALL', 25, 3348, 'https://www.youtube.com/watch?v=ZBB7H21KXss', '2026-09-03 16:16:54', NULL);
