INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3263, 'The Idolm@ster: Live for You!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/4033.jpg', 'series', '5.8', 'On the day before the 765 Productions Fan Appreciation Event, each of the idols prepare to head home. However, Chihaya Kisaragi, uneasy about tomorrow''s events, decides to have a last minute personal rehearsal. One thing leads to another as Chihaya, Miki and Haruka are dragged from one exciting situation to the next. What is the truck driver''s true destination? What is the secret behind the old house? Will the girls make it in time for the event? Watch as Miki, Haruka, Chihaya and the other idols join together for their biggest adventure yet!

(Source: e-n-m.net)', NULL, '2008', 'series', 'released', '2008-02-28', 4033, 0, NULL, '2026-08-08 15:57:43', '2026-09-03 16:17:01', NULL, 'Comedy, Music', 'OVA', 'WINTER', 1, 3069, NULL, '2026-09-03 16:17:01', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3264, 'IDOLM@STER: XENOGLOSSIA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1694-0fQrbEdvEBYW.png', 'series', '5.9', '107 years ago, the Moon was destroyed in a massive cataclysm that shattered Earth''s former satellite into 81 quintillion tons of orbital debris. However, thanks to super-science, the Earth itself was saved and today no one really thinks much about that century-past disaster. Which is why when teenage Haruka Amami auditions for something called the Idolmaster Project, she THINKS she''s trying out to be a singing idol. Instead, Haruka finds herself at a secret school run by the Mondenkind Agency, living with a group of other girls who have also been selected as candidates to pilot an iDOL - an advanced robot specifically designed to intercept falling chunks of moon rock. Except, the people who run the Mondenkind Agency aren''t exactly knights in shining armor. And then there''s the question of whether the iDOLs are really JUST robots. Because from almost the first moment, Haruka starts to feel emotions resonating from within the iDOL called Imber. 

(Source: Sentai Filmworks)', NULL, '2007', 'series', 'released', '2007-04-03', 1694, 0, NULL, '2026-08-08 15:57:43', '2026-09-03 16:17:04', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1694-VsGYnIykMeJw.jpg', 'Action, Comedy, Mecha, Romance, Sci-Fi', 'TV', 'SPRING', 26, 6766, NULL, '2026-09-03 16:17:04', NULL);
