INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3274, 'Girls und Panzer der Film', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx18617-bzfsyLDahhm8.jpg', 'movies', '8.1', 'When the Ministry of Education goes back on its promise to keep Ooarai Girls Academy open, the task of saving the five-mile-long Academy Ship from the wreckers falls to Miho and her barely-seasoned tankery team. However, things go off track almost immediately. While the Oorai tank crew may have won the high school tournament, they’re now facing a larger and more experienced university team, and if they fail, their armored vehicles will be forfeit! Will they be swapping their tanks for the memories? It’s possible, but winning a tank battle is all about tactics and teamwork, and the fledgling Ooarai students have more friends and allies than anyone suspects.

(Source: Sentai Filmworks)', 'Actas', '2015', 'movie', 'released', '2015-11-21', 18617, 0, NULL, '2026-08-08 15:57:54', '2026-09-03 16:17:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/18617-Wyk9axRcIrjv.jpg', 'Action, Sports', 'MOVIE', 'FALL', 1, 31892, 'https://www.youtube.com/watch?v=Oqk8Eg1A0RI', '2026-09-03 16:17:33', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3275, 'Girls und Panzer OVA Series', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx15811-xa6AKWptSjG1.png', 'series', '7.0', 'Mini episodes bundled with Blu-rays and DVDs.

The girls from Oorai are back in six special episodes! And whether they''re shopping for swimsuits, camping out or doing the Ankou Dance, they bring their own special brand of Tankery to the task at hand. There''s also a tour of the Oorai school ship, a look at what REALLY happened while Yukari and Erwin were out doing reconnaissance and a team talent contest that''s not to be missed!

(Source: Sentai Filmworks)', 'Actas', '2012', 'series', 'released', '2012-12-21', 15811, 0, NULL, '2026-08-08 15:57:54', '2026-09-03 16:17:37', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/15811-DHj5QlJBB2lF.jpg', 'Action, Slice of Life, Sports', 'SPECIAL', 'WINTER', 6, 13968, NULL, '2026-09-03 16:17:37', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3276, 'Girls und Panzer: This is the Real Anzio Battle!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx18619-HLJObts9x0rp.jpg', 'series', '7.6', '“A piece of spaghetti or a military unit,” George S. Patton famously said, “can only be led from the front end.” However, once the heat of battle has cooled and the fog of war turns as thick as minestrone, determining which end was front and who pulled on what can be difficult. Therefore, for the enthusiasts who’ve puzzled over the epic tank battle between the girls of Oorai Girls’ Academy and their Italian-themed rivals from Anzio High School, we present these classified videos for your eyes-only! Miho and Team Oorai will have their hands full with the impulsive attacks of Vice-Commander Pepperoni and facing the raw fury of Vice-Commander Carpaccio… but the real question is whether they can hold off Anchovy’s ultra-secret secret weapons! Will they persevere? Or will their opponents end up saying “tank” you very much…

(Source: Sentai Filmworks)', 'Actas', '2014', 'series', 'released', '2014-07-05', 18619, 0, NULL, '2026-08-08 15:57:54', '2026-09-03 16:17:40', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/18619-boKy3n5AoHSz.jpg', 'Action, Sports', 'OVA', 'SUMMER', 1, 17357, 'https://www.youtube.com/watch?v=2av7PfmTuZM', '2026-09-03 16:17:40', NULL);
