INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3301, 'Inazuma Eleven GO', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx10507-keU7zPCp3vJF.jpg', 'series', '6.9', 'Matsukaze Tenma, a first year who loves soccer, has exceptional dribbling skills, but still has lots of room for improvement. The story starts with him entering Raimon Jr. High ten years after the first Football Frontier International, where Raimon has become famous for its soccer. However, an organization called Fifth Sector has taken control of soccer over the years, and the passion that Raimon once had for soccer is no longer there.', 'OLM', '2011', 'series', 'released', '2011-05-04', 10507, 0, NULL, '2026-08-08 15:59:08', '2026-09-03 16:12:34', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10507-eI71i4Za09Xf.jpg', 'Sports, Supernatural', 'TV', 'SPRING', 47, 25090, NULL, '2026-09-03 16:12:34', NULL);
