INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3308, 'Persona -trinity soul-', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/3366.jpg', 'series', '5.9', 'The stage is Ayanagi City, a city near the Japan Sea. It is a futuristic city that was built to carry out the recovery from the calamity caused by the "Apathy Syndrome" ten years previous. High school student Shin Kanzato with his little brother Jun, meet with their elder brother Ry&#333;, who is the chief of the Ayanagi City Police, again after ten years. At that time, a series of strange incidents happen in Ayanagi City such as the crew of a submarine that suddenly disappears while in their submarine, or a spiritless symptom which disturbs the world after ten years, or the case of the inside out corpse where a student took on a cruel appearance. Ry&#333; tracks down the organization behind the string of incidents, and having become involved in the incidents, Shin awakens the "Persona". 

(Source: Wikipedia)', 'A-1 Pictures', '2008', 'series', 'released', '2008-01-05', 3366, 0, NULL, '2026-08-09 16:54:46', '2026-09-03 16:13:51', NULL, 'Action, Drama, Mystery, Sci-Fi, Supernatural', 'TV', 'WINTER', 26, 16275, NULL, '2026-09-03 16:13:51', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3309, 'Persona 3 the Movie: #1 Spring of Birth', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b14407-MgkKNW85qOot.png', 'movies', '7.3', 'Terrible creatures lurk in the dark, preying on those who wander into the hidden hour that lies between one day and the next—the Dark Hour. A secret school club known as SEES defends humanity from horrors and disasters while working to solve the mystery of the Dark Hour once and for all.


A movie based on the 2006 RPG Persona 3, announced at the end of the Persona 4 movie, The Factor of Hope.', 'AIC A.S.T.A.', '2013', 'movie', 'released', '2013-11-23', 14407, 0, NULL, '2026-08-09 16:54:46', '2026-09-03 16:13:55', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/14407-uhju1oqI26dU.jpg', 'Action, Adventure, Drama, Psychological, Sci-Fi, Supernatural', 'MOVIE', 'FALL', 1, 36308, NULL, '2026-09-03 16:13:55', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3310, 'PERSONA5 the Animation', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx99693-3YTkA0ZnEOqH.jpg', 'series', '6.2', 'Ren Amamiya is about to enter his second year after transferring to Shujin Academy in Tokyo.

Following a particular incident, his Persona awakens, and together with his friends they form the “Phantom Thieves of Hearts” to reform hearts of corrupt adults by stealing the source of their distorted desires.

Meanwhile, bizarre and inexplicable crimes have been popping up one after another…

Living an ordinary high school life in Tokyo during the day, the group maneuvers the metropolitan city as Phantom Thieves after hours.

Let the curtain rise for this grand, picaresque story!

(Source: Official website)', 'CloverWorks', '2018', 'series', 'released', '2018-04-08', 99693, 0, NULL, '2026-08-09 16:54:46', '2026-09-03 16:13:58', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99693-b3wrYly0eEa6.png', 'Action, Fantasy, Supernatural', 'TV', 'SPRING', 26, 78496, 'https://www.youtube.com/watch?v=sGKXdPW0qXc', '2026-09-03 16:13:58', NULL);
