INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3312, 'Blue Exorcist: Runaway Kuro', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx11266-fSF6j9lTkcxs.png', 'series', '6.9', 'Feeling slighted by Rin, Kuro goes on the hunt for a new master, but can he find anyone who can truly replace Rin?', 'A-1 Pictures', '2011', 'series', 'released', '2011-10-26', 11266, 0, NULL, '2026-08-09 16:55:08', '2026-09-03 16:14:05', NULL, 'Action, Comedy, Fantasy, Supernatural', 'OVA', 'FALL', 1, 28526, NULL, '2026-09-03 16:14:05', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3313, 'Blue Exorcist: Kyoto Saga', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx21861-KDvJJQenJJlT.jpg', 'series', '7.2', 'In the late Edo Period, a demon known as the Impure King killed thousands of people. After defeating the demon, the Knights of the True Cross kept its left eye safely sealed away on Academy grounds - but now someone has stolen it! Hearing the thief has taken a child hostage, Yukio and Rin go to help. The investigation and pursuit will lead Rin and his friends to Kyoto and involve them even deeper in a sinister plot! But will his friends'' knowledge that Rin is the son of Satan drive a wedge between them?

(Source: VIZ Media)', 'A-1 Pictures', '2017', 'series', 'released', '2017-01-07', 21861, 0, NULL, '2026-08-09 16:55:08', '2026-09-03 16:14:09', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21861-liQDH4AtMeK6.jpg', 'Action, Fantasy, Supernatural', 'TV', 'WINTER', 12, 178382, NULL, '2026-09-03 16:14:09', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3314, 'Precure All Stars DX2: Kibou no Hikari☆Rainbow Jewel wo Mamore!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx8133-XlBoDplQefLt.jpg', 'movies', '6.9', 'Tsubomi Hanasaki is woken by her best friend Erika Kurumi only to find out that their two fairies, Coffret and Shypre, have left just leaving a note explaining where to find them. Fairy Park is not only the destination of both girls, it is also the meeting point of all other Precures who planned to spend this special day together. This magical theme park holds the Rainbow Jewel, a special gem that represents all of the hopes and dreams of the world. Such a powerful stone is the object of desire of a malefic entity named Bottom who has waited one thousand years for the opportunity to possess it.', 'Toei Animation', '2010', 'movie', 'released', '2010-03-20', 8133, 0, NULL, '2026-08-09 16:55:14', '2026-09-03 16:14:14', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/8133-wCD4dTgUwfc7.jpg', 'Action, Comedy, Fantasy, Mahou Shoujo', 'MOVIE', 'WINTER', 1, 2854, NULL, '2026-09-03 16:14:14', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3315, 'Precure All Stars New Stage: Mirai no Tomodachi', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx12221-HsqYZlXHxd38.jpg', 'movies', '7.0', 'In the city of Minato Mirai in Yokohama, the news of Fusion''s defeat by the Pretty Cures is the hottest topic in town! Girls everywhere are dressing up and acting as their favorite Cures. Only Sakagami Ayumi, the new transfer student, is alone by herself.

On her way home from school, Ayumi encounters a strange creature. After naming it Fu-Chan, Ayumi and the creature soon become good friends. However, Fu-Chan is actually a piece of Fusion, and holds the power of darkness. In an effort to make Ayumi happy, Fu-chan swallows up everything that Ayumi dislikes, creating chaos in school and throughout the city!

To help bring across Ayumi''s true feelings to Fu-Chan, all 28 Pretty Cures gather once more. When everyone''s power comes together, a miraculous light starts to shine.', 'Toei Animation', '2012', 'movie', 'released', '2012-03-17', 12221, 0, NULL, '2026-08-09 16:55:14', '2026-09-03 16:14:17', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/12221-foxhDVjiAyBt.jpg', 'Action, Fantasy, Mahou Shoujo', 'MOVIE', 'WINTER', 1, 2879, NULL, '2026-09-03 16:14:17', NULL);
