INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3317, 'Towanoquon: The Return of the Invincible', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/10716.jpg', 'movies', '7.1', 'With their home in jeopardy, some feel it is time to abandon the gardens. A new character steps in, one that Quon knows very well. The end is near, the players are set, and the final battle is about to begin!', 'bones', '2011', 'movie', 'released', '2011-11-05', 10716, 0, NULL, '2026-08-09 16:55:26', '2026-09-03 16:07:25', NULL, 'Action, Sci-Fi, Supernatural', 'MOVIE', 'FALL', 1, 8693, NULL, '2026-09-03 16:07:25', NULL);
