INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3323, 'The Prince of Tennis II OVA vs Genius 10', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx20941-3ee7xYdPbHXs.png', 'series', '7.3', 'The story of the OVA series tells the continuation of the 13-episode TV anime in 2012, setting in the Japanese U-17 (under 17) High School Representatives Selection Camp.', 'Production I.G', '2014', 'series', 'released', '2014-10-29', 20941, 0, NULL, '2026-08-09 16:55:44', '2026-09-03 16:07:50', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20941-fhYYreuSqWNY.jpg', 'Action, Comedy, Sports', 'OVA', 'FALL', 10, 4919, NULL, '2026-09-03 16:07:50', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3324, 'Ryoma! The Prince of Tennis', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx113254-XmphpjR4LO7f.jpg', 'movies', '5.5', 'The movie features an original story that takes place during the three months between the first manga and its currently running sequel.

Inspired by his tennis champion father, Ryoma is determined to take his game to the next level and train in the US. But in the middle of an intense tennis battle to save his classmate Sakuno from dangerous villains, they somehow find themselves transported back to the past, just as Ryoma’s father is about to undertake his final championship match at the US Open – when he was mysteriously forced to retire. Sing, Dance, and Play along with the innovative 3D digital animation that brings the magnificent and colorful world of The Prince of Tennis to life on the big screen. 

(Sources: Natalie, Crunchyroll, edited)', 'The Monk Studios', '2021', 'movie', 'released', '2021-09-03', 113254, 0, NULL, '2026-08-09 16:55:44', '2026-09-03 16:07:54', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/113254-CKS0AF692DVy.jpg', 'Action, Comedy, Sports', 'MOVIE', 'SUMMER', 1, 1707, 'https://www.youtube.com/watch?v=lDFrh_RXoPs', '2026-09-03 16:07:54', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3325, 'Horizon in the Middle of Nowhere', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx10456-HgdpzfTdg7XE.jpg', 'series', '6.6', 'In the far future, humans abandon a devastated Earth and traveled to outer space. However, due to unknown phenomenon that prevents them from traveling into space, humanity returns to Earth only to find it inhospitable except for Japan. 

To accomodate the entire human population, pocket dimensions are created around Japan to house in the populace. In order to find a way to return to outer space, the humans began reenacting human history according to the Holy book Testament. But in the year 1413 of the Testament Era, the nations of the pocket dimensions invade and conquer Japan, dividing the territory into feudal fiefdoms and forcing the original inhabitants of Japan to leave. 

It is now the year 1648 of the Testament Era, the refugees of Japan now live in the city ship Musashi, where it constantly travels around Japan while being watched by the Testament Union, the authority that runs the re-enactment of history. However, rumors of an apocalypse and war begins to spread when the Testament stops revealing what happens next after 1648. 

Taking advantage of this situation, Toori Aoi, head of Musashi Ariadust Academy''s Supreme Federation and President of the student council, leads his fellow classmates to use this opportunity to regain their homeland. 

(Source: Wikipedia)', 'Sunrise', '2011', 'series', 'released', '2011-10-02', 10456, 0, NULL, '2026-08-09 16:55:53', '2026-09-03 16:08:01', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10456-qirI5rDVj4Gc.jpg', 'Action, Comedy, Drama, Fantasy, Romance, Sci-Fi', 'TV', 'FALL', 13, 39373, NULL, '2026-09-03 16:08:01', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3326, 'Horizon in the Middle of Nowhere XXI-PV', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/104211-sNjlLLOCx4VI.jpg', 'series', '5.7', 'The official website of the Kyoukaisenjou no Horizon (Horizon in the Middle of Nowhere) anime announced on June 11 that a Blu-ray Box containing both seasons of the series will go on sale on December 21, 2018. The bundle will also include a new special anime created especially for this release.

(Source: Anime News Network)', 'Sunrise', '2018', 'series', 'released', '2018-12-21', 104211, 0, NULL, '2026-08-09 16:55:53', '2026-09-03 16:08:05', NULL, 'Action, Fantasy, Sci-Fi', 'SPECIAL', 'FALL', 1, 1805, 'https://www.youtube.com/watch?v=hlarZQssDvA', '2026-09-03 16:08:05', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3327, 'Inazuma Eleven Go: Galaxy', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx18097-dAqYhaGafOqS.jpg', 'series', '6.5', 'Inazuma Eleven Go Galaxy introduces Football Frontier International Vision 2 (FFIV2) with Shinsei Inazuma Japan as the protagonist team. The team includes previous characters such as Matsukaze Tenma, Shindou Takuto, and Tsurugi Kyousuke, as well as other new characters, all who are known to be talented in fields such as boxing, mathematics, and rhythmic gymnastics, but poor at soccer.', NULL, '2013', 'series', 'released', '2013-05-08', 18097, 0, NULL, '2026-08-09 16:55:56', '2026-09-03 16:08:09', NULL, 'Sci-Fi, Sports, Supernatural', 'TV', 'SPRING', 43, 15448, NULL, '2026-09-03 16:08:09', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3328, 'Inazuma Eleven GO vs Danball Senki W', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx15785-C3kFaPPwnP8i.png', 'movies', '6.6', 'The "Inazuma Legend Japan" that won the FFI one day and the "New Inazuma Eleven", that played through the Holy Road Tournament are having an exhibition match. But suddenly a  lot of little objects appear and start attacking the stadium. They were the little robots "LBX", a technology never saw before in that world. Tenma and his friends try to respond to the attack, but the little robots continue to appear one after another, until Yamano Ban appears to save them. The strongest soccer team and the strongest LBX army are now united, and a fierce battle is about to begin!', NULL, '2012', 'movie', 'released', '2012-12-01', 15785, 0, NULL, '2026-08-09 16:55:56', '2026-09-03 16:08:14', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/15785-xL2UaLsPeQeS.jpg', 'Action, Mecha, Sci-Fi, Sports, Supernatural', 'MOVIE', 'FALL', 1, 4681, NULL, '2026-09-03 16:08:14', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3329, 'UN-GO', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx10798-C8caHKEm5uTa.jpg', 'series', '7.0', 'He pursues his job as the "Last Great Detective". Others call him the "Defeated Detective". What''s certain is that he''s Shinjurou Yuuki, a young man with a passion for mysteries and a talent for solving them that has made him the target of dark forces now stirring within the sinister underworld of a near future Tokyo. That could prove lethal, given that not even the other "good guys", including the police, are exactly on Shinjuro''s side. Fortunately Yuuki''s not completely on his own, and with the aid of his uniquely talented associate Inga, he''s ready to cut a swath through the veils of secrecy that have been laid before him. 

Get ready for mind against matter and a lot of cloak and dagger as the ultimate battle of clue and deduction begins in UN-GO! 

(Source: Sentai Filmworks)', 'bones', '2011', 'series', 'released', '2011-10-14', 10798, 0, NULL, '2026-08-09 16:56:09', '2026-09-03 16:08:29', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10798-AkCeCgoz5TSr.jpg', 'Drama, Mystery, Psychological, Sci-Fi, Supernatural', 'TV', 'FALL', 11, 32980, 'https://www.youtube.com/watch?v=wKXlljzjXnk', '2026-09-03 16:08:29', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3330, 'Pretty Rhythm: Dear My Future', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx12863-YerEY4cnzlfl.png', 'series', '6.4', 'Three years after the events of "Pretty Rhythm: Aurora Dream," Aira, Mion and Rizumu have grown up and tutor a new group of aspiring idols: Karin, Reina, Mia and Ayami, who form the Prizmmy&#9734;. Teenage girls from Korea, named Somin, Shiyoon, Haein, Chaekyung and Jae Eun (who are the PURETTY), appear as a rival group.', 'Tatsunoko Production', '2012', 'series', 'released', '2012-04-07', 12863, 0, NULL, '2026-08-09 16:56:13', '2026-09-03 16:08:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/12863-HxTIpY9svpvZ.jpg', 'Drama, Music, Romance, Sports', 'TV', 'SPRING', 51, 3101, NULL, '2026-09-03 16:08:33', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3331, 'Pretty Rhythm Shougekijou', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx11911-C6efPz0gE6jh.png', 'series', '6.4', 'Short specials included in the DVDs of the TV series.', 'Tatsunoko Production', '2011', 'series', 'released', '2011-07-22', 11911, 0, NULL, '2026-08-09 16:56:13', '2026-09-03 16:04:09', NULL, 'Music, Sports', 'SPECIAL', 'SUMMER', 51, 1199, NULL, '2026-09-03 16:04:09', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3332, 'KING OF PRISM by Pretty Rhythm', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx21409-F2Hpn9bGn23c.jpg', 'movies', '6.0', 'The unit Over The Rainbow succeeds in its debut. Aiming to become like the boy band, more students enroll in Edel Rose. Hiro and the others begin practice for the Prism King Cup, an event that is held once every four years. However, a rival called "Schwarz Rose" appears... Who will become the Prism King, the one who can make girls'' hearts throb the most!?

(Source: Anime News Network)', 'Tatsunoko Production', '2016', 'movie', 'released', '2016-01-09', 21409, 0, NULL, '2026-08-09 16:56:13', '2026-09-03 16:04:17', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21409-DTclCZjWqhg8.jpg', 'Music, Sports', 'MOVIE', 'WINTER', 1, 3626, 'https://www.youtube.com/watch?v=t3DDjRMbB-4', '2026-09-03 16:04:17', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3333, 'Pretty Rhythm: Rainbow Live', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx17249-FIqUTQWXkBWf.png', 'series', '7.6', 'Naru Ayase is an 8th grader who can see the colors of music when she listens to it. For Naru, who is extremely good at decorating, becoming the owner of a shop like Dear Crown was her dream. One day, she finds out that the manager of a newly-opened shop is recruiting middle school girls who can do Prism Dance, and immediately applies. Naru begins to Prism Dance at the audition, and an aura she''s never experienced spreads out in front of her. At that moment, a mysterious girl named Rinne asks her if she can see "rainbow music".

(Source: Anime News Network)', 'Tatsunoko Production', '2013', 'series', 'released', '2013-04-06', 17249, 0, NULL, '2026-08-09 16:56:13', '2026-09-03 16:05:41', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/17249-9JhXEAcNus3l.jpg', 'Drama, Music, Romance, Sports', 'TV', 'SPRING', 51, 4529, NULL, '2026-09-03 16:05:41', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3334, 'PriPara', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx20742-2B84gO4uhuJy.jpg', 'series', '7.4', 'The anime is set in the PriPara world, filled with girls'' dreams and yearnings for fashion, dance, and music. Seemingly every day, there are auditions that send top idols to worldwide fame on television and online. Laala and her friends are all fascinated with this world. However, Laala''s school prohibits PuriPara for elementary school children. An unexpected chance leads Laala to make her first entrance into the world of PriPara, where she just might make her debut.

(Source: Anime News Network)', 'Tatsunoko Production', '2014', 'series', 'released', '2014-07-05', 20742, 0, NULL, '2026-08-09 16:56:13', '2026-09-03 16:05:47', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n20742-rI7bzRHjrYKv.jpg', 'Comedy, Music, Slice of Life', 'TV', 'SUMMER', 38, 8946, 'https://www.youtube.com/watch?v=kK7peuFP0Lo', '2026-09-03 16:05:47', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3335, 'Kiratto Pri☆chan', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx101097-29lNA3Ot2l6S.jpg', 'series', '7.0', 'First-year middle school girls Mirai Momoyama and Emo Moegi are two aspiring idols who decide to use the "Pri☆Chan System," a system used by famous people and companies to broadcast content. Like many girls starting their own channels and uploading content, the pair decide to become their own producers, starting their own channel in an attempt to become Pri☆Chan idols.

(Source: Anime News Network)', 'Tatsunoko Production', '2018', 'series', 'released', '2018-04-08', 101097, 0, NULL, '2026-08-09 16:56:13', '2026-09-03 16:05:54', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n101097-d0FJRgJJXE32.jpg', 'Music, Slice of Life', 'TV', 'SPRING', 51, 3529, NULL, '2026-09-03 16:05:54', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3336, 'Waccha PriMagi!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx136119-vuJsJpnJeyL7.jpg', 'series', '6.7', 'Matsuri Hibino spends her days in middle school dreaming about PriMagi, the sparkling stage show that combines song, dance and fashion with actual magic. She’d love to star in the PriMagi one day, and when the spirited troublemaker Myamu appears from another, magical world to scout Matsuri as her PriMagi partner, the pair takes to the stage to become the top stars of PriMagi hand in hand!

(Source: Sentai Filmworks)', 'Tatsunoko Production', '2021', 'series', 'released', '2021-10-03', 136119, 0, NULL, '2026-08-09 16:56:13', '2026-09-03 16:06:17', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/136119-f5b5KUToIAA3.jpg', 'Mahou Shoujo, Music, Slice of Life', 'TV', 'FALL', 51, 3461, NULL, '2026-09-03 16:06:17', NULL);
