INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3357, 'Kidou Senshi Gundam UC: A Phantom World', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b112452-DAHV6rmyly0n.jpg', 'movies', '4.8', 'The short begins when an Anaheim Electronics-manufacture Sinanju Stein unit, stolen and now affiliated with the Neo Zeon unit Sleeves, bursts through the Earth''s stratosphere. The Unicorn takes off from the Nahel Argama and moves to intercept. While it engages with the Sinanju Stein, the Banshee Norn and Phenex are moving to assist.', NULL, '2016', 'movie', 'released', '2016-03-26', 112452, 0, NULL, '2026-08-09 16:57:35', '2026-09-03 16:14:29', NULL, 'Action, Mecha', 'MOVIE', NULL, 1, 737, NULL, '2026-09-03 16:14:29', NULL);
