INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3363, 'Birdy the Mighty', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b566-o7Btb4cx4Ku4.png', 'series', '6.8', 'Tsutomu, a perfectly average student, is busy studying for his high school exams when he stumbles into a police chase in progress. Caught in the crossfire, the boy is hit and on the verge of death when he''s approached by a young woman. Birdy is on the scene and, by joining her consciousness with his, manages to save him from his imminent demise. Now they share a body and will have to learn to live together as she continues her career, capturing criminals and saving lives as an interplanetary police agent.', 'MADHOUSE', '1996', 'series', 'released', '1996-07-25', 566, 0, NULL, '2026-08-09 17:23:42', '2026-09-03 16:15:06', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n566-lE7xa0XONTiw.jpg', 'Action, Sci-Fi', 'OVA', 'SUMMER', 4, 11352, NULL, '2026-09-03 16:15:06', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3364, 'MAJOR 2nd', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx100306-picxGtylsEST.jpg', 'series', '7.2', 'Shigeno Daigo is an elementary student whose father, Goro, is a professional baseball player. Inspired by his father, who was once a Major League player, Daigo started playing baseball with the Mifune Dolphins, a youth team. However, he was unable to live up to the expectations of being the son of a professional, and quit baseball after less than a year. Then, in the spring of his sixth-grade year, Daigo''s school welcomes a transfer student, Sato Hikaru, whose father is Sato Toshiya, a former Major League player and Goro''s close friend. The fate of these two young men begins to move forward!

(Source: Crunchyroll)', 'OLM', '2018', 'series', 'released', '2018-04-07', 100306, 0, NULL, '2026-08-09 17:23:45', '2026-09-03 16:15:10', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100306-15AYgi4A4ghv.jpg', 'Comedy, Drama, Sports', 'TV', 'SPRING', 25, 9896, 'https://www.youtube.com/watch?v=tk4rmNvDgLI', '2026-09-03 16:15:10', NULL);
