INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3397, 'Saki Biyori Animation', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx21642-s4ZFO0X7nqH5.png', 'series', '6.3', 'A single episode OVA released with the 14th volume of the Saki manga, consisting of 4-koma gags featuring characters from the first season. The two pros meet up at a family restaurant. The captains of the four teams prepare for a joint training camp. Ikeda keeps her little sisters occupied. The Tsuruga team goes on an unplanned camping trip. Ryuumonbuchi celebrate Koromo''s birthday.

(Source: Anime News Network)', 'Studio Gokumi', '2015', 'series', 'released', '2015-07-25', 21642, 0, NULL, '2026-08-09 17:29:37', '2026-09-03 15:53:29', NULL, 'Slice of Life', 'OVA', 'SUMMER', 1, 1738, 'https://www.youtube.com/watch?v=Rc8ztOVfpnQ', '2026-09-03 15:53:29', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3398, 'Yozakura Quartet', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b4548-MscKClt97d7N.jpg', 'series', '6.5', 'When demons walk the streets, the cops need to recruit more demons!

In a town where humans and demons co-exist, it takes more than a normal police force to maintain the peace. Enter the Hiizumi Life Counseling Office, a fantastic foursome of unique teenagers, each gifted with an amazing super power! Since it sometimes takes real demon-fire to fight demon fire, the first three quarters of the team aren''t exactly human: Ao, a cat-eared telepath; Kotoha, a half-human conjuror; and Hime, descended from a dragon (and the town''s acting mayor), all of whom also happen to be delightfully female.

Rounding out the group is the token male and human, Akina, the office director and "Oyakume," capable of banishing spirits permanently (and from their point of view quite fatally) via a process called tuning. They may not look as impressive as some other superhero teams, and they certainly don''t have the most dynamic name ever, but come hell hounds or high water, but they will defend their city!

(Source: RightStuf)', 'Nomad', '2008', 'series', 'released', '2008-10-03', 4548, 0, NULL, '2026-08-09 17:29:52', '2026-09-03 15:53:32', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4548-p6ivM17LcinI.jpg', 'Action, Comedy, Supernatural', 'TV', 'FALL', 12, 39531, NULL, '2026-09-03 15:53:32', NULL);
