INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3400, 'Letter Bee Academy', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/8022.jpg', 'series', '6.5', 'Tegami Bachi specials.', NULL, '2010', 'series', 'released', '2010-01-27', 8022, 0, NULL, '2026-08-09 17:29:59', '2026-09-03 15:53:38', NULL, 'Comedy', 'SPECIAL', 'WINTER', 25, 2133, NULL, '2026-09-03 15:53:38', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3401, 'FAIRY TAIL OVA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/9982.jpg', 'series', '7.0', 'OVAs bundled with special editions volumes of the manga.

1. Youkoso Fairy Hills!

Lucy comes across a mysterious written request. The client is looking for an object that is in Fairy Tail''s female dormitory, Fairy Hills. To verify the request, Lucy visits Fairy Hills, and discovers that the client is Hilda, the dormitory head who is looking for a "shining treasure." Meanwhile, Natsu and the other guild members are cleaning their pool.

2. Yousei Gakuen: Yankee-kun to Yankee-chan

The anime adaptation of the manga side story "Yousei Gakuen Yankee-kun to Yankee-chan," which puts the characters of Fairy Tail in a school setting. The title is a parody of Miki Yoshikawa''s "Yankee-kun to Megane-chan."

3. Memory Days

An all-new original story storyboarded by Hiro Mashima, the author of Fairy Tail, released on February 17, 2012. "Natsu''s Secret" is going to be revealed in the "Past World"?! Guided by a "magic book" that''s lying in the Guild''s storage room, Natsu, Lucy, Happy, Gray, and Erza have traveled back into the past!!

4. Yousei-tachi no Gasshuku

Natsu, Lucy, and the others go to a training camp for the Grand Magic Games. While there, the Fairy Tail Guild take a much needed break at the beach and hot spring.

5. Dokidoki Ryuuzetsu Land

Adapting the chapter 298. The story is set during the Grand Magic Games when various guilds gather at the pool for some fun (and the chaos that ensues).', NULL, '2011', 'series', 'released', '2011-04-15', 9982, 0, NULL, '2026-08-09 17:30:05', '2026-09-03 15:53:41', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n9982-Fjghh23UovUm.jpg', 'Action, Adventure, Comedy, Fantasy', 'OVA', 'SPRING', 5, 35146, NULL, '2026-09-03 15:53:41', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3402, 'Fairy Tail: Phoenix Priestess', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx12049-FIx0K2s81SPa.png', 'movies', '7.1', 'The film revolves around a mysterious girl named &Eacute;clair who appears before Fairy Tail, the world''s most notorious wizard''s guild. She lost all of her memories, except for the imperative that she must deliver two Phoenix Stones somewhere. The stones may spell the collapse of the magical world, and Natsu, Lucy, and the rest of the Fairy Tail guild are caught up in the intrigue.

(Source: Anime News Network)', 'Satelight', '2012', 'movie', 'released', '2012-08-18', 12049, 0, NULL, '2026-08-09 17:30:05', '2026-09-03 15:53:44', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n12049-kyR6RCH0IAgo.jpg', 'Action, Adventure, Comedy, Fantasy', 'MOVIE', 'SUMMER', 1, 45214, 'https://www.youtube.com/watch?v=SKp0okAo-fA', '2026-09-03 15:53:44', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3403, 'Fairy Tail Series 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx20626-9LTreIofBgnu.jpg', 'series', '7.4', 'The Grand Magic Games reaches its climax following Natsu Dragneel and Gajeel Redfox''s stunning victory over Sting Eucliffe and Rogue Cheney of the Sabertooth guild. This success pushes the Fairy Tail guild closer to being crowned the overall champions, but obtaining victory isn''t the only challenge they face. A mystery still surrounds a hooded stranger and the ominous Eclipse Gate, leaving more questions than answers.
 
More crazy adventures are on the horizon for Fairy Tail as their destructive antics and joyful rowdiness continue unabated. Their greatest trial is quickly approaching, but united as a family, the guild will always be ready to face any threat that comes their way.', 'A-1 Pictures', '2014', 'series', 'released', '2014-04-05', 20626, 0, NULL, '2026-08-09 17:30:05', '2026-09-03 15:53:47', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20626-tVqtIqsuRhCJ.jpg', 'Action, Adventure, Fantasy', 'TV', 'SPRING', 102, 184149, 'https://www.youtube.com/watch?v=usaOd9A00U0', '2026-09-03 15:53:47', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3404, 'Tales of Symphonia: The Animation - Sylvarant Arc', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1731-OQPp1N1OL9Lk.jpg', 'series', '6.8', 'Two worlds exist, both unaware of the existance of the other. In order for one world to flourish, the other will have to perish. On the perishing world, a Chosen one is sent on a journey to restore that world''s mana by awakening the Spirits and becoming an angel. Colette Brunel, the Chosen of Sylvarant, sets out on her journey accompanied by her best friends Lloyd Irving and Genis Sage. As they travel further they meet more friends and even more enemies, while they learn more and more about the truth behind the World Regeneration.

(Source: Anime News Network)', 'ufotable', '2007', 'series', 'released', '2007-06-08', 1731, 0, NULL, '2026-08-09 17:30:13', '2026-09-03 15:53:50', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1731-THd6dUhpPXkt.jpg', 'Action, Adventure, Fantasy', 'OVA', 'SUMMER', 4, 9817, NULL, '2026-09-03 15:53:50', NULL);
