INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3409, 'Baka and Test Mini Special', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/n107348-vkHnMvcgSoSc.jpg', 'series', '6.2', 'Included with the Baka to Test to Shoukanjuu complete Blu-ray Box.', NULL, '2017', 'series', 'released', '2017-11-29', 107348, 0, NULL, '2026-08-09 17:30:16', '2026-09-03 15:54:05', NULL, 'Comedy', 'SPECIAL', 'FALL', 1, 4284, NULL, '2026-09-03 15:54:05', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3410, 'Hakuoki ~Demon of the Fleeting Blossom~', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx6895-S4QTn9uPlVrL.png', 'series', '6.8', 'The protagonist, Yukimura Chizuru, is the daughter of a doctor who works in Edo. The father leaves Edo to work as a volunteer doctor and moves to Kyoto without his daughter. As time passes by, Chizuru starts worrying about losing contact with her father, so she decides to go to Kyoto in search of him. On the way, Chizuru is attacked by few criminals and witnesses a fight between an oni and the Shinsengumi. Taking her into custody and saving her, the Shinsengumi debate on what to do with Chizuru when they discover that she is the daughter of the doctor they are also looking for. So they decide to become Chizuru''s protectors and help her look for her father (the doctor). Lots of events happen while she stays with the Shinsengumi, as they discover mysterious secrets and also fight against the Bakumatsu group. The story is overall romantic with a historical and political background. 

(Source: Hakuouki official website)', 'Studio DEEN', '2010', 'series', 'released', '2010-04-04', 6895, 0, NULL, '2026-08-09 17:30:18', '2026-09-03 15:54:08', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/6895-80ov7fZRCJam.jpg', 'Action, Drama, Supernatural', 'TV', 'SPRING', 12, 24818, NULL, '2026-09-03 15:54:08', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3411, 'HAKUOKI: WARRIOR SPIRIT OF THE BLUE SKY', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx13119-VsSwIwKDqxVc.png', 'movies', '7.2', 'Second and last part of the movies that remake season 1 and 2.

The battle at Koufu Castle has been lost, the Furies are no longer restrained by daylight, and while the individual members of the Shinsengumi still survive, the links that bound them together have been torn and shattered.

As Harada, Shinpachi, and Saito try to fight their way out of Koufu, Chizuru holds true to her oath to Hijikata, standing guard over Kondou, while he and Okita fight to recover from their gunshot wounds.

And Hijikata faces the greatest test of all. Having partaken of the Water Of Life, he must now balance his humanity against a need for blood and the deeds the Fury''s power makes possible.

(Source: SENTAI FILMWORKS)', 'Studio DEEN', '2014', 'movie', 'released', '2014-03-09', 13119, 0, NULL, '2026-08-09 17:30:18', '2026-09-03 15:54:11', NULL, 'Action, Drama, Supernatural', 'MOVIE', 'WINTER', 1, 4008, 'https://www.youtube.com/watch?v=oFwONT-aEfY', '2026-09-03 15:54:11', NULL);
