INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3415, 'Anne of Green Gables', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx283-HlHQFRlU8IfB.png', 'series', '8.0', 'Anne is an orphan full of imagination. When she arrives at her new home she learns that sometimes you have to be a sensible person too; at the same time her unique character changes, or at least attracts, the people around her. The story covers Anne''s growth from about eleven to seventeen years old as she makes friends, goes to school and studies. At a difficult point in her life, Anne will have to make a hard choice and perhaps find a new dream.', 'Nippon Animation', '1979', 'series', 'released', '1979-01-07', 283, 0, NULL, '2026-08-09 17:31:16', '2026-09-03 15:54:23', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/283-ayiNXKSSQpE7.jpg', 'Drama, Slice of Life', 'TV', 'WINTER', 50, 17039, 'https://www.youtube.com/watch?v=JaBmyPPbId0', '2026-09-03 15:54:23', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3416, 'Akage no Anne: Green Gables e no Michi', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/8950.jpg', 'movies', '6.0', 'The story covers Annes'' arrival at Green Gables, where she has travelled to to live her new live with the Cuthberts after having been in an orphanage for half a year. Anne, an orphan full of character and imagination, already imagines her wonderful new life and how things will turn better in her life from now on. Unexpectedly, when she arrives at Green Gables, she has to learn that there has been made a fatal mistake as the Cuthberts wanted to adopt a young boy of her age instead. Therefore she has to face another difficult point in her life, whether she''ll be able to stay in Green Gables or being sent back to the orphanage. Or even worse,  she might be sent to stay at the house of Mrs. Blewett, an elderly, strict and very intimidating woman. For once, will she be able to overcome even more difficulties and find at least a little bit of kindness and happiness?', NULL, '2010', 'movie', 'released', '2010-07-17', 8950, 0, NULL, '2026-08-09 17:31:16', '2026-09-03 15:54:26', NULL, 'Adventure, Slice of Life', 'MOVIE', 'SUMMER', 1, 1652, NULL, '2026-09-03 15:54:26', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3417, 'Anne Shirley', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx184639-tmj8NbTroNeI.jpg', 'series', '7.6', 'A new adaptation of  Akage no Anne (Anne of Green Gables).

On the beautiful Prince Edward Island in Canada, an orphan named Anne Shirley is mistakenly sent to Green Gables, the home of Matthew and Marilla Cuthbert. They choose to adopt her anyway, as Anne finds friendship, love, and happiness in her new home. Come along for the story of a purehearted and imaginative girl growing up, leaving for college, and returning home a changed woman.

(Source: Crunchyroll)', 'The Answer Studio', '2025', 'series', 'released', '2025-04-05', 184639, 0, NULL, '2026-08-09 17:31:16', '2026-09-03 15:54:29', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/184639-fXvQzDPP4bHL.jpg', 'Drama, Slice of Life', 'TV', 'SPRING', 24, 22502, 'https://www.youtube.com/watch?v=-oaZ3DRpjAk', '2026-09-03 15:54:29', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3418, 'Sengoku Basara: Samurai Kings', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx5355-TGrgtbiJ5zlH.png', 'series', '6.9', 'Sengoku Basara drops you directly into the burning battlefields of feudal Japan, where rival warlords hack and slash their way to total domination. Each conqueror wields a special attack that boosts their powers of devastation, and each commands a horde of relentless warriors. But when a supreme evil - the Demon Lord - threatens the land, these fierce generals launch a co-op campaign of annihilation and build an army of armies to obliterate their common foe.

As the front line grows crowded with gun-toting, mechanized samurai and mystical ninja, some will say that war is hell - but Sengoku Basara proves it can also be kick ass.

(Source: Manga Entertainment)', 'Production I.G', '2009', 'series', 'released', '2009-04-02', 5355, 0, NULL, '2026-08-09 17:31:18', '2026-09-03 15:54:32', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n5355-ZZsFYvWD3t4G.jpg', 'Action, Drama, Fantasy', 'TV', 'SPRING', 12, 26407, NULL, '2026-09-03 15:54:32', NULL);
