INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3427, 'Mobile Suit Gundam', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx80-pdYJ12vSTmad.jpg', 'series', '7.7', 'What would you do if you suddenly found yourself in the middle of a war? Teenager Amuro Ray sees his life shattered when war comes to his home. During the chaos, Amuro finds himself inside the mobile suit Gundam, the Earth Federation''s new secret weapon, and he somehow gets it to work. Amuro and the other refugees flee their homeland on the warship White Base. This group of children and inexperienced soldiers will change the outcome of the war. 

(Source: Sunrise)', 'Sunrise', '1979', 'series', 'released', '1979-04-07', 80, 0, NULL, '2026-08-09 17:32:28', '2026-09-03 15:54:58', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/80-LcQhJ600WeDn.jpg', 'Drama, Mecha, Sci-Fi', 'TV', 'SPRING', 43, 47972, NULL, '2026-09-03 15:54:58', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3428, 'Inazuma Eleven: Choujigen Dream Match', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b98225-fTWs8p9izVGR.png', 'movies', '6.8', 'A movie featuring a match between fan-voted members of the Inazuma Best Eleven team and the special Battle Eleven team.', 'OLM', '2014', 'movie', 'released', '2014-06-13', 98225, 0, NULL, '2026-08-09 18:17:23', '2026-09-03 15:55:01', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/98225-ERSc1Givj8K7.jpg', 'Sports, Supernatural', 'MOVIE', 'SPRING', 1, 5514, NULL, '2026-09-03 15:55:01', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3429, 'Inazuma Eleven Ares', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx21879-h5RaJDRqPg8N.jpg', 'series', '6.4', 'Ares no Tenbin depicts an alternative canon following the events of the first season of the original Inazuma Eleven anime. Taking place sometime after Raimon''s victory in the Football Frontier, in this alternative universe, the alien attack from the second season never occurs. Japanese soccer has been deemed weak compared to international competition. Due to this, the Raimon Eleven have been disbanded, and its members are sent to different soccer teams across Japan in the hopes of strengthening Japan''s soccer at a national level. Moreover, in the modern world of Japanese youth soccer, sponsorship has become a vital aspect of a team''s survival. A youth team must have a sponsor, otherwise, their club will face disbandment, and are not permitted to partake in matches.

The series focuses on the forward Asuto Inamori and his team, Inakuni Raimon, which is made up of players from the remote Inakunijima Island. They have replaced the original Raimon Eleven as Raimon Junior High''s soccer team, and are competing as underdogs in the annual Football Frontier youth tournament.

(Source: Wikpedia)', 'OLM', '2018', 'series', 'released', '2018-04-06', 21879, 0, NULL, '2026-08-09 18:17:23', '2026-09-03 15:55:04', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21879-Ac6WnBmgL5T0.jpg', 'Action, Sports, Supernatural', 'TV', 'SPRING', 26, 13462, 'https://www.youtube.com/watch?v=wLFWgPe_GCc', '2026-09-03 15:55:04', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3430, 'Inazuma Eleven: Outer Code', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx99059-kA7alh9r8L9Y.jpg', 'series', '6.4', 'A spin-off of the Inazuma Eleven soccer anime franchise featuring a alternative universe with various diferences in the basic concepts of the original plot.', NULL, '2016', 'series', 'released', '2016-11-04', 99059, 0, NULL, '2026-08-09 18:17:23', '2026-09-03 15:55:07', NULL, 'Action, Sports', 'ONA', 'FALL', 6, 3198, NULL, '2026-09-03 15:55:07', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3431, 'Inazuma Eleven: Soushuuhen - Densetsu no Kickoff', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx180804-XedQP8o3pUCO.jpg', 'movies', '6.6', 'Compilation film of Inazuma Eleven; a recap of the original video game and the first 26 episodes of the series which focuses on the matches.', 'OLM', '2024', 'movie', 'released', '2024-12-27', 180804, 0, NULL, '2026-08-09 18:17:23', '2026-09-03 15:55:10', NULL, 'Action, Sports', 'MOVIE', 'FALL', 1, 2209, 'https://www.youtube.com/watch?v=-119oCbVCB8', '2026-09-03 15:55:10', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3432, 'Inazuma Eleven GO: TCG CM NG-shuu', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/16964.jpg', 'series', '5.7', 'Compilation and bloopers of the Inazuma Eleven Go Trading Card Game commercials presented by Wonderbot.', NULL, '2012', 'series', 'released', '2012-11-22', 16964, 0, NULL, '2026-08-09 18:20:42', '2026-09-03 15:55:13', NULL, 'Comedy', 'SPECIAL', 'FALL', 1, 909, NULL, '2026-09-03 15:55:13', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3433, 'Inazuma Eleven: Reloaded - Reformation of Soccer', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx102933-REEZB2GCMqkg.png', 'series', '6.7', 'Special prologue episode of the Inazuma Eleven: Ares no Tenbin series. It is a remake of the original Inazuma Eleven episode 27.

After defeating Zeus and becoming the Football Frontier champions, the members of Raimon return to the soccer club. Unlike episode 27, the club is not invaded by aliens. Instead, everyone congratulates the team members for their remarkable achievements.

Kidou Yuuto and Gouenji Shuuya then propose to take on the world. Hibiki Seigou comes in and, incidentially, proposes a match between Raimon and the Spanish youth league champion, Barcelona Orb.

(Source: Inazuma Eleven Wiki)', 'OLM', '2018', 'series', 'released', '2018-01-21', 102933, 0, NULL, '2026-08-09 18:20:52', '2026-09-03 15:55:15', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/102933-dyLIMFcmpVin.jpg', 'Sports, Supernatural', 'SPECIAL', 'WINTER', 1, 3370, NULL, '2026-09-03 15:55:15', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3434, 'Natsume''s Book of Friends Season 6', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx97983-Uqn04SR6hVW9.jpg', 'series', '8.5', 'Takashi Natsume has grown accustomed to his encounters with youkai through the Book of Friends, which contains the names of youkai whom his grandmother, Reiko Natsume, has sealed in contracts. These encounters allow Natsume to better understand the youkai, Reiko, and himself.

The Book of Friends is a powerful tool that can be used to control youkai; it is sought after by both youkai and exorcists alike. Natsume just wants to live out his daily life in peace but is constantly disrupted by these experiences. If he is to end this torment, Natsume must explore more about the book and the world of exorcism, as well as begin to open his heart to those who can help him.

(Source: MAL Rewrite)', 'Shuka', '2017', 'series', 'released', '2017-04-12', 97983, 0, NULL, '2026-08-29 14:55:49', '2026-09-03 15:55:18', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97983-gnWWi3k6xstM.jpg', 'Drama, Fantasy, Slice of Life, Supernatural', 'TV', 'SPRING', 11, 40059, 'https://www.youtube.com/watch?v=xmJz_MyU3bc', '2026-09-03 15:55:18', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3435, 'Natsume Yuujinchou Go Tokubetsu-hen', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx99363-vFOXsEm0340k.png', 'series', '8.0', 'Two special episodes bundled in the fourth and fifth volume of the Blu-ray/DVD.', 'Shuka', '2017', 'series', 'released', '2017-03-22', 99363, 0, NULL, '2026-08-29 14:55:49', '2026-09-03 15:55:21', NULL, 'Drama, Fantasy, Slice of Life, Supernatural', 'SPECIAL', 'SPRING', 2, 12182, NULL, '2026-09-03 15:55:21', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3436, 'Natsume Yuujinchou Roku Tokubetsu-hen', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx100283-R41Jk9AHLuXj.png', 'series', '8.2', 'New unaired episodes included in 4th and 5th DVD volumes of Natsume Yuujinchou Roku.', 'Shuka', '2017', 'series', 'released', '2017-09-27', 100283, 0, NULL, '2026-08-29 14:56:02', '2026-09-03 15:55:24', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100283-rIiiC4d63JZ4.png', 'Drama, Fantasy, Slice of Life, Supernatural', 'SPECIAL', 'FALL', 2, 12314, NULL, '2026-09-03 15:55:24', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3437, 'Natsume''s Book of Friends the Movie: Ephemeral Bond', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx100268-SUZCprpenPzC.png', 'movies', '8.2', 'Natsume has been busy, navigating between humans and Yokai when he coincidentally reunites with an old classmate, Yuki. It brings back painful memories of a certain Yokai. Meanwhile, Natsume also became acquainted with Yorie Tsumura, a woman in the memories of a Yokai whose name he had returned. Yorie knew much about Reiko, but now lived a peaceful life with her only son, Mukuo. Being with this family was comforting for Natsume, but apparently a mysterious Yokai has been lurking in their town. 

On the way back from investigating, a “Yokai seed” that had latched itself to Nyanko Sensei drops into the Fujiwaras’ garden and grows overnight into a fruit tree. When Nyanko Sensei eats a fruit that is somehow shaped like himself, he suddenly splits into three! 

(Source: Aniplex USA)', 'Shuka', '2018', 'movie', 'released', '2018-09-29', 100268, 0, NULL, '2026-08-29 14:56:02', '2026-09-03 15:55:27', NULL, 'Drama, Fantasy, Slice of Life, Supernatural', 'MOVIE', 'SUMMER', 1, 18302, 'https://www.youtube.com/watch?v=18cHHCJ_C2E', '2026-09-03 15:55:27', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3438, 'Natsume Yuujinchou: Ishi Okoshi to Ayashiki Raihousha', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx124132-1CMeg6ZKv09Q.jpg', 'movies', '8.0', 'In "Ishi Okoshi," Natsume meets a small youkai called Mitsumi in a forest. Mitsumi is entrusted to wake up the divine youkai "Iwatetsu" from its deep slumber. Mitsumi weighs on Natsume''s mind, so he sets out to help Mitsumi with his task.

In "Ayashiki Raihousha," a mysterious visitor appears in front of Tanuma. Nearly every day, the visitor visits Tanuma, talks to him a little, and then leaves. Natsume, who knows the visitor is a youkai, worries for Tanuma, but Tanuma enjoys these exchanges with the youkai. The youkai means no harm, but Tanuma''s health slowly starts to deteriorate.

(Source: Anime News Network)', 'Shuka', '2021', 'movie', 'released', '2021-01-16', 124132, 0, NULL, '2026-08-29 14:56:02', '2026-09-03 15:55:30', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/124132-iykyxLcgEKzH.jpg', 'Drama, Fantasy, Slice of Life, Supernatural', 'MOVIE', 'WINTER', 1, 11576, 'https://www.youtube.com/watch?v=IuSKZlwGRNs', '2026-09-03 15:55:30', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3439, 'Natsume''s Book of Friends Season 7', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx166611-MXGsOlPv2IKj.png', 'series', '8.4', 'As a young child, Takashi Natsume believed his ability to see youkai to be nothing but a curse. Now a high school student, Natsume has managed to heal from his old wounds and form unbreakable bonds with humans and youkai alike. Natsume''s newfound friendships—including the one with his spirit bodyguard Madara, nicknamed "Nyanko-sensei"—are often interlaced with his duty to return the names of the spirits written inside the Book of Friends, his late grandmother Reiko''s keepsake. While more remarkable youkai reach out to him, Natsume discovers that he still has much to learn about the world that surrounds him.

(Source: MAL Rewrite)', 'Shuka', '2024', 'series', 'released', '2024-10-08', 166611, 0, NULL, '2026-08-29 14:56:02', '2026-09-03 15:55:33', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/166611-xCBiQMGZMBhI.jpg', 'Drama, Fantasy, Slice of Life, Supernatural', 'TV', 'FALL', 12, 15875, 'https://www.youtube.com/watch?v=yNmx5gKcHrQ', '2026-09-03 15:55:33', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3440, 'Ichiban Kuji Natsume Yuujinchou: Nyanko-sensei to Hana Shirabe', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b154978-Z2iI3yeVfNO4.jpg', 'series', '5.8', 'Kogitsune tells Nyanko-sensei the meanings of different flowers and assembles a bouquet as a gift for Natsume.

Note: This ONA was a promotional video made for a Bandai Spirits Ichiban Kuji event which ran from March 19, 2021 at FamilyMart, Ministop, and other convenience stores, bookstores, hobby shops, and game centers. The theme is "The Language of Flowers". It had a lineup of stuffed animals, stoles, tote bags, brooches, stationery, handkerchiefs, and acrylic charms. Last drawn prize was a clover cushion.', NULL, '2021', 'series', 'released', '2021-03-12', 154978, 0, NULL, '2026-08-29 14:56:09', '2026-09-03 15:55:35', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/154978-sxKUhRKJV8bD.jpg', 'Fantasy, Slice of Life, Supernatural', 'ONA', 'WINTER', 1, 788, NULL, '2026-09-03 15:55:35', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3441, 'Natsume Yuujinchou × Kumamoto-ken: Hitoyoshi Kuma de no Yasashii Jikan', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b188619-zBWxqUo3oWXo.png', 'series', '6.6', 'Takashi Natsume and his loyal feline protector Madara take a trip to Hitoyoshi Kuma, a peaceful area in Kumamoto. From admiring the Kaname Falls to relaxing at the Tsurukame hot spring, the duo unwind and take in the beautiful scenery throughout the eventful day.

(Source: MAL Rewrite)', 'Shuka', '2021', 'series', 'released', '2021-04-21', 188619, 0, NULL, '2026-08-29 14:56:09', '2026-09-03 15:55:38', NULL, 'Fantasy, Slice of Life, Supernatural', 'ONA', 'SPRING', 1, 974, 'https://www.youtube.com/watch?v=cj2iB3vwjwg', '2026-09-03 15:55:38', NULL);
