INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3451, 'Macross Dynamite 7', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx1398-9gRQTxYob2Ji.jpg', 'series', '6.7', 'Less than a year after the events that transpired in the Macross 7 TV series, Basara leaves Fire Bomber and travels to the planet Zola. There, he meets a girl named Elma, who is a big fan of Fire Bomber. It is also on this planet where he must once again use his Spiritia powers; this time, to stop an army of poachers and Elma''s father Graham from killing a group of space whales travelling within the planetary system.', 'Ashi Productions', '1997', 'series', 'released', '1997-12-18', 1398, 0, NULL, '2026-08-29 15:02:28', '2026-09-03 15:56:46', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n1398-6frQ1HEiuyAa.jpg', 'Adventure, Comedy, Mecha, Music, Sci-Fi', 'OVA', 'WINTER', 4, 5210, NULL, '2026-09-03 15:56:46', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3452, 'Macross Delta', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx20680-IVFFnv8oXahy.jpg', 'series', '7.0', 'Macross Delta is set in the year 2067, 8 years after the events of the latest Macross TV series, Macross Frontier. The story focuses on Walküre, a team of talented idols and the Delta Squadron, a team of experienced Valkyrie pilots as they battle against the Var Syndrome, a mysterious phenomena that is consuming the galaxy and there is also the mysterious Aerial Knights Valkyrie fighter team of the Kingdom of Wind.

(Source: Anime News Network)', 'Satelight', '2016', 'series', 'released', '2016-04-03', 20680, 0, NULL, '2026-08-29 15:02:29', '2026-09-03 15:56:49', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20680-S1KKV9DLwPm2.jpg', 'Action, Mecha, Music, Romance, Sci-Fi', 'TV', 'SPRING', 26, 24472, 'https://www.youtube.com/watch?v=GMKiLsbWiHY', '2026-09-03 15:56:49', NULL);
