INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3459, 'Ramen Tenshi Pretty Menma', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/7882.jpg', 'series', '3.9', 'The plot revolves around Kaoru Torigara, only son of a ramen shop owner, who is going to renovate his inherited ramen shop. He discovers that his shop has a guardian angel named Pretty Menma. Pretty Menma tells Kaoru that his dead father''s intention is making him succeed in the "Food King Wars", a battle of restaurants around the world that is held every 4 years. Kaoru and Menma must help each other to go through the struggles of the "Food King Wars".

(Source: Wikipedia)', NULL, '2008', 'series', 'released', '2008-01-25', 7882, 0, NULL, '2026-08-29 15:03:02', '2026-09-03 15:57:08', NULL, 'Comedy', 'SPECIAL', 'WINTER', 1, 1424, NULL, '2026-09-03 15:57:08', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3460, 'Genshiken Second Generation OVA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx19159-54ox490MBf5H.png', 'series', '6.9', 'Bundled with the limited edition of the 15th volume of the manga.', 'Production I.G', '2013', 'series', 'released', '2013-12-20', 19159, 0, NULL, '2026-08-29 15:03:02', '2026-09-03 15:57:11', NULL, 'Comedy, Slice of Life', 'OVA', NULL, 1, 5931, NULL, '2026-09-03 15:57:11', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3461, 'Tennis no Ouji-sama OVA ANOTHER STORY: Kako to Mirai no Message', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx5751-JesSCzrB9xeg.png', 'series', '7.0', 'An OVA series covering the past and the future of the regulars that participated in the National Tournament.

