INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3463, 'Gunslinger Girl: Il Teatrino OVA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx4765-h3AwHcF2UEM7.png', 'series', '6.7', 'Episodes 14 and 15 of Gunslinger Girl: Il Teatrino.', 'Artland', '2008', 'series', 'released', '2008-10-24', 4765, 0, NULL, '2026-08-29 15:03:15', '2026-09-03 15:57:21', NULL, 'Action, Drama, Sci-Fi', 'OVA', 'FALL', 2, 5195, NULL, '2026-09-03 15:57:21', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3464, 'Casshan: Robot Hunter', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx1598-2p6wAuyMHN7z.jpg', 'series', '5.8', 'In the near future, robot technology has advanced to the point of self-awareness. Under the leadership of the "Black King," machines have decimated the human population and conquered the world. Those who survived the early holocaust have been enslaved for life. But throughout the hardships, a lone hero appears as the savior of mankind. He is Casshan - a fusion of man and machine driven to combat Black King and his forces to the end.

(Source: Anime News Network)', 'Tatsunoko Production', '1993', 'series', 'released', '1993-08-21', 1598, 0, NULL, '2026-08-29 15:03:35', '2026-09-03 15:57:24', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n1598-dCIGIhK0aHuR.jpg', 'Adventure, Mecha, Sci-Fi', 'OVA', 'SUMMER', 4, 3242, NULL, '2026-09-03 15:57:24', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3465, 'Neo Human Casshan', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx4810-z6hzFJ09abAC.png', 'series', '6.2', 'The brilliant Dr. Azuma created many robots to aid humankind. However, during a thunderstorm his lab was struck by lightning, corrupting the programming of one of his robots, BK-1, who renames himself Braiking Boss and declares that instead of serving mankind, mankind will now serve him!  He brings other robots together into an overwhelming army bent on enslaving the human race. 

Tetsuya, Dr. Azuma''s son, asks his father to turn him into an indestructible android so that he will have the power to destroy the threat his father inadvertently created. Shortly thereafter, Braiking Boss captures Dr. Azuma and his wife,  Tetsuya, now renamed Casshern, sets out to turn the tide of the war and rescue his parents, with the help of his girlfriend, Luna, and robot dog, Friender.', 'Tatsunoko Production', '1973', 'series', 'released', '1973-10-02', 4810, 0, NULL, '2026-08-29 15:03:35', '2026-09-03 15:57:26', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n4810-sVl431wBc162.jpg', 'Action, Mecha, Sci-Fi', 'TV', 'FALL', 35, 3049, NULL, '2026-09-03 15:57:26', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3466, 'Initial D BATTLE STAGE 3', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx132634-ePR2y63z2sZO.jpg', 'series', '7.2', 'The third compilation OVA of Initial D. This time it features every race from Fifth Stage and Final Stage. Although it follows the same format as the two previous Battle Stages, this OVA doesn''t include any conversation nor any new races.', 'SynergySP', '2021', 'series', 'released', '2021-03-05', 132634, 0, NULL, '2026-08-29 15:03:39', '2026-09-03 15:57:29', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/132634-49yez1qj7sdd.jpg', 'Action, Sports', 'OVA', 'WINTER', 1, 3576, NULL, '2026-09-03 15:57:29', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3467, 'Magical Girl Lyrical Nanoha ViVid', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/20820-QjhVyCHX5ZI8.jpg', 'series', '6.4', 'The manga takes place four years after the JS incident in Magical Girl Lyrical Nanoha StrikerS, and stars Vivio Takamichi, a fourth-year elementary student at St. Hilde Academy of Magic. Vivio has learned to conjure her adult form and has received her own Device — named Sacred Heart — from Nanoha, and has promised Nanoha to never use either for mischief. Then a mysterious magical fighter appears and targets Vivio.

(Source: Anime News Network)', 'A-1 Pictures', '2015', 'series', 'released', '2015-04-03', 20820, 0, NULL, '2026-08-29 15:03:47', '2026-09-03 15:57:32', NULL, 'Action, Adventure, Mahou Shoujo, Sports', 'TV', 'SPRING', 12, 9023, NULL, '2026-09-03 15:57:32', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3468, 'Mahou Shoujo Lyrical Nanoha StrikerS: Picture Drama - Midchilda Gakuen e Youkoso!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b108730-mrqPezOjeeVo.jpg', 'series', '4.9', 'A picture drama released on the BD Box Set of Mahou Shoujo Lyrical Nanoha StrikerS. Subaru, Teana, Vivio host a radio show promoting their own BD Box Sets. They look at a hypothetical Midchilda Academy with all the core cast is present be it as students or as teachers.', NULL, '2015', 'series', 'released', '2015-02-25', 108730, 0, NULL, '2026-08-29 15:03:47', '2026-09-03 15:57:35', NULL, 'Comedy, Mahou Shoujo', 'SPECIAL', 'WINTER', 1, 684, NULL, '2026-09-03 15:57:35', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3469, 'Forest of Piano', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx100401-frKNiXOnRKdu.jpg', 'series', '7.1', 'A tranquil tale about two boys from very different upbringings. On one hand you have Kai, born as the son of a prostitute, who''s been playing the abandoned piano in the forest near his home ever since he was young. And on the other you have Shuuhei, practically breast-fed by the piano as the son of a family of prestigious pianists. Yet it is their common bond with the piano that eventually intertwines their paths in life.

(Source: KEFI)', 'Gaina', '2018', 'series', 'released', '2018-04-09', 100401, 0, NULL, '2026-08-29 15:03:50', '2026-09-03 15:57:38', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100401-ox7dBr8i1q35.jpg', 'Drama, Music', 'TV', 'SPRING', 12, 36793, 'https://www.youtube.com/watch?v=fRVj2zFlpyM', '2026-09-03 15:57:38', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3470, 'My Bride is a Mermaid Fan Disc', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/5199.jpg', 'series', '6.2', 'Fan discs containing shorts that weren''t included in the TV series. 

1. Aoi Koi-hen

2. Ibara Koiji-hen

Music videos from both discs are not included in the entry, as they don''t contain any new scenes.

The same specials were included in the Blueray box set, but divided into 6 episodes of 2 minutes each.', NULL, '2008', 'series', 'released', '2008-09-16', 5199, 0, NULL, '2026-08-29 15:03:54', '2026-09-03 15:57:41', NULL, 'Comedy', 'SPECIAL', 'FALL', 2, 2201, NULL, '2026-09-03 15:57:41', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3471, 'Seto no Hanayome Picture Drama', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/n107255-XSxjF8KSIN4s.jpg', 'series', '5.2', 'An exclusive picture drama released with the Blu-Ray Box Set of Seto no Hanayome. The first part starts out with gags and the characters drawn in a simplistic chibi style. It''s followed by a quick recap and then goes into the main picture drama story.

(Source: Kitsu).', 'AIC', '2010', 'series', 'released', '2010-03-03', 107255, 0, NULL, '2026-08-29 15:03:54', '2026-09-03 15:57:44', NULL, 'Comedy, Romance', 'SPECIAL', 'WINTER', 1, 854, NULL, '2026-09-03 15:57:44', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3472, 'Yu-Gi-Oh! 3D: Bonds Beyond Time', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx6951-v1SyAUSXOJXD.png', 'movies', '6.9', 'While riding with Jack Atlas and Crow Hogan, Yusei Fudos''s Stardust Dragon is captured by Paradox, a mysterious Turbo Duelist from the future, during a Turbo Duel and turned into a Sin Monster. With the help of the Crimson Dragon, Yusei chases after Paradox as he enters a time slip, ending up in the past. During this time, Paradox duels against Jaden Yuki, who is still able to use the powers of Yubel and The Supreme King. However, by this time Paradox had also captured Cyber End Dragon and Rainbow Dragon and overwhelms Jaden. He is saved thanks to Yusei and the Crimson Dragon. Jaden informs Yusei of Paradox''s true intentions. By stealing various monsters from across time and turning them dark, he plans to kill Maximillion Pegasus, the creator of Duel Monsters, preventing the game from being created and causing the events of all three series to never happen. Yusei and Jaden agree to pursue Paradox, which leads them to the past and causes a meeting with the King of Games, Yugi Mutou. However, by the time Yusei & Jaden arrive, Paradox had already attacked his time, supposedly killing both Pegasus and Yugi''s grandpa, and had also managed to steal Blue-Eyes White Dragon and Red-Eyes Black Dragon. After explaining everything to Yugi, he agrees to fight with Yusei and Jaden against Paradox in the ultimate three-on-one duel to free the trapped monsters and save both the world and time itself before it''s too late.

(Source: Wikipedia)', 'Studio Gallop', '2010', 'movie', 'released', '2010-01-23', 6951, 0, NULL, '2026-08-29 15:03:57', '2026-09-03 15:57:47', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/6951-MEnJ8PCCwDHK.jpg', 'Adventure', 'MOVIE', 'WINTER', 1, 15394, NULL, '2026-09-03 15:57:47', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3473, 'Yu☆Gi☆Oh! 5D''s: Shinkasuru Kettou! Stardust VS Red Demon''s', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx21590-uBTVEwa90RIB.jpg', 'series', '6.7', 'A non-canon Yu-Gi-Oh! 5D''s special from the 2008 Super Jump Anime Tour. Yuusei Fudou and Jack Atlas face off in a Riding Duel for the title of Duel King, with Aki and the twins watching. The ace dragons, Stardust Dragon and Red Daemon''s Dragon, clash once again, and this time gain the power to ''evolve'' using the Buster Mode trap card, becoming "Stardust Dragon/Buster" and "Red Demon''s Dragon/Buster."', NULL, '2008', 'series', 'released', '2008-09-21', 21590, 0, NULL, '2026-08-29 15:03:58', '2026-09-03 15:57:50', NULL, 'Action, Fantasy, Sci-Fi', 'SPECIAL', 'FALL', 1, 3041, NULL, '2026-09-03 15:57:50', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3474, 'Black Butler II', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx6707-eZvzqWlu51DD.png', 'series', '6.7', 'In late-nineteenth century England, one year and three months after the dramatic conclusion of the original series, Kuroshitsuji II introduces a new butler and young master. The sadistic yet cheerful Alois Trancy has faced some harsh times. He was kidnapped as a baby, and was forced to work in a village as a slave. Gradually, he lost his parents, his brother, and everyone he knew. Alois eventually returned home and became the head of his mansion, but seemed to exhibit some strange behavior ever since. Even more curiously, he returned with Claude Faustus, an enigmatic, emotionless butler with unfathomable talent...

(Source: AnimeNewsNetwork)', 'A-1 Pictures', '2010', 'series', 'released', '2010-07-02', 6707, 0, NULL, '2026-08-29 15:04:01', '2026-09-03 15:57:53', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/6707-44Od4mQqKm2f.jpg', 'Action, Comedy, Fantasy, Mystery, Supernatural', 'TV', 'SUMMER', 12, 102789, NULL, '2026-09-03 15:57:53', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3475, 'Black Butler: Book of Circus', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/nx20606-58LzabjtVrwt.jpg', 'series', '7.9', 'In late-nineteenth-century England, the Noah''s Ark Circus enlivens the city of London with their grandeur and spectacular stunts. However, children are mysteriously disappearing from the town in a manner correlating to the troupe''s movement. The Queen, then, sends her notorious Watchdog, Ciel Phantomhive, on an investigative mission to retrieve the missing children. Ciel and his demon butler, Sebastian Michaelis, infiltrate the circus, disguised as team members, to study and possibly unearth its ulterior motive.

This arc immediately follows the Curry Contest Arc in the manga, which ended at episode 15 in the first season of the anime.', 'A-1 Pictures', '2014', 'series', 'released', '2014-07-11', 20606, 0, NULL, '2026-08-29 15:04:01', '2026-09-03 15:57:56', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n20606-W6v0Gn5E5X0Z.jpg', 'Comedy, Fantasy, Mystery, Supernatural', 'TV', 'SUMMER', 10, 81237, NULL, '2026-09-03 15:57:56', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3476, 'Kyo Kara Maoh R', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx2971-7ZapuZNnTdzE.jpg', 'series', '7.0', 'Life has returned to some form of normalcy after the end of the series, and so His Majesty Yuuri Shibuya travels to oversee how things are going. While doing so, he runs into the king of Small Shimeron--Sararegi. But it seems there may be something more to him than the friendly king he presents himself as. Yuuri go back to Shimaron to relax and meet some friends, when the "king" of Little Shimaron suddenly joins the group and wants the Maou to come to his country. The Original king sends a message to Yuuri''s brother and his friend that Yuuri is in trouble.

