INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3498, 'Tentai Senshi Sunred: DVD Short Corners', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/8314.jpg', 'series', '5.4', 'Short corners released exclusively on DVD.', NULL, '2009', 'series', 'released', '2009-02-11', 8314, 0, NULL, '2026-08-29 15:08:11', '2026-09-03 15:59:40', NULL, 'Comedy', 'SPECIAL', 'WINTER', 4, 296, NULL, '2026-09-03 15:59:40', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3499, 'Junjo Romantica', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx3092-HjwfgrWFiUlu.jpg', 'series', '6.6', 'Three very different couples caught up in a storm of pure romance!

Romantica: Misaki is struggling to prepare for his college entrance exams, so his brother arranges for a private tutor. But Misaki''s nightmare is just beginning when his tutor, Usami, comes on to him! How will Misaki ever manage to pass his exam? And why does he feel so mysteriously drawn to Usami?

Egoist: Just when Kamijou''s life is at its lowest, he has a chance meeting with a man who never lets anything hold him back: Nowaki. His name means "typhoon," and he''s about to take Kamijou on a whirlwind ride that will turn everything upside-down.

Terrorist: Miyagi always seems to shrug off the cares of the world with a joke and a smile, but even he has problems, although he doesn''t let them show. Foremost is Shinobu, a relentless young man who''s adamant that they''re destined to be together.

(Source: RightStuf)', 'Studio DEEN', '2008', 'series', 'released', '2008-04-11', 3092, 0, NULL, '2026-08-29 15:08:20', '2026-09-03 15:59:43', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/3092-g60dQLpR39ra.jpg', 'Comedy, Drama, Romance', 'TV', 'SPRING', 12, 38599, NULL, '2026-09-03 15:59:43', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3500, 'Junjou Romantica 3', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx20796-GPazIJ2vnSea.png', 'series', '7.1', 'The third season of Junjou Romantica.

It follows the ongoing story of three couples:

The Romantica relationship between college student Misaki Takahashi and his tutor, Akihiko Usami.

The stormy Egoist couple—Professor Hiroki Kamijou, a tsundere, doted on by Nowaki Kusama.

The dramatic Terrorist couple—divorced literature professor Yo Miyagi, and his younger lover, Shinobu Tatasuki.

It’s complicated.

But so worth it.

(Source: Crunchyroll, edited)', 'Studio DEEN', '2015', 'series', 'released', '2015-07-09', 20796, 0, NULL, '2026-08-29 15:08:20', '2026-09-03 15:59:45', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20796-znkTkdoe9a4z.jpg', 'Drama, Romance', 'TV', 'SUMMER', 12, 19900, 'https://www.youtube.com/watch?v=yDrkg7RO2bk', '2026-09-03 15:59:45', NULL);
