INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3508, 'Blood: The Last Vampire', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/405-umT1upaBF6VG.jpg', 'movies', '6.6', 'Teropterids are evil beasts which pose as humans and live only to drink human blood. Fortunately for the human world there are groups dedicated to destroying them. A brooding and mysterious girl named Saya is the best teropterid slayer there is, and now, in 1960''s Japan, she is sent to a U. S. army base which may be infested... 

(Source: Anime News Network)', 'Production I.G', '2000', 'movie', 'released', '2000-11-18', 405, 0, NULL, '2026-08-29 15:08:53', '2026-09-03 16:00:09', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/405-yNU6meEyJuFs.jpg', 'Horror, Supernatural', 'MOVIE', 'FALL', 1, 24732, NULL, '2026-09-03 16:00:09', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3509, 'Blood-C', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx10490-Rqx4jlTOMFWx.jpg', 'series', '6.2', 'Saya is a seemingly normal girl living with her father in a shrine. During the day she goes to school and spends time with her friends at a local cafe. But when night falls Saya is called upon to protect her village from strange monsters. 

(Source: Anime News Network)', 'Production I.G', '2011', 'series', 'released', '2011-07-08', 10490, 0, NULL, '2026-08-29 15:08:53', '2026-09-03 16:00:13', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10490-N8ycOPxYdLda.jpg', 'Action, Horror, Mystery, Supernatural', 'TV', 'SUMMER', 12, 99974, 'https://www.youtube.com/watch?v=OWT9nlLp3q8', '2026-09-03 16:00:13', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3510, 'BLOOD-C: The Last Dark', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b10681-uogOpLtvaUX2.jpg', 'movies', '6.9', 'Despite the use of the Youth Ordinance Bill to enforce curfews for minors and regulate the use of the internet, young people continue to fight for their own freedom through underground methods. One such group calls themselves SIRRUT. They have decided to take on Fumito Nanahara, a man who has great influence on the political world, and basically controls Tokyo with an iron fist. While using the internet as a weapon to discover more information about Fumito, they learn about "Tower", the secret organization behind Fumito which engages in human experimentation.

When members of Surat attempt to set up an ambush in the subway to expose the truth behind "Tower", mysterious creatures suddenly appear and attack the passengers. During this crisis, Saya appears - a young girl who uses a Japanese blade to slay the Old Ones. The same Saya who lost everything dear to her in that horrifying incident in Ukishima Province. What sort of "experiment" is Fumito and "Tower" trying to conduct using the Old Ones? And can Saya finally deliver vengeance to Fumito?

Now, the final battle begins...

(Source: Official site)', 'Production I.G', '2012', 'movie', 'released', '2012-06-02', 10681, 0, NULL, '2026-08-29 15:08:53', '2026-09-03 16:00:16', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10681-3t28j15HfTtW.jpg', 'Action, Horror, Supernatural', 'MOVIE', 'SPRING', 1, 26991, NULL, '2026-09-03 16:00:16', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3511, 'Ghost in the Shell: Stand Alone Complex 2nd GIG - Individual Eleven - Tachikomatic Days', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/10948.jpg', 'series', '5.9', 'Tachikomatic Days short that was released on the Individual Eleven DVD.', NULL, '2006', 'series', 'released', '2006-01-27', 10948, 0, NULL, '2026-08-29 15:08:59', '2026-09-03 16:00:19', NULL, 'Comedy, Mecha, Sci-Fi', 'SPECIAL', 'WINTER', 1, 1892, NULL, '2026-09-03 16:00:19', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3512, 'The World''s Strongest Rearguard', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx198409-EiWJXfYnvfu4.png', 'series', '5.5', 'After a fatal accident, overworked office worker Arihito Atobe is reborn in the Labyrinth Country as a Seeker with the rare Rearguard class—an all-purpose support role that excels in attack, defense, and healing. Joined by a fierce demi-human mercenary and his former boss, Arihito dives into deadly dungeons and rises through the ranks. The adventure of the strongest support class begins!

(Source: Crunchyroll)', 'Maho Film', '2026', 'series', 'airing', '2026-07-05', 198409, 0, NULL, '2026-08-29 15:10:15', '2026-09-03 15:28:10', NULL, 'Action, Adventure, Fantasy', 'TV', 'SUMMER', 12, 26226, 'https://www.youtube.com/watch?v=vdJo_3uZ92s', '2026-09-03 15:28:10', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3513, 'The Insipid Prince''s Furtive Grab for the Throne', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx169582-quL8VMg45fcu.png', 'series', '5.8', 'To the empire, Prince Arnold is one big joke, a completely inept prince outshone by his more talented twin, Leonard. But in secret, Arnold operates as Silver, one of only five magic-wielding SS-rank adventurers on the continent. As the bloody battle for the throne intensifies after the crown prince’s death, Arnold pulls the strings from the shadows to crown his twin emperor to his own advantage.

(Source: Crunchyroll)', 'Maho Film', '2026', 'series', 'airing', '2026-07-06', 169582, 0, NULL, '2026-08-29 15:10:15', '2026-09-03 15:28:07', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/169582-D5p5iRI5XqML.jpg', 'Action, Comedy, Drama, Fantasy, Romance', 'TV', 'SUMMER', 12, 23479, 'https://www.youtube.com/watch?v=tcaxQBQMTEk', '2026-09-03 15:28:07', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3514, 'The Oblivious Saint Can''t Contain Her Power', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx196219-imvC0rbk4VzH.jpg', 'series', '6.3', 'Lady Carolina, the overlooked daughter of a powerful duke, has always believed herself to be the black sheep amid her illustrious kin. Her father is the distinguished prime minister; her elder sister, a prodigious mage destined to become their nation’s next Saint. In comparison, Carolina resigns herself to a quiet existence in their shadows until a sudden and unexpected royal decree alters her destiny, thrusting her into a political marriage with the formidable “Bloodthirsty Prince” of the neighboring Empire of Malcosias. Determined to prove her worth, Carolina takes a bold step into a world fraught with both political and mortal peril. As royal obligations intertwine with hints of true love and the stirrings of her own latent power, Carolina moves ever closer to understanding what it truly means to be exceptional.

(Source: J-Novel Club)', 'Magic Bus', '2026', 'series', 'airing', '2026-06-30', 196219, 0, NULL, '2026-08-29 15:10:17', '2026-09-03 15:28:03', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/196219-2F64WTRfqRU9.jpg', 'Drama, Fantasy, Romance', 'TV', 'SUMMER', 12, 19220, 'https://www.youtube.com/watch?v=R82wqxOXPIM', '2026-09-03 15:28:03', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3515, 'Victoria of Many Faces', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx198709-3PFLvU6eqPvf.jpg', 'series', '7.3', 'Betrayed by her own organization, Chloe flees her life as a spy and starts over under the new identity of Victoria in the Kingdom of Ashberry. Victoria wants a simple civilian life, but the locals have other plans, becoming enmeshed with an abandoned girl and a knight. As the trio bonds and Victoria’s past catches up to her, the skills she perfected as a spy prove useful in her new life.

(Source: Crunchyroll)', 'Studio DEEN', '2026', 'series', 'released', '2026-07-08', 198709, 0, NULL, '2026-08-29 15:10:17', '2026-09-03 15:27:57', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/198709-wyZYzcKM5itk.jpg', 'Action, Drama, Fantasy, Romance', 'TV', 'SUMMER', 9, 14923, 'https://www.youtube.com/watch?v=dm8QPSlRYdI', '2026-09-03 15:27:56', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3516, 'The Forsaken Saintess and Her Foodie Roadtrip in Another World', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx209504-yRxHWxKuNGtg.jpg', 'series', '6.1', 'Rin Takanashi, a caregiver in her thirties, was unceremoniously discarded as "trash" despite being summoned as a saint.

However, as a lover of the great outdoors and all things camping, she was blessed with a special skill, "Survival," as well as another unique skill! Thus, a riveting tale begins: one of sweat, tears, and insatiable hunger as Rin, together with companions she picked up along the way, leisurely explores this parallel world and savours gourmet cuisine to her heart''s content...

Or so the story should have gone, but it looks like their road is going in an unexpected direction...?', 'EMT Squared', '2026', 'series', 'airing', '2026-07-06', 209504, 0, NULL, '2026-08-29 15:10:17', '2026-09-03 15:27:53', NULL, 'Action, Adventure, Comedy, Fantasy', 'TV', 'SUMMER', 12, 13431, 'https://www.youtube.com/watch?v=VS0bW7JnEm0', '2026-09-03 15:27:53', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3517, 'Dara-san of the Reiwa Era', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx203880-lnruKftb27Nr.png', 'series', '6.5', 'After venturing into a restricted, treacherous mountain forest, siblings Hinata and Kaoru meet a terrifying serpent god and become besties! Despite her initially scary appearance, the self-named “god of misfortune” is awkward, lonely, and surprisingly easy to talk to. This is the tale of an unexpected friendship, and the many comedic, heartfelt adventures that ensue.

(Source: Crunchyroll)', 'Asahi Production', '2026', 'series', 'airing', '2026-07-02', 203880, 0, NULL, '2026-08-29 15:10:17', '2026-09-03 15:28:25', NULL, 'Comedy, Horror, Supernatural', 'TV', 'SUMMER', 13, 12731, 'https://www.youtube.com/watch?v=AZKlUSu5tQ0', '2026-09-03 15:28:25', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3518, 'False Memory (2026)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx141953-S3RozQSOxzrw.png', 'series', '8.5', 'In order to return to the past, Guan Chao searches for the "Burning Stone", the energy source that can activate the Time Gun, but unexpectedly falls into the Memory Administration Bureau. To return to reality, Guan Chao teams up with memory administrators such as Fang Tang and Bai Zhong to recover the BUG Beings in the memory layers level by level. As the battles conclude one after another, what Guan Chao must face is...

(Source: Bilibili, translated)', 'Studio Tumble', '2026', 'series', 'released', '2026-08-02', 141953, 0, NULL, '2026-08-29 15:10:17', '2026-09-03 15:28:16', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/141953-5o87aOKuZf8c.jpg', 'Action, Mystery, Psychological', 'ONA', NULL, 7, 13012, 'https://www.youtube.com/watch?v=yfz2c9LE6ew', '2026-09-03 15:28:16', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3519, 'My Stepmother and Stepsisters Aren’t Wicked', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx196356-2TNt2b9tu0jm.jpg', 'series', '6.4', 'Miya is the illegitimate child of a prominent family. When her mother dies and her father’s estate agrees to take her in, she’s convinced she knows what awaits her in her new home: a life of servitude and misery at the hands of her wicked stepmother and stepsisters. Yet when she finally meets the women she expects to treat her like dirt, they actually end up being…sweet?! A hilarious and heartfelt comedy that’s sure to put a smile on your face!

(Source: Seven Seas Entertainment)', 'NEWON', '2026', 'series', 'airing', '2026-07-08', 196356, 0, NULL, '2026-08-29 15:10:17', '2026-09-03 15:28:00', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/196356-OUT2nMhW0IdS.jpg', 'Comedy, Slice of Life', 'TV', 'SUMMER', NULL, 11455, 'https://www.youtube.com/watch?v=2UBOHZNG1fM', '2026-09-03 15:28:00', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3520, 'Red River', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx207809-cpS7CAyjN7iP.jpg', 'series', '6.1', 'After a mysterious hand drags her beneath a puddle, modern Japanese teenager Yuri awakens in the Hittite Empire of the 14th century BCE. Thrust into a deadly struggle for the throne, she joins Prince Kail to battle assassins, outwit royal conspiracies, and survive a world at war. As her exploits earn her renown as the goddess Ishtar, Yuri must choose between her old life and an uncertain future.

(Source: Crunchyroll)', 'Tatsunoko Production', '2026', 'series', 'airing', '2026-07-08', 207809, 0, NULL, '2026-08-29 15:10:17', '2026-09-03 15:40:04', NULL, 'Action, Adventure, Drama, Fantasy, Romance', 'TV', 'SUMMER', 24, 10150, 'https://www.youtube.com/watch?v=qpFcQ1Bek08', '2026-09-03 15:40:04', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3521, 'Iron Wok Jan!', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx204060-bKhovD8jAlW8.jpg', 'series', '7.0', 'Jan Akiyama, a cocky arrogant teenager wants to fulfill his grandfathers wish of defeating his arch nemesis Mutsuju Gobancho. When he arrives at the Gobancho restaurant he meets his granddaughter Kiriko Gobancho. Their rivalry is easily compared to Jan''s and Kiriko''s grandfathers, for Jan believes cooking is about competition and Kiriko believes cooking is about heart.', 'TROYCA', '2026', 'series', 'airing', '2026-07-05', 204060, 0, NULL, '2026-08-29 15:10:17', '2026-09-03 15:40:07', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/204060-3y19sqCToRaN.jpg', 'Action, Comedy', 'TV', 'SUMMER', NULL, 9973, 'https://www.youtube.com/watch?v=awvmDnz3URo', '2026-09-03 15:40:07', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3522, 'Mebius Dust', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx108992-skuOsfmLmMd2.jpg', 'series', '4.8', 'On February 29, 2000, a group of Möbius meteorites fell down to earth. These meteorites brought new material called Möbius Dust, which dissolves in air and can cause miracles. The day the Möbius meteorites fell was dubbed 2.29, and the economic disparity in Japan increased dramatically after that day. A group of people fed up with the wealth inequality fought back with acts of terrorism. The police established a special group to fight against the terrorists and a school to train members for that group.

</br>
(Sources: Comic Natalie, Live Chart)', 'Doga Kobo', '2026', 'series', 'airing', '2026-07-09', 108992, 0, NULL, '2026-08-29 15:10:17', '2026-09-03 15:28:19', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108992-5OIDQkTbM1id.jpg', 'Action, Supernatural', 'TV', 'SUMMER', NULL, 7568, 'https://www.youtube.com/watch?v=ByOF3FLlAws', '2026-09-03 15:28:19', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3523, 'BanG Dream! YUME∞MITA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx198376-sc5qcFv0RSH9.jpg', 'series', '7.4', 'Suddenly thrown together, a group of girls are now debuting as the virtual band, Mugendai Mewtype. They’ve got talent and personality, but no clue how to perform as one. Can they survive, let alone make it to the top in this unforgiving music world?

(Source: Crunchyroll)', 'NICHICALINE', '2026', 'series', 'airing', '2026-07-02', 198376, 0, NULL, '2026-08-29 15:10:19', '2026-09-03 15:40:01', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/198376-1b4DxjIUwMIY.jpg', 'Comedy, Drama, Music, Slice of Life', 'TV', 'SUMMER', 13, 7089, 'https://www.youtube.com/watch?v=sMcHl3g6aS4', '2026-09-03 15:40:01', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3524, 'Hana-Kimi Season 2', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx209669-7GlPe2ra5f1i.jpg', 'series', '6.9', 'The second season of Hanazakari no Kimitachi e.

Note: Hanazakari no Kimitachi e 2nd Season is streaming 1 week in advance of the TV broadcast on Prime Video and Crunchyroll beginning with episode 2 on July 2nd.', 'Signal.MD', '2026', 'series', 'airing', '2026-07-02', 209669, 0, NULL, '2026-08-29 15:10:19', '2026-09-03 15:39:58', NULL, 'Comedy, Drama, Romance, Slice of Life', 'ONA', 'SUMMER', 13, 6810, 'https://www.youtube.com/watch?v=dN7LV-oVFBg', '2026-09-03 15:39:58', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3525, 'Let''s go KAIKIGUMI', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx200230-YuzdgbXSgi38.png', 'series', '5.6', 'The horror comedy manga begins one fateful day when the cowardly (unnamed) protagonist meets Mechako, the leader of the "Kaikigumi" organization which is in charge of the ghosts and supernatural creatures scaring humans. The protagonist somehow takes part in the revival of the Kaikigumi, after which one bizarre (yet not scary) phenomenon after another crops up around him.

(Source: ANN)', 'C-Station', '2026', 'series', 'airing', '2026-07-05', 200230, 0, NULL, '2026-08-29 15:10:19', '2026-09-03 15:39:55', NULL, 'Comedy, Horror, Supernatural', 'TV', 'SUMMER', 12, 5577, 'https://www.youtube.com/watch?v=3DKfmW2aDhY', '2026-09-03 15:39:55', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3526, 'Crowned in a Hundred Days', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx213484-FIyYH43ASHgB.png', 'series', '6.2', 'Driven to the brink of despair, restaurant owner Ming forms an unlikely bond with the soul of the true King Lie after swallowing it to save his loved one. Bound together by fate, the two embark on a perilous journey to challenge the tyrant who has usurped the throne.

With only one hundred days to change their destiny, Ming uses his extraordinary memory to master long-lost magic, gathering allies and winning the support of the people along the way. As their strength grows, so does their resolve to overthrow a corrupt regime, reclaim the rightful king''s throne, and restore peace to the realm.

(Source: Bilibili TV)', 'Studio LAN', '2026', 'series', 'airing', '2026-07-03', 213484, 0, NULL, '2026-08-29 15:10:19', '2026-09-03 15:28:22', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/213484-Apezw4iSrrr6.jpg', 'Action, Adventure, Fantasy', 'ONA', NULL, 25, 3257, 'https://www.youtube.com/watch?v=IYcGvpXYfGE', '2026-09-03 15:28:22', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3527, 'One-Room TA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx205068-KPJVtEp9imju.jpg', 'series', '6.8', 'When college student U-Yun meets the quiet and introverted TA Jin-Hyeong, he immediately asks him out, saying he wants to get to know him more. After just three days of dating, Jin-Hyeong moves in with him, and that’s when he starts showing a completely different wild side. All of his BL novel and comic consumption has perverted his perception of the perfect first time with his boyfriend. He’s thought of it all, from doing it in the subway to having U-Yun role-play as a K-pop idol. But as weird as Jin-Hyeong’s ideas are, U-Yun doesn’t entirely hate it...?

(Source: Tappytoon)', NULL, '2026', 'series', 'airing', '2026-08-28', 205068, 0, NULL, '2026-08-29 15:10:19', '2026-09-03 15:28:50', NULL, 'Comedy, Romance, Slice of Life', 'ONA', NULL, 7, 3007, 'https://www.youtube.com/watch?v=MIGS_dy-teU', '2026-09-03 15:28:50', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3528, 'Saved By the Ice Cold Prince''s Embrace', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx213665-E6byznDKrKY0.png', 'series', '5.0', 'As the illegitimate daughter of a count and his maid, Katrina was born into miserable circumstances. And now that she''s lost her mother, the treatment from her stepsister and stepmother the countess has only grown worse. One day, her stepsister receives a royal order to move to the northern outskirts due to her unseemly behavior at a recent party. There, she is to learn proper conduct under the tutelage of the resident prince, rumored to be a cruel man. Not wanting to subject her daughter to such punishment, the countess decides to send Katrina instead. Katrina arrives in the north shaking in fear. But contrary to the stories, the "merciless and cold-hearted" prince is kinder than she believed. Might the pure-hearted Katrina find love in the wintry countryside?

(Source: MangaPlaza)', 'Imageworks Studio', '2026', 'series', 'airing', '2026-07-07', 213665, 0, NULL, '2026-08-29 15:10:19', '2026-09-03 15:28:47', NULL, 'Fantasy, Romance', 'TV_SHORT', 'SUMMER', NULL, 2772, 'https://www.youtube.com/watch?v=Q3zyZrf3uyY', '2026-09-03 15:28:47', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3529, 'Perfect Addiction', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx213666-nnKcumRblZi1.jpg', 'series', '5.3', 'Akihito is a college student obsessed with looks and sex, but he can''t stand the handsome-yet-aloof Sae. Things come to a head when Akihito is shot down at a singles mixer by a girl who''s set her romantic sights on Sae. Furious, he follows Sae to the hotel district where he learns Sae''s secret: he''s gay, and a bottom. Sae confesses he''s been having trouble feeling pleasure from sex. Breaking through Sae''s mental barriers is exactly the lovemaking challenge Akihito needed. It awakens something in them both. Will they ever be able to control themselves again?

(Source: Seven Seas Entertainment)', 'Imagica Infos', '2026', 'series', 'airing', '2026-07-08', 213666, 0, NULL, '2026-08-29 15:10:22', '2026-09-03 15:28:13', NULL, 'Drama, Romance', 'ONA', 'SUMMER', NULL, 2590, 'https://www.youtube.com/watch?v=F087cECqMr8', '2026-09-03 15:28:13', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3530, 'Sazae-san', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx2406-nP8NIct9Sci3.jpg', 'series', '5.6', 'The main character is a mother named Sazae-san. She lives in a house with her husband, her kid, her siblings and her parents. The show is the ultimate family program and tends to follow traditional themes. Think of this show as the Japanese equivalent to "The Partridge Family" and you''ll get a good feel for this show''s atmosphere. Don''t expect to see things like violence, swearing, kung-fu action or magical girls. The plots are more like "Today, Sazae-san goes to the new mall and gets lost". Such "boring" plotlines and the simplistic art are often a turn-off to non-Japanese audiences, but most Japanese find the show incredibly good. As a result, it continues to be one of the top ratings grabbers on TV and is one of the few anime that is considered "acceptable" by adults.', 'Eiken', '1969', 'series', 'airing', '1969-10-05', 2406, 0, NULL, '2026-08-29 15:10:22', '2026-09-03 15:28:44', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2406-ROqXxejQ5bH9.jpg', 'Comedy, Slice of Life', 'TV', 'FALL', NULL, 2507, NULL, '2026-09-03 15:28:44', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3531, 'Flaming Dodgeball Girl Danko', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx195833-h7x6i3NQWROA.jpg', 'series', '5.8', 'The sequel to the legendary dodgeball manga Honou no Toukyuuji Dodge Danpei! In this modern version of the hot-blooded dodgeball story, Danpei''s daughter, Danko, follows in his footsteps, struggling to build a dodgeball team with the strongest fighting spirit in the modern age of 2025! Can Danko overcome the apathetic attitude of today''s world? 

(Source: Corocoro, translated)', 'CUE', '2026', 'series', 'airing', '2026-07-06', 195833, 0, NULL, '2026-08-29 15:10:22', '2026-09-03 15:28:40', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/195833-DlR4ToMXP3if.jpg', 'Comedy, Sports', 'TV', 'SUMMER', 12, 1982, 'https://www.youtube.com/watch?v=IRbt0J3l5js', '2026-09-03 15:28:40', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3532, 'Tunshi Xingkong 4', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx166219-tREIb5l5huVe.png', 'series', '8.0', 'The fourth season of Tunshi Xingkong.

