INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3534, 'RILAKKUMA', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b183231-z7SgjmXZBcoX.png', 'series', '6.2', 'Everyday life gets a cozy twist with the laid-back Rilakkuma. Gentle moments of friendship, change, and small joys unfold, turning ordinary moments into something quietly magical—one soft, comforting day at a time.

It''s a moment that will make your heart feel lighter and lighter. No matter where you are or what you''re doing, Rilakkuma will be by your side. An exciting new story begins! Experience the stress-free world of Rilakkuma, the relaxed bear who makes being lazy look effortless!

(Source: Crunchyroll, Rilakkuma Anime Site, translated)', 'Production I.G', '2026', 'series', 'airing', '2026-04-04', 183231, 0, NULL, '2026-08-29 15:10:22', '2026-09-03 15:28:28', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/183231-JFjTqQe3rPCw.jpg', 'Fantasy, Slice of Life', 'TV_SHORT', 'SPRING', NULL, 1632, 'https://www.youtube.com/watch?v=rV-fcFL5vtU', '2026-09-03 15:28:28', NULL);
