INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3537, 'ONE PIECE FILM: BAAD', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/b215856-0V3mzYbhODqZ.png', 'movies', '0.0', NULL, NULL, '2029', 'movie', 'upcoming', '2029-01-01', 215856, 0, NULL, '2026-09-03 15:29:40', '2026-09-03 15:45:53', NULL, '', 'MOVIE', NULL, 1, 4539, 'https://www.youtube.com/watch?v=E3Zk2270um8', '2026-09-03 15:45:53', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3538, 'Pokémon: Wild Card', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/bx216167-rqCRXovzDMJO.png', 'movies', '0.0', 'Pokémon: Wild Card tells the exciting story of a Pokémon TCG player and his partner Mimikyu. When the time comes to put their cards on the table, will they have what it takes to achieve their goals?

(Source: The Pokémon Company)', 'CloverWorks', '2027', 'movie', 'upcoming', '2027-01-01', 216167, 0, NULL, '2026-09-03 15:29:42', '2026-09-03 15:45:56', NULL, '', 'MOVIE', NULL, 1, 1919, 'https://www.youtube.com/watch?v=H6_jMQ6whtQ', '2026-09-03 15:45:56', NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3539, 'Area 88 (TV)', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/284.jpg', 'series', '6.5', 'Deep in the sandy plains of the Middle Eastern kingdom of Asran, Japanese photojournalist Makoto Shinjou travels to the remote airbase Area 88 to document the activities of the mercenaries who destroy the country''s enemies for a living. Among their ranks is Shin Kazama, a Japanese ace pilot who was tricked by his former best friend into signing a contract with the Asran''s fighter squad. Because of this, he lost his career as an airline pilot and the chance to marry his fiancee Ryoko Tsugumo. Now, Shin has three choices in order to leave Area 88 and return to Japan: serve the mercenary group for three years, earn US$1.5 million, or desert the base, risking imminent death.

(Source: Anime News Network)', 'TV Asahi', '2004', 'series', 'released', '2004-01-09', 284, 0, NULL, '2026-09-03 16:33:19', '2026-09-03 16:33:19', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/284-aWFTdXqk9KLi.jpg', 'Action, Drama, Romance', 'TV', 'WINTER', 12, 3530, NULL, NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3540, 'Area 88 Movie', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/98129-thueGScDFCCf.jpg', 'movies', '6.1', 'Kazama Shin, tricked and forced into fighting for the remote country of Arslan, can only escape the hell of war by earning money for shooting down enemy planes or die trying. As the war rages on, Shin has to deal with the consequences of killing and friends dying around him as he tries to keep his mind on freeing himself from this nightmare.

(Source: Anime News Network)', NULL, '1985', 'movie', 'released', '1985-07-20', 98129, 0, NULL, '2026-09-03 16:33:19', '2026-09-03 16:33:19', NULL, 'Action, Adventure, Drama, Romance', 'MOVIE', 'SUMMER', 1, 908, NULL, NULL, NULL);
INSERT INTO `animes` (`id`, `name`, `src`, `category`, `rating`, `description`, `studio`, `year`, `type`, `status`, `releaseDate`, `anilistId`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`, `bannerImage`, `genres`, `format`, `season`, `episodes`, `popularity`, `trailer`, `lastSuccessfulRefreshAt`, `relationsCheckedAt`) VALUES (3542, 'Tomorrow Will Become Better!: Half a Sweet Potato', 'https://s4.anilist.co/file/anilistcdn/media/anime/cover/small/17493.jpg', 'movies', '4.7', 'The story is about a 5-year-old girl who lived in just after World War II when people were struggle for living.

(Source: AnimeNfo)', 'AYCO', '2005', 'movie', 'released', '2005-06-30', 17493, 0, NULL, '2026-09-03 16:33:43', '2026-09-03 16:33:43', NULL, 'Drama', 'MOVIE', 'SUMMER', 1, 452, NULL, NULL, NULL);

