  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `src` varchar(255) NOT NULL,
  `category` varchar(255) NOT NULL,
  `rating` varchar(255) NOT NULL,
  `year` varchar(255) DEFAULT NULL,
  `studio` varchar(255) DEFAULT NULL,
  `description` text,
  `homeFeatured` tinyint(1) DEFAULT '0',
  `homeOrder` int DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  UNIQUE KEY `name_2` (`name`),
  UNIQUE KEY `name_3` (`name`),
  UNIQUE KEY `name_4` (`name`),
  UNIQUE KEY `name_5` (`name`),
  UNIQUE KEY `name_6` (`name`),
  UNIQUE KEY `name_7` (`name`),
  UNIQUE KEY `name_8` (`name`),
  UNIQUE KEY `name_9` (`name`),
  UNIQUE KEY `name_10` (`name`),
  UNIQUE KEY `name_11` (`name`),
  UNIQUE KEY `name_12` (`name`),
  UNIQUE KEY `name_13` (`name`),
  UNIQUE KEY `name_14` (`name`),
  UNIQUE KEY `name_15` (`name`),
  UNIQUE KEY `name_16` (`name`),
  UNIQUE KEY `name_17` (`name`),
  UNIQUE KEY `name_18` (`name`),
  UNIQUE KEY `name_19` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (1, 'SANDA', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086307/sanda_jw2n6h.jpg', 'Shounen, Action, Mystery, School', '0.00', '2025', 'Science SARU', 'In a future where children are few and regarded as Japan''s most valuable assets, Christmas has become a mere legend of the past. For the students of Daikoku Welfare Academy—a boarding school where they are educated, protected, and monitored—the mythical Santa Claus is a forgotten character of fiction. For the adults, Santa Claus is a very real menace that needs to be neutralized by the Saint Nick Pursuit Unit in case he makes an appearance.

Shiori Fuyumura, a student of Daikoku Welfare Academy, is determined to find her best friend, Ichie Ono, who has been declared dead after being missing for six months. One morning, Fuyumura summons her fellow class representative, Kazushige Sanda, only to attack the unknowing boy. She is convinced that Sanda is the descendant of the infamous Santa Claus—the only person who can make her wish of finding Ono come true—and is determined to force out his dormant true self by any means necessary.

(Source: MAL Rewrite)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:00');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (2, 'THE SUMMER HIKARU DIED', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086290/hikaru-ga-shinda-natsu-655f6629af_fdj4l1.jpg', 'Supernatural, Mystery, Horror', '0.00', '2025', 'CygamesPictures', 'Two best friends living in a rural Japanese village: Yoshiki and Hikaru. Growing up together, they were inseparable… until the day Hikaru came back from the mountains, and was no longer himself. “Something” has taken over Hikaru’s body, memories, feelings… and everything they know begins to unravel.

(Source: Netflix)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:01');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (3, 'TOUGEN ANKI', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086312/tougen-anki-d229b4fd56_odclfu.jpg', 'Shounen, Action, Fiction', '0.00', '2025', 'Studio Hibari', 'The bloodlines of “Oni” and “Momotarou” have been passed down among certain humans for generations.

Long ago, the Oni, aware of their own ferocity, lived in seclusion. However, their peace was shattered by an invasion led by Momotarou.
Over thousands of years, these two factions formed the “Momotarou Agency” and the “Oni Agency,” respectively, and have been locked in conflict ever since.

The protagonist, Shiki Ichinose, suddenly learns of his Oni lineage following an unexpected attack by Momotarou. This revelation sets Shiki on a path to discover the destiny that lies within his blood — a meeting with the Oni dwelling within him.

—A new generation of dark heroics begins here in this tale of demons!

(Source: Official Site)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:03');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (4, 'IKOKU NIKKI', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086293/ikoku-nikki-d440b93c03_hjqc5j.jpg', 'Drama, Josei', '0.00', '2026', 'Shuka', 'Reclusive novelist Makio Koudai has always preferred the company of books—but when her sister and brother-in-law pass away, Makio unexpectedly becomes the guardian of her 15-year-old niece, Asa Takumi. As they navigate grief, clashing personalities, and the challenges of living together, the two slowly open their hearts to each other, discovering warmth, understanding, and the meaning of family.

(Source: Crunchyroll)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:04');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (5, 'JUJUTSU KAISEN 3RD SEASON', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086296/jjk3rd_mnsyzv.jpg', 'Shounen, Action, Fiction, School', '0.00', '2023', 'MAPPA', 'The second season of Jujutsu Kaisen.

The past comes to light when second-year students Satoru Gojou and Suguru Getou are tasked with escorting young Riko Amanai to Master Tengen. But when a non-sorcerer user tries to kill them, their mission to protect the Star Plasma Vessel threatens to turn them into bitter enemies and cement their destinies—one as the world’s strongest sorcerer, and the other its most twisted curse user!

(Source: Crunchyroll)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:05');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (6, 'ONE PUNCH MAN 3', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086306/one-punch-man-3-7243d9cfca_secaej.jpg', 'Seinen, Comedy, Action, Parody, Super Power', '0.00', '2025', 'J.C.STAFF', 'The third season of One Punch Man.

Saitama is a hero who only became a hero for fun. After three years of "special training," he’s become so strong that he''s practically invincible. In fact, he''s too strong—even his mightiest opponents are taken out with a single punch. Alongside Genos, his faithful disciple, Saitama performs his official hero duties as a member of the Hero Association.

One day, monsters claiming to be from the Monster Association suddenly appeared, taking a child of Hero Association executive hostage. The S-class heroes gather and plan a raid on the Monster Association hideout to rescue the hostage. Meanwhile, Garou, a "human monster" who was taken by the Monster Association during a battle with the heroes, awakens in the Monster Association hideout.

(Source: EMOTION Label YouTube Channel Description)

Note: Excludes recap episode that aired a week before regular broadcast.', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:06');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (7, 'KILL AO', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086301/killao_hxtknu.webp', 'Shounen, Action, Comedy, School', '0.00', '2026', 'CUE', 'Juuzou Oogami is a legendary hitman who has never failed an assignment, no matter how impossible. One day, after wiping out a powerful organization, he is stung by a mysterious wasp and collapses. When he wakes up, the fearsome 39-year-old assassin has been transformed into a 13-year-old boy!

Before he can even process what happened, his boss delivers a new order: “In that body, infiltrate a middle school.”

What awaits him is an unexpected school life filled with colorful classmates, youthful chaos, and looming danger. Can Juuzou ever return to his original form? Or will the assassins closing in on him end his second life before it even begins!?

(Source: Official Site)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:08');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (8, 'MAID-SAN WA TABERU DAKE', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086302/maid-san-wa-taberu-dake-a79358a852_mckba6.jpg', 'Slice of Life', '0.00', '2026', 'EMT Squared', 'What''s a maid to do when she finds herself suddenly stuck in Japan for a year? Eat, of course! Follow maid-in-training Suzume Tachibana as she tries all sorts of Japanese food, from sweets like taiyaki and melon bread to savory snacks like takoyaki and onigiri! Be warned, though—while Suzume sates her appetite through delicious treat after delicious treat, she might just end up whetting yours!

(Source: Kodansha USA)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:09');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (9, 'LIAR GAME', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086301/liar-game-e71aedd1b2_atz0p4.jpg', 'Drama, Seinen, Psychological, Thriller, Game', '0.00', '2026', 'MADHOUSE', 'Wishing she would live up to the ideal, Kanzaki Nao''s father named her thusly for “honesty”. Nao has more than lived up to her father''s wishes--even exceeding them and earning the label of "a foolishly honest girl". This makes Nao the least qualified candidate for the high stakes ''Liar Game'', where winning requires deceiving the opponent out of their money and losing means receiving massive debt. However, that doesn''t stop a box containing a hundred million yen in cash and a card informing her of her participation in the game from arriving at her doorstep, nor does it stop her from being promptly tricked out of the entire sum of money. Upon hearing that a genius swindler, responsible for the bankruptcy of a major corporation, is being released from jail, Nao goes to the swindler, Shinichi Akiyama, to enlist his help. With that, the two are drawn into the dark, greed-filled, and deceptive world of the Liar Game.', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:10');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (10, 'JIGOKURAKU 2ND SEASON', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086294/jigokuraku-2nd-season_z5ddko.jpg', 'Shounen, Action, Adventure, Supernatural, Historical, Samurai', '0.00', '2026', 'MAPPA', 'The second season of Jigokuraku.', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:11');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (11, 'SEIHANTAI NA KIMI TO BOKU', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086308/seihantai-na-kimi-to-boku-04548b55a2_ib55cw.jpg', 'Shounen, Comedy, Romance, School', '0.00', '2026', 'Lapin Track', 'Suzuki’s a high school girl in love, but the guy she’s fallen for is nothing like her! While she’s cheerful, outgoing, and always trying to fit in, her classmate Yusuke Tani is stoic, quiet, and doesn’t seem to care what people think of him. Will Suzuki be able to overcome her anxieties and ask him out, or will she discover that opposites really don’t attract?

(Source: Crunchyroll)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:13');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (12, 'DARWIN JIHEN', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086289/darwin-jihen-3f995826e4_vifqiw.jpg', 'Seinen, Sci-Fi', '0.00', '2026', 'BELLNOX FILMS', 'Created in a biological science lab, Charlie is a half human, half chimpanzee hybrid known as a "Humanzee". Raised by his adoptive human parents, Charlie is now 15 and starting high school. There he meets Lucy, a clever loner who becomes his first-ever friend. But his “normal” life is shattered when the animal rights extremists who freed his mother from the lab fifteen years ago reemerge as terrorists bent on kidnapping Charlie at all costs.

(Source: Kodansha USA)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:14');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (13, 'ERIS NO SEIHAI', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086293/eris-no-seihai-223823430f_cmpfzr.jpg', 'Mystery, Supernatural', '0.00', '2026', 'Ashi Productions', 'Betrayed by her fiancé’s lover and sentenced to public execution, Constance Grail, a plain viscount’s daughter known for her honesty, faces death—until a mysterious voice offers salvation. Scarlett Castiel, a noblewoman long thought dead, may be her only hope. Together, these unlikely allies uncover a dark conspiracy lurking in the heart of high society, where betrayal, secrets, and power collide.

(Source: Crunchyroll)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:15');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (14, 'DEAD ACCOUNT', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086289/dead-account-08027de694_b7794u.jpg', 'Shounen, Action, Supernatural', '0.00', '2026', 'SynergySP', 'Always ready for a fight! Destruction for destruction’s sake! The online streamer Aoringo is a troll, making the worst of the worst of boundary-pushing flamebait content and raking in the revenue from the hate-watchers. You may think he’s nothing more than a bottom feeder and a drain on society, but in reality, he’s high school dropout Souji Enishiro, a caring older brother with a sweet tooth who loves nothing more than his little sister. His viral videos? Just a way to pay his sister’s medical bills. And even if all of humanity hates him, he doesn’t care, so long as his little sister gets better. But then, something very strange begins to happen...

(Source: Crunchyroll)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:41');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (15, 'MEDALIST 2ND SEASON', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086303/medalist-2nd-season-67a9250fc2_etvkuh.jpg', 'Drama, Sports, Psychological', '0.00', '2026', 'ENGI', 'The second season of Medalist.', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:43');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (16, 'CHAINSAW MAN: REZE-HEN', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086289/chainsaw-man-movie-reze-hen-b25d1e4562_bubmx3.jpg', 'Shounen, Action, Fiction', '0.00', '2025', 'MAPPA', 'Theatrical follow-up to Chainsaw Man.

Denji became “Chainsaw Man”, a boy with a devil’s heart, and is now part of Special Division 4’s devil hunters. After a date with Makima, the woman of his dreams, Denji takes shelter from the rain. There he meets Reze, a girl who works in a café.

(Source: MAPPA CHANNEL)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:44');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (17, 'KAGE NO JITSURYOKUSHA NI NARITAKUTE!: ZANKYOU-HEN', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086297/kage-no-jitsuryokusha-ni-naritakute-movie-zankyou-hen-1463b1a532_muowsi.jpg', 'Comedy, Action, Fiction, Isekai', '0.00', NULL, 'Nexus', 'Theatrical follow-up to Kage no Jitsuryokusha ni Naritakute! 2nd season.', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:55:12');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (18, 'MAHOU SHOUJO MADOKA☆MAGICA: WALPURGIS NO KAITEN', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086301/mahou-shoujo-madoka-magica-walpurgis-no-kaiten-7dc10f4bea_tmtuy4.jpg', 'Action, Thriller', '0.00', '2026', 'Shaft', 'The 10th anniversary online event for the Mahou Shoujo Madoka☆Magica anime revealed that the franchise is getting a new anime film titled Mahou Shoujo Madoka☆Magica: Walpurgis no Kaiten. The film will be an official sequel to the Mahou Shoujo Madoka☆Magica: Hangyaku no Monogatari film that opened in October 2013. The tagline on the new film''s visual reads, "Now, let''s continue the story."

(Source: Anime News Network, edited)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:47');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (19, 'ZOMBIELAND SAGA: YUME GINGA PARADISE', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086313/zombieland-saga-movie-471c461720_znahxa.jpg', 'Music, Parody, Comedy, Supernatural', '0.00', '2025', 'MAPPA', 'Anime movie announced during the live concert "Zombie Land Saga LIVE ～FranChouChou Saga yo tomoni waite kure～" held on Oct 17, 2021.', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:48');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (20, 'HYAKUEMU.', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771086292/hyakuemu-9b34b2327f_puucva.jpg', 'Drama, Sports', '0.00', '2025', 'ROCK''N ROLL MOUNTAIN', '100 METERS follows Togashi, a track star who is born to run. As a kid, he is naturally gifted and wins every 100-meter race without effort. But in sixth grade, he meets Komiya, a transfer student who is full of determination but lacks technique. In teaching him, Togashi gives Komiya a new purpose: to win no matter what. Years pass by, and Togashi and Komiya meet again as rivals on the track and reveal their true selves.

(Source: GKIDS)', 0, NULL, '2026-03-08 03:43:02', '2026-03-08 01:08:50');
INSERT INTO `comings` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (21, 'RE:ZERO KARA HAJIMERU ISEKAI SEIKATSU 4th SEASON', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1772929666/re-zero-starting-life-in-another-world-693d575e7fcbf_txqgxx.jpg', 'Fantasy, Isekai, Psychological, Drama, Thriller', '0.00', '2026', 'WHITE FOX', 'The fourth season of Re:Zero kara Hajimeru Isekai Seikatsu.

Note: World Premiere of Episode 1 screened at Lucca Comics & Games 2025 on November 1, 2025, before the Japanese television broadcast.', 0, NULL, '2026-03-08 03:57:05', '2026-03-08 01:08:51');

DROP TABLE IF EXISTS `contactmessages`;
CREATE TABLE `contactmessages` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `subject` varchar(255) NOT NULL,
  `message` text NOT NULL,
  `status` enum('unread','read','replied') NOT NULL DEFAULT 'unread',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

