DROP TABLE IF EXISTS `movies`;
CREATE TABLE `movies` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `src` varchar(255) NOT NULL,
  `category` varchar(255) NOT NULL,
  `rating` varchar(255) NOT NULL,
  `year` varchar(255) DEFAULT NULL,
  `studio` varchar(255) DEFAULT NULL,
  `description` text,
  `homeFeatured` tinyint(1) DEFAULT '0',
  `homeOrder` int DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  UNIQUE KEY `name_2` (`name`),
  UNIQUE KEY `name_3` (`name`),
  UNIQUE KEY `name_4` (`name`),
  UNIQUE KEY `name_5` (`name`),
  UNIQUE KEY `name_6` (`name`),
  UNIQUE KEY `name_7` (`name`),
  UNIQUE KEY `name_8` (`name`),
  UNIQUE KEY `name_9` (`name`),
  UNIQUE KEY `name_10` (`name`),
  UNIQUE KEY `name_11` (`name`),
  UNIQUE KEY `name_12` (`name`),
  UNIQUE KEY `name_13` (`name`),
  UNIQUE KEY `name_14` (`name`),
  UNIQUE KEY `name_15` (`name`),
  UNIQUE KEY `name_16` (`name`),
  UNIQUE KEY `name_17` (`name`),
  UNIQUE KEY `name_18` (`name`),
  UNIQUE KEY `name_19` (`name`),
  UNIQUE KEY `name_20` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (1, 'GINTAMA: THE FINAL', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085457/gintama-the-final-d071df2f41_hd7hyg.jpg', 'Drama, Action, Sci-Fi, Historical, Samurai', '9.08', '2021', 'Bandai Namco Pictures', 'Gintama: THE FINAL is the 3rd and final film adaptation of the remainder of the Silver Soul arc and is the series finale.

Two years have passed following the Tendoshuu''s invasion of the O-Edo Central Terminal. Since then, the Yorozuya have gone their separate ways. Foreseeing Utsuro''s return, Gintoki Sakata begins surveying Earth''s ley lines for traces of the other man''s Altana. After an encounter with the remnants of the Tendoshuu—who continue to press on in search of immortality—Gintoki returns to Edo.

Later, the regrouped Shinsengumi and Yorozuya begin an attack on the occupied Central Terminal. With the Altana harvested by the wreckage of the Tendoshuu''s ship in danger of detonating, the Yorozuya and their allies fight their enemies while the safety of Edo—and the rest of the world—hangs in the balance. Fulfilling the wishes of their teacher, Shouyou Yoshida''s former students unite and relive their pasts one final time in an attempt to save their futures.', 0, NULL, '2026-03-08 03:42:58', '2026-03-08 01:07:15');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (2, 'VIOLET EVERGARDEN MOVIE', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085469/violet-evergarden-movie-703dbc58ec_oofxkf.jpg', 'Drama, Sci-Fi', '8.93', '2020', 'Kyoto Animation', 'While writing other people’s emotions, she may have neglected her own. Violet Evergarden, the child soldier turned Auto Memory Doll, writes letters that evoke the words her clients can’t. But when a terminally ill boy requests her services for his family, her own feelings about love and loss resurface. Now she must confront her past and the death of the Major.

(Source: Funimation)', 0, NULL, '2026-03-08 03:42:58', '2026-03-08 01:07:16');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (3, 'KOE NO KATACHI', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085464/koe-no-katachi-bc9f756373_xekco8.jpg', 'Drama, Shounen', '8.88', '2016', 'Kyoto Animation', 'After transferring into a new school, a deaf girl, Shouko Nishimiya, is bullied by the popular Shouya Ishida. As Shouya continues to bully Shouko, the class turns its back on him. Shouko transfers and Shouya grows up as an outcast. Alone and depressed, the regretful Shouya finds Shouko to make amends.

(Source: Eleven Arts)', 0, NULL, '2026-03-08 03:42:58', '2026-03-08 01:07:18');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (4, 'KIMI NO NA WA.', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085459/kimi-no-na-wa-e0df3c0ba8_lnasaj.jpg', 'Drama', '8.78', '2016', 'CoMix Wave', 'Mitsuha Miyamizu, a high school girl, yearns to live the life of a boy in the bustling city of Tokyo—a dream that stands in stark contrast to her present life in the countryside. Meanwhile in the city, Taki Tachibana lives a busy life as a high school student while juggling his part-time job and hopes for a future in architecture.

One day, Mitsuha awakens in a room that is not her own and suddenly finds herself living the dream life in Tokyo—but in Taki''s body! Elsewhere, Taki finds himself living Mitsuha''s life in the humble countryside. In pursuit of an answer to this strange phenomenon, they begin to search for one another.

Kimi no Na wa. revolves around Mitsuha and Taki''s actions, which begin to have a dramatic impact on each other''s lives, weaving them into a fabric held together by fate and circumstance.

(Source: MAL Rewrite)', 0, 3, '2026-03-08 03:42:58', '2026-03-08 01:07:19');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (5, 'KAGUYA-SAMA WA KOKURASETAI: FIRST KISS WA OWARANAI', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085458/kaguya-sama-wa-kokurasetai-shinsaku-animation-be7fc51167_dhxsdf.jpg', 'Drama, Comedy, Seinen, Romance, School', '8.76', '2023', 'A-1 Pictures', 'Shuchiin Academy’s student council room: the place where Student Council Vice President Kaguya Shinomiya and President Miyuki Shirogane met. After a long battle in love, these two geniuses communicated their feelings and, at the Hoshin Festival, had their very first kiss. However, there was no clear confession of love. The relationship between these two, who assumed they would be a couple, remains ambiguous. Now, overly conscious of their feelings, they must face the biggest challenge yet: Christmas. It’s Shirogane who wants it to be perfect versus Kaguya who pursues the imperfect situation. This is the very “normal” love story of two geniuses and the first kiss that never ends.

(Source: Aniplex of America)

Note: The anime first premiered in theaters across Japan on December 17, 2022. It was later split into 2 parts on TV, and 4 episodes on streaming, and Blu-Ray/DVD.', 0, NULL, '2026-03-08 03:42:58', '2026-03-08 01:07:20');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (6, 'SEISHUN BUTA YAROU WA YUMEMIRU SHOUJO NO YUME WO MINAI', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085465/seishun-buta-yarou-wa-yumemiru-shoujo-no-yume-wo-minai-30ca761c7c_jpqjnm.jpg', 'Drama, Supernatural, Romance, School', '8.67', '2019', 'CloverWorks', 'In Fujisawa, where the skies are bright and the seas glisten, Sakuta Azusagawa is in his second year of high school. His blissful days with his girlfriend and upperclassman, Mai Sakurajima, are interrupted with the appearance of his first crush, Shouko Makinohara. For reasons unknown, he encounters two Shouko''s: one in middle school and another who has become an adult.

As Sakuta finds himself helplessly living with the Shouko''s, the adult Shouko leads him around by the nose, causing a huge rift in his relationship with Mai.

In the midst of all of this, he discovers that the middle school Shouko is suffering from a grave illness and his scar begins to throb...

(Source: Aniplex USA)', 0, NULL, '2026-03-08 03:42:58', '2026-03-08 01:07:22');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (7, 'KIMI NO SUIZOU WO TABETAI', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085463/kimi-no-suizou-wo-tabetai-f816fce47e_z01ijl.jpg', 'Drama, Romance, School', '8.67', '2018', 'Studio VOLN', 'Spring time in April and the last of the cherry blossoms are still in bloom. The usually aloof bookworm with no interest in others comes across a book in a hospital waiting room. Handwritten on the cover are the words: "Living with Dying." He soon discovers that it is a diary kept by his very popular and genuinely cheerful classmate, Sakura Yamauchi, who reveals to him that she is secretly suffering from a pancreatic illness and only has a limited time left. It is at this moment that she gains just one more person to share her secret.

Trying to maintain a normal life as much as possible, Sakura is determined to live her life to the fullest until the very last day. As her free spirit and unpredictable actions throw him for a loop, his heart begins to gradually change.

(Source: Aniplex USA)', 1, 4, '2026-03-08 03:42:58', '2026-03-08 01:07:23');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (8, 'MADE IN ABYSS: FUKAKI TAMASHII NO REIMEI', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085464/made-in-abyss-fukaki-tamashii-no-reimei-3044f6ece9_vxkgfb.jpg', 'Drama, Adventure, Sci-Fi, Mystery', '8.66', '2020', 'Kinema Citrus', 'Dawn of the Deep Soul continues the epic adventure of plucky Riko and Reg who are joined by their new friend Nanachi. Together they descend into the Abyss’ treacherous fifth layer, the Sea of Corpses, and encounter the mysterious Bondrewd, a legendary White Whistle whose shadow looms over Nanachi’s troubled past. Bondrewd is ingratiatingly hospitable, but the brave adventurers know things are not always as they seem in the enigmatic Abyss...

(Source: Sentai Filmworks)', 0, NULL, '2026-03-08 03:42:58', '2026-03-08 01:07:25');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (9, 'HAIKYUU!!: GOMI SUTEBA NO KESSEN', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085457/haikyuu-final-ffa65d64bd_jjfhrx.jpg', 'Sports, Shounen, School', '8.65', '2024', 'Production I.G', 'Theatrical follow-up to Haikyuu!! TO THE TOP 2. The first film of Haikyuu!! FINAL.

The Spring Nationals tournament continues on, with Karasuno High matched against rivals Nekoma High, the fated battle between cats versus crows, also known as the highly anticipated “Dumpster Battle”. This match is the long awaited ultimate showdown between two opposing underdog teams.

(Source: Crunchyroll, edited)', 1, 5, '2026-03-08 03:42:58', '2026-03-08 01:07:51');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (10, 'KIMETSU NO YAIBA: MUGEN RESSHA-HEN', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085458/kimetsu-no-yaiba-mugen-ressha-hen-5f89f5bdc5_ooa8ky.jpg', 'Shounen, Supernatural, Historical, Action', '8.58', '2020', 'ufotable', 'This Demon Slayer movie sees Tanjiro Kamado and friends from the Demon Slayer corps board the Infinity Train on a new mission to investigate a mysterious series of disappearances, perpetrated by a demon who has been tormenting people and killing the demon slayers who oppose it.', 0, NULL, '2026-03-08 03:42:58', '2026-03-08 01:07:52');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (11, 'JOSE TO TORA TO SAKANA-TACHI', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085458/josee-to-tora-to-sakana-tachi-e0cb3a439c_amlsye.jpg', 'Drama, Romance', '8.46', '2020', 'bones', 'The story centers on the relationship between Tsuneo and Josee. Tsuneo is a university student, and Josee is a young girl who has rarely gone out of the house by herself due to her being unable to walk. The two meet when Tsuneo finds Josee''s grandmother taking her out for a morning walk.

(Source: Anime News Network)', 0, NULL, '2026-03-08 03:42:58', '2026-03-08 01:07:54');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (12, 'JUJUTSU KAISEN 0', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085458/jujutsu-kaisen-0-77628e3b56_fceqar.jpg', 'Shounen, Fiction, Action, School', '8.38', '2021', 'MAPPA', 'Yuta Okkotsu is a nervous high school student who is suffering from a serious problem—his childhood friend Rika has turned into a curse and won''t leave him alone. Since Rika is no ordinary curse, his plight is noticed by Satoru Gojo, a teacher at Jujutsu High, a school where fledgling exorcists learn how to combat curses. Gojo convinces Yuta to enroll, but can he learn enough in time to confront the curse that haunts him?

(Source: VIZ Media)', 0, NULL, '2026-03-08 03:42:58', '2026-03-08 01:07:55');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (13, 'SEN TO CHIHIRO NO KAMIKAKUSHI', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085468/sen-to-chihiro-no-kamikakushi-7706878438_upt2ix.jpg', 'Supernatural, Adventure', '8.38', '2001', 'Studio Ghibli', 'On the way to their new home, 10-year-old Chihiro Ogino''s family stumbles upon a deserted theme park. Intrigued, the family investigates the park, though unbeknownst to them, it is secretly inhabited by spirits who sleep by day and appear at night. When Chihiro''s mother and father eat food from a restaurant in the street, angry spirits turn them into pigs. Furthermore, a wide sea has appeared between the spirit world and the human one, trapping Chihiro, the sole human, in a land of spirits. Luckily for her though, a mysterious boy named Haku appears, claiming to know her from the past. Under his instructions, Chihiro secures a job in the bathhouse where Haku works. With only her courage and some new found friends to aid her, Chihiro embarks on a journey to turn her parents back to their original forms and return home.', 0, NULL, '2026-03-08 03:42:58', '2026-03-08 01:07:56');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (14, 'SUZUMIYA HARUHI NO SHOUSHITSU', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085468/suzumiya-haruhi-no-shoushitsu-7b921d80de_ssco92.jpg', 'Comedy, Mystery, Romance, Sci-Fi, School', '8.34', '2010', 'Kyoto Animation', 'It is mid-December, and SOS Brigade chief Haruhi Suzumiya announces that the Brigade is going to hold a Christmas party in their clubroom, with Japanese hotpot for dinner. The brigade members Kyon, Yuki Nagato, Mikuru Asahina and Itsuki Koizumi start preparing everything for the party, such as costumes and decorations. But a couple of days later, Kyon arrives at school only to find that Haruhi is missing. Not only that, but Mikuru claims she has never known Kyon before, Koizumi is also missing, and Yuki has become the sole member of the literature club. The SOS Brigade seems to have never existed, nor has Haruhi Suzumiya. No one in the school has ever heard about her... except for Kyon.

(Source: Anime News Network)', 0, NULL, '2026-03-08 03:42:58', '2026-03-08 01:07:57');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (15, 'ORANGE: MIRAI', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1771085464/orange-mirai-3eecbb9f28_s6qico.jpg', 'Drama, Shoujo, Romance, Sci-Fi, School', '6.97', '2016', 'Telecom Animation Film', 'This film retells the main story from the viewpoint of Hiroto Suwa, as he continues to support Kakeru and Naho''s relationship. The film also features an original story which takes place after the events in the manga and anime series.', 0, NULL, '2026-03-08 03:42:58', '2026-03-08 01:07:59');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (16, 'MONONOKE HIME', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1772934638/princess-mononoke-681478c85f2b9_qdxn7n.jpg', 'Action, Adventure, Fantasy', '8.67', '1997', 'Studio Ghibli', 'A calm village residing in the mountains comes under attack from a demon-possessed boar one day.

Ashitaka, a young man and prince of the tribe, engages the creature in an attempt to save his village. During the battle, the boar bites him on the arm, leaving it blackened and cursed. Following his village''s traditions, Ashitaka is exiled and becomes a wanderer, looking for a solution to the curse before it engulfs him.

Iron Town is a fortress under the leadership of Lady Eboshi. Through the clearing of the surrounding forests, Iron Town produces large amounts of Ironsand, used for gunpowder and other machinery. However, because of the forests destruction, nearby animal clans seek revenge led by a human girl of the Wolf clan called San.

When Ashitaka comes to Iron Town, he discovers the area consumed in battle. Horrified, he attempts to create peace and befriend the Wolf Clan. However, after the forest''s eradication and the ongoing war between Human and Beast, will the Spirit of the Forest be forgiving and accept Ashitaka''s request to expel his curse?

[Written by MAL Rewrite]', 0, NULL, '2026-03-08 04:54:53', '2026-03-08 01:55:05');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (17, 'HOWL NO UGOKU SHIRO', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1772934640/howls-moving-castle-56fd913973358_qzlaef.jpg', 'Adventure, Drama, Fantasy, Romance', '8.66', '2004', 'Studio Ghibli', 'Sophie, a quiet girl working in a hat shop, finds her life thrown into turmoil when she is literally swept off her feet by a handsome but mysterious wizard named Howl. The vain and vengeful Witch of the Waste, jealous of their friendship, puts a spell on Sophie. In a life-changing adventure, Sophie climbs aboard Howl''s magnificent flying castle and enters a magical world on a quest to break the spell. 


(Source: Disney)', 0, NULL, '2026-03-08 04:54:53', '2026-03-08 01:55:07');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (18, 'PERFECT BLUE', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1772934636/perfect-blue-57d8dab079bff_jw0y23.jpg', 'Drama, Horror, Psychological', '8.54', '1998', 'MADHOUSE', 'Rising pop star Mima has quit singing to pursue a career as an actress and model, but her fans aren’t ready to see her go... Encouraged by her managers, Mima takes on a recurring role on a popular TV show, when suddenly her handlers and collaborators begin turning up murdered. Harboring feelings of guilt and haunted by visions of her former self, Mima’s reality and fantasy meld into a frenzied paranoia. As her stalker closes in, in person and online, the threat he poses is more real than even Mima knows, in this iconic psychological thriller that has frequently been hailed as one of the most important animated films of all time.

(Source: Shout! Factory)

Note: The film received an early premiere at the Fantasia Film Festival on August 5, 1997.', 0, NULL, '2026-03-08 04:54:53', '2026-03-08 01:55:08');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (19, 'PAPRIKA', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1772934636/paprika-66def5943cfed_gku8no.jpg', 'Fantasy, Mystery, Psychological, Sci-Fi', '8.45', '2006', 'MADHOUSE', 'Prepare to enter the realm of fantasy and imagination where reality and dreams collide in a kaleidoscopic mindscape of sheer visual genius. The magical tale centers on a revolutionary machine that allows scientists to enter and record a subject''s dream. After being stolen, a fearless detective and brilliant therapist join forces to recover the device before it falls into the hands of a dream terrorist.

(Source: Sony Pictures Home Entertainment)

Note: The film received an early premiere at the 63rd Venice International Film Festival on September 2, 2006.', 0, NULL, '2026-03-08 04:54:53', '2026-03-08 01:55:09');
INSERT INTO `movies` (`id`, `name`, `src`, `category`, `rating`, `year`, `studio`, `description`, `homeFeatured`, `homeOrder`, `createdAt`, `updatedAt`) VALUES (20, 'MILLENNIUM ACTRESS', 'https://res.cloudinary.com/dcignxwwq/image/upload/v1772934635/millennium-actress-59b10ca0dcc61_kmh1iq.jpg', 'Drama, Fantasy, Romance', '8.26', '2002', 'MADHOUSE', 'Millennium Actress blurs the lines between the past and the present, and truth and fiction, when a documentary filmmaker fulfills his quest to find the legendary actress Chiyoko Fujiwara, and learn why she mysteriously vanished at the height of her brilliant career. When Chiyoko grants the filmmaker’s request, he, in turn, presents her with a token – a key she had lost and thought was gone forever. The filmmaker could not have imagined that the key would not only unlock the long-held secrets of Chiyoko’s life, but also his own.

(Source: Dreamworks)

Note: The film received an early premiere at the Fantasia Film Festival on July 28, 2001.', 0, NULL, '2026-03-08 04:54:53', '2026-03-08 01:55:10');

DROP TABLE IF EXISTS `refreshtokens`;
CREATE TABLE `refreshtokens` (
  `id` int NOT NULL AUTO_INCREMENT,
  `token` varchar(500) NOT NULL,
  `expiryDate` datetime NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `userId` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `token` (`token`),
  UNIQUE KEY `token_2` (`token`),
  UNIQUE KEY `token_3` (`token`),
  UNIQUE KEY `token_4` (`token`),
  UNIQUE KEY `token_5` (`token`),
  UNIQUE KEY `token_6` (`token`),
  UNIQUE KEY `token_7` (`token`),
  UNIQUE KEY `token_8` (`token`),
  UNIQUE KEY `token_9` (`token`),
  UNIQUE KEY `token_10` (`token`),
  UNIQUE KEY `token_11` (`token`),
  UNIQUE KEY `token_12` (`token`),
  UNIQUE KEY `token_13` (`token`),
  UNIQUE KEY `token_14` (`token`),
  UNIQUE KEY `token_15` (`token`),
  KEY `userId` (`userId`),
  CONSTRAINT `refreshtokens_ibfk_1` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_10` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_11` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_12` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_13` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_14` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_15` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_2` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_3` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_4` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_5` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_6` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_7` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_8` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `refreshtokens_ibfk_9` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2995 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

